"use strict";
window.SPACR_LESSON_CATALOG = Object.freeze({"schema": 1, "title": "spaCR complete tutorial library", "series": [{"number": 1, "title": "Getting started and core analysis"}, {"number": 2, "title": "Time-resolved analysis and segmentation models"}, {"number": 3, "title": "Annotation quality control and biological assays"}, {"number": 4, "title": "Operations, reporting, and data utilities"}, {"number": 5, "title": "Additional registered modules"}], "lessons": [{"id": "01_pypi_github", "number": 1, "slug": "pypi_github", "title": "Find spaCR on GitHub, PyPI and conda-forge", "series": 1, "app_key": null, "section": "spaCR", "description": "Find the official package and installer sources, compare the release available on each channel, and choose the matching installation tutorial.", "objectives": ["Find the official download pages.", "Choose the installation route for your computer.", "Open the matching installation tutorial."], "prerequisite": "Open a web browser and decide whether you want a desktop installer or a Python environment.", "scenes": [{"visual": "01_pypi_current_release", "narration": "Choose how you want to install spaCR. Use a desktop installer for a ready-to-launch application, pip for a Python virtual environment, or conda-forge for a Conda environment. Start from the official spaCR links shown here.", "hold_after": 0.7}, {"visual": "01_pypi_current_release", "narration": "On PyPI, find spaCR and read the installation command beside the current release. Copy that command when you are ready to install into your Python environment. The pip tutorial shows how to create and activate that environment first.", "hold_after": 0.7}, {"visual": "02_pypi_project_links", "narration": "Use Project links to open the documentation, source repository or issue tracker. Bookmark the documentation so you can return to the module walkthroughs while working in spaCR.", "hold_after": 0.7}, {"visual": "03_github_main_branch", "narration": "On GitHub, open the spaCR repository. Main contains the release source, and nightly contains the latest development work. For a packaged desktop installation, open Releases and choose a release.", "hold_after": 0.7}, {"visual": "04_github_current_assets", "narration": "Expand Assets and download the installer for Windows, macOS or Linux. Keep the checksum file from the same release if you want to verify the download. The Platform installers lesson walks through launching the installer and opening spaCR.", "hold_after": 0.7, "related_lessons": ["04_platform_installers"]}, {"visual": "05_conda_current_package", "narration": "On conda-forge, open the spaCR package page and check the available version. Package channels can update at different times, so select the version available through the route you choose.", "hold_after": 0.7}, {"visual": "05_conda_current_package", "narration": "The conda-forge command installs spaCR into your active Conda environment. Follow the Conda lesson to create that environment, install the package and launch the application.", "hold_after": 0.7, "related_lessons": ["02_conda_install"]}, {"visual": "01_pypi_current_release", "narration": "Continue with pip, Conda or Platform installers. Once spaCR opens, move to the Home lesson, then the pipeline overviews to choose a workflow for your data.", "hold_after": 0.7, "related_lessons": ["02_conda_install", "03_pip_install", "04_platform_installers"]}], "narration_voices": {"en": ["af_heart"]}, "poster": "01_pypi_github/poster.jpg", "silent": "01_pypi_github/video/01_pypi_github_silent.mp4"}, {"id": "02_conda_install", "number": 2, "slug": "conda_install", "title": "Installation with Conda", "series": 1, "app_key": null, "section": "spaCR", "description": "Install the official conda-forge package in a separate environment, verify the actual channel version, and recognize when that version differs from the current module tutorials.", "objectives": ["Create and activate a dedicated Conda environment.", "Verify the installed channel package, Qt and diagnostic results.", "Choose the newer pip or desktop-installer route when the channel still has the older interface."], "prerequisite": "A Conda-compatible manager must already be installed. This recording verifies conda-forge spaCR 1.5.0.4 on Linux, with Python 3.12.14 and Qt 6.11.2, on 2026-09-10. The clean installation used a new private prefix, only conda-forge, and the pinned channel version; command cards illustrate the corresponding named-environment workflow rather than replaying installation output. The actual GUI still has Home (63), not the new nested layout in PyPI/installer 1.5.0.5. Default spacr-doctor performed its small CUDA allocation check successfully but warned about optional CZI support; this is not a speed benchmark or verification of every analysis or format. The native capture uses a private dark profile at font scale 1.5 with the tour already dismissed, unchanged preload defaults and no unsupported --no-setup flag. Other platforms were not tested. Original authoring and published narration differ, so unchanged audio reuse is not claimed.", "scenes": [{"visual": "02_conda_environment", "narration": "Use a dedicated Conda environment for spaCR, and check which release the channel actually provides. At this recording, conda-forge installs one point five point zero point four. PyPI and the desktop installer already offer one point five point zero point five; these are not interchangeable version labels.", "hold_after": 0.7}, {"visual": "07_create_conda", "narration": "Open a Conda-enabled shell and create a new environment with Python three point twelve. The command card uses the name spacr-conda. Choose another unused name if it already exists, and keep this environment separate from ongoing analyses.", "hold_after": 0.7}, {"visual": "08_activate_conda", "narration": "Activate the environment and print sys dot prefix to confirm where Python belongs. The actual verification uses a longer private prefix instead of the short example name. A terminal prompt alone is not proof that you are using the intended interpreter.", "hold_after": 0.7}, {"visual": "09_install_conda", "narration": "Install the channel-qualified conda-forge package, then use conda list spacr to inspect the version and channel. Our recorded installation used only conda-forge and pinned the channel release. Its installation completed before the verification frames; these cards are instructions, not fabricated terminal output.", "hold_after": 0.7}, {"visual": "03_installed_versions", "narration": "Check the spaCR version, Qt version and package location in the installed environment. Here the package is one point five point zero point four and Qt imports successfully. This proves which package is active, not that every scientific workflow or optional format has been validated.", "hold_after": 0.7}, {"visual": "05_doctor", "narration": "Run spacr-doctor and read the warnings too. Here its small GPU allocation check succeeds, while optional CZI support has a missing dependency. Skipped checks are not passes. The suggested repair concerns that feature; assess any environment changes before applying it, especially when mixing package managers.", "hold_after": 0.7}, {"visual": "06_installed_home", "narration": "The installed Conda package opens and closes normally, but this is its older Home with sixty-three tiles. It does not have the new nested module layout. Do not assume that a successful installation means every screen matches tutorials for a newer release.", "hold_after": 0.7}, {"visual": "10_current_release_choice", "narration": "For the newer nested interface shown in the refreshed module tutorials, use the current pip or Platform installers lesson in a separate environment. If you need the Conda channel, keep track of its actual release and check again for updates. Preserve the version used for an ongoing analysis.", "related_lessons": ["01_pypi_github", "03_pip_install", "04_platform_installers"], "hold_after": 0.7}], "poster": "02_conda_install/poster.jpg", "silent": "02_conda_install/video/02_conda_install_silent.mp4"}, {"id": "03_pip_install", "number": 3, "slug": "pip_install", "title": "Install spaCR with pip", "series": 1, "app_key": null, "section": "spaCR", "description": "Create an isolated Python environment, install the public package, verify its dependencies, and launch the installed Qt application.", "objectives": ["Keep spaCR's dependencies in a dedicated Python environment.", "Verify the installed package, Qt and optional-feature warnings.", "Launch Home and update the intended environment deliberately."], "prerequisite": "This lesson verifies public PyPI spaCR 1.5.0.5 on Linux with Python 3.12.13, not an editable checkout. Command-reference cards are instructions, not recorded terminal output; Windows and macOS commands were not executed here. The actual clean installation completed before the recorded verification. Current base dependencies include Qt. Doctor reports an optional CZI warning; its GPU allocation probe is explicitly skipped. The native GUI capture uses --no-setup, a private dark profile at font scale 1.5, and an already-dismissed tour. It proves a normal Home launch and close, not every module, optional format, GPU computation or another platform.", "scenes": [{"visual": "01_python_version", "narration": "Install spaCR in its own Python environment. This demonstration uses Python three point twelve on Linux and the public PyPI release, not a source checkout. Check python dash dash version before choosing the interpreter for your environment.", "hold_after": 0.7}, {"visual": "07_create_environment", "narration": "Create a new virtual environment with the command for your platform. Here dot venv is a new folder in your working directory. Python three point twelve must already be installed; this command creates an environment, not Python itself.", "hold_after": 0.7}, {"visual": "08_activate_environment", "narration": "Activate that environment using the command for your shell. PowerShell, Command Prompt, bash and zsh use different activation commands. If PowerShell blocks the script, use Command Prompt or call the environment's Python directly; do not weaken machine-wide security settings.", "hold_after": 0.7}, {"visual": "02_pip_environment", "narration": "Run python dash m pip dash dash version. Its location should point inside the environment you chose. This actual terminal shows the longer private path used for the recording. Using python dash m pip ties package installation to that interpreter.", "hold_after": 0.7}, {"visual": "09_install_package", "narration": "Upgrade pip, then install spacr. Pinning one point five point zero point five reproduces this lesson's release. The clean installation completed before these verification frames. Allow time and disk space for scientific dependencies; current base dependencies already include the Qt desktop components.", "hold_after": 0.7}, {"visual": "03_installed_versions", "narration": "Check the installed spaCR version, Qt version and package path. All three come from the new environment here. An import alone does not prove that every optional format or analysis works, and it does not prove the window will open.", "hold_after": 0.7}, {"visual": "04_dependency_check", "narration": "Run python dash m pip check. No broken requirements means the installed dependency declarations are consistent. If it reports a conflict, resolve it before proceeding; a successful check is not a scientific validation of an analysis.", "hold_after": 0.7}, {"visual": "05_doctor", "narration": "Run spacr-doctor and read warnings as well as passes. This installation has an optional CZI warning, with its repair command shown. The recording uses dash dash no gpu probe, so it detects the device but does not test a GPU allocation. Skipped checks are not passes.", "hold_after": 0.7}, {"visual": "10_launch_commands", "narration": "Launch spacr from the same activated environment. A normal first launch may ask setup questions. This bounded verification explicitly uses dash dash no setup and a prepared recording profile, so it does not demonstrate answering those questions.", "hold_after": 0.7}, {"visual": "06_installed_home", "narration": "This is the actual Home window from the installed wheel, with the six core modules and the Data, Tools and Assays groups. It opened and closed normally without starting an analysis. Continue with Home for navigation, nested tools and the module tutorials.", "related_lessons": ["05_home"], "hold_after": 0.7}, {"visual": "11_update_intentionally", "narration": "For an update, close spaCR and activate the environment you intend to change. Upgrade the package, repeat pip check and spacr-doctor, and record the resulting version with your analysis. Upgrades can change dependencies and behaviour; do not silently change an environment supporting ongoing work.", "related_lessons": ["01_pypi_github", "04_platform_installers"], "hold_after": 0.7}], "poster": "03_pip_install/poster.jpg", "silent": "03_pip_install/video/03_pip_install_silent.mp4"}, {"id": "04_platform_installers", "number": 4, "slug": "platform_installers", "title": "Platform installers", "series": 1, "app_key": null, "section": "spaCR", "description": "Choose an official desktop installer, understand automatic accelerator selection and optional privacy choices, and verify the actual installed Linux runtime.", "objectives": ["Select the official installer for the operating system.", "Distinguish automatic acceleration from an explicit CPU-only choice.", "Read privacy choices, installed versions and diagnostic warnings."], "prerequisite": "This recording verifies the checksum-matched public Linux x86-64 online installer for spaCR 1.5.0.5 on 2026-09-10, with Python 3.12.13, Qt 6.11.2 and Torch 2.14.0+cu132. The real install finished before these verification frames. It used a new private runtime and launcher directory, existing system GUI libraries, --skip-system-deps and --no-launch; no existing environment or system dependency was changed. Four reference cards are instructions, not recorded Windows/macOS installations or fabricated terminal output. Windows/macOS guidance was checked against current installer source only. The GUI recording uses a private dark profile at font scale 1.5, a dismissed tour, on-demand preload and --no-setup, which does not bypass the separate privacy prompt. Native Escape rejects that prompt with every optional choice off; the private preferences were read back. Doctor used --no-gpu-probe; no allocation, speed, analysis or other-platform validation is claimed. Earlier failed recorder takes are retained, not counted as application defects.", "scenes": [{"visual": "08_official_release", "narration": "Use the official spaCR GitHub release and match the installer to your operating system. The online installers download a private Python runtime and scientific dependencies; an existing Conda environment is not required. For this Linux example, we checked the downloaded file against the release checksum before running it.", "hold_after": 0.7}, {"visual": "09_windows_guidance", "narration": "On Windows, select the online setup executable. The current installer source preselects automatic acceleration; its optional component can be unticked for CPU-only operation. This card explains that choice, but it is not a Windows installation recording or a compatibility test on your computer.", "hold_after": 0.7}, {"visual": "10_macos_guidance", "narration": "On macOS, select the universal online package for Intel and Apple silicon. The app launcher starts per-user setup if its runtime is missing. Verify the official source before approving security prompts, and allow time for downloads. This is source-reviewed guidance, not an executed macOS installation.", "hold_after": 0.7}, {"visual": "11_linux_commands", "narration": "On Linux, make the verified download executable and run it from its folder. Automatic accelerator selection is now the default; request the CPU backend explicitly if that is what you need. Our isolated run reused existing system libraries and used private paths, so it did not demonstrate installing system dependencies.", "hold_after": 0.7}, {"visual": "02_installer_backend", "narration": "Read the actual install profile rather than inferring the backend from a successful launch. Here the request was auto and the selected backend is CUDA on NVIDIA hardware. The installed Torch build is CUDA thirteen point two. This identifies the selection; it is not a GPU speed benchmark.", "hold_after": 0.7}, {"visual": "03_installed_versions", "narration": "Check the installed package version, Qt import and package path. This private runtime contains spaCR one point five point zero point five. Its files come from the installation, not an editable source checkout. Successful imports do not validate every analysis or optional file format.", "hold_after": 0.7}, {"visual": "07_privacy_keep_off", "narration": "The real first launch asks about optional diagnostic sharing, public issue reports and account setup. Reports would be public, so read the explanation. This recording rejects the dialog with Escape, equivalent to Skip, keep all off. No accounts are connected, and the private preferences confirm that sharing and issue actions remain off.", "hold_after": 0.7}, {"visual": "06_installed_home", "narration": "After that choice, the installed application opens its current Home with twenty-one tiles and six core modules. The window closes normally too. Continue with the Home lesson to learn the nested workflows and their example data; opening Home alone is not an analysis test.", "related_lessons": ["05_home"], "hold_after": 0.7}, {"visual": "05_doctor", "narration": "Run spacr-doctor from the installed runtime and read warnings as well as passes. Here it confirms the installer backend but warns about a missing optional CZI dependency. This run skipped GPU allocation, database and settings checks. A skipped check is not a pass; assess the suggested repair before changing the environment.", "hold_after": 0.7}, {"visual": "12_logs_and_versions", "narration": "Keep install dot log and install-profile dot json from the chosen installation directory when diagnosing a problem. Review logs for private information before sharing them. Record the version used for each analysis, and treat updates deliberately. The pip and Conda lessons describe the separate environment-based installation routes.", "related_lessons": ["01_pypi_github", "02_conda_install", "03_pip_install"], "hold_after": 0.7}], "poster": "04_platform_installers/poster.jpg", "silent": "04_platform_installers/video/04_platform_installers_silent.mp4"}, {"id": "05_home", "number": 5, "slug": "home", "title": "Home screen and navigation", "series": 1, "app_key": null, "section": "spaCR", "description": "Open a module from Home, find its related tools and example data, then choose a pipeline to follow.", "objectives": ["Choose a starting module for images, measurements or sequencing reads.", "Find related tools and organism-specific assays.", "Load an example, find help and open a pipeline overview."], "prerequisite": "Install spaCR and open the desktop application.", "scenes": [{"visual": "00_home", "narration": "Home is your starting point. Click a tile to open a module, or use the sidebar on the left. Click Home in the sidebar to return here. The Core, Data, Tools and Assays tabs help you find the task you want to do.", "hold_after": 0.7}, {"visual": "01_core  (6)", "narration": "For microscope images, begin with Mask to outline objects, then Measure to extract their features and crops. Annotate lets you label example objects, and Classify learns from those labels to score more objects. Map Barcodes reads sequencing data. Regression combines the resulting phenotype scores and guide counts to find associations.", "hold_after": 0.7, "focus_modules": ["mask", "measure", "annotate", "classify_merged", "map_barcodes", "regression"], "related_lessons": ["07_mask", "08_measure", "09_annotate", "41_classify", "12_map_barcodes", "13_regression"]}, {"visual": "02_data  (7)", "narration": "Open Data to bring existing files into a project or work with results. Import accepts images, masks and measurement tables. Use Run Compare to compare runs, Experiment Design to prepare plate layouts, and QC to inspect recorded quality checks. Choose the tile that matches your next task.", "hold_after": 0.7, "focus_modules": ["foreign", "embeddings", "run_compare", "experiment_design", "power", "dose_response", "qc_dashboard"], "related_lessons": ["36_import", "35_converter", "31_external_masks", "77_embeddings"]}, {"visual": "03_tools  (5)", "narration": "Open Tools for image editing and exploration. Make Masks lets you edit masks and open the Cellpose Workbench. Align and Stitch combines overlapping image tiles. Image UMAP, Gate Editor and Graph Builder help you explore measurements and make plots. Open a module to find its related tools in the toolbar.", "hold_after": 0.7, "focus_modules": ["make_masks", "align", "umap", "gate_editor", "graph_builder"], "related_lessons": ["14_make_masks", "32_align_stitch", "15_image_umap", "64_gate_editor", "58_graph_builder"]}, {"visual": "04_assays  (3)", "narration": "Open Assays and choose your organism: Toxoplasma, Plasmodium or Candida. Then choose an assay from that organism’s menu. For example, open Toxoplasma for plaque analysis or host–pathogen measurements. Follow the selected assay’s tutorial to prepare its images, masks and measurement inputs.", "hold_after": 0.7, "focus_modules": ["toxoplasma", "plasmodium", "candida"], "related_lessons": ["24_plaque", "25_recruitment", "26_invasion", "27_replication"]}, {"visual": "05_classify_host", "narration": "Open Classify and use Classifier family to choose your input. Select Computer Vision for object images, or Tabular Machine Learning for measured feature columns. The linked tutorials take you through training, evaluation and scoring for each family.", "hold_after": 0.7, "related_lessons": ["41_classify", "10_classify_cv", "11_classify_ml"]}, {"visual": "05_classify_host", "narration": "The toolbar in Classify opens Classifier Evaluation, Explain CV Model, Activation, Training Runs and Feature Explorer. Hover over an icon to see its name, then click it to open the tool. Use these views to inspect a model, compare training runs or explore important features.", "hold_after": 0.7, "focus_buttons": "FoldButton", "related_lessons": ["39_classifier_evaluation", "70_explain_cv", "16_activation", "28_training_runs", "65_feature_explorer"]}, {"visual": "06_mask_host", "narration": "To try a module, click Load test data when it is available. Wait for the download to finish, then review the filled inputs and settings. In Mask, click Live to inspect a field before pressing Run. Turn on Time for a time series or three-D for a volumetric image.", "hold_after": 0.7, "related_lessons": ["07_mask", "17_timelapse"]}, {"visual": "08_help_search", "narration": "Type a module, setting or function name into the search field beside Help. Here, searching for Performance finds the matching Preferences page. Click a result to open its destination. API results open the documentation for the selected function.", "hold_after": 0.7}, {"visual": "09_performance", "narration": "In Preferences, choose a Performance profile for your computer. Laptop uses fewer resources; the higher profiles allow more caching and background work. Start with a modest profile if memory is limited. Your analysis settings stay under your control in each module.", "hold_after": 0.7}, {"visual": "00_home", "narration": "Return to Home and click Pipeline overviews to choose a workflow. Start with spaCR screens for a pooled image-based screen, or choose an image-analysis or sequencing pathway for your data. The next tutorials show how those modules connect, and the module lessons then walk through each task.", "hold_after": 0.7, "related_lessons": ["78_spacr_screens", "80_image_analysis_pathways", "81_sequencing_pathways"], "focus": [3341, 180, 499, 96]}], "narration_voices": {"en": ["af_heart"]}, "poster": "05_home/poster.jpg", "silent": "05_home/video/05_home_silent.mp4"}, {"id": "06_api", "number": 6, "slug": "api", "title": "Python API and batch commands", "series": 1, "app_key": null, "section": "spaCR", "description": "Find an analysis function, load saved settings, check the inputs and run spaCR from a terminal.", "objectives": ["Find the installed batch commands and their Python functions.", "Inspect a function signature and its API reference.", "Check saved settings before running an analysis."], "prerequisite": "Install spaCR and activate its Python environment. Follow the Regression tutorial to prepare paired score/count tables and save the analysis settings. Use your own file paths in the commands.", "scenes": [{"visual": "01_version", "focus": [200, 100, 1900, 650], "narration": "Activate the Python environment where you installed spaCR. Import spacr and print its version with the command shown. Keep the version with your analysis notes so you can reproduce the same run later.", "related_lessons": ["02_conda_install", "03_pip_install", "04_platform_installers"], "hold_after": 0.7}, {"visual": "02_list", "focus": [200, 100, 2800, 1900], "narration": "Run spacr-run with dash dash list to find the available batch commands. The list shows each command key and its Python function. Choose the command for your task, such as mask, measure or regression. Use the desktop application for interactive tasks such as labelling images in Annotate.", "hold_after": 0.7}, {"visual": "03_describe", "focus": [200, 100, 2250, 900], "narration": "Run spacr-run with dash dash describe followed by regression. Read the required inputs, defaults and function name. Here, the batch command calls perform_regression in spacr.ml. Open that function in the API reference to read its parameters and returned results.", "related_lessons": ["13_regression", "15_image_umap"], "hold_after": 0.7}, {"visual": "05_report_api", "focus": [200, 100, 2800, 700], "narration": "In Python, import the function you need and inspect its signature. This example imports build_report from spacr.report. Look up the same name in the API reference, prepare the required arguments, and call the function from your script or notebook.", "hold_after": 0.7}, {"visual": "06_dry_run", "focus": [200, 1320, 3440, 680], "narration": "Save the settings from your module workflow, then pass the file with dash dash settings. Add dash dash dry-run to check the configuration and input paths. In this Regression example, the settings pair phenotype scores with guide counts for each plate. Read the messages and correct any missing inputs before continuing.", "hold_after": 0.7}, {"visual": "03_describe", "focus": [200, 100, 2250, 900], "narration": "To execute the analysis, run the same command without dash dash dry-run. Follow the console until the command finishes, then inspect the outputs described by that module’s tutorial and API page. Keep the settings file, input tables, package version and console log with the results.", "related_lessons": ["13_regression", "15_image_umap"], "hold_after": 0.7}], "narration_voices": {"en": ["af_heart"]}, "poster": "06_api/poster.jpg", "silent": "06_api/video/06_api_silent.mp4"}, {"id": "07_mask", "number": 7, "slug": "mask", "title": "Mask: segment images and inspect the results", "series": 1, "app_key": "mask", "section": "Core", "description": "Load microscope images, choose segmentation settings, preview objects and save masks for measurement.", "objectives": ["Load the microscopy example and identify its intensity channels.", "Compare model settings and object-size filters in Live preview.", "Run segmentation, inspect overlays and find the merged outputs."], "example_files": ["Mask_overlay_API_workaround.zip"], "prerequisite": "Open Mask and choose Load test data. For your own images, prepare a source folder with consistent filenames and known channel identities. This example uses nucleus channel 0, cell channel 1 and pathogen channel 2, with an additional intensity channel 3.", "scenes": [{"visual": "native_01_module", "narration": "From Home, open Mask. Use this module to outline cells, nuclei and pathogens in microscope images. This walkthrough processes two-dimensional images. The Time, three-dimensional and OPS workflows have their own tutorials.", "related_lessons": ["05_home", "17_timelapse", "76_ops"], "hold_after": 0.7}, {"visual": "native_02_download", "narration": "Click Load test data and wait for the microscopy example to load. Check Source before continuing. For your own images, select their folder and confirm that the filenames identify the plate, well, field and channel.", "hold_after": 0.7}, {"visual": "native_03_data_ready", "narration": "Check the channel assignments against the images. In this example, nucleus intensity is channel zero, cell intensity is channel one, and pathogen intensity is channel two. Channel three is an additional intensity image. Choose only the object types present in your experiment.", "hold_after": 0.7}, {"visual": "preview_04_live_image", "narration": "Turn on Live and select a field. Inspect the image and proposed masks together before running the full folder. Try several fields that represent the range of image quality in your experiment.", "hold_after": 0.7}, {"visual": "preview_05_live_settings", "narration": "Open Live settings and choose the model for the object you want to segment. Set the approximate object diameter and run the preview. Compare the outlines with the image, paying attention to missed objects and objects joined together.", "hold_after": 0.7}, {"visual": "preview_09_filters_after", "narration": "Use the minimum-area filter to hide objects smaller than the chosen number of pixels. Increasing it removes small labels from the preview. This filter updates an existing mask result, so you can compare size cutoffs quickly.", "hold_after": 0.7}, {"visual": "preview_12_model_result", "narration": "Change diameter when the model is splitting or joining objects at the wrong scale, then run the preview again. Check the boundaries as well as the object count. Restore the settings you want to use before moving to the batch run.", "hold_after": 0.7}, {"visual": "native_20_batch_settings", "narration": "For a small first run, select two test images, keep Plot on, and review the cell, nucleus and pathogen flow thresholds. Here they are zero point four. Check the output and original-image retention settings, then click Run.", "hold_after": 0.7}, {"visual": "native_23_batch_finished", "narration": "Follow the console and inspect any failed fields or missing plots. The merged folder contains the image intensities and final object labels. Keep its plane-layout metadata with the arrays so Measure can identify each channel and mask.", "hold_after": 0.7}, {"visual": "command_01_explicit_numeric_inputs", "narration": "If an overlay export is missing, the linked plotting helper can export the saved arrays separately. Extract the helper and choose this run’s merged folder. Keep the layout file in place; the helper uses it to check the intensity and mask planes.", "focus": [190, 80, 3450, 1120], "related_lessons": ["06_api"], "hold_after": 0.7}, {"visual": "command_02_explicit_plotting_api", "narration": "Run the helper with the merged folder as its source and a new output folder as its destination. It saves a separate overlay for each image array. Open the saved PNG files to inspect the results.", "focus": [190, 80, 3450, 1000], "hold_after": 0.7}, {"visual": "viewer_10_saved_plate1_L02_18_1", "narration": "Review the outlines on each intensity channel and the combined mask view. Check small objects, touching cells and missed regions. Keep the input images, settings, masks and quality reports together, then continue to Measure to extract object features and crops.", "focus": [200, 680, 3440, 880], "hold_after": 0.7}], "narration_voices": {"en": ["af_heart"]}, "poster": "07_mask/poster.jpg", "silent": "07_mask/video/07_mask_silent.mp4"}, {"id": "08_measure", "number": 8, "slug": "measure", "title": "Measure: extract object features and crops", "series": 1, "app_key": "measure", "section": "Core", "description": "Load images with masks, inspect objects, choose crop settings and save measurements for annotation and classification.", "objectives": ["Identify intensity channels and mask planes in the example.", "Inspect fields and choose saved-crop normalization deliberately.", "Run Measure and locate the database, object crops and figures."], "prerequisite": "Use the merged outputs from Mask, or choose Load test data in Measure. The example supplies sixteen fields with intensity planes 0–3 and cell, nucleus and pathogen masks in planes 4, 5 and 6.", "scenes": [{"visual": "preview_01_module", "narration": "From Home, open Measure. Start with images that already have object masks. Measure extracts features such as area and intensity, pairs related objects, and can save individual object crops for Annotate and Classify.", "related_lessons": ["07_mask", "43_illumination", "18_motility", "59_anndata_export"], "hold_after": 0.7}, {"visual": "preview_03_data_ready", "narration": "Click Load test data and wait for the example to load, or select your own merged project. Check the plane mapping: this example has four intensity channels followed by cell, nucleus and pathogen masks in planes four, five and six.", "hold_after": 0.7}, {"visual": "preview_04_preview_normalization_setup", "narration": "To inspect these sixteen-bit example crops, turn Normalize on before opening Live. This makes the preview easier to see. Remember that this main setting also affects saved crops; we will switch it off before this batch run.", "hold_after": 0.7}, {"visual": "preview_05_live_all_channels", "narration": "Turn on Live and choose a field. Inspect the object crops and their mask relationships. Scroll through the categories and enlarge the preview if needed to see the boundaries clearly.", "hold_after": 0.7}, {"visual": "preview_06_live_channel_zero", "narration": "Use the displayed-channel selector to inspect one intensity channel at a time. Channel zero shows a grayscale view; All channels restores the combined view. This selector changes the preview without changing the labels or batch channel mapping.", "hold_after": 0.7}, {"visual": "preview_07_live_second_field", "narration": "Choose another field and compare its objects. Review the segmentation-quality banner before measuring the project. If masks are missing or joined incorrectly, correct them or adjust Mask before continuing.", "hold_after": 0.7}, {"visual": "preview_08_saved_normalization_restored", "narration": "Turn Live off and restore Normalize off for this example. Choose normalization deliberately when saving crops: per-crop scaling changes the intensity differences visible to a later image classifier. Keep the original merged arrays for quantitative measurements.", "related_lessons": ["09_annotate"], "hold_after": 0.7}, {"visual": "batch_20_batch_settings", "narration": "Enable saving measurements and object crops, keep Plot on, and choose the crop size and output channels. Use one worker for this example. Leave Test mode off to process all sixteen supplied fields, then click Run.", "hold_after": 0.7}, {"visual": "batch_26_measure_console_complete", "narration": "Follow the console until the run completes. Check which fields succeeded and inspect any failures before proceeding. Keep the settings saved with this run so you can reproduce the measurements.", "hold_after": 0.7}, {"visual": "batch_25_measure_figure_00", "narration": "Use the figure list to compare objects before and after filtering. Size filters and parent-child relationships can change which objects are measured. Drag the divider to give the figures more space and inspect any unexpected changes.", "hold_after": 0.7}, {"visual": "batch_25_measure_figure_02", "narration": "Inspect the crop figure, then locate measurements.db in the measurements folder and the saved object images in the project’s crop output. Keep the database and image paths together. Continue to Annotate to label example objects, or to Classify when you already have labelled training data.", "related_lessons": ["09_annotate", "11_classify_ml"], "hold_after": 0.7}], "narration_voices": {"en": ["af_heart"]}, "poster": "08_measure/poster.jpg", "silent": "08_measure/video/08_measure_silent.mp4"}, {"id": "09_annotate", "number": 9, "slug": "annotate", "title": "Annotate: label objects and save your annotations", "series": 1, "app_key": "annotate", "section": "Core", "description": "Load example crops, choose an annotation column, label objects, adjust the view and prepare your labels for classification.", "objectives": ["Load saved crops or stream crops from merged images.", "Choose an annotation column, assign and clear labels, and save your changes.", "Adjust channel colours and review class counts and coverage.", "Find Agreement and the image and feature training routes."], "prerequisite": "Open Annotate from Home. Use Load test data and choose Load for the example crops and measurements database. For your own project, use the folder containing its measurements database and crops or merged images.", "scenes": [{"visual": "01_module", "narration": "Open Annotate from Home. The grid shows individual objects from your project. You will label these objects and save the labels in the measurements database.", "hold_after": 0.7}, {"visual": "02_data_choice_load", "focus": [1680, 896, 460, 477], "narration": "Click Load test data and choose Load. This downloads the example image crops and their measurements database, then opens them in Annotate.", "hold_after": 0.7}, {"visual": "02_data_choice_stream", "focus": [1680, 896, 460, 477], "narration": "Choose Stream when you want to read crops directly from merged images. Choose Load for already exported crops. We will use Load for this walkthrough.", "hold_after": 0.7}, {"visual": "04_open_source_dialog", "focus": [1393, 810, 1300, 950], "narration": "To open your own data, click Open source and select the plate folder containing measurements and the image data. The grid then loads the objects from that project.", "hold_after": 0.7}, {"visual": "05_loaded_crops", "narration": "Inspect the crop grid. Use the page controls to browse the objects. Adjust the crop size if you need a closer view or want more objects on each page.", "hold_after": 0.7}, {"visual": "06_annotation_settings", "focus": [1536, 309, 748, 1462], "narration": "Open Settings and choose an annotation column. Create a new column to keep this labelling task separate from existing annotations. Decide what each class represents before you start.", "hold_after": 0.7}, {"visual": "08_class_one_pending", "narration": "Left-click a crop to assign class one. Right-click assigns class two. Click the same class again to clear it. The coloured ring shows the label, and the white ring marks the focused crop.", "hold_after": 0.7}, {"visual": "08_next_page_saved", "narration": "Press Next to move to the next page and submit your labels for saving. Wait for saving to finish before closing the application.", "hold_after": 0.7}, {"visual": "08_class_one_saved", "narration": "Press Back to return to the previous page and check your labels. You can also use keys one to nine to assign classes and zero to clear a label. The on-screen legend lists the navigation and undo shortcuts.", "hold_after": 0.7}, {"visual": "09_class_counts", "focus": [1768, 972, 285, 136], "narration": "Open Class counts to see how many objects you have labelled in each class. Use this to find classes that need more examples.", "hold_after": 0.7}, {"visual": "09_annotation_coverage", "focus": [1450, 730, 920, 620], "narration": "Open Coverage to see how your annotations are distributed across the project. Include examples from the conditions and image groups you want the classifier to recognize.", "hold_after": 0.7}, {"visual": "10_class_cleared", "narration": "To clear a label, click the same class again. Move to the next page to save the change, then return to check the cleared crop.", "hold_after": 0.7}, {"visual": "11_display_colour_settings", "focus": [1536, 309, 748, 1462], "narration": "In Settings, Channel colours selects the display palette. Display order assigns source channels to the colour slots. Choose a view that makes your classes easy to distinguish.", "hold_after": 0.7}, {"visual": "12_cmy_view", "narration": "Here is the CMY palette. You can return to RGB through the same settings. Keep the view consistent while comparing and labelling objects.", "hold_after": 0.7}, {"visual": "15_agreement_fold", "narration": "Open Annotator Agreement from the icon at the top right to compare annotation columns. Use it to find objects where reviewers assigned different labels.", "focus_buttons": "FoldButton", "hold_after": 0.7, "related_lessons": ["23_agreement"]}, {"visual": "16_training_routes", "focus": [1832, 204, 416, 80], "narration": "When your labels are ready, open Train. Choose images for an image classifier or measured features for a tabular classifier. The linked Classify lessons explain the training settings.", "hold_after": 0.7, "related_lessons": ["41_classify", "10_classify_cv", "11_classify_ml"]}, {"visual": "14_restored_rgb", "narration": "Suggest can propose labels for you to review. Retrain updates the model after you add labels, and Rounds helps you follow that review cycle. Check suggested labels before accepting them.", "hold_after": 0.7}, {"visual": "17_generate_database_entry", "narration": "Generate annotation database creates a crop set from suitable source data. Use it when preparing a new annotation project; the downloaded example already includes the crops and database needed here.", "hold_after": 0.7, "related_lessons": ["06_api", "08_measure"]}, {"visual": "18_annotation_console", "narration": "Open Console to check source-loading and save messages. Your annotation column is stored in the project database and can be selected when you prepare training data in Classify.", "hold_after": 0.7}, {"visual": "30_ai_unsent_question", "narration": "For help with a setting, open spaCR AI in Console after configuring a provider in Preferences. When you have finished labelling, continue to Classify with your project and chosen annotation column.", "hold_after": 0.7}], "narration_voices": {"en": ["af_heart"]}, "poster": "09_annotate/poster.jpg", "silent": "09_annotate/video/09_annotate_silent.mp4"}, {"id": "10_classify_cv", "number": 10, "slug": "classify_cv", "title": "Classify: train an image classifier", "series": 1, "app_key": "classify", "host_app_key": "classify_merged", "section": "Core", "description": "Prepare labelled image crops, choose the computer-vision family, train a small model and find its predictions.", "objectives": ["Prepare the downloadable image-classification example.", "Choose the model, image channels and training settings.", "Keep wells separate and inspect saved models and predictions."], "example_files": ["Classify_existing_split_example.zip"], "prerequisite": "Download the measured example through Annotate using Load test data, then Load. Keep its plate1 folder with measurements/measurements.db and the png crops. Download Classify_existing_split_example.zip below and extract the helper. In your spaCR environment, run prepare_classify_split.py --source /path/to/plate1 --destination /path/to/new_split. Select the new_split folder in Classify. The helper is for this four-well example; it copies 64 labelled RGB crops into train and test folders.", "scenes": [{"visual": "gui_19_setting_classifier_family", "narration": "From Home, open Classify and choose Computer Vision, Torch. This family learns from labelled object crops and saves a model that can score other crops. Follow the Annotate lesson first to download the example images and their labels.", "focus": [350, 190, 1730, 430], "related_lessons": ["41_classify", "11_classify_ml"], "hold_after": 0.7}, {"visual": "prepare_01_source_example", "narration": "In Annotate, choose Load test data, then Load. Keep the plate folder containing measurements and PNG crops. For your own data, start with crops from Measure and assign the classes you want to learn in Annotate.", "focus": [190, 80, 3450, 1250], "related_lessons": ["09_annotate", "08_measure"], "hold_after": 0.7}, {"visual": "prepare_02_prepare_existing_split", "narration": "Download the linked example ZIP and extract prepare_classify_split.py. Run it in your spaCR environment with source pointing to the example plate folder and destination pointing to a new folder. The helper prepares sixty-four labelled images for this exercise.", "focus": [190, 80, 3450, 1300], "hold_after": 0.7}, {"visual": "prepare_03_exported_manifest", "narration": "Open the new folder and its manifest. The train and test directories each contain two class folders. The manifest lists each copied image and its well. Keep whole wells on one side of the split when images from the same well share experimental conditions.", "focus": [190, 80, 3450, 1300], "hold_after": 0.7}, {"visual": "gui_18_source_folder_choice", "narration": "Return to Classify and choose the prepared folder as Source. Select the parent containing train and test. Keep that prepared folder for the rest of this lesson so the model and its output files stay together.", "focus": [1439, 390, 943, 1300], "hold_after": 0.7}, {"visual": "gui_19_setting_generate_training_dataset", "narration": "Turn Generate training dataset off because the helper has already prepared the split. Enable Train and Test. Leave application to the full dataset off for this first run. The model uses class indices zero and one for the two class folders.", "focus": [350, 190, 1730, 520], "hold_after": 0.7}, {"visual": "gui_19_setting_model_type", "narration": "Choose ResNet18, image size one hundred twenty-eight, all three RGB channels, batch size eight and one epoch. Set loader workers to two, with pretrained weights and augmentation off for this short example. Epochs controls how many times training passes through its input images.", "focus": [350, 190, 1730, 700], "hold_after": 0.7}, {"visual": "gui_19_setting_val_split", "narration": "Set validation fraction to one half, keep grouping by well and leave the leakage checks enabled. Validation monitors the model during training; the separate test folder is used for the final assessment. Check the reported well assignments before interpreting the scores.", "focus": [350, 190, 1730, 900], "hold_after": 0.7}, {"visual": "gui_19_setting_plot", "narration": "Turn Plot on, clear the settings search and press Run. Watch the console for dataset loading, the resolved split, training progress and output paths. Wait for training and testing to finish before opening the saved results.", "focus": [350, 190, 1730, 650], "hold_after": 0.7}, {"visual": "gui_24_batch_figure", "narration": "Open Figures to inspect loss and accuracy. One epoch gives a quick first pass. Compare the test results across classes before increasing training time. If predictions favour only one class, review the labels, class balance and input channels before using the model on a larger dataset.", "focus": [2090, 180, 1720, 1320], "hold_after": 0.7}, {"visual": "gui_23_batch_finished", "narration": "Open model, resnet18, rgb, epochs underscore one inside the prepared folder. Keep the checkpoint, model card and result tables together. Use the saved predictions to review errors, then continue to Classifier Evaluation or Activation Maps to inspect the model further.", "focus": [2090, 180, 1720, 1320], "related_lessons": ["39_classifier_evaluation", "28_training_runs", "16_activation"], "hold_after": 0.7}], "narration_voices": {"en": ["af_heart"]}, "poster": "10_classify_cv/poster.jpg", "silent": "10_classify_cv/video/10_classify_cv_silent.mp4"}, {"id": "11_classify_ml", "number": 11, "slug": "classify_ml", "title": "Classify: learn from measured features", "series": 1, "app_key": "ml_analyze", "host_app_key": "classify_merged", "section": "Core", "description": "Load measurements, define classes, train a tabular classifier and inspect object scores and plate summaries.", "objectives": ["Select the tabular family and a measured project.", "Define classes and choose feature channels, model size and held-out wells.", "Find model outputs, object predictions and summary figures."], "prerequisite": "Use Load test data in Classify and choose Load, then confirm the downloaded plate folder with Choose source data. For your own project, run Measure first. The example uses columnID values c1 and c2 as two classes; use labels appropriate to your experiment when working with your own data.", "scenes": [{"visual": "19_setting_classifier_family", "narration": "From Home, open Classify and choose Tabular Machine Learning. This family uses the object measurements saved by Measure. It produces a fitted model and a score for each object with the required measurements.", "focus": [350, 190, 1730, 650], "related_lessons": ["41_classify", "10_classify_cv"], "hold_after": 0.7}, {"visual": "02_data_choice_load", "narration": "Click Load test data and choose Load. Wait for the measured example to download. For your own data, select the project folder created by Measure, including its measurements database.", "focus": [1663, 914, 495, 365], "related_lessons": ["08_measure", "09_annotate"], "hold_after": 0.7}, {"visual": "18_source_folder_choice", "narration": "Use Choose source data to confirm the downloaded plate folder. Select the folder containing measurements. This gives the classifier access to the object tables and the metadata used to define classes.", "focus": [1439, 390, 943, 1300], "hold_after": 0.7}, {"visual": "19_setting_classes", "narration": "Choose metadata as the class basis and define two Classes using column I D values c1 and c2. These labels distinguish the two plate columns in the example. To train from your own cell annotations, choose the annotation basis and the label column you created in Annotate.", "focus": [350, 190, 1730, 1190], "hold_after": 0.7}, {"visual": "19_setting_channel_of_interest", "narration": "Set Channel of interest to one for the example. This controls which channel-specific measurement features enter the model. For your own experiment, select the channel that contains the signal relevant to your classes.", "focus": [350, 190, 1730, 820], "hold_after": 0.7}, {"visual": "19_setting_n_estimators", "narration": "Choose Random Forest, sixteen estimators and two worker jobs. Estimators controls the number of trees. More trees increase fitting work. Leave feature pruning and cross-validation off for this first pass; you can compare those choices after you have a working baseline.", "focus": [350, 190, 1730, 820], "hold_after": 0.7}, {"visual": "19_setting_test_size", "narration": "Set Test size to one tenth and keep grouping by well. spaCR holds out complete wells, so the final fraction of objects can differ from the requested fraction. Read the resolved split in the console and make sure it suits your experiment.", "focus": [350, 190, 1730, 820], "hold_after": 0.7}, {"visual": "19_setting_plot", "narration": "Enable Plot, clear the search and press Run. The console shows feature filtering, the training and test split, model fitting and the saved output paths. Wait for the run to finish before comparing its scores.", "focus": [350, 190, 1730, 1640], "hold_after": 0.7}, {"visual": "23_batch_finished", "narration": "Find the results under results, random_forest, channel underscore one. The database stores the predicted class in predictions and the class-one probability in ml_pred. Objects missing required measurements can remain unscored; inspect missing values when exporting a summary.", "focus": [2090, 950, 1720, 600], "hold_after": 0.7}, {"visual": "25_ml_figure_02", "narration": "Browse the feature-importance figures and plate heatmap. With Predictions and mean grouping, a well value is the average of its binary predicted classes. Use the saved object scores for detailed review, and compare held-out performance before applying the classifier to another experiment.", "focus": [2090, 190, 1720, 1200], "hold_after": 0.7}], "narration_voices": {"en": ["af_heart"]}, "poster": "11_classify_ml/poster.jpg", "silent": "11_classify_ml/video/11_classify_ml_silent.mp4"}, {"id": "12_map_barcodes", "number": 12, "slug": "map_barcodes", "title": "Map Barcodes: from sequencing reads to counts", "series": 1, "app_key": "map_barcodes", "section": "Core", "description": "Load paired reads and library references, find barcode positions, apply the settings and save guide counts.", "objectives": ["Download a small paired-read example and select matching reference tables.", "Inspect barcode positions and orientation before applying a proposal.", "Run mapping and inspect count and quality-control outputs."], "prerequisite": "Choose Load test data in Map Barcodes. The example uses SRR33531217 reads, the matching primers_3 column and row tables, and guide references. Use reference tables matching your own library when processing other reads.", "scenes": [{"visual": "gui_01_module", "hold_after": 0.7, "related_lessons": ["47_barcode_qc"], "narration": "From Home, open Map Barcodes. The inputs are sequencing reads and reference tables that name the barcodes in your library. The output counts each observed combination, ready for sequencing quality control and downstream analysis."}, {"visual": "gui_02_archive_bounded_choice", "hold_after": 0.7, "narration": "Click Load test data and select both mates of the first archive run. Limit each file to ten thousand reads for this example, then wait for the paired sample to download."}, {"visual": "gui_04_reference_tables", "hold_after": 0.7, "narration": "Select the matching column, row and guide reference tables. Each table pairs barcode names with sequences. Keep those names consistent with the plate layout and guide identifiers used by the rest of your analysis."}, {"visual": "gui_06_live_search_progress", "hold_after": 0.7, "narration": "Open Find barcodes and start the search. The preview samples both mates and checks barcode positions and orientations. Wait for the results before changing the main form."}, {"visual": "gui_07_search_verdicts", "hold_after": 0.7, "narration": "Compare Observed with By chance, then inspect the proposed orientation, offset and verdict for each barcode. Prefer positions supported by many reads and distinct expected references. Open the verdict explanation if the result is uncertain."}, {"visual": "gui_07b_guide_verdicts", "hold_after": 0.7, "focus": [1000, 1210, 2820, 640], "narration": "Inspect the guide results for both mates. In this example, read one supports the reverse-complemented guide sequence and read two supports the stored orientation. Use the results for your library and read pair when choosing an orientation."}, {"visual": "gui_07c_row_verdicts", "hold_after": 0.7, "focus": [1000, 1210, 2820, 640], "narration": "Check the row barcode as well. Here, read one supports its reverse complement and read two supports the stored sequence. Review column, guide and row together so the complete combination identifies the intended well and guide."}, {"visual": "gui_08_coloured_reads", "hold_after": 0.7, "narration": "Open the read viewer to inspect individual reads. Use the colour legend to find the column, guide, row and anchor segments. Check that the proposed positions agree with the expected library structure."}, {"visual": "gui_09_proposed_settings", "hold_after": 0.7, "narration": "Review the proposed extraction settings, then click Apply these settings to copy them into the form. The example uses an extraction window of eighty-nine bases. Check the updated fields before starting the run."}, {"visual": "gui_11_oriented_reference_copies", "hold_after": 0.7, "narration": "Follow the orientation notes when selecting your final reference files. For this example, select reverse-complemented copies of the row and guide references and keep the column reference as stored. Preserve every barcode name when preparing those copies."}, {"visual": "gui_20_batch_settings", "hold_after": 0.7, "narration": "Choose the downloaded read pair, two workers and chunks of one thousand reads. Enable annotated-read saving if you want to inspect individual assignments. Click Run; this mapping workflow uses the CPU."}, {"visual": "gui_23_batch_finished", "hold_after": 0.7, "narration": "When mapping finishes, inspect unique_combinations.csv and the quality-control outputs. The count table links column, row and guide names with read counts. Review unmatched and ambiguous assignments in Barcode QC, then pair these counts with phenotype scores in Regression."}], "example_files": ["SRR33531217_barcode_references.zip"], "narration_voices": {"en": ["af_heart"]}, "poster": "12_map_barcodes/poster.jpg", "silent": "12_map_barcodes/video/12_map_barcodes_silent.mp4"}, {"id": "13_regression", "number": 13, "slug": "regression", "title": "Regression: from paired tables to results", "series": 1, "app_key": "regression", "section": "Core", "description": "Pair phenotype scores with guide counts, choose an inference method, run the example and explore guide and gene results.", "objectives": ["Load paired score/count tables and choose an output folder.", "Set the inference method, reporting level and analysis unit.", "Run the example and inspect results with the accompanying diagnostics."], "prerequisite": "Open Regression and choose Load test data to obtain four paired score/count tables. Use a new output folder. A measurement database is optional for this score-and-count analysis; object-level views require the corresponding measured data and images.", "scenes": [{"visual": "01_module", "narration": "From Home, open Regression. This module relates phenotype scores to guide abundance. Start with a score table and a count table for each plate, then choose how to test and report associations.", "focus_buttons": "FoldButton", "hold_after": 0.7}, {"visual": "02_download", "narration": "In Input Tables, click Load test data and wait for the example to load. It provides four score tables and four count tables, paired by plate.", "hold_after": 0.7}, {"visual": "19_setting_paired_data", "narration": "Inspect each paired row and check the plate name, score file and count file. Leave the optional measurement-database column empty for this example. Choose a new output folder for the analysis.", "hold_after": 0.7}, {"visual": "19_setting_inference", "narration": "Switch to All settings and use the search box to find Inference. Choose nonparametric for this guide-permutation example. Use a parametric method when your question and design call for fitting predictors together.", "hold_after": 0.7}, {"visual": "19_setting_level", "narration": "Level chooses which results to report. Select both to obtain guide-level and gene-level results. Keep these testing families separate when reviewing adjusted significance.", "hold_after": 0.7}, {"visual": "19_setting_analysis_unit", "narration": "Choose well as the analysis unit for this example. Review the response column, transformations, controls and excluded wells. Adapt these settings to the design of your own screen before running new data.", "hold_after": 0.7}, {"visual": "19_setting_guide_min_wells", "narration": "Minimum guide support controls how many wells must contain a guide before it is tested. Set it to two to follow this small example. Choose an appropriate support requirement for your experiment.", "hold_after": 0.7}, {"visual": "19_setting_guide_permutations", "narration": "Set one hundred and ninety-nine permutations for a quick first run. More permutations give finer empirical p-value resolution and take longer. Choose a larger count when your final analysis requires it.", "hold_after": 0.7}, {"visual": "19_setting_guide_permutation_seed", "narration": "Set the permutation seed to zero to repeat the same randomization. Keep the example’s plate blocks and row and column nuisance terms. For your own data, choose blocks that respect which observations can be exchanged under the experimental design.", "hold_after": 0.7}, {"visual": "19_setting_annotation_source", "narration": "Choose none for Annotation source to run the example without gene-annotation lookup. For another screen, select annotations that match its organism and identifier system.", "hold_after": 0.7}, {"visual": "21_batch_running", "narration": "Clear the search, check the paired inputs and output folder, then click Run. Follow the console as the module aligns the tables, filters guides and calculates the results. Diagnostic figures are generated with the analysis.", "hold_after": 0.7}, {"visual": "25_result_runs", "narration": "When the run finishes, open Runs and select the saved analysis. Confirm the folder and settings before comparing it with another run. Rerun the analysis after changing settings if you want new results.", "hold_after": 0.7, "related_lessons": ["73_parameter_sweep"]}, {"visual": "25_result_results", "narration": "Open Results and use Level to switch between guide and gene results. Inspect the result table and interactive views. The saved results_grna.csv and results_gene.csv files contain the corresponding tables for further analysis.", "hold_after": 0.7}, {"visual": "26_detail_p_values", "narration": "Open the p-values view and the Diagnostics tool. Review the result distribution together with the permutation resolution, testing family and design warnings. Resolve important diagnostic concerns before interpreting associations.", "hold_after": 0.7, "related_lessons": ["75_regression_diagnostics"]}, {"visual": "26_detail_coefficients", "narration": "Use the toolbar to open Volcano Explorer, Hit List or Investigate Hit for the next step. Their tutorials show how to inspect selected results. Keep the input tables, saved settings, result files and diagnostic reports together when sharing the analysis.", "hold_after": 0.7, "related_lessons": ["06_api", "73_parameter_sweep"]}], "narration_voices": {"en": ["af_heart"]}, "poster": "13_regression/poster.jpg", "silent": "13_regression/video/13_regression_silent.mp4"}, {"id": "14_make_masks", "number": 14, "slug": "make_masks", "title": "Make Masks: edit labels and prepare training images", "series": 1, "app_key": "make_masks", "section": "Tools", "description": "Open image-mask pairs, inspect and edit objects, save measurements and create paired training crops.", "objectives": ["Open images with matching instance masks and inspect objects in the magnifier.", "Measure paired fields and save an object-feature database.", "Correct labels with Undo, drawing, division and size filters.", "Save curated masks and create image-mask crops for training."], "prerequisite": "Prepare a folder of two-dimensional images with matching instance-label TIFFs in a masks subfolder. Each mask uses the image filename stem. Work on a copy when practising edits and recropping. The example uses ER images and cell masks from Measure’s downloadable microscopy project.", "scenes": [{"visual": "01_module", "narration": "From Home, open Make Masks in Tools. Choose this editor to inspect and correct individual image masks. Open the folder of paired images and labels before choosing an editing tool.", "hold_after": 0.7, "related_lessons": ["07_mask"]}, {"visual": "02_folder_picker", "narration": "Select the image folder. For this example, use the ER intensity images and corresponding cell masks from the Measure sample. Keep the image and mask dimensions equal and their filenames paired.", "hold_after": 0.7, "related_lessons": ["08_measure"]}, {"visual": "03_real_labels", "narration": "The editor loads the image and its matching mask from the masks subfolder. Coloured labels identify individual objects. Check that the outlines follow the image boundaries. If a companion mask is missing, start with an empty mask and draw the objects you need.", "hold_after": 0.7}, {"visual": "readouts_04_otsu_magnifier_settings", "narration": "Open Magnifier settings. Select Otsu and Region under the mouse to preview threshold-based objects around the pointer. Choose a model-based mode when thresholding does not separate your objects well.", "hold_after": 0.7}, {"visual": "readouts_05_live_otsu_magnifier", "narration": "Turn on Magnifier and hover over an object to enlarge its preview. Move across several objects to inspect the proposed outlines. Click to add the outlined objects when they look correct, or switch Magnifier off to continue editing.", "hold_after": 0.7, "focus": [1370, 280, 2200, 1775]}, {"visual": "readouts_06_features_real_files", "narration": "Click Features to measure image-mask pairs. Add a row for each field and choose the intensity images and corresponding object masks. Check manual assignments if automatic filename matching leaves files unassigned.", "hold_after": 0.7, "focus": [650, 355, 2400, 1490], "related_lessons": ["08_measure"]}, {"visual": "readouts_08_features_choose_cell_mask", "narration": "For each row, select the ER intensity image in Channel 1 and its matching label image in Cell mask. Repeat for the second field. Use the original intensity images to measure fluorescence.", "hold_after": 0.7, "focus": [650, 355, 2400, 1490], "related_lessons": ["08_measure"]}, {"visual": "readouts_09_features_assigned_table", "narration": "Review both rows, then choose the measurement settings. This example uses one worker, a minimum cell size of one pixel and no saved PNG crops. Increase the size cutoff to exclude small objects when appropriate for your experiment. Click Measure.", "hold_after": 0.7, "focus": [650, 355, 2400, 1490], "related_lessons": ["08_measure"]}, {"visual": "readouts_12_features_measurements_saved", "narration": "When measurement finishes, open the output folder. The measurements folder contains measurements.db with the object features for both fields. Keep the database with its source images, masks and settings, then close Features to return to editing.", "hold_after": 0.7, "focus": [650, 355, 2400, 1490], "related_lessons": ["08_measure"]}, {"visual": "03_real_labels", "narration": "Choose the tool that matches the correction. Brush adds pixels, Erase removes pixels and Erase object removes a whole label. Draw adds an outlined object; Divide splits one. Zoom helps you inspect boundaries before making changes.", "hold_after": 0.7, "focus": [345, 195, 2500, 65]}, {"visual": "04_erase_one_object", "narration": "Choose Erase object and click inside the object you want to remove. Check the updated outline and object count. Use this for an unwanted label, such as debris or an object outside your analysis criteria.", "hold_after": 0.7}, {"visual": "06_redo", "narration": "Click Undo to restore the deletion. Redo applies it again. Use these history controls to compare an edit with the previous mask, then return to the version you want to keep.", "hold_after": 0.7}, {"visual": "07_draw_demo_not_annotation", "narration": "Select Draw and trace a closed boundary around a missing object. The editor fills it with a new label. In this practice step the outline is in the background, so undo it before saving. For training data, trace the actual object boundary.", "hold_after": 0.7}, {"visual": "08_divide_demo", "narration": "Use Divide when two touching objects share one label. Draw a cut across the whole joined region and inspect the separated labels. Undo the split if it cuts through one object or leaves an incorrect boundary.", "hold_after": 0.7}, {"visual": "08b_contrast_only", "narration": "Adjust Display percentiles to make dim structures easier to inspect. These controls change the image view while preserving raw intensity values and labels. Return to a consistent display when comparing fields.", "hold_after": 0.7}, {"visual": "08c_filter_edits_labels", "narration": "Set the minimum and maximum object areas, then press Filter to remove labels outside those bounds. Choose bounds that fit your objects and inspect what was removed. The filter edits the mask, so use Undo if the cutoff removes useful objects.", "hold_after": 0.7}, {"visual": "11_saved_restored_mask", "narration": "After reviewing the edits, click Save mask. Reset size bounds to zero to disable them before moving to another field if needed. Preserve the source images and keep the saved curation record with the edited masks.", "hold_after": 0.7}, {"visual": "09_fold_train_cellpose", "narration": "Use the header tools for the next step. Train Cellpose learns from your curated image-mask pairs; Mask the whole folder applies a model to a folder of images. Follow the linked tutorial for the workflow you need.", "hold_after": 0.7, "focus_buttons": "FoldButton", "related_lessons": ["19_train_cellpose", "20_cellpose_masks"]}, {"visual": "09_fold_napari_bridge", "narration": "The header also opens Model Compare, Model Zoo, Curate and Open in napari. Use Model Compare to inspect masks side by side, Model Zoo to choose weights, and the curation tools to review or edit more examples.", "hold_after": 0.7, "focus_buttons": "FoldButton", "related_lessons": ["21_model_compare", "22_model_zoo", "42_curate", "46_napari_bridge"]}, {"visual": "12_recrop_written", "narration": "Choose Recrop and drag a box around the objects you want in a smaller training field. This writes a new image and matching mask. Objects cut by the boundary are dropped, so leave space around complete objects and inspect the crop.", "hold_after": 0.7}, {"visual": "13_child_and_recovery_archive", "narration": "Click Next to open the new crop. The parent image and mask are retained in recropped_originals for recovery. Review the crop and its labels before adding it to your training dataset.", "hold_after": 0.7, "related_lessons": ["09_annotate"]}, {"visual": "14_cellpose_settings", "narration": "To detect objects in the current field, select the Cellpose model and review its settings. This example uses cpsam, normalization on, cell-probability threshold zero and flow threshold zero point four. Check whether detections will replace existing labels or be added to them.", "hold_after": 0.7}, {"visual": "15_cellpose_detected", "narration": "Click Object detection and compare the resulting outlines with the image. Here the model selects the partial object at the upper left instead of the central cell. Undo that replacement and adjust the model settings before trying again.", "hold_after": 0.7}, {"visual": "16_cell_probability", "narration": "Open Cell probability to inspect the foreground score map. Use it to see which regions the model supports. Change the foreground threshold when useful, then run detection again to produce a new result.", "hold_after": 0.7}, {"visual": "17_flows", "narration": "Open Flows to inspect the directional view. The flow-consistency threshold controls which detected objects are retained: lower values are stricter, and zero disables this check. Compare the final masks after each setting change.", "hold_after": 0.7}, {"visual": "19_detection_undone", "narration": "Undo restores the labels from before the detection. Keep the mask that best follows the image, then save it. Continue through the remaining fields and inspect each result before including it in training.", "hold_after": 0.7}, {"visual": "19_detection_undone", "narration": "Keep curated images and same-stem masks together. Use Train Cellpose to learn from those pairs, or return to Features or Measure to extract measurements. The related tutorials show each next step.", "hold_after": 0.7, "related_lessons": ["06_api", "19_train_cellpose"]}], "narration_voices": {"en": ["af_heart"]}, "poster": "14_make_masks/poster.jpg", "silent": "14_make_masks/video/14_make_masks_silent.mp4"}, {"id": "15_image_umap", "number": 15, "slug": "image_umap", "title": "Image UMAP: explore measurements with image crops", "series": 1, "app_key": "umap", "section": "Tools", "description": "Select measurement tables, build a UMAP embedding and click points to inspect the corresponding objects.", "objectives": ["Load a measured project and choose its feature tables.", "Control neighbourhood size, point spacing and the sampled row count.", "Run the embedding, inspect crops and find saved results."], "prerequisite": "Follow Annotate and choose Load test data, then Load, to obtain the measured example and its image crops. Keep the downloaded plate folder. For your own data, complete Measure with saved crops before opening Image UMAP.", "scenes": [{"visual": "01_module", "narration": "From Home, open Image UMAP. Use it to explore similarities between measured objects while viewing their image crops. Start with a project containing a measurements database and the crops saved by Measure.", "hold_after": 0.7}, {"visual": "19_setting_src", "narration": "Under Source, choose Add project folders and select the example plate folder downloaded through Annotate. Review the available databases, rows and shared columns. You can add more project folders when you want to compare several datasets.", "related_lessons": ["09_annotate", "08_measure"], "hold_after": 0.7}, {"visual": "19_setting_tables", "narration": "Choose the tables whose features you want to compare. For this example, select cell, cytoplasm, nucleus and pathogen measurements. Leave Resnet features off to use the existing measurements. Review missing-data and correlated-feature settings before running.", "hold_after": 0.7}, {"visual": "19_setting_row_limit", "narration": "Set Row limit to four hundred for a quick first view and use two workers. Row limit controls how many objects enter the embedding. Increase it when you are ready to explore more of the dataset.", "hold_after": 0.7}, {"visual": "19_setting_reduction_method", "narration": "Choose UMAP as the reduction method. Each point will represent an object using two plotted coordinates. You can explore PCA through its linked tool when you want a linear projection and feature loadings.", "hold_after": 0.7}, {"visual": "19_setting_n_neighbors", "narration": "Set Neighbours to fifteen and Minimum distance to zero point one. Neighbours controls the size of the neighbourhood used to build the map. Minimum distance controls how closely points can pack in the displayed embedding.", "hold_after": 0.7}, {"visual": "19_setting_random_seed", "narration": "Set Random seed to forty-two so repeated runs with the same inputs and settings are easier to compare. Save your chosen feature tables and preprocessing settings alongside the seed.", "hold_after": 0.7}, {"visual": "19_setting_clustering", "narration": "Clustering assigns labels to groups after the embedding is built. This example uses DBSCAN with noise removal off. Inspect the crops within any group before using its label in a later analysis.", "hold_after": 0.7}, {"visual": "19_setting_plot_images", "narration": "Enable Plot images and Plot points. Use twelve small crop images so the overview remains readable. You can inspect individual objects more closely in the interactive view after fitting.", "hold_after": 0.7}, {"visual": "23_batch_finished", "narration": "Press Run and watch the console for feature preparation and embedding progress. Wait for the completed result. If you change the input tables or reduction settings, run again to produce a new map.", "hold_after": 0.7}, {"visual": "24_batch_figure", "narration": "Inspect the embedding in Figures and open the results folder reported in the console. Keep the saved figure, selected measurement rows, metadata and cluster labels together so you can trace an interesting group back to its objects.", "hold_after": 0.7}, {"visual": "25_interactive_embedding", "narration": "Enable Interactive to explore the fitted map. Zoom into a region and click its points. The view uses the completed embedding, so you can inspect different objects without fitting it again.", "hold_after": 0.7}, {"visual": "26_point_0", "narration": "Click a point to show its crop in the side panel. Use the displayed object path to connect the image to its source record. Compare morphology across nearby points and across distant regions of the map.", "hold_after": 0.7}, {"visual": "26_point_200", "narration": "Click another point to compare its crop. The sidebar also provides selection labelling and cluster-label propagation. Those controls save annotations, so choose the intended label and selection before applying them.", "hold_after": 0.7}, {"visual": "27_fold_image_scatter", "narration": "Open Image Scatter from the Image UMAP header to compare selected features directly, or open PCA for a linear projection. Continue with the linked tutorials for their input settings and saved outputs.", "focus_buttons": "FoldButton", "related_lessons": ["55_image_scatter", "60_pca"], "hold_after": 0.7}], "narration_voices": {"en": ["af_heart"]}, "poster": "15_image_umap/poster.jpg", "silent": "15_image_umap/video/15_image_umap_silent.mp4"}, {"id": "16_activation", "number": 16, "slug": "activation", "title": "Activation Maps: inspect an image classifier’s saliency maps", "series": 1, "app_key": "activation", "host_app_key": "classify_merged", "section": "Classify", "description": "Select a trained classifier and matching image crops, compare channel and image saliency, and open the saved maps.", "objectives": ["Match the crop archive, model and preprocessing settings.", "Run channel saliency with an image overlay.", "Compare image saliency and locate the saved grids."], "prerequisite": "Use a trained image-classification checkpoint and a TAR archive of compatible image crops. Retain the crop-format marker when present and follow the model card’s channel order, image size and normalization. The example uses four RGB crops from Annotate and a ResNet18 model from Classify. Train or obtain a model whose preprocessing is known before starting.", "scenes": [{"visual": "02_activation_fold", "narration": "From Home, open Classify, then Activation Maps. This tool shows where a trained image classifier’s prediction is sensitive to the input pixels. Start with the model and an archive of crops prepared in the same way as its training data.", "related_lessons": ["09_annotate", "70_explain_cv"], "hold_after": 0.7}, {"visual": "03_00_dataset", "narration": "Select the crop archive in Dataset. This example contains four RGB cell crops from Annotate. Include the crop-format marker when packaging the images, and keep their filenames so you can connect each map to its original object.", "hold_after": 0.7}, {"visual": "03_03_image_size", "narration": "Select the trained model and choose its model type. Here the model is ResNet eighteen. Read its model card and set Image size to one hundred and twenty-eight to match the training input.", "hold_after": 0.7}, {"visual": "03_05_channels", "narration": "Set Channels to the order expected by the model. In this example the selector uses one, two and three for the RGB input. Preserve that order when comparing maps from different images.", "hold_after": 0.7}, {"visual": "03_06_normalize_input", "narration": "Set Normalize input to match training. The separate display normalization controls how the image appears in the saved overlay. Keep both settings consistent when comparing runs.", "hold_after": 0.7}, {"visual": "04_channel_saliency_method_and_overlay", "narration": "Choose saliency channel and enable Overlay, Plot and Save. This produces separate channel maps over the images. For the four-crop example, use a batch size of four and one worker, then click Run.", "hold_after": 0.7}, {"visual": "04_channel_saliency_finished_console", "narration": "Follow the console until processing finishes. If the Figures panel is empty, open the output folder and inspect the saved batch grids. Check error messages and the saved results before continuing.", "hold_after": 0.7}, {"visual": "04_channel_saliency_09_saved_batch_0_grid", "narration": "Open batch_0_grid.png from the method’s batch_grids folder. Match each occupied slot with its source crop; unused slots may be blank. The corner labels are model predictions. Compare salient regions with the original image and known object boundaries.", "hold_after": 0.7}, {"visual": "05_image_saliency_method_and_overlay", "narration": "To compare a combined map, select saliency image and turn Overlay off. Run the same images again with the same preprocessing. Keep the two methods’ outputs in their respective folders.", "hold_after": 0.7}, {"visual": "05_image_saliency_09_saved_batch_0_grid", "narration": "Open the second saved grid. Image saliency combines the channel sensitivities into one map for each crop. Compare the highlighted regions with the channel maps. The displayed colours indicate the map scale; interpreting them requires checking the model and image context.", "hold_after": 0.7}, {"visual": "03_11_correlation", "narration": "Leave Correlation off for this first walkthrough. Review examples from different classes, including prediction errors, before interpreting patterns. Use Classifier Evaluation to assess performance on independently held-out data.", "related_lessons": ["39_classifier_evaluation", "70_explain_cv"], "hold_after": 0.7}, {"visual": "05_image_saliency_11_back_to_actual_gui", "narration": "Keep the input archive, model and model card, settings, maps and output database together. Return to the original crops to investigate unexpected regions, or compare another method using the same inputs.", "related_lessons": ["06_api"], "hold_after": 0.7}], "narration_voices": {"en": ["af_heart"]}, "poster": "16_activation/poster.jpg", "silent": "16_activation/video/16_activation_silent.mp4"}, {"id": "17_timelapse", "number": 17, "slug": "timelapse", "title": "Timelapse", "series": 2, "app_key": "timelapse", "section": "Core", "host_app_key": "mask", "description": "Use the nested Mask workflow, run a synthetic eight-frame demo and compare real cached-mask linking through the current Track preview.", "objectives": ["Find Timelapse under Mask and preserve the time axis and original images.", "Compare baseline, excessive-overlap and explicitly re-linked restored tracks on the same masks.", "Distinguish tracking indicators, playback speed, model inference and measured biological motion."], "example_files": ["SYNTHETIC_timelapse_preview.zip"], "prerequisite": "Use Help > Demos > Timelapse demo in a new folder. The generated data are synthetic: eight 256-by-256 timepoints, nucleus channel 0 and cell channel 1. They are not an acquired experiment or a segmentation-accuracy benchmark. The recording uses the current Mask > Time fold, Plot and Keep original images on, IoU tracking of cells, frame slice [0, 8] and displacement 50. All sixteen generated TIFFs survive byte-identically in orig; older tutorial inputs remain unchanged. The actual run writes eight merged arrays, five displayed figures, four eight-frame MP4 files and 128 cell-table rows for sixteen eight-frame tracks. Independent checks cover every saved centroid and mask membership. The companion ZIP contains only exact exported cell intensity and cell label planes, a manifest and teaching instructions; it is not a second acquired dataset. Its grayscale preview channel is 0, whereas the original cell channel was 1. Choose image_sequences/field_A01 and label_sequences/field_A01 separately, with one displayed field and eight frames. IoU 0.1 gives sixteen complete tracks; 1.0 gives 128 single-frame tracks. Restore 0.1, wait until idle, then explicitly click Re-link: typing can trigger an intermediate-value pass. Actual worker signals confirm the final requested value and no segmentation during this loaded-mask exercise. The IoU threshold is not propagated to the batch form. The normal font preference (1.0) keeps preview controls readable; the larger 1.5 setting clipped them in this layout. The build reports inherited flow-threshold, relationships-table and settings-status warnings; those are disclosed, not suppressed. Its measurement database has count/status tables, not measured object relationships. Figure intensities are display-normalized, not raw pixel values. This is bounded tutorial validation, not release certification, physical velocity calibration, native-language listening approval or biological validation. API entry point: spacr.core.preprocess_generate_masks; tracking implementations: spacr.timelapse. spaCR AI was kept off and no provider request was sent.", "scenes": [{"visual": "02_timelapse_fold", "narration": "Open Mask and enable its Time switch. Timelapse is now nested inside Mask, not a separate Home tile. It adds time-axis and tracking settings to the segmentation workflow. Motility measurements belong to Measure, which is a later step.", "hold_after": 0.7, "focus": [3535, 1905, 280, 85], "related_lessons": ["07_mask", "18_motility"]}, {"visual": "03_actual_demo_menu", "narration": "Choose Help, Demos, then Timelapse demo, and select a new folder. This creates eight synthetic frames with drifting objects and loads their settings. These are teaching images, not a biological experiment or evidence of segmentation accuracy.", "hold_after": 0.7, "focus": [70, 20, 535, 230]}, {"visual": "05_demo_loaded", "narration": "Check the populated source and channels. This demo has nucleus intensity in channel zero and cell intensity in channel one, with no pathogen channel. Its filenames encode time separately from field and channel. Do not substitute the ordinary static test plate for a time series.", "hold_after": 0.7, "focus": [235, 175, 1185, 470]}, {"visual": "05_setting_timelapse_frame_limits", "narration": "Frame limits are zero-based slice boundaries: zero to eight includes all eight frames, while the end is excluded. Keep a single field's timepoints together. A playback rate cannot supply a missing acquisition interval, and this demo does not establish velocities in physical units.", "hold_after": 0.7, "focus": [235, 1225, 1185, 300]}, {"visual": "05_setting_timelapse_mode", "narration": "Track cells with the overlap-based mode, labelled iou. It links masks by intersection over union between adjacent frames. The other backends have different assumptions and optional dependencies. A displacement setting is not an overlap threshold; use controls that the chosen backend actually reads.", "hold_after": 0.7, "focus": [235, 1500, 1185, 490]}, {"visual": "05_setting_keep_original_images", "narration": "Turn Keep original images on before Run. The pipeline can otherwise remove its intermediate and original-image folders during cleanup. This recording keeps all sixteen generated TIFFs unchanged, and never touches the older tutorial data. Always keep a separate backup of an acquired experiment.", "hold_after": 0.7, "focus": [235, 1140, 1185, 300]}, {"visual": "05_setting_plot", "narration": "Turn Plot on and run this small example. The current pipeline processes the complete eight-frame sequence together even if the requested batch size is smaller. Watch the console and resource monitor; more frames, larger images and additional objects can require much more memory.", "hold_after": 0.7, "focus": [235, 1070, 1185, 230]}, {"visual": "08_actual_figure_04", "narration": "The run produces five figures and eight merged arrays. In this normalized display, the first two planes are intensities; the last two are cell and nucleus labels, not extra acquisition channels. The saved cell table contains sixteen tracks, each spanning eight frames.", "hold_after": 0.7, "focus": [1440, 140, 2370, 355]}, {"visual": "07_actual_finished", "narration": "Read the warnings as well as Finished. This build warns about inherited flow-threshold values and an unavailable relationships table, and shows a settings-status warning. We verified the saved masks and tracks separately; this is not a clean release test or a substitute for running Measure.", "hold_after": 0.7, "focus": [1440, 500, 2370, 1260]}, {"visual": "09_actual_track_preview", "narration": "Open Track preview. For a reproducible linking exercise, download and extract the synthetic preview archive linked below. It contains exact cell-image and cell-mask planes from this recorded batch. Loading those masks tests linking without running another segmentation model.", "hold_after": 0.7, "focus": [1440, 755, 2370, 1150]}, {"visual": "10_actual_image_sequence_folder", "narration": "Choose the image-sequence folder for field A zero one. These exported images contain only the original cell-intensity plane, so choose channel zero here. Keep image and label sequences under separate parent folders, and set Frames previewed to eight and Fields to one.", "hold_after": 0.7}, {"visual": "11_actual_mask_sequence_folder", "narration": "Choose the corresponding label-sequence folder using Masks. These are computed masks, not ground truth. Leave Keep only full-length tracks off and do not click Propagate settings. The model controls do not create new masks when an existing mask sequence is being read.", "hold_after": 0.7}, {"visual": "12_actual_linked_preview", "narration": "Run preview with the overlap threshold at zero point one. It reports sixteen tracks of eight frames, with no short tracks in this example. The fragmentation and jump values are indicators computed without ground truth; small values alone do not prove that identities are biologically correct.", "hold_after": 0.7, "focus": [1440, 755, 2370, 800]}, {"visual": "13_actual_strict_overlap", "narration": "Raise the overlap threshold to one. Requiring exact overlap breaks this moving example into one hundred twenty-eight one-frame tracks. The images and masks are unchanged; only the links change. This deliberately excessive value demonstrates fragmentation, not a recommended analysis setting.", "hold_after": 0.7, "focus": [1440, 755, 2370, 800]}, {"visual": "14_actual_overlap_restored", "narration": "Restore zero point one, wait for the current preview to finish, then click Re-link. Typing can start a pass for an intermediate value, so confirm the final pass explicitly. The sixteen complete tracks return. Do not click Propagate settings: the overlap threshold is not transferred to the batch form.", "hold_after": 0.7, "focus": [1440, 755, 2370, 1150]}, {"visual": "15_actual_final_frame", "narration": "Scrub to frame eight to inspect the linked objects. Playback speed only changes viewing speed, not the acquisition time. Continue to Measure and Motility for measurements using a validated interval and scale. The API and spaCR AI can help explain settings, but neither replaces checking images, tracks and warnings.", "hold_after": 0.7, "focus": [1440, 1250, 2370, 320], "related_lessons": ["08_measure", "18_motility", "06_api"]}], "poster": "17_timelapse/poster.jpg", "silent": "17_timelapse/video/17_timelapse_silent.mp4"}, {"id": "18_motility", "number": 18, "slug": "motility", "title": "Motility assay", "series": 2, "app_key": "motility", "section": "Core", "host_app_key": "measure", "description": "Measure movement from tracked objects, inspect track filters, and save per-frame and per-well results.", "objectives": ["Load a project containing tracked merged arrays.", "Choose mask planes, track filters and acquisition units.", "Run the analysis and find the movement tables and plots."], "example_files": ["SYNTHETIC_motility_tracks.zip"], "prerequisite": "Complete a Timelapse run, or download and extract SYNTHETIC_motility_tracks.zip. Select the folder containing merged. The example has eight frames, nucleus intensity in channel 0, cell intensity in channel 1, tracked cell masks in plane 2 and nucleus masks in plane 3. It has no pathogen mask or physical calibration.", "scenes": [{"visual": "01_measure_host", "narration": "From Home, open Measure, then use Time to open Motility Assay. Start with tracked images from Timelapse, or download the example archive below to follow along.", "related_lessons": ["08_measure", "17_timelapse"], "hold_after": 0.7}, {"visual": "03_actual_setting_src", "narration": "Extract the example and set Source to the folder containing merged. Choose cells as the tracked objects, nucleus channel zero and cell channel one. Leave the pathogen channel unset for this example.", "hold_after": 0.7}, {"visual": "07_actual_preview", "narration": "Turn on Live to open Motility preview and choose the same project folder. Use the preview to inspect tracks and try filters before running the full analysis. Keep Propagate settings off while exploring temporary choices.", "hold_after": 0.7}, {"visual": "09_actual_plane_and_unit_settings", "narration": "Set two intensity channels, tracked mask plane two, and pathogen mask plane minus one, meaning none. Preview all eight frames. In the preview, set both calibration values to zero for this uncalibrated example, then click Run preview.", "hold_after": 0.7}, {"visual": "10_actual_uncalibrated_preview", "narration": "At minimum track length three, the example has sixteen usable tracks. Review the trajectories, length distribution and speed summary. Speed is about one point four pixels per frame because the example has no acquisition scale or interval.", "hold_after": 0.7}, {"visual": "12_actual_length_restored", "narration": "Min track length sets how many frames an object must span to enter the summary. Increase it to exclude brief tracks, and watch the retained count. Keep it at three for this eight-frame example.", "hold_after": 0.7}, {"visual": "13_actual_straightness_filter", "narration": "Drop over-straight tracks excludes tracks above the chosen straightness threshold. Straightness is net displacement divided by total path length. Compare the retained tracks and plots before choosing a threshold; leave this filter off when straight movement is part of your experiment.", "hold_after": 0.7}, {"visual": "16_actual_hypothetical_calibration", "narration": "For acquired data, enter pixels per micrometre and seconds per frame from your microscope and acquisition metadata. With both values, the preview can express speed in micrometres per minute. To try the conversion on this teaching example, two pixels per micrometre and sixty seconds per frame change the mean to about zero point seven. Those are example values, not measured calibration.", "hold_after": 0.7}, {"visual": "03_actual_setting_pixels_per_um", "narration": "Set the full analysis form’s pixel scale and frame interval as well; preview edits are separate until you propagate them. Check the chosen object, channels and filters before starting the run. Keep the acquisition values with your results.", "hold_after": 0.7}, {"visual": "03_actual_setting_infection_intensity_qc_graphs", "narration": "Leave Reuse existing measurements off for the first run and enable the quality-control graphs. With no pathogen channel, leave infection quality control disabled. Click Run and follow progress in the console.", "hold_after": 0.7}, {"visual": "05_actual_finished", "narration": "When the run finishes, open measurements, then measurements.db in the project folder. The selected table contains per-frame observations; its well_motility companion summarizes movement by well. Inspect the saved plots and their units before comparing conditions or exporting figures.", "hold_after": 0.7}], "narration_voices": {"en": ["af_heart"]}, "poster": "18_motility/poster.jpg", "silent": "18_motility/video/18_motility_silent.mp4"}, {"id": "19_train_cellpose", "number": 19, "slug": "train_cellpose", "series": 3, "app_key": "train_cellpose", "host_app_key": "make_masks", "section": "Tools", "title": "Train Cellpose: verified pairs and an explicit API workaround", "description": "Find Train inside the Cellpose Workbench, recognise the current source-import defect, and follow a real two-epoch Python training demonstration using six downloadable cell-image/mask pairs.", "objectives": ["Find Train and Apply within Make Masks rather than looking for separate Home tiles.", "Check matching cell-image/mask filenames and distinguish existing labels from reviewed ground truth.", "Recognise partial settings import and keep the explicit API route separate from the broken GUI route.", "Inspect actual training inputs, warm-up rates, changed weights and the verified checkpoint path.", "Distinguish training loss, placeholder test slots and checkpoint deserialization from independent model accuracy."], "example_files": ["Train_Cellpose_API_example.zip"], "prerequisite": "Use the linked six-pair bundle with the recorded helper and source manifest. The corrected examples preserve cell intensity channel 1 and cell mask plane 4 from real downloaded fields; plane 6 is pathogen. Existing labels and edge-cut instances are NOT independently reviewed ground truth. The native Train CSV import still drops required src and keeps model_name=new_model, although numerical controls import. No GUI training starts. The explicit spacr.submodules.train_cellpose call uses a new private destination, two epochs, minibatch 1, learning_rate=1e-5, weight_decay=1e-5, target_size=512 and no extra spaCR augmentations. normalize=False disables spaCR percentile preprocessing, not maximum scaling or Cellpose's internal normalisation. Cellpose still rotates/resizes and uses internal 256-pixel patches. Seed 19 is set at entry; internal randomisation remains. CUDA is bounded to 65 percent on the recorded RTX 3090, with a 100 GiB system-RAM guard appropriate only to this workstation. All 3,145,728 image/label values and twelve preview arrays were checked. All six pairs remained in training. Actual warm-up rates were 0 and 1.1111111111111112e-6; 345 of 347 trainable parameter tensors changed. Loss rose from 1.496740683913231 to 1.5215517828861873. No test data were supplied; zero test-loss slots are placeholders. The checkpoint under models/cellpose_model/models was read with weights_only=True; the generic console path omits the second models directory. Deserialization is not inference or accuracy validation. The real figure is shown in an external viewer, never inserted into GUI Figures. Original data, previous failed captures and the old GUI hold are preserved. No AI request, provider response, scientific approval or publication.", "scenes": [{"visual": "gui_01_make_masks_host", "narration": "Open Make Masks, then its nested Cellpose Workbench. Train and Apply are tabs inside that workbench, not separate Home tiles. This lesson shows the current route, a settings-import problem and an explicit Python workaround. The linked Make Masks lesson covers inspecting and editing masks before any training.", "related_lessons": ["14_make_masks", "20_cellpose_masks"], "hold_after": 0.7}, {"visual": "gui_02_actual_train_tab", "narration": "On Train, inspect the starting point and training schedule. Do not copy the initial epoch count or learning rate as a recommendation. Training needs matching images and instance masks, plus a source folder and an output name. Merely seeing a form does not mean those requirements are satisfied.", "hold_after": 0.7}, {"visual": "gui_02a_real_settings_import_picker", "narration": "The real Import settings picker opens a CSV with our bounded example settings. After import, two epochs, minibatch one and the small learning rate appear. However, the required source is dropped and the requested model name stays new model. This is a partial import, not a ready configuration; do not press Run.", "hold_after": 0.7}, {"visual": "gui_02b_actual_imported_values", "narration": "The Python route below is separate from this GUI defect. It does not secretly set a hidden source or repair the form. Use the linked example bundle in a fresh folder. Its helper refuses an existing destination, preserves the original pairs, and records exactly which API implementation and inputs were used.", "related_lessons": ["06_api"], "hold_after": 0.7}, {"visual": "command_01_verified_cell_pairs", "narration": "There are six real, five-hundred-and-twelve-pixel image and mask pairs with matching filenames. Original settings identify cell intensity as channel one and cell masks as plane four; plane six is pathogen. These existing labels are not independently reviewed ground truth. Check boundaries and edge-cut objects before using any such labels for production training.", "focus": [190, 80, 3450, 900], "hold_after": 0.7}, {"visual": "gui_09_saved_actual_training_pairs", "narration": "This is the actual six-pair figure saved by the API run and opened in an external viewer, not inserted into spaCR. Each top image corresponds to the mask directly below it. We checked all input image and label values and these twelve displayed arrays against the source pairs. That verifies correspondence, not annotation quality.", "focus": [560, 610, 2750, 970], "hold_after": 0.7}, {"visual": "command_02_actual_two_epoch_api", "narration": "Run the helper with its data source and a new destination. This bounded CUDA example uses all six pairs, two epochs and minibatch one. The input target is five hundred twelve pixels; Cellpose internally trains on two-hundred-and-fifty-six-pixel patches. Disabling spaCR's extra augmentations does not disable Cellpose's own normalisation, rotation and resizing.", "focus": [190, 80, 3450, 1150], "hold_after": 0.7}, {"visual": "command_03_actual_checkpoint_checks", "narration": "The first warm-up epoch has zero learning rate. The second uses a small positive rate, allowing actual weight updates. We compared the saved checkpoint with the initial trainable weights: three hundred forty-five of three hundred forty-seven parameter tensors changed. A changed diameter setting alone would not pass that check. Changed weights still do not establish a good model.", "focus": [190, 80, 3450, 950], "hold_after": 0.7}, {"visual": "command_03_actual_checkpoint_checks", "narration": "Training loss rose slightly, from about one point four nine seven to one point five two two. No test set was supplied. The zero test-loss slots are placeholders, not perfect test performance. This is a short mechanics demonstration, not convergence, improved segmentation or held-out accuracy. Keep an independent evaluation separate from training.", "focus": [190, 80, 3450, 950], "hold_after": 0.7}, {"visual": "command_03_actual_checkpoint_checks", "narration": "Use the checkpoint path in the verified checks file. It includes a second models directory that the generic console summary omits. Keep the checkpoint with its settings, source manifest and checks. Loading its tensors safely verifies a readable checkpoint, not an inference result; the downloadable bundle contains the pairs and helper, not a certified model.", "focus": [190, 80, 3450, 950], "hold_after": 0.7}, {"visual": "gui_12_actual_apply_tab_no_inference", "narration": "Apply has a separate source folder, custom-model field and live preview. Opening this tab does not select our external checkpoint or run inference. Follow its linked lesson before applying a model, and validate on independent images. The optional spaCR AI console control is unused here: no question or provider response substitutes for inspecting the real evidence.", "related_lessons": ["20_cellpose_masks", "14_make_masks", "06_api"], "hold_after": 0.7}], "poster": "19_train_cellpose/poster.jpg", "silent": "19_train_cellpose/video/19_train_cellpose_silent.mp4"}, {"id": "20_cellpose_masks", "number": 20, "slug": "cellpose_masks", "series": 3, "app_key": "cellpose_masks", "host_app_key": "make_masks", "section": "Tools", "title": "Apply Cellpose: segment a folder and inspect masks", "description": "Choose a segmentation model, process the supplied images and inspect saved masks and live size filters.", "objectives": ["Select images, model weights and segmentation settings.", "Run Apply and locate the saved mask TIFFs.", "Inspect live results and compare object-size filters."], "example_files": ["Apply_Cellpose_stock_example.zip"], "prerequisite": "Extract the linked Apply Cellpose example into a new folder. It contains three single-channel cell images and a settings reference. Select its images folder as Source. This walkthrough uses the stock cpsam model; for a custom model, choose compatible weights and settings for your images.", "scenes": [{"visual": "02_actual_train_and_apply_tabs", "narration": "From Home, open Make Masks, then its Cellpose Workbench. Choose Apply to segment images with an existing model. Use Train when you want to learn new weights from curated image-mask pairs.", "related_lessons": ["14_make_masks", "19_train_cellpose"], "hold_after": 0.7}, {"visual": "04_setting_src", "narration": "Extract the linked example and set Source to its images folder. It contains three single-channel cell images, each five hundred and twelve pixels square. If you use the recorded settings file as a reference, replace its source path with your extracted folder.", "hold_after": 0.7}, {"visual": "05_setting_model_name", "narration": "Select cpsam and leave Custom model empty for this example. Set Channels to zero, normalization percentiles to two and ninety-nine, Diameter to thirty, Flow threshold to zero point four and Cell probability to zero. Adjust these settings after inspecting a few representative fields from your own experiment.", "hold_after": 0.7}, {"visual": "14_actual_inference_outcome", "narration": "Enable Save and Verbose, choose a batch size of one, and click Run in Apply. Follow the console as each image is processed. Review failures before proceeding to measurement.", "hold_after": 0.7}, {"visual": "15_actual_mask_and_flow_figures", "narration": "Open the masks subfolder inside Source. Each image has a same-stem mask TIFF. Inspect the figures beside the original images, paying attention to missed objects and joined cells. The flow panel shows model directions used for segmentation.", "focus": [1000, 450, 2780, 640], "hold_after": 0.7}, {"visual": "17_actual_preview_image_picker", "narration": "Turn on Live preview and choose an image with the image picker. Open Live settings and check the channel and normalization controls. Collapse Console and System to give the preview more room if needed.", "hold_after": 0.7}, {"visual": "20_actual_preview_result", "narration": "Compare the preview with the saved batch mask. Preview and Apply use different processing paths in this example, so they can produce different boundaries and counts. Review the saved TIFFs when deciding whether the batch outputs are suitable for measurement.", "focus": [1000, 1160, 2780, 610], "hold_after": 0.7}, {"visual": "20a_actual_zoomed_preview", "narration": "Use the mouse wheel to enlarge an area on both preview canvases. Inspect touching objects and dim boundaries, then zoom back out to check the complete field.", "focus": [1010, 1280, 2750, 455], "hold_after": 0.7}, {"visual": "22_native_filter_reduces_objects", "narration": "Open Live settings and increase Minimum cell area to remove small objects from the preview. The cutoff is in pixels; choose it according to your object sizes. Close the dialog to inspect the filtered result.", "hold_after": 0.7}, {"visual": "22b_actual_zoomed_filtered_preview", "narration": "Compare the filtered outlines with the original image. Changing this live filter updates the preview without rewriting masks already saved by Apply. Rerun the batch with the intended settings when you need new saved outputs.", "focus": [1010, 1280, 2750, 455], "hold_after": 0.7}, {"visual": "23b_actual_zoomed_restored_preview", "narration": "Return Minimum cell area to zero to restore the unfiltered preview. Keep the input images, model identity, settings and saved masks together. Use Make Masks for corrections or Measure to extract object features from the reviewed masks.", "focus": [1010, 1280, 2750, 455], "related_lessons": ["07_mask", "06_api"], "hold_after": 0.7}], "narration_voices": {"en": ["af_heart"]}, "poster": "20_cellpose_masks/poster.jpg", "silent": "20_cellpose_masks/video/20_cellpose_masks_silent.mp4"}, {"id": "21_model_compare", "number": 21, "slug": "model_compare", "title": "Model Compare: compare saved segmentation masks", "series": 2, "app_key": "model_compare", "host_app_key": "make_masks", "section": "Segmentation models", "description": "Load two masks of the same image, run the downloadable comparison helper and inspect overlap scores and overlays.", "objectives": ["Choose masks of the same field with matching pixel geometry.", "Run the saved-mask comparison example.", "Read the agreement table and inspect boundary differences."], "example_files": ["Model_Compare_saved_masks_example.zip"], "prerequisite": "Download and extract the linked Model Compare example. It provides one image, two saved masks and a Python helper. Use an environment with spaCR installed and choose a new output folder outside the extracted inputs. The example compares two preprocessing choices with the same cpsam weights; assessing accuracy requires reviewed reference labels.", "scenes": [{"visual": "gui_00_home", "narration": "From Home, open Make Masks and choose Model Compare. Use this workflow to inspect segmentation differences on the same image. This walkthrough uses the linked saved-mask example and its Python helper.", "focus_modules": ["make_masks"], "related_lessons": ["14_make_masks", "22_model_zoo"], "hold_after": 0.7}, {"visual": "gui_02_model_parameters", "narration": "Keep the model weights and preprocessing settings with each set of masks. When preparing your own comparison, use the same fields and pixel geometry so object overlaps refer to corresponding image locations.", "focus": [350, 420, 3450, 700], "hold_after": 0.7}, {"visual": "api_00_inputs", "narration": "Extract the linked example. The inputs are image.tif, batch.tif and preview.npy. Both masks describe the same field; they were produced with the same model and different preprocessing settings. Keep their original filenames for the supplied helper.", "focus": [200, 100, 3440, 900], "related_lessons": ["20_cellpose_masks"], "hold_after": 0.7}, {"visual": "api_02_actual_comparison", "narration": "Run the supplied helper in your spaCR Python environment. Set source to the example input folder and output to a new results folder. The printed summary lists object counts, matched objects, mean matched overlap and adjusted Rand index. Higher agreement means the masks are more similar; it does not by itself establish which mask is correct.", "focus": [200, 100, 3440, 900], "hold_after": 0.7}, {"visual": "api_04_actual_comparison_figure", "narration": "Open comparison.png. Compare the two mask overlays with the image and inspect splits, merges and boundary shifts. The right panel highlights pixels where foreground membership differs. Check touching-object boundaries in the overlays as well.", "focus": [450, 480, 2950, 1230], "hold_after": 0.7}, {"visual": "api_03_outputs", "narration": "Open comparison.csv for the numerical results and retain it with comparison.png, the inputs and the recorded settings. Use reviewed reference masks and representative fields when comparing segmentation accuracy or choosing a model for your experiment.", "focus": [200, 100, 3440, 1100], "related_lessons": ["23_agreement", "19_train_cellpose"], "hold_after": 0.7}], "narration_voices": {"en": ["af_heart"]}, "poster": "21_model_compare/poster.jpg", "silent": "21_model_compare/video/21_model_compare_silent.mp4"}, {"id": "22_model_zoo", "number": 22, "slug": "model_zoo", "title": "Model Zoo: choose a model and try it on your images", "series": 2, "app_key": "model_zoo", "host_app_key": "make_masks", "section": "Segmentation models", "description": "Open Model Zoo, find or download a checkpoint, inspect its details, and choose a small image set for a trial.", "objectives": ["Open Model Zoo and scan a local model folder.", "Choose a model family and version, then inspect its details.", "Run a small image trial and inspect the resulting masks and quality summaries."], "prerequisite": "Extract the linked example and use its images folder for the three-field trial. Choose an installed Cellpose segmentation model, or download a suitable checkpoint through Model Zoo. For your own trial, prepare a few representative TIFF, PNG, NPY or NPZ images.", "scenes": [{"visual": "00_home", "narration": "From Home, open Make Masks, then choose Model Zoo. Use this page to find a segmentation model and try it on a small image set.", "hold_after": 0.7, "focus_modules": ["make_masks"]}, {"visual": "03_current_catalogue_and_local_models", "narration": "Click Choose folder and select your model directory to scan it. If you type the path instead, click Scan. Turn on the source headings you want to browse, such as Cellpose or local models.", "hold_after": 0.7}, {"visual": "04_actual_cpsam_provenance", "narration": "Select a model family and use its Version control to choose the checkpoint. Read the details for its image type, training information and local path. For a remote checkpoint, choose a Save to folder and click Download before trying it.", "hold_after": 0.7}, {"visual": "06_three_verified_real_fields", "narration": "Extract the linked example and choose its images folder under Test on fields. Set the field count to three. For your own images, start with a small set that includes typical fields and difficult cases.", "hold_after": 0.7}, {"visual": "07_actual_test_started", "narration": "Select the local segmentation model and click Test on fields. Wait for the trial to finish. Larger images and models can take longer, especially on a CPU.", "hold_after": 0.7}, {"visual": "08_actual_preview_02", "narration": "Select a result row to inspect its mask preview. Check boundaries, touching objects and missed objects against the image. Use the object count and quality flags to help find fields that need closer inspection.", "hold_after": 0.7}, {"visual": "09_actual_benchmark_summary", "narration": "Review the field summaries, then keep the chosen checkpoint path for your analysis module. To compare two different model families on the same images, select both rows and choose Compare the two selected. Use the version control to try another version of one family.", "hold_after": 0.7, "related_lessons": ["21_model_compare", "14_make_masks"]}], "example_files": ["Apply_Cellpose_stock_example.zip"], "narration_voices": {"en": ["af_heart"]}, "poster": "22_model_zoo/poster.jpg", "silent": "22_model_zoo/video/22_model_zoo_silent.mp4"}, {"id": "23_agreement", "number": 23, "slug": "agreement", "title": "Annotator Agreement: compare independent annotation passes", "series": 3, "app_key": "agreement", "host_app_key": "annotate", "section": "Results and quality control", "description": "Choose annotation columns, compare agreement and inspect the crops where labels differ.", "objectives": ["Open the example database and select two annotation passes.", "Read pairwise agreement and the confusion matrix.", "Inspect disagreements and compare three annotation passes."], "prerequisite": "Extract the linked Annotator Agreement example and keep its database with the crop images. It contains sixteen images from the Annotate example and three artificial teaching-label columns, DEMO_A, DEMO_B and DEMO_C. For your own analysis, use independently collected annotations of the same images.", "scenes": [{"visual": "02_agreement_fold", "narration": "From Home, open Annotate, then choose Annotator Agreement. Use this tool to compare labels collected in separate annotation passes. The results help you find images that need review.", "related_lessons": ["09_annotate"], "hold_after": 0.7}, {"visual": "04_demo_database", "narration": "Open the example database. Keep the extracted crop folders beside it so the image previews can load. The DEMO columns contain artificial teaching labels; use your own independent annotation columns when assessing agreement in a study.", "hold_after": 0.7}, {"visual": "05_one_column_not_a_comparison", "narration": "Select at least two annotation columns from the list. For this example, start with DEMO A and DEMO B. Check the column names so you compare the intended passes.", "hold_after": 0.7}, {"visual": "06_two_columns", "narration": "Click Compute agreement. The two selected passes share twelve labelled crops. Three more crops have a label in only one pass, and one has neither label. Pairwise agreement uses the crops labelled by both passes.", "hold_after": 0.7}, {"visual": "07_pairwise_results", "narration": "Read the pairwise results. The passes agree on nine of twelve crops, giving seventy-five percent agreement and a Cohen kappa of zero point five. Read these values alongside the number of shared labels; a small sample gives an uncertain estimate.", "hold_after": 0.7}, {"visual": "08_confusion_matrix", "narration": "Open the confusion matrix. Rows represent DEMO A and columns represent DEMO B. The diagonal contains matching labels: five for class one and four for class two. The off-diagonal cells contain the three disagreements.", "hold_after": 0.7}, {"visual": "09_disagreement_crop_1", "narration": "Select a disagreement to view its crop and the labels assigned by each pass. Compare the image with your class definitions. To revise a label after review, return to Annotate.", "hold_after": 0.7}, {"visual": "10_three_columns", "narration": "Add DEMO C and click Compute agreement again. The pairwise table now shows all three pairs. Each pair uses its shared labels, while the overall summary uses crops labelled in all three selected passes.", "hold_after": 0.7}, {"visual": "11_three_pass_results", "narration": "Read the overall Fleiss kappa and the unanimous agreement summary. This example gives a Fleiss kappa of about zero point six six three. Review the disagreement list as well: it can include a crop that has labels in only two of the three passes.", "hold_after": 0.7}, {"visual": "12_pairwise_restored", "narration": "To focus on one pair again, select only A and B and click Compute agreement. The results stay in this comparison view; your annotation columns remain in the source database. Continue in Annotate to collect another independent pass or review the identified disagreements.", "related_lessons": ["09_annotate", "34_database"], "hold_after": 0.7}], "example_files": ["Agreement_artificial_labels_real_crops.zip"], "narration_voices": {"en": ["af_heart"]}, "poster": "23_agreement/poster.jpg", "silent": "23_agreement/video/23_agreement_silent.mp4"}, {"id": "24_plaque", "number": 24, "slug": "plaque-assay", "title": "Plaque Assay: count plaques and measure their areas", "series": 3, "app_key": "analyze_plaques", "section": "Toxoplasma assays", "description": "Open the synthetic example, choose saved masks or model segmentation, inspect a preview, and read the per-image and per-plaque results.", "objectives": ["Open Plaque Assay from Toxoplasma and select the image folder.", "Choose a model, inspect a preview and set area filters.", "Run the analysis and inspect counts, areas and calibration in the output database."], "example_files": ["SYNTHETIC_plaque_example.zip"], "prerequisite": "Download and extract SYNTHETIC_plaque_example.zip. It contains four grayscale TIFF images and their saved label masks. Use a working copy when trying new segmentation. Have a local plaque checkpoint available or download one through Model Zoo. The synthetic example has no physical calibration.", "scenes": [{"visual": "01_module", "narration": "From Home, open Toxoplasma, then choose Plaque Assay. Start with a folder of plaque images. This walkthrough uses the linked synthetic example so you can practise selecting masks, adjusting the preview and opening the results.", "focus": [346, 50, 1200, 155], "hold_after": 0.7}, {"visual": "03_setting_src", "narration": "Download and extract the example. Set Source to SYNTHETIC_plaque, the folder containing the TIFF images and the masks subfolder. Keep a working copy if you plan to generate replacement masks.", "focus": [346, 170, 1150, 215], "hold_after": 0.7}, {"visual": "04_setting_masks", "narration": "Leave Masks off to analyse the supplied label masks. Switch Masks on when you want the selected model to segment the images first. For new segmentation, choose a plaque model and review its diameter and detection thresholds on a representative image.", "focus": [346, 170, 1150, 215], "hold_after": 0.7}, {"visual": "08_setting_well_diameter_mm", "narration": "Leave well detection off for this example. For images containing a whole plate, use well detection to separate the wells. If you know the image scale, enter pixels per micrometer; a known physical well diameter can also provide calibration. Record formation time in hours when it is known. Leave unknown calibration values unset.", "focus": [346, 170, 1150, 215], "hold_after": 0.7}, {"visual": "05_setting_plaque_model", "narration": "Set Plaque model to a local checkpoint. If you need one, open Model Zoo and download a plaque model, then enter its local path. The analysis resolves this model setting even when it reuses saved masks.", "focus": [346, 170, 1150, 215], "hold_after": 0.7}, {"visual": "11_preview_settings_unmatched", "narration": "Open Live preview and Live settings. Check the selected model and image before running the preview. Match the model in the preview to the one you plan to use for the full analysis.", "focus": [1020, 456, 1800, 380], "hold_after": 0.7}, {"visual": "12c_actual_download_verified", "narration": "In Model Zoo, select the plaque model, choose a Save to folder and click Download. Wait until the model is available locally, then select that checkpoint for the preview. Keep its saved path for later runs.", "focus": [1025, 568, 1790, 1035], "hold_after": 0.7}, {"visual": "16_readable_preview", "narration": "Choose an example image and click Run preview. Switch View between outlines and coloured masks to check whether the predicted regions follow plaque boundaries. Inspect several representative images before running a plate.", "focus": [1510, 1248, 2300, 598], "hold_after": 0.7}, {"visual": "18_actual_filter_changed", "narration": "Raise Min area to hide small predicted regions. Watch which objects disappear, and adjust the threshold to the smallest plaque you intend to measure. Change one setting at a time so its effect is clear.", "focus": [1980, 286, 432, 660], "hold_after": 0.7}, {"visual": "19_actual_filter_restored", "narration": "Lower Min area to bring smaller regions back; zero removes this lower area cutoff. Check the final preview and the batch settings before Run. A preview shows the selected image; Run produces the analysis outputs.", "focus": [3040, 1570, 760, 230], "hold_after": 0.7}, {"visual": "09_actual_completion", "narration": "Press Run and follow the console until the analysis finishes. With Masks off, the example reads the supplied labels and writes masks/plaques_analysis.db. The database contains the counts and areas for the images in Source.", "focus": [1510, 170, 2300, 1450], "hold_after": 0.7}, {"visual": "20_actual_database_help_route", "narration": "Open Help, then Database browser. Select plaques_analysis.db in the masks folder. Leave Edit mode off while inspecting the output, and choose a table from the table list.", "related_lessons": ["34_database"], "hold_after": 0.7}, {"visual": "21_actual_summary_table", "narration": "Open summary for an overview by image. Match rows using their filenames. The supplied synthetic masks contain four, three, two and one objects. Average size reports their mean area in pixels.", "focus": [345, 278, 1420, 225], "hold_after": 0.7}, {"visual": "22_actual_stats_table", "narration": "Open stats to compare each image’s plaque count, mean area and area spread. The standard deviation describes the range of plaque sizes within that image. Use independent experimental replicates when comparing biological conditions.", "focus": [345, 278, 1930, 225], "hold_after": 0.7}, {"visual": "23_actual_details_table", "narration": "Open details to inspect individual plaque areas. Physical-area columns are empty when calibration is unavailable. Save the database together with the images, masks and settings. Experimental growth estimates additionally require a known scale to estimate time, or a known time to estimate scale; validate the reference curve for your assay.", "focus": [345, 278, 1420, 410], "hold_after": 0.7}], "host_app_key": "toxoplasma", "narration_voices": {"en": ["af_heart"]}, "poster": "24_plaque/poster.jpg", "silent": "24_plaque/video/24_plaque_silent.mp4"}, {"id": "25_recruitment", "number": 25, "slug": "recruitment", "series": 3, "app_key": "recruitment", "section": "Assays", "title": "Recruitment: measure marker enrichment around parasites", "description": "Choose a measured project, map the marker channel and conditions, set object filters, then inspect recruitment ratios by host cell and well.", "objectives": ["Select a project containing linked cell, nucleus, pathogen and cytoplasm measurements.", "Set the marker channel, plate conditions and object filters.", "Run Recruitment and read the host-cell and well CSV results."], "prerequisite": "Start with a project from Measure containing measurements/measurements.db and linked cell, nucleus, pathogen and cytoplasm tables. Include merged images to display image overlays. The example uses an ER marker on channel 1; use the channel mapping and condition labels recorded for your own project.", "scenes": [{"visual": "01_module", "narration": "From Home, open Toxoplasma, then choose Recruitment. Use this analysis to compare marker intensity in parasite-associated regions with the surrounding host-cell cytoplasm. Begin with a project whose objects and intensity channels have already been measured.", "hold_after": 0.7, "related_lessons": ["08_measure"]}, {"visual": "19_setting_src", "narration": "Set Source to the project folder containing measurements/measurements.db. Keep the cell, nucleus, pathogen and cytoplasm tables together. Include the merged image folder if you want image overlays.", "hold_after": 0.7, "focus": [450, 220, 1700, 560]}, {"visual": "19_setting_channel_of_interest", "narration": "Set Channel of interest to the marker you want to measure. Channels use zero-based numbering: one means the second image plane. This example uses channel one for the ER marker. Choose the channel that matches your acquisition.", "hold_after": 0.7, "focus": [450, 220, 1700, 560]}, {"visual": "19_setting_channel_dims", "narration": "Set Channel dims to the channels needed for the auxiliary recruitment summaries. For a first run, use the same single channel as Channel of interest so the main ratio and additional intensity summaries are easy to compare.", "hold_after": 0.7, "focus": [450, 220, 1700, 560]}, {"visual": "19_setting_cell_chann_dim", "narration": "Check the cell, nucleus and pathogen channel mapping against the measured project. The example uses cell one, nucleus zero and pathogen three. Keep the mapping with your settings so overlays and filters refer to the intended signals.", "hold_after": 0.7, "focus": [450, 220, 1700, 560]}, {"visual": "19_setting_pathogen_plate_metadata", "narration": "Enter the cell, pathogen and treatment labels, then map each label to its plate rows or columns. Only annotated wells enter the analysis. Match these assignments to your plate layout, including the positive and negative controls.", "hold_after": 0.7, "focus": [450, 220, 1700, 560]}, {"visual": "19_setting_pathogen_size_range", "narration": "Use the size ranges to exclude objects outside the areas you intend to analyse. Areas are in pixels, and the bounds are strict. Pathogen area is aggregated within each host cell for this analysis, so choose its range for the cell-level total.", "hold_after": 0.7, "focus": [450, 220, 1700, 560]}, {"visual": "19_setting_nuclei_limit", "narration": "Set Nuclei limit and Pathogen limit to control which host cells are retained. A nuclei limit of one keeps single-nucleus cells. Raise a limit to include cells with more associated objects, then inspect how many cells remain.", "hold_after": 0.7, "focus": [450, 220, 1700, 560]}, {"visual": "19_setting_nucleus_intensity_range", "narration": "Start with broad intensity ranges so you can inspect the initial results. Narrow a range when you have a defined intensity-based selection rule. Target intensity minimum applies an additional cutoff to the marker’s cell intensity.", "hold_after": 0.7, "focus": [450, 220, 1700, 560]}, {"visual": "19_setting_pathogen_intensity_range", "narration": "Check the channel used by each intensity filter before narrowing its bounds. With the example’s mapping, the nucleus intensity filter uses channel three and the pathogen intensity filter uses channel one. Keep the broad example ranges while learning the workflow.", "hold_after": 0.7, "focus": [450, 220, 1700, 560]}, {"visual": "19_setting_cells_per_well", "narration": "Set Cells per well to the minimum source-cell count required for a well to remain in the analysis. This setting filters wells, while the object filters select cells. Inspect the final retained counts as well as the threshold.", "hold_after": 0.7, "focus": [450, 220, 1700, 560]}, {"visual": "19_setting_plot_nr", "narration": "Enable Plot to display available image overlays and use Plot number to limit how many are shown. Keep Plot control enabled if you want the control-intensity figures. Use the plots to check channel choices and filtering before interpreting the ratios.", "hold_after": 0.7, "focus": [450, 220, 1700, 560], "related_lessons": ["07_mask", "08_measure"]}, {"visual": "21_batch_running", "narration": "Press Run. Follow the console as the module joins the measurements, applies conditions and filters, calculates ratios and writes the results. Wait until the analysis finishes before opening the output tables.", "hold_after": 0.7}, {"visual": "25_recruitment_figure_02", "narration": "Inspect the recruitment plot. The main value divides the host cell’s aggregated pathogen mean intensity by its cytoplasm mean intensity on the selected marker channel. Values above one indicate enrichment relative to that reference. Read the numeric exports for ratios below the plotted range or invalid denominators.", "hold_after": 0.7, "focus": [1450, 280, 900, 520]}, {"visual": "25_recruitment_figure_04", "narration": "Inspect the well summary and compare the control conditions. Each well averages its retained cell ratios; condition plots summarize those well values. Error bars show between-well standard deviation. The cell table represents host cells with aggregated pathogen measurements.", "hold_after": 0.7, "focus": [1450, 280, 900, 520]}, {"visual": "26_recruitment_console_counts", "narration": "Open results/cells.csv for retained host-cell measurements and results/wells.csv for well summaries. Keep both files with the saved settings. Check cell counts, condition labels and finite ratios before comparing experiments, and use independent wells as the experimental replicates.", "hold_after": 0.7, "focus": [1300, 620, 2510, 960]}], "host_app_key": "toxoplasma", "narration_voices": {"en": ["af_heart"]}, "poster": "25_recruitment/poster.jpg", "silent": "25_recruitment/video/25_recruitment_silent.mp4"}, {"id": "26_invasion", "number": 26, "slug": "invasion-assay", "title": "Invasion Assay: score outside and total staining", "series": 3, "app_key": "invasion", "section": "Toxoplasma assays", "description": "Map two staining channels, choose the staining baseline, run the analysis and inspect invasion calls and threshold sensitivity.", "objectives": ["Choose the measurement database and map outside and total staining.", "Set baseline wells and threshold controls, then run the analysis.", "Inspect distributions, well denominators and saved result tables."], "prerequisite": "Extract the linked synthetic Invasion Assay example and use its settings reference. The database contains 1,800 synthetic parasite measurements; condition names and results are illustrative. For your own assay, use a validated two-colour staining design with outside staining before permeabilisation and total staining afterwards, and review representative images.", "scenes": [{"visual": "01_module", "narration": "From Home, open Toxoplasma, then choose Invasion Assay. Start with a measurement database containing parasite intensities for the outside and total stains. Use the linked synthetic sample to practise channel mapping, threshold selection and result inspection.", "focus": [346, 50, 1140, 155], "related_lessons": ["08_measure"], "hold_after": 0.7}, {"visual": "02_setting_src", "narration": "Extract the sample and set Source to its invasion folder, which contains measurements/measurements.db. Enter the accompanying settings reference and replace its Source placeholder. The sample contains baseline wells and two assay conditions.", "focus": [346, 170, 1150, 215], "hold_after": 0.7}, {"visual": "03_setting_outside_channel", "narration": "Set Outside channel to one and Total channel to zero. Outside represents the stain applied before permeabilisation; total represents the stain applied afterwards. Outside-positive parasites are classified as attached, and those at or below the outside threshold as invaded. Check your acquisition channel order when using your own measurements.", "focus": [346, 170, 1150, 215], "hold_after": 0.7}, {"visual": "05_setting_intensity_statistic", "narration": "Select mean under Intensity statistic to match the columns in the example database. For your own assay, choose an available statistic suited to the stain and inspect representative objects. Keep Minimum total intensity at one hundred for this sample.", "focus": [346, 170, 1150, 215], "hold_after": 0.7}, {"visual": "06_setting_stain_baseline_wells", "narration": "Set Stain baseline wells to column one, using c1. These negative-stain measurements establish the cutoff and are excluded from the assay denominators. Under Pathogen plate metadata, map vehicle to column two and inhibitor to column three.", "focus": [346, 170, 1150, 215], "hold_after": 0.7}, {"visual": "07_setting_control_quantile", "narration": "Set Control quantile to zero point nine nine and leave the fixed Outside threshold unset. The baseline measurements then determine the cutoff, about twenty-two point eight in this example. Check the applied threshold in the output before interpreting the classifications.", "focus": [346, 170, 1150, 215], "hold_after": 0.7}, {"visual": "08_setting_threshold_sensitivity", "narration": "Set Threshold sensitivity to zero point two five. This also evaluates cutoffs twenty-five percent below and above the selected threshold. Compare the resulting invasion-efficiency range to see how strongly your result depends on threshold choice.", "focus": [346, 170, 1150, 215], "hold_after": 0.7}, {"visual": "10_setting_extracellular_class", "narration": "Set Extracellular class to classify for the sample. For objects without a host link, classify uses the stain, attached assigns them to attached, and exclude removes them from the scored population. Choose this setting with the quality of your host-cell assignments in mind.", "focus": [346, 170, 1150, 215], "hold_after": 0.7}, {"visual": "15_figure_02", "narration": "Keep Save enabled and click Run. Open the threshold figure after processing finishes. It shows distributions by well and the applied cutoff. For an experiment, compare these distributions with representative stained images and investigate weak outside staining.", "focus": [1685, 260, 2125, 875], "hold_after": 0.7}, {"visual": "16_legend_00", "narration": "If a legend extends beyond the figure, open Figure settings. In the axes tab, set Legend position to best, then confirm. Check that the labels remain visible in both the on-screen and exported figures.", "focus": [1420, 330, 1000, 1500], "related_lessons": ["27_replication"], "hold_after": 0.7}, {"visual": "17_readable_figure_00", "narration": "Open the per-well figure. Each bar shows attached and invaded fractions, with the number of scored parasites above it. Baseline wells are excluded. Read the counts alongside the fractions when comparing wells.", "focus": [1685, 260, 2125, 875], "hold_after": 0.7}, {"visual": "17_readable_figure_01", "narration": "Open the condition summary. Compare the pooled invasion fraction with the mean across wells, since they use different weighting. Check the per-well results for variation before making comparisons between conditions.", "focus": [1685, 260, 2125, 875], "hold_after": 0.7}, {"visual": "14_actual_completion", "narration": "Open results/analyze_invasion inside Source. Review parasite_calls.csv, field_thresholds.csv, well_invasion.csv and condition_summary.csv, together with the saved figures and settings. Use independent experimental replicates when assessing differences in your own assay.", "focus": [1510, 1200, 2300, 370], "related_lessons": ["08_measure", "13_regression"], "hold_after": 0.7}], "example_files": ["SYNTHETIC_invasion_example.zip"], "narration_voices": {"en": ["af_heart"]}, "poster": "26_invasion/poster.jpg", "silent": "26_invasion/video/26_invasion_silent.mp4"}, {"id": "27_replication", "number": 27, "slug": "replication", "title": "Replication Assay: count parasites per vacuole", "series": 3, "app_key": "replication", "section": "Toxoplasma assays", "description": "Load parasite measurements, choose the vacuole identity, run the analysis and inspect count distributions and exports.", "objectives": ["Choose a measurement database and its vacuole identifier.", "Set host-assignment and size filters, then run the analysis.", "Read per-well distributions and locate the saved result tables."], "prerequisite": "Extract the linked synthetic Replication Assay example. It contains a measurement database and a settings reference, with 1,992 parasite rows in 480 vacuoles across twelve wells. The condition names and measurements are teaching data. For your own assay, use measured parasites with reviewed vacuole assignments and independent experimental replicates.", "scenes": [{"visual": "01_module", "narration": "From Home, open Toxoplasma, then choose Replication Assay. Start with a measurement database containing parasite rows and their vacuole assignments. The linked synthetic example lets you practise the settings and read the resulting count distributions.", "focus": [346, 50, 1140, 155], "hold_after": 0.7, "related_lessons": ["08_measure"]}, {"visual": "03_setting_src", "narration": "Extract the sample and set Source to its replication folder. The database is inside measurements. Enter the accompanying settings reference, replacing its Source placeholder with your extracted folder. Keep Save enabled to write the results.", "focus": [346, 170, 1150, 215], "hold_after": 0.7}, {"visual": "04_setting_vacuole_key", "narration": "Set Vacuole key to vacuole_id. This groups parasites by the vacuole they belong to. The sample contains two vacuoles per host-cell group, so use the vacuole identifier to keep those counts separate.", "focus": [346, 170, 1150, 215], "hold_after": 0.7}, {"visual": "05_setting_require_host_cell", "narration": "Enable Require host cell to include only parasites linked to a host cell. Review unassigned objects when using your own data. For this sample, set Minimum parasite area to two hundred and Maximum parasite area to eight hundred.", "focus": [346, 170, 1150, 215], "hold_after": 0.7}, {"visual": "07_setting_max_parasites_per_vacuole", "narration": "Set Maximum parasites per vacuole to sixteen. This sets the largest named power-of-two bucket. Larger power-of-two counts go into an overflow bucket, while counts such as three remain in the separate non-power-of-two category.", "focus": [346, 170, 1150, 215], "hold_after": 0.7}, {"visual": "09_setting_pathogen_plate_metadata", "narration": "Enter vehicle and inhibitor as the two Pathogen types, and map them to column one and column two in Pathogen plate metadata. Each group contains six practice wells. For your experiment, enter the condition names and well assignments from your plate design.", "focus": [346, 170, 1150, 560], "hold_after": 0.7}, {"visual": "11_actual_run", "narration": "Check Source, Vacuole key, filters and Save, then click Run. Follow the console until processing finishes. The Figures area will show distributions by well and by condition.", "focus": [1510, 170, 2310, 1840], "hold_after": 0.7}, {"visual": "15_readable_legend_00", "narration": "Open the per-well figure. Each stacked bar shows the fraction of vacuoles in each parasite-count category. Read the colours with the legend. In this sample, each well contains forty vacuoles and five percent fall in the non-power-of-two category.", "focus": [1510, 170, 2310, 1020], "hold_after": 0.7}, {"visual": "14_legend_settings_00", "narration": "Open Figure settings to adjust the legend. In the axes tab, choose an inside Legend position if the labels extend beyond the figure. This changes the presentation while retaining the calculated counts.", "hold_after": 0.7, "focus": [1420, 330, 1000, 1500]}, {"visual": "15_readable_legend_01", "narration": "Open the by-condition figure to compare the pooled count distributions. Inspect the per-well results alongside this summary. When analysing an experiment, use independent biological replicates and a suitable experimental unit for statistical comparisons.", "focus": [1510, 170, 2310, 1020], "hold_after": 0.7}, {"visual": "12_actual_completion", "narration": "Read any export warnings in the console. Check the saved figures as well as the on-screen view, and choose colours that remain readable against the export background.", "focus": [1510, 1190, 2310, 440], "hold_after": 0.7}, {"visual": "10_setting_save", "narration": "Open results/analyze_replication inside Source. Review vacuole_counts.csv for individual vacuoles, well_distribution.csv for each well, and the condition summaries and figures. Keep these outputs with the settings and source database so you can trace the analysis.", "focus": [346, 170, 1150, 215], "hold_after": 0.7, "related_lessons": ["08_measure", "34_database"]}], "example_files": ["SYNTHETIC_replication_example.zip"], "narration_voices": {"en": ["af_heart"]}, "poster": "27_replication/poster.jpg", "silent": "27_replication/video/27_replication_silent.mp4"}, {"id": "28_training_runs", "number": 28, "slug": "training_runs", "series": 4, "app_key": "train_compare", "host_app_key": "classify_merged", "section": "Tools", "title": "Training Runs: compare curves and settings", "description": "Load training logs, overlay metrics, compare settings and explore cross-validation folds.", "objectives": ["Find saved runs and select the ones to compare.", "Overlay training and validation metrics and inspect settings differences.", "Switch between individual folds and their mean and standard deviation."], "prerequisite": "Download and extract the linked synthetic Training Runs example. Its curves are practice data. For your own analysis, select a parent folder containing saved train.csv and validation.csv files with each run’s settings. Keep independent evaluation results with your model when assessing performance.", "scenes": [{"visual": "01_module", "narration": "From Home, open Classify, then Training Runs. Use this tool to compare the progress logs and settings from saved training runs. The linked sample contains synthetic curves for practising the controls.", "hold_after": 0.7, "related_lessons": ["41_classify"]}, {"visual": "01_current_training_runs_fold", "narration": "Training Runs provides a folder selector, run list, Metric menu, Folds menu and Overlay selected button. Begin by choosing the parent folder containing the runs you want to compare.", "hold_after": 0.7, "focus": [465, 310, 3350, 1650]}, {"visual": "02_synthetic_source_folder_picker", "narration": "Extract the linked sample and click Choose folder. Select its training_runs folder, then confirm the choice. For your own projects, select a parent folder containing the run folders and their saved CSV logs.", "hold_after": 0.7, "focus": [1555, 790, 1410, 965]}, {"visual": "03_synthetic_runs_and_real_warnings", "narration": "Scan the folder and inspect the discovered runs. The sample has baseline, tuned and cross_validated examples, plus one incomplete entry. Select the usable runs you want to compare.", "hold_after": 0.7, "focus": [465, 530, 940, 285]}, {"visual": "03_synthetic_runs_and_real_warnings", "narration": "Check warnings on incomplete entries. Missing train.csv, validation.csv or settings can prevent curves or settings from appearing. Locate the complete run folder before adding it to a comparison.", "hold_after": 0.7, "focus": [465, 1845, 3350, 175]}, {"visual": "04b_actual_metric_choices", "narration": "Tick baseline and tuned, then choose accuracy under Metric. The menu lists the numeric columns available in the selected logs. Choose loss or another recorded metric when it answers your comparison question.", "hold_after": 0.7, "focus": [465, 1680, 940, 300]}, {"visual": "05_actual_synthetic_accuracy_overlay", "narration": "Click Overlay selected. Training curves are dashed and validation curves are solid. Read each run and split in the legend. Each curve ends at its own final recorded epoch.", "hold_after": 0.7, "focus": [1390, 530, 2420, 960]}, {"visual": "06_actual_synthetic_settings_diff", "narration": "Inspect the settings comparison below the plot. It highlights differences such as batch size, epoch count and learning rate. Use it to identify what changed between the runs before interpreting their curves.", "hold_after": 0.7, "focus": [1390, 1490, 2420, 360]}, {"visual": "06_actual_synthetic_settings_diff", "narration": "The environment row separates execution settings, such as worker count, from training configuration. Read these alongside the configuration differences when comparing runs made on different machines.", "hold_after": 0.7, "focus": [1390, 1490, 2420, 360]}, {"visual": "07_actual_series_pick_best_and_last_epochs", "narration": "Click a validation curve to see its last and best recorded values and epochs. Use the same selection rule when comparing runs. Evaluate a selected checkpoint on independent data to assess its performance.", "hold_after": 0.7, "focus": [465, 2000, 3350, 105]}, {"visual": "08_actual_synthetic_loss_overlay", "narration": "Choose loss under Metric to update the vertical axis and overlay. Compare the training and validation trajectories, including their direction near the end of training.", "hold_after": 0.7, "focus": [1390, 530, 2420, 960]}, {"visual": "08b_actual_fold_choices", "narration": "Select tuned and cross_validated, choose accuracy, then click Overlay selected. Open Folds and choose whether to display individual folds, their mean and standard deviation, or both.", "hold_after": 0.7, "focus": [465, 1730, 940, 175]}, {"visual": "09_actual_synthetic_fold_mean_sd", "narration": "Choose mean plus or minus standard deviation to summarize the fold curves. Each band shows one sample standard deviation across the available folds at that epoch. Read the band as variation across folds.", "hold_after": 0.7, "focus": [1390, 530, 2420, 960]}, {"visual": "10_actual_synthetic_folds_and_mean", "narration": "Choose both to show the individual fold curves together with their mean. Compare the folds to see whether a summary hides a run with a different trajectory.", "hold_after": 0.7, "focus": [1390, 530, 2420, 960]}, {"visual": "11_actual_synthetic_per_fold_curves", "narration": "Choose per fold to show only the individual curves. The settings comparison updates with your selected runs. Keep each curve’s epoch range in mind when comparing where training ended.", "hold_after": 0.7, "focus": [1390, 530, 2420, 1315]}, {"visual": "11_actual_synthetic_per_fold_curves", "narration": "Return to Metric to compare another logged quantity, or change the selected runs to narrow the comparison. Keep the original CSV logs and settings together so the same comparison can be reopened.", "hold_after": 0.7}, {"visual": "11_actual_synthetic_per_fold_curves", "narration": "For scripted analysis, use find_runs and load_run in spacr.train_compare, then compare_runs and plot_curves. Keep the comparison with your model and independent evaluation results when choosing the next training configuration.", "hold_after": 0.7, "related_lessons": ["06_api", "41_classify"]}], "example_files": ["SYNTHETIC_training_runs.zip"], "narration_voices": {"en": ["af_heart"]}, "poster": "28_training_runs/poster.jpg", "silent": "28_training_runs/video/28_training_runs_silent.mp4"}, {"id": "29_report", "number": 29, "slug": "report", "series": 4, "app_key": "report", "section": "Help", "title": "Report: create a document from project results", "description": "Choose a completed project, select the output format and figure limit, then generate and read its report.", "objectives": ["Choose a completed project and inspect its available report sections.", "Set the format, figure limit and output filename.", "Generate the report and inspect its results, settings and provenance."], "prerequisite": "Start with a completed spaCR project containing its saved settings, measurements and figures. You can reuse the project from the External Masks tutorial. Report collects files already present in the project.", "scenes": [{"visual": "00a_help_report_menu", "narration": "Open Help, then Report. Use this tool to collect a completed project’s results, figures and settings into a document.", "hold_after": 0.7, "related_lessons": ["31_external_masks", "54_qc_dashboard"]}, {"visual": "02_existing_project_picker", "narration": "Click Choose run folder and select your project. For this example, use the two-field project from External Masks, keeping its measurements, settings and figures together.", "hold_after": 0.7, "related_lessons": ["31_external_masks"]}, {"visual": "03_actual_completion_not_qc_pass", "narration": "Read the processing status after the scan. Complete means the recorded processing steps finished. Review the available quality-control results separately when assessing the analysis.", "hold_after": 0.7, "focus": [450, 275, 3000, 150]}, {"visual": "04_read_only_missing_sections", "narration": "Check the section list to see which project artifacts are available. A missing section remains labelled in the report. Add the relevant analysis outputs to the project if you need that section.", "hold_after": 0.7, "focus": [450, 330, 2800, 350]}, {"visual": "05_actual_output_format_choices", "narration": "Choose HTML, PDF or Both under Format. HTML opens in a browser; PDF provides a document version. This example uses HTML.", "hold_after": 0.7}, {"visual": "06_actual_figure_cap", "narration": "Set Embed at most to limit the number of raster figures included in the document. Vector PDFs are listed as source files rather than embedded previews. Use a smaller limit for a compact report.", "hold_after": 0.7, "focus": [450, 1900, 1650, 130]}, {"visual": "07_separate_output_picker", "narration": "Click Choose output and enter the destination filename. Check that the selected format and extension agree. Before sharing the report, review any project paths and metadata it includes.", "hold_after": 0.7}, {"visual": "09_actual_report_written", "narration": "Press Generate report and wait for the written-file confirmation. Open the saved HTML file in a browser to inspect the result.", "hold_after": 0.7, "focus": [450, 1975, 3370, 160]}, {"visual": "browser_01_report_top_completion_and_contents", "narration": "Use the contents links to jump between sections. Start with the processing summary, then review figures, result tables and saved settings.", "hold_after": 0.7}, {"visual": "browser_06_figures", "narration": "Open Key figures to find the project’s figures. Follow the listed file locations for vector PDFs, or inspect embedded raster previews when available.", "hold_after": 0.7, "related_lessons": ["31_external_masks"]}, {"visual": "browser_07_statistics", "narration": "Review Statistics and result tables for the available object tables and their row counts. This cell-only example has matching cell and cytoplasm regions, so treat them as measurements of the same cells.", "hold_after": 0.7, "related_lessons": ["34_database", "31_external_masks"]}, {"visual": "browser_09_settings_first_native_disclosure", "narration": "Expand Saved settings to inspect the configuration retained with the project. Keep the report together with the project files when sharing an analysis that refers to external figures.", "hold_after": 0.7}], "narration_voices": {"en": ["af_heart"]}, "poster": "29_report/poster.jpg", "silent": "29_report/video/29_report_silent.mp4"}, {"id": "30_plate_queue", "number": 30, "slug": "plate_queue", "series": 4, "app_key": "queue", "section": "Data and batch runs", "title": "Plate Queue: run several prepared projects", "description": "Add the current project or drop prepared folders into a queue, run jobs in order, and continue after a controlled stop.", "objectives": ["Add prepared projects with their saved module settings.", "Run the queue and stop between jobs.", "Find each project’s results and clear completed queue entries."], "prerequisite": "Prepare a project and its saved module settings. For practice, use two copies of the Recruitment example in separate folders; they contain the same data and are not biological replicates.", "scenes": [{"visual": "00a_import_recruitment_settings", "narration": "Prepare the first project in its analysis module. In Recruitment, choose Import settings and open the project’s settings CSV. The example uses two separate copies of the same measured data to practise running several jobs.", "hold_after": 0.7, "related_lessons": ["25_recruitment"]}, {"visual": "00b_current_recruitment_settings", "narration": "Check Source, the channel mapping and the condition labels. Save the settings you want the queue to use, then leave this project open.", "hold_after": 0.7}, {"visual": "01_help_queue", "narration": "Open Help, then Plate queue. The queue runs one item at a time in the listed order.", "hold_after": 0.7}, {"visual": "03_added_replay_1", "narration": "Choose Add current plate. A new row stores the current module and settings. Check its module, source and label before starting the queue.", "hold_after": 0.7, "focus": [450, 160, 2120, 420]}, {"visual": "03_added_replay_2", "narration": "Drag another prepared project folder onto the queue. Its saved settings identify the module, and the dropped folder becomes its source. Use separate project folders when each job needs separate output files.", "hold_after": 0.7, "focus": [450, 160, 2120, 420]}, {"visual": "04_first_job_running", "narration": "Choose Run queue. The first row changes to running while later items remain queued. Watch the status and elapsed time to follow progress.", "hold_after": 0.7, "focus": [450, 160, 2120, 420]}, {"visual": "05_stop_requested", "narration": "Press Stop when you want the queue to finish its current item and pause before the next one. Wait until the active job finishes.", "hold_after": 0.7, "focus": [450, 160, 2120, 420]}, {"visual": "06_stopped_between_jobs", "narration": "The completed row now says success and the next row remains queued. Choose Run queue again to continue with the remaining item.", "hold_after": 0.7, "focus": [450, 160, 2120, 420]}, {"visual": "07_both_jobs_finished", "narration": "When both jobs finish, open each project’s output folder. For Recruitment, inspect the cells and wells CSV results. Use Recruitment directly when you want its figure workflow; this queue does not display or save those plots.", "hold_after": 0.7, "focus": [450, 160, 2120, 420]}, {"visual": "08_finished_records_cleared", "narration": "Choose Clear finished to remove completed entries from the list. Their project folders and saved results remain available.", "hold_after": 0.7, "related_lessons": ["06_api", "25_recruitment"]}], "narration_voices": {"en": ["af_heart"]}, "poster": "30_plate_queue/poster.jpg", "silent": "30_plate_queue/video/30_plate_queue_silent.mp4"}, {"id": "31_external_masks", "number": 31, "slug": "external_masks", "series": 4, "app_key": "external_masks", "host_app_key": "foreign", "section": "Data", "title": "External Masks: measure images with supplied object labels", "description": "Assign image and mask files, preview their pairing, then create a measured spaCR project with object tables and crops.", "objectives": ["Assign intensity images and label masks to the correct roles.", "Choose channels, output location and measurement options.", "Preview the pairing, run Measure and inspect the output project."], "prerequisite": "Prepare matching intensity images and integer-labelled masks with the same spatial dimensions. Each object needs its own positive integer label; zero is background. The example reuses two image and cell-mask pairs from the Import Project tutorial.", "scenes": [{"visual": "01b_current_external_masks_fold", "narration": "From Home, open Import Project, then choose External Masks. Use this tool when you already have segmentation labels and want spaCR to measure the corresponding images.", "hold_after": 0.7, "related_lessons": ["36_import", "08_measure"]}, {"visual": "02_choose_real_images", "narration": "Prepare matching intensity images and labelled masks. This example uses two image and cell-mask pairs. Keep each pair aligned and use filenames or metadata that let the importer match the correct field.", "hold_after": 0.7, "related_lessons": ["36_import"]}, {"visual": "04_review_detected_roles", "narration": "Click Add folder for the image folder and again for the masks. Review Use as: choose Image for intensity files and Mask for labels. Set Mask type to the compartment represented by each mask, such as Cell.", "hold_after": 0.7, "focus": [470, 815, 1660, 350]}, {"visual": "04b_image_ignored_not_submitted", "narration": "Set Use as to Ignore for any group you want to leave out. Its files stay on disk. Keep the image group and the masks required for your analysis included.", "hold_after": 0.7, "focus": [470, 815, 1660, 350]}, {"visual": "04c_image_role_restored", "narration": "Restore Image for the example’s intensity group. Check the Image and Cell-mask assignments before choosing the destination.", "hold_after": 0.7, "focus": [470, 815, 1660, 350]}, {"visual": "05_setting_recursive", "narration": "Set Dst to a new project folder. Choose Layout, Z handling and Plate naming to match your files. This example uses flat layout, the first Z plane and index-based plate naming. Use acquisition metadata when original well identities must be retained.", "hold_after": 0.7, "focus": [470, 1120, 1660, 380]}, {"visual": "05_setting_channels", "narration": "Choose the intensity Channels to measure. This example’s TIFFs each contain one intensity plane, so select channel zero and leave Normalize off. Channel numbers refer to the files you are importing.", "hold_after": 0.7, "focus": [470, 1515, 1660, 270]}, {"visual": "05_setting_cytoplasm", "narration": "Choose whether to measure cytoplasm. With cell masks alone, the derived region covers the whole cell. Supply the interior compartment masks when you need them excluded from that region.", "hold_after": 0.7, "focus": [470, 815, 1660, 395]}, {"visual": "05_setting_png_size", "narration": "Under Object Crops, enable Save PNG and choose cell in Crop mode. Set PNG size to two hundred and twenty-four by two hundred and twenty-four. Select channel zero for this single-channel example’s PNG mapping.", "hold_after": 0.7, "focus": [470, 980, 1660, 805]}, {"visual": "05_setting_test_mode", "narration": "Choose the measurement features you need, then enable Save measurements. Use N jobs to set concurrency. Start with a small input set while learning the settings and inspecting the resulting crops.", "hold_after": 0.7, "focus": [470, 810, 1660, 975]}, {"visual": "07_preview_plan_no_project_written", "narration": "Enable Preview only and press Run. Check the proposed image-to-mask pairings, field count and channel layout in the plan. Correct any assignment before writing the project.", "hold_after": 0.7, "focus": [2140, 840, 1670, 440]}, {"visual": "08_preview_only_disabled", "narration": "Turn off Preview only and press Run again. The tool prepares the project’s images and masks, then runs Measure to calculate object features and create the requested crops.", "hold_after": 0.7, "focus": [470, 805, 1660, 535]}, {"visual": "10_external_figure_00_export_preview", "narration": "Inspect the intensity image beside the supplied labels. Check object boundaries, missing objects and image-to-mask alignment before interpreting the measurements.", "hold_after": 0.7, "focus": [50, 550, 3730, 1450]}, {"visual": "10_external_figure_02_export_preview", "narration": "Browse the object montage to inspect the extracted crops. Use the figure viewer to move between fields and check that the selected channels and crop size show the objects clearly.", "hold_after": 0.7, "focus": [50, 550, 3730, 1450]}, {"visual": "11_external_measurement_summary", "narration": "Open measurements/measurements.db for the object tables and data for annotation crops. Keep conversion_map.csv and the source manifest with the project so imported fields remain traceable. Continue in Annotate to label the crops, or use the measurement tables in a downstream analysis.", "hold_after": 0.7, "focus": [990, 1330, 2440, 90]}], "narration_voices": {"en": ["af_heart"]}, "poster": "31_external_masks/poster.jpg", "silent": "31_external_masks/video/31_external_masks_silent.mp4"}, {"id": "32_align_stitch", "number": 32, "slug": "align_stitch", "series": 4, "app_key": "align", "section": "Tools", "title": "Align & Stitch: plan and write an image mosaic", "description": "Choose image tiles, set their acquisition layout, inspect the registration plan, and write the mosaic with its coordinates.", "objectives": ["Choose tiles and set the grid, overlap and registration channel.", "Inspect the planned positions and registration quality.", "Write the mosaic and retain its coordinate database."], "prerequisite": "Download and unzip the nine-tile example below, or prepare image tiles with known acquisition order, overlap and a useful registration channel. The example uses overlapping crops from one microscopy field to provide a practice layout.", "scenes": [{"visual": "01_module", "narration": "From Home’s Tools category, open Align and Stitch. Choose the tiles, review their layout with Plan, then use Write stack to create the mosaic.", "hold_after": 0.7}, {"visual": "02_preserved_real_pixel_tiles", "narration": "Download and unzip the example below, then select its tiles folder. It contains nine overlapping crops arranged in a three-by-three grid. For your own acquisition, keep the original tile order and stage metadata available.", "hold_after": 0.7}, {"visual": "03_actual_layout_and_budget", "narration": "Set the grid to three by three, row-major order and overlap zero point two five for this example. Match these settings to your acquisition; use serpentine order when alternate rows were acquired in opposite directions.", "hold_after": 0.7, "focus": [450, 300, 1800, 170]}, {"visual": "03_actual_layout_and_budget", "narration": "Set Reference channel to the image plane used for registration. This example uses channel one, the second plane with zero-based numbering. Choose a channel with visible structure across overlaps; the resulting placement applies to all image channels.", "hold_after": 0.7, "focus": [450, 300, 1800, 170]}, {"visual": "03_actual_layout_and_budget", "narration": "Set Minimum confidence for accepting a registration and Neighbour radius for the nearby tiles to compare. The example uses zero point three and one, with feather blending across overlaps. The band-buffer budget controls memory used by the image writer.", "hold_after": 0.7, "focus": [450, 300, 1800, 170]}, {"visual": "04_registered_plan_not_yet_written", "narration": "Press Plan. Inspect the registered, nominal and unplaced tile counts and the proposed canvas size. The layout shows tile positions. Review any nominal fallback or unplaced tiles before writing the mosaic.", "hold_after": 0.7, "focus": [1700, 440, 2100, 850]}, {"visual": "05_actual_tile_detail", "narration": "Click a tile to inspect its coordinates, confidence, residual and contributing pairs. Use these details to investigate unexpected positions, then adjust the registration settings and plan again if needed.", "hold_after": 0.7}, {"visual": "05_actual_tile_detail", "narration": "Choose an output folder and a coordinate-database path. Leave Overwrite off when creating a new result. Once the plan and destination are ready, press Write stack.", "hold_after": 0.7, "focus": [450, 1990, 3370, 140]}, {"visual": "06_real_stitch_complete", "narration": "Wait for the completion summary and open the output stack. Inspect the overlaps and object boundaries in the mosaic. Keep the coordinate database and source tiles with it so downstream locations can be traced back to the acquisition.", "hold_after": 0.7, "focus": [1700, 440, 2100, 1100]}], "example_files": ["Align_Stitch_nine_tiles.zip"], "narration_voices": {"en": ["af_heart"]}, "poster": "32_align_stitch/poster.jpg", "silent": "32_align_stitch/video/32_align_stitch_silent.mp4"}, {"id": "33_plate_viewer", "number": 33, "slug": "plate_viewer", "title": "Plate Viewer", "series": 4, "app_key": "plate_view", "section": "Results and quality control", "description": "Explore measurements as plate heatmaps and detect spatial artifacts or edge effects.", "objectives": ["Build an appropriate plate heatmap.", "Recognize spatial and low-count artifacts.", "Inspect and export traceable well summaries."], "prerequisite": "Measure a plate with stable plate and well identifiers.", "scenes": [{"narration": "Plate Viewer turns object measurements into well-level heatmaps with spatial quality checks beside them.", "visual": "01_overview", "hold_after": 0.7, "focus_key": "screen", "speech_text": "Plate Viewer turns object measurements into well-level heat maps with spatial quality checks beside them."}, {"narration": "Open a measurements database or run folder. The source is queried read-only.", "visual": "02_database", "hold_after": 0.7, "focus_key": "source", "speech_text": "Open a measurements database or run folder. The source is queryd read-only."}, {"narration": "Choose the object table, numeric feature, and plate to display.", "visual": "03_measurement", "hold_after": 0.7, "focus_key": "selection", "speech_text": "Choose the object table, numeric feature, and plate to display."}, {"narration": "Select aggregation, color scaling, and the minimum evidence required for a well. Count is useful for spotting segmentation or seeding differences.", "visual": "04_options", "hold_after": 0.7, "focus_key": "options", "speech_text": "Select aggregation, color scaling, and the minimum evidence required for a well. Count is useful for spotting segmentation or seeding differences."}, {"narration": "Render the view, then compare the heatmap with row, column, ring, and edge diagnostics.", "visual": "05_render", "hold_after": 0.7, "focus_key": "render", "speech_text": "Render the view, then compare the heat map with row, column, ring, and edge diagnostics."}, {"narration": "Select a well to inspect its identifier, object count, displayed value, and position.", "visual": "07_well_detail", "hold_after": 0.7, "focus_key": "well_detail", "speech_text": "Select a well to inspect its identifier, object count, displayed value, and position."}, {"narration": "Wells below the evidence threshold become explicit blanks rather than misleading zeros.", "visual": "11_filtered_result", "hold_after": 0.7, "focus_key": "result", "speech_text": "Wells below the evidence threshold become explicit blanks rather than misleading zeros."}, {"narration": "Export the current tidy well grid with counts and spatial annotations for audit or replotting.", "visual": "13_export", "hold_after": 0.7, "focus_key": "export", "speech_text": "Export the current tidy well grid with counts and spatial annotations for audit or replotting."}], "host_app_key": "graph_builder", "poster": "33_plate_viewer/poster.jpg", "silent": "33_plate_viewer/video/33_plate_viewer_silent.mp4"}, {"id": "34_database", "number": 34, "slug": "database", "title": "Database Browser: filter and export measurements", "series": 4, "app_key": "db_browser", "section": "Data", "description": "Open a measurement database, select columns and rows, and export the result.", "objectives": ["Open and browse a measurement table.", "Select columns and filter rows.", "Export the matching records."], "prerequisite": "Have a spaCR measurements.db file or a run folder containing one. Measure’s example project provides a database after measurement.", "scenes": [{"narration": "Open Help, then Database Browser to inspect and export measurement tables.", "visual": "01_overview", "hold_after": 0.7, "focus_key": "screen"}, {"narration": "Choose measurements.db, or the run folder containing it, and open the database.", "visual": "02_open", "hold_after": 0.7, "focus_key": "source"}, {"narration": "Select the table you need. Choose cell for cell measurements, or a different object table for that object’s features.", "visual": "03_tables", "hold_after": 0.7, "focus_key": "tables"}, {"narration": "Read the total row and column counts, then inspect the displayed page. Use the page controls to move through larger tables.", "visual": "04_cell_table", "hold_after": 0.7, "focus_key": "preview"}, {"narration": "Search column names to locate a feature. Select the columns you want to view and export.", "visual": "05_column_search", "hold_after": 0.7, "focus_key": "column_search"}, {"narration": "Build a filter by choosing a column, an operator and a value. Apply it to select matching records across the full table.", "visual": "08_filter", "hold_after": 0.7, "focus_key": "filter"}, {"narration": "Check the filtered row count and inspect the matching records. Adjust or clear the filter to change your selection.", "visual": "09_filtered", "hold_after": 0.7, "focus_key": "status"}, {"narration": "Choose Export and a destination file. The export includes all matching rows and your selected columns, while keeping the source database unchanged.", "visual": "10_export", "hold_after": 0.7, "focus_key": "export"}], "narration_voices": {"en": ["af_heart"]}, "poster": "34_database/poster.jpg", "silent": "34_database/video/34_database_silent.mp4"}, {"id": "35_converter", "number": 35, "slug": "converter", "series": 4, "app_key": "convert", "host_app_key": "foreign", "section": "Data", "title": "Format Converter: preview and convert image files", "description": "Select a source folder, check the target names and channel assignments, then convert images and resume completed work.", "objectives": ["Choose source and destination folders with the correct acquisition layout.", "Preview target names, fields and channel assignments.", "Convert the files and use Resume for completed fields."], "prerequisite": "Prepare a folder of supported image files and retain their acquisition metadata. You can practise with the two TIFF images used in the Import Project tutorial. Set the layout and Z handling for your own acquisition.", "scenes": [{"visual": "01_module", "narration": "From Home, open Import Project and choose Format Converter. Use it to prepare image files and filenames for the next analysis step.", "hold_after": 0.7, "related_lessons": ["36_import", "74_import_images"]}, {"visual": "01b_current_converter_fold", "narration": "Use the converter’s Source, Destination, Preview and Convert controls. Preview displays the planned source-to-target mapping so you can inspect the assignments before writing files.", "hold_after": 0.7, "focus": [460, 600, 3370, 1190]}, {"visual": "02_real_source_folder", "narration": "Choose the folder containing your source images. This example uses two single-channel TIFFs. Keep the original acquisition metadata available when checking the converted names.", "hold_after": 0.7, "related_lessons": ["36_import"]}, {"visual": "03_new_private_destination", "narration": "Choose a new destination folder. The converter writes the new images there together with a mapping file; retain your original images separately.", "hold_after": 0.7}, {"visual": "04_explicit_flat_single_plane_settings", "narration": "Set Layout to match your folders. Choose images directly in source for the example’s flat folder, and select the plate-naming rule you need. For a plate-and-well directory tree, choose its corresponding layout.", "hold_after": 0.7, "focus": [460, 815, 3370, 200]}, {"visual": "04_explicit_flat_single_plane_settings", "narration": "Choose how to handle Z planes. Keep every plane when you need the full stack, use maximum projection for a projected image, or choose the first plane when that is the intended input. This example contains one plane per file.", "hold_after": 0.7, "focus": [460, 870, 3370, 100]}, {"visual": "05_preview_no_output_written", "narration": "Press Preview. Inspect every source-to-target assignment, including plate, well, field and channel. Indexed names are assigned identities; use the original metadata to confirm which experimental conditions they represent.", "hold_after": 0.7, "focus": [460, 995, 3370, 790]}, {"visual": "06_preview_source_channel_and_plane_provenance", "narration": "Review From field and From channel alongside the target names. Channel indexes in arrays and channel numbers in filenames can use different conventions. Check that each target contains the image plane you intend to analyse.", "hold_after": 0.7, "focus": [460, 1020, 2750, 180]}, {"visual": "05_preview_no_output_written", "narration": "If a mapping is wrong, change the source layout or conversion settings and preview again. The preview table is read-only.", "hold_after": 0.7, "focus": [460, 1020, 2750, 180]}, {"visual": "07_actual_conversion_complete", "narration": "Press Convert and read the completion summary for converted, failed and skipped files. Open a converted image to inspect its dimensions and channels before continuing to segmentation or measurement.", "hold_after": 0.7, "focus": [460, 1580, 3370, 210]}, {"visual": "07_actual_conversion_complete", "narration": "Keep conversion_map.csv with the converted images. It records source and target paths, assigned identities and conversion status. Retain the original acquisition metadata alongside it.", "hold_after": 0.7, "focus": [460, 1580, 3370, 210]}, {"visual": "08_resume_enabled", "narration": "For a later run with the same source, plan and destination, enable Resume. Compatible completed fields can be reused. Read the summary to see which files were converted and which were already present.", "hold_after": 0.7, "focus": [2700, 825, 1130, 190]}], "narration_voices": {"en": ["af_heart"]}, "poster": "35_converter/poster.jpg", "silent": "35_converter/video/35_converter_silent.mp4"}, {"id": "36_import", "number": 36, "slug": "import", "series": 5, "title": "Import Project: bring images, masks and measurements into spaCR", "app_key": "foreign", "section": "Data", "description": "Choose matching images, instance masks and measurement tables, review their mapping, and create a spaCR project.", "objectives": ["Match images, masks and measurement rows.", "Review and save the column mapping.", "Import the project and inspect its outputs."], "prerequisite": "Prepare corresponding image files, instance-label masks and a measurement CSV. Keep each field’s original plate and well identity, and use documented measurement units.", "scenes": [{"visual": "01_module", "narration": "From Home’s Data category, open Import. Use this screen to bring existing images, instance masks and measurements into a spaCR project.", "hold_after": 0.7}, {"visual": "02_fold_import_images", "narration": "The header also opens Import Images, Format Converter and External Masks. Choose the tool that matches your starting files; this walkthrough uses images, masks and an existing measurement table together.", "hold_after": 0.7, "focus_buttons": "FoldButton", "related_lessons": ["74_import_images", "35_converter", "31_external_masks"]}, {"visual": "03_choose_images", "narration": "Choose the image folder. The example uses two microscopy fields with one intensity channel and matching cell labels. Keep a record of each file’s original plate, well and field.", "hold_after": 0.7, "related_lessons": ["08_measure"]}, {"visual": "04_choose_masks", "narration": "Choose the Cell mask folder and press Add. Each object needs its own integer label. Add further mask classes when you have corresponding labels for the same fields.", "hold_after": 0.7}, {"visual": "05_choose_table", "narration": "Choose the measurement CSV. Match ImageNumber to each field and ObjectNumber to its mask label. Use both identifiers to distinguish objects across fields.", "hold_after": 0.7}, {"visual": "06_inputs_unknown_calibration", "narration": "Enter micrometres per pixel when you know the calibration; otherwise leave it blank. Check that area and intensity columns retain their documented units.", "hold_after": 0.7, "focus": [350, 440, 3450, 65]}, {"visual": "06b_safe_inferred_names", "narration": "Press Preview to inspect the proposed column mapping and joins before creating the project. Review the suggested foreign-prefixed names and their scientific meaning.", "hold_after": 0.7, "focus": [350, 500, 2650, 155]}, {"visual": "07_conflict_refused", "narration": "Select a target cell and press F two to edit its name. A reserved-name conflict disables Import when Refuse the import is selected; choose a distinct target name or use the Rename policy.", "hold_after": 0.7}, {"visual": "08b_join_report", "narration": "Read the join report and resolve unmatched rows or objects. In the example, all one hundred and three measurement rows match mask objects.", "hold_after": 0.7, "focus": [350, 1830, 3450, 195]}, {"visual": "09_mapping_edited", "narration": "Give the imported area a clear name, such as foreign reviewed area pixels squared. Review the source, target, transform and units together.", "hold_after": 0.7, "focus": [350, 500, 2650, 155]}, {"visual": "10_save_mapping", "narration": "Use Save mapping to keep the reviewed column definitions as a CSV. Keep the mapping with your images, masks, measurement table and acquisition identities.", "hold_after": 0.7}, {"visual": "12_mapping_reloaded", "narration": "Use Load mapping to reuse saved definitions. Review the resulting plan whenever source columns, labels or units differ.", "hold_after": 0.7}, {"visual": "13_imported", "narration": "Press Import and read the completion report. The example writes two image files, two masks and two merged arrays, with one hundred and three rows in each of two object tables.", "hold_after": 0.7}, {"visual": "14_import_scope", "narration": "Open the project and inspect the imported measurements. The foreign columns table records their origin. Use Measure when you want spaCR to calculate new features from the images.", "hold_after": 0.7, "focus": [350, 1830, 3450, 195], "related_lessons": ["08_measure"]}, {"visual": "14_import_scope", "narration": "Keep the conversion map with the project and check its plate, well and field assignments. Generic file names may receive new coordinates, so resolve their original identities before plate-level analysis.", "hold_after": 0.7, "related_lessons": ["74_import_images"]}, {"visual": "14_import_scope", "narration": "Continue in Database Browser to inspect the tables or in Annotate to review object crops. Retain the reviewed mapping with the completed project.", "hold_after": 0.7, "related_lessons": ["06_api", "08_measure"]}], "narration_voices": {"en": ["af_heart"]}, "poster": "36_import/poster.jpg", "silent": "36_import/video/36_import_silent.mp4"}, {"id": "37_batch", "number": 37, "slug": "batch", "series": 5, "app_key": "batch", "section": "Data and batch runs", "title": "Batch Runner: configure and run a queue", "description": "Add module settings, arrange dependencies, run jobs, and inspect their separate logs.", "objectives": ["Add jobs with their settings and dependencies.", "Save, run and continue the queue.", "Inspect each job’s log and outputs."], "prerequisite": "Prepare the input data and exported settings JSON for each job. The example runs three image conversions into separate output folders.", "scenes": [{"visual": "01_help_batch", "narration": "Open Help, then Batch runner. Use it to queue module jobs with their settings files, execution order and separate logs.", "hold_after": 0.7, "related_lessons": ["30_plate_queue"]}, {"visual": "03_choose_settings_1", "narration": "Choose the module and click Choose settings. For this example, select convert and the JSON settings for the first microscopy field.", "hold_after": 0.7, "related_lessons": ["35_converter"]}, {"visual": "04_configure_job_1", "narration": "Check the source and destination in the settings, add a descriptive label, then click Add job. Use a separate output folder for each conversion.", "hold_after": 0.7, "focus": [450, 235, 3370, 255]}, {"visual": "04_configure_job_2", "narration": "For the second job, enter convert one in After to make it depend on the first. Add a setting override when this job needs a different value. Set any input paths explicitly; a dependency controls order.", "hold_after": 0.7, "focus": [450, 235, 3370, 255]}, {"visual": "05_added_job_3", "narration": "Add further jobs and review their identifiers, labels and dependencies. Select a row to load its configuration into the editor.", "hold_after": 0.7, "focus": [450, 530, 3360, 235]}, {"visual": "06b_dependency_error_scrolled", "narration": "Use the move controls to arrange jobs. A dependency must appear before the job that needs it; read any validation message and correct the order.", "hold_after": 0.7, "focus": [450, 1225, 3350, 180]}, {"visual": "07_valid_reordered_queue", "narration": "Click Validate after arranging the queue. Resolve the listed problems until Run queue becomes available.", "hold_after": 0.7, "focus": [450, 530, 3360, 235]}, {"visual": "09_continue_policy", "narration": "Choose On failure to continue with independent jobs or stop at the first failure. Set Stop after to limit consecutive failures.", "hold_after": 0.7, "focus": [450, 440, 1760, 95]}, {"visual": "10_save_queue_picker", "narration": "Click Save queue to store the plan as JSON. Use Load queue to reopen it later, keeping the referenced settings files and inputs available.", "hold_after": 0.7}, {"visual": "14_stopped_between_jobs", "narration": "Click Run queue. To pause between jobs, press Stop; the current job finishes and the remaining jobs stay unrun.", "hold_after": 0.7, "focus": [450, 530, 3360, 235]}, {"visual": "15_completed_real_queue", "narration": "Click Run queue again to continue with the remaining jobs. Watch each row’s status as the queue progresses.", "hold_after": 0.7, "focus": [450, 530, 3360, 235]}, {"visual": "16_log_convert-2", "narration": "Select a row to read its log and inspect errors or output paths. For the conversion example, check the reported field and channel identifiers.", "hold_after": 0.7, "focus": [450, 1380, 3350, 705]}, {"visual": "16_log_convert-1", "narration": "Open each output folder and inspect the converted images and conversion record. Keep the queue JSON, settings and logs with the results.", "hold_after": 0.7, "related_lessons": ["06_api", "35_converter", "30_plate_queue"]}], "narration_voices": {"en": ["af_heart"]}, "poster": "37_batch/poster.jpg", "silent": "37_batch/video/37_batch_silent.mp4"}, {"id": "38_distributed_jobs", "number": 38, "slug": "distributed_jobs", "title": "Distributed Jobs: configure an execution target", "series": 5, "app_key": "distributed_jobs", "section": "Data and batch runs", "description": "Create an execution profile and prepare a module job for another workstation or cluster.", "objectives": ["Create a profile for your execution target.", "Configure paths and backend options.", "Prepare submission and inspect job status."], "prerequisite": "Arrange access to a target with spaCR, its dependencies and your input data. Export the module settings you intend to run. Replace the illustrative host and paths shown here with your own.", "scenes": [{"visual": "01_help_route", "narration": "Open Help, then Distributed jobs. Start by creating an execution profile for the workstation or cluster you want to use.", "focus": [80, 0, 1200, 1500], "related_lessons": ["05_home"], "hold_after": 0.7}, {"visual": "02_empty_actual_workbench", "narration": "Install compatible spaCR dependencies on the target and make the input data available there. Set up SSH keys or your provider’s command-line authentication outside spaCR.", "focus": [455, 155, 3350, 430], "related_lessons": ["06_api", "37_batch"], "hold_after": 0.7}, {"visual": "03_empty_profile_refused", "narration": "Choose New profile. Enter a descriptive name and select the backend. Complete the required fields shown by the form.", "focus": [695, 195, 2210, 1220], "hold_after": 0.7}, {"visual": "06_saved_profile_reopened", "narration": "For SSH, enter your host, remote work directory and spaCR runner. Save the profile, then reopen it whenever you need to update these settings.", "focus": [695, 380, 2210, 390], "hold_after": 0.7}, {"visual": "06_saved_profile_reopened", "narration": "Set the local and remote dataset roots when the same data has different absolute paths on the two machines. This rewrites settings paths; arrange shared storage or copy the files separately.", "focus": [695, 595, 2210, 170], "hold_after": 0.7}, {"visual": "07_slurm_controls_not_submitted", "narration": "For Slurm, choose the partition, time limit and accelerator request supported by your cluster. Keep the host and directory settings appropriate for its login environment.", "focus": [695, 450, 2210, 430], "hold_after": 0.7}, {"visual": "08_custom_argument_templates", "narration": "For a cloud or custom command, enter submit, status and cancel argument templates, plus log retrieval if needed. Include the required settings and external-ID placeholders shown by the controls.", "focus": [695, 805, 2210, 350], "hold_after": 0.7}, {"visual": "05_profile_saved_not_connected", "narration": "Save the changes you want to retain, or use Cancel to leave the profile unchanged. Poll interval sets how frequently to check job status.", "focus": [455, 220, 3350, 205], "hold_after": 0.7}, {"visual": "09_submission_controls_no_job", "narration": "Select the profile, module and its exported settings, then use Submit when the target is ready. Monitor status and logs in the job table. Use Cancel job to stop a selected job, and inspect its results at the configured output location.", "focus": [455, 220, 3350, 1510], "related_lessons": ["37_batch", "40_run_history", "06_api"], "hold_after": 0.7}], "narration_voices": {"en": ["af_heart"]}, "poster": "38_distributed_jobs/poster.jpg", "silent": "38_distributed_jobs/video/38_distributed_jobs_silent.mp4"}, {"id": "39_classifier_evaluation", "number": 39, "slug": "classifier_evaluation", "title": "Classifier Evaluation: inspect predictions and errors", "series": 3, "app_key": "classifier_evaluation", "section": "Tools", "host_app_key": "classify_merged", "description": "Load a saved evaluation bundle, inspect leakage and confusion counts, and filter predictions for review.", "objectives": ["Load a bundle and review leakage.", "Inspect confusion counts and confidence groups.", "Filter predictions and locate saved figures."], "example_files": ["REAL_evaluation_known_overlap.zip"], "prerequisite": "Download and unzip the linked saved-results example. It contains predictions, tables and figures; crops require your matching experiment in Annotate. The example shares wells between training and test data, so use it to learn the inspector rather than estimate independent-well accuracy.", "scenes": [{"visual": "01_classify_host", "narration": "Open Classify, then Classifier Evaluation. Use this inspector to explore a saved evaluation bundle after producing predictions.", "focus": [3510, 105, 320, 80], "related_lessons": ["41_classify"], "hold_after": 0.7}, {"visual": "03_actual_bundle_folder", "narration": "Download and unzip the example below. Click Browse and choose the folder containing evaluation manifest dot json.", "focus": [1563, 798, 1400, 950], "hold_after": 0.7}, {"visual": "04_actual_summary", "narration": "Read Summary for the number of predictions and the recorded class names. The example contains two hundred thirty-four predictions across two classes.", "focus": [475, 650, 3335, 1170], "hold_after": 0.7}, {"visual": "05_actual_leakage_requires_review", "narration": "Open Leakage audit before interpreting accuracy. This example flags wells shared between training and test data. For an independent-well evaluation, prepare a split with separate wells and rerun training and evaluation.", "focus": [475, 650, 3335, 1390], "hold_after": 0.7}, {"visual": "06_actual_confusion_counts", "narration": "Open Confusion matrix. Rows are recorded classes and columns are predictions. The diagonal shows agreement; off-diagonal cells identify disagreements to review.", "focus": [475, 600, 3335, 265], "hold_after": 0.7}, {"visual": "07_actual_error_cell", "narration": "Click a disagreement cell to list its examples. The selected cell contains eleven disagreements, grouped by confidence.", "focus": [475, 1090, 3335, 530], "hold_after": 0.7}, {"visual": "08_actual_confidence_threshold", "narration": "Change Confidence threshold to choose which disagreements enter the high-confidence list. Raising it from zero point seven five to zero point nine five leaves two in the high list and nine in the low list.", "focus": [475, 1090, 3335, 700], "hold_after": 0.7}, {"visual": "07_actual_error_cell", "narration": "Review the selected examples alongside their images and annotations. Use the displayed explanations as prompts for investigation, and check the evidence before changing labels.", "focus": [475, 1170, 3335, 160], "hold_after": 0.7}, {"visual": "09_actual_per_plate", "narration": "Open Per-plate metrics to compare results by plate. This example has one plate; a multi-plate bundle provides separate rows for comparison.", "focus": [475, 595, 3335, 205], "hold_after": 0.7}, {"visual": "10_actual_calibration_table", "narration": "Open Calibration to compare predicted probability with observed class frequency. Check each bin’s count when interpreting the differences.", "focus": [475, 595, 3335, 450], "hold_after": 0.7}, {"visual": "12_actual_prediction_filter", "narration": "Open Predictions and type a sample or well identifier to filter the records. In the example, r five underscore c two selects one well’s predictions.", "focus": [475, 595, 3335, 400], "hold_after": 0.7}, {"visual": "13_actual_filter_cleared", "narration": "Clear the filter to restore all records. To open crops in your own project, first load the matching experiment in Annotate; the downloadable results example contains no crops.", "focus": [475, 595, 2350, 460], "related_lessons": ["09_annotate"], "hold_after": 0.7}, {"visual": "04_actual_summary", "narration": "Find the saved calibration and confusion figures in the bundle folder. Check labels and readability before using them in a report.", "focus": [475, 650, 3335, 1170], "hold_after": 0.7}, {"visual": "14_actual_final_leakage", "narration": "Keep the leakage audit with reported metrics. Use Training Runs to compare saved training progress, and return to Annotate when image or label review is needed.", "focus": [475, 650, 3335, 1390], "related_lessons": ["28_training_runs"], "hold_after": 0.7}], "narration_voices": {"en": ["af_heart"]}, "poster": "39_classifier_evaluation/poster.jpg", "silent": "39_classifier_evaluation/video/39_classifier_evaluation_silent.mp4"}, {"id": "40_run_history", "number": 40, "slug": "run_history", "series": 5, "app_key": "run_history", "section": "Data and batch runs", "title": "Run History: inspect past jobs and restore settings", "description": "Find saved runs, inspect settings and logs, and load a previous configuration into its module.", "objectives": ["Find runs using filters and search.", "Inspect saved settings, files and problems.", "Restore settings for a new run."], "prerequisite": "Complete a spaCR job to create a local run record. The example browses records from conversion, Recruitment and Regression runs.", "scenes": [{"visual": "01_help_history", "narration": "Open Help, then Run history to browse the run records saved on this computer.", "hold_after": 0.7, "related_lessons": ["37_batch", "25_recruitment"]}, {"visual": "02_loaded_history", "narration": "Click Refresh to load available records. Select a run to inspect its details, and drag the divider if you need more room.", "hold_after": 0.7}, {"visual": "03_batch_search", "narration": "Choose a module and status, then enter a search term to narrow the list. For example, select convert and Success to find completed conversions.", "hold_after": 0.7, "focus": [340, 175, 3480, 180]}, {"visual": "04_batch_empty_inventory", "narration": "Open Files and models for recorded input and output details. Runs that skipped file hashing can have an empty inventory; use the output paths in settings or logs to find their results.", "hold_after": 0.7, "focus": [345, 710, 1500, 580], "related_lessons": ["37_batch"]}, {"visual": "05_no_match", "narration": "Clear or adjust the filters if the table is empty. Search terms and status selections work together.", "hold_after": 0.7}, {"visual": "07_recruitment_overview", "narration": "Select a Recruitment run and read Overview for its elapsed time and recorded file counts. These summarize that saved execution.", "hold_after": 0.7, "focus": [345, 710, 2200, 580], "related_lessons": ["25_recruitment"]}, {"visual": "09_settings_source", "narration": "Open Settings to inspect its source folder, channels and object filters. Scroll through the saved configuration before deciding to reuse it.", "hold_after": 0.7, "focus": [345, 710, 3000, 1380]}, {"visual": "10_recorded_files", "narration": "Open Files and models to inspect recorded paths, sizes and hashes. Keep the referenced project files available when you need to revisit the analysis.", "hold_after": 0.7, "focus": [345, 710, 3000, 1380]}, {"visual": "12_hashes_and_seeds", "narration": "Open Environment for recorded software versions and seeds. Use Copy path to locate the run’s journal folder.", "hold_after": 0.7, "focus": [345, 710, 2650, 1380]}, {"visual": "14_recorded_warning", "narration": "Open Warnings and failure to read warnings attached to a completed run. Investigate relevant warnings before using its results.", "hold_after": 0.7, "focus": [345, 710, 3400, 340], "related_lessons": ["13_regression"]}, {"visual": "16_failure_exception", "narration": "Choose Failed to find unsuccessful jobs. Read the traceback and software versions when diagnosing a problem or preparing a bug report.", "hold_after": 0.7, "focus": [345, 710, 2450, 730]}, {"visual": "18_restored_recruitment", "narration": "Return to the desired run and choose Load settings in module. Review the restored controls and current input paths before pressing Run.", "hold_after": 0.7, "related_lessons": ["25_recruitment"]}, {"visual": "17_ready_to_restore", "narration": "Keep the journals you need with your project records. Use Clear all only when you intend to delete run records. Open Report to create a project summary.", "hold_after": 0.7, "related_lessons": ["06_api", "29_report"]}], "narration_voices": {"en": ["af_heart"]}, "poster": "40_run_history/poster.jpg", "silent": "40_run_history/video/40_run_history_silent.mp4"}, {"id": "41_classify", "number": 41, "slug": "classify", "title": "Classify: choose a model and explore its results", "series": 4, "app_key": "classify_merged", "section": "Core", "description": "Choose image or feature classification, load example data, inspect prediction results and open the related tools inside Classify.", "objectives": ["Choose Computer Vision for images or Tabular Machine Learning for measurements.", "Start with test data and follow the matching training walkthrough.", "Inspect predictions and open evaluation, feature and training tools."], "prerequisite": "Open Classify from Home. Use Load test data for an example project. For your own project, prepare object crops or measured features and class labels from annotations or experimental metadata.", "scenes": [{"visual": "main_00_home", "narration": "Open Classify from Home. Start by choosing the classifier family. The image and tabular lessons linked here each walk through a complete example.", "focus_modules": ["classify_merged"], "related_lessons": ["05_home", "10_classify_cv", "11_classify_ml"], "hold_after": 0.7}, {"visual": "main_02_family_choices", "narration": "Choose Computer Vision to learn from object images. Choose Tabular Machine Learning to learn from measured feature columns. Measure provides these inputs, and Annotate lets you add object labels.", "related_lessons": ["07_mask", "08_measure"], "hold_after": 0.7}, {"visual": "ml_02_data_choice_load", "narration": "For the tabular example, click Load test data and choose Load. Select your class labels and feature settings, then follow the tabular lesson to train the model and save predictions.", "related_lessons": ["11_classify_ml", "09_annotate"], "hold_after": 0.7}, {"visual": "ml_25_ml_figure_02", "narration": "After the tabular run, inspect the prediction heatmap and saved object scores. Objects with missing required measurements may remain unscored. Check the evaluation results to decide whether to revise your labels, features or model settings.", "focus": [2090, 190, 1720, 1200], "related_lessons": ["11_classify_ml"], "hold_after": 0.7}, {"visual": "cv_24_batch_figure", "narration": "For image classification, follow the Computer Vision lesson to prepare labelled crops, choose a model, and set the training, validation and test splits. After training, inspect the evaluation figures and saved predictions.", "focus": [2090, 180, 1720, 1320], "related_lessons": ["10_classify_cv"], "hold_after": 0.7}, {"visual": "main_05_classifier_evaluation_tooltip", "narration": "Open Classifier Evaluation from the top-right tools. Select a saved evaluation bundle to inspect predictions, metrics and the data split.", "focus": [2690, 65, 1120, 280], "related_lessons": ["39_classifier_evaluation"], "hold_after": 0.7}, {"visual": "main_05_explain_cv_tooltip", "narration": "Open Explain CV to relate an image classifier’s predictions to measured features. Supply the image prediction results and the corresponding measurements, then inspect which features explain the scores.", "focus": [2480, 65, 1330, 280], "related_lessons": ["70_explain_cv"], "hold_after": 0.7}, {"visual": "main_05_activation_tooltip", "narration": "Open Activation to view which image regions influence model responses. Select the trained checkpoint and use the same image channels and preprocessing as during training.", "focus": [2930, 65, 880, 280], "related_lessons": ["16_activation"], "hold_after": 0.7}, {"visual": "main_05_train_compare_tooltip", "narration": "Open Training Runs to compare saved training histories. Select runs with compatible metrics and data splits, then inspect their learning curves and settings.", "focus": [2600, 65, 1210, 300], "related_lessons": ["28_training_runs"], "hold_after": 0.7}, {"visual": "main_06_feature_explorer_nested", "narration": "Open Feature Explorer to compare measured features between selected groups. Choose the groups and filters, then inspect the feature ranking and plots.", "related_lessons": ["65_feature_explorer"], "hold_after": 0.7}, {"visual": "ml_25_ml_figure_02", "narration": "Keep your trained model, predictions and evaluation results in the run folder. You can use object scores in Regression together with matching guide counts. The linked module lessons show the next steps.", "focus": [2090, 190, 1720, 1200], "related_lessons": ["06_api", "10_classify_cv", "11_classify_ml"], "hold_after": 0.7}], "narration_voices": {"en": ["af_heart"]}, "poster": "41_classify/poster.jpg", "silent": "41_classify/video/41_classify_silent.mp4"}, {"id": "42_curate", "number": 42, "slug": "curate", "title": "Curate: edit masks and tracks", "series": 5, "app_key": "curate", "host_app_key": "make_masks", "section": "Make Masks", "example_files": ["Curate_SYNTHETIC_practice.zip"], "description": "Practise brush edits, track splitting and joining, and save the corrected files.", "objectives": ["Edit a label mask with the brush and undo controls.", "Split, join and save tracks.", "Preserve source files and curation history."], "prerequisite": "Download the synthetic practice archive and work on copies. Keep separate backups of masks and their .curation.json sidecars before reopening: saving a reopened mask currently replaces its earlier edit log.", "scenes": [{"visual": "02_actual_curate_page", "narration": "Open Make Masks, then Curate to edit label masks and tracks. Download the synthetic practice example below and keep an untouched copy.", "related_lessons": ["14_make_masks", "17_timelapse"], "hold_after": 0.7}, {"visual": "04_original_sixteen_label_mask", "narration": "Browse to the example’s integer-label TIFF. Each object has its own label, with zero reserved for background. Use the TIFF example for this walkthrough.", "hold_after": 0.7}, {"visual": "05_practice_disk_not_a_real_object", "narration": "Set Brush radius to eight and click New to select a new label. Click an empty part of the practice image to paint a small region.", "focus": [355, 470, 3450, 660], "hold_after": 0.7}, {"visual": "06_undo_restores_every_original_pixel", "narration": "Click Undo stroke to remove the last brush edit. Paint again and inspect the result before saving.", "focus": [3380, 480, 425, 710], "hold_after": 0.7}, {"visual": "07_saved_mask_and_ledger", "narration": "Click Save mask to write the working TIFF and its curation sidecar. Before reopening, preserve both files in a new backup folder; the download includes a checkpoint script for this step.", "focus": [3380, 480, 425, 710], "hold_after": 0.7}, {"visual": "10_second_session_saved_history", "narration": "Keep each session’s backup and edit notes. Reopening a mask starts a new in-memory log, and another save replaces its sidecar with that session’s history.", "hold_after": 0.7}, {"visual": "13_overlapping_tracks_cannot_join", "narration": "Browse to the tracks CSV and select tracks to review. Join accepts tracks with non-overlapping frame ranges; an overlap produces a message to resolve first.", "focus": [3380, 480, 425, 1250], "hold_after": 0.7}, {"visual": "14_split_tail_starts_at_frame_four", "narration": "Select track two, set Split at frame to four, and click Split. The later frames move to a new track while the earlier frames retain the original identifier.", "focus": [3380, 480, 425, 1250], "hold_after": 0.7}, {"visual": "16_saved_tracks_and_history", "narration": "Select the two non-overlapping halves and click Join to combine them. Click Save tracks to write the CSV and its separate curation sidecar.", "focus": [3380, 480, 425, 1250], "hold_after": 0.7}, {"visual": "17_unsaved_delete_removes_eight_rows", "narration": "Use Delete only for tracks you intend to remove. To discard an unsaved change, reopen the last saved CSV.", "focus": [3380, 480, 425, 1250], "hold_after": 0.7}, {"visual": "19_saved_tracks_and_two_actions_return", "narration": "Inspect the reopened tracks and saved history. Keep originals and reasons for edits, and rerun any downstream analysis affected by corrected masks or trajectories.", "related_lessons": ["06_api", "17_timelapse"], "hold_after": 0.7}], "narration_voices": {"en": ["af_heart"]}, "poster": "42_curate/poster.jpg", "silent": "42_curate/video/42_curate_silent.mp4"}, {"id": "43_illumination", "number": 43, "slug": "illumination", "title": "Illumination: estimate and inspect a correction model", "series": 5, "app_key": "illumination", "host_app_key": "measure", "section": "Data", "description": "Choose image channels, estimate an illumination field, inspect its QC figure, and reuse the saved model.", "objectives": ["Select representative fields and intensity channels.", "Estimate and inspect an illumination model.", "Reuse the model in Mask or Measure."], "prerequisite": "Use a merged image folder with representative fields from each acquisition group. The example uses the sixteen fields from Measure’s downloaded plate example. Know which stored planes contain intensities and which contain labels.", "scenes": [{"visual": "01_measure_host", "narration": "Open Measure, then Illumination to estimate a correction model for uneven image brightness.", "focus": [3625, 65, 110, 100], "related_lessons": ["08_measure"], "hold_after": 0.7}, {"visual": "05_setting_src", "narration": "Set Source to the merged folder containing image arrays. Use representative fields from your acquisition; the example uses sixteen fields from one plate.", "focus": [363, 375, 1140, 160], "related_lessons": ["07_mask", "08_measure"], "hold_after": 0.7}, {"visual": "05_setting_channels", "narration": "Set Channels to the stored intensity planes you want to correct. The example uses channel zero. Check your channel mapping and exclude label-mask planes.", "focus": [374, 475, 850, 65], "hold_after": 0.7}, {"visual": "04_correction_off_finished", "narration": "Enable Illumination correction before estimating a field. When it is off, Run completes without creating a correction model.", "focus": [1518, 405, 2280, 260], "hold_after": 0.7}, {"visual": "05_setting_illumination_degree", "narration": "Choose an estimator and its settings. For the polynomial example, use degree four and leave Illumination model empty to estimate a new field. Inspect the result for structures that belong to cells rather than illumination.", "focus": [363, 550, 1140, 300], "hold_after": 0.7}, {"visual": "05_setting_illumination_max_fields", "narration": "Enable Illumination per plate to fit separate acquisition groups. Set Maximum fields to a representative sample; the example includes all sixteen available fields.", "focus": [363, 858, 1140, 160], "hold_after": 0.7}, {"visual": "05_setting_illumination_dark", "narration": "Set Illumination dark from your camera calibration when available. It is an additive offset in raw counts; zero is the example setting.", "focus": [374, 775, 1110, 61], "hold_after": 0.7}, {"visual": "05_setting_illumination_on_missing", "narration": "Enable Illumination QC and choose a missing-model policy. With error selected, a missing plate correction stops processing so you can resolve it.", "focus": [363, 1020, 1140, 150], "hold_after": 0.7}, {"visual": "06_correction_on_finished", "narration": "Press Run and read the saved model path in the console. This step estimates the model; enable it in a subsequent analysis to apply the correction.", "focus": [1518, 405, 2280, 485], "hold_after": 0.7}, {"visual": "08_exported_qc_system_viewer", "narration": "Open the saved illumination QC PNG in the illumination folder. Use an image viewer if it does not appear in the Figures panel.", "focus": [200, 100, 3440, 1920], "hold_after": 0.7}, {"visual": "08_exported_qc_system_viewer", "narration": "Inspect the estimated illumination field for smooth brightness variation and unwanted cell-shaped structure. Correction subtracts the dark offset and divides by this mean-one field.", "focus": [400, 680, 790, 825], "hold_after": 0.7}, {"visual": "08_exported_qc_system_viewer", "narration": "Compare the before and after radial profiles. Use additional fields to assess how well the correction works beyond the images used to fit it.", "focus": [1270, 680, 1080, 840], "hold_after": 0.7}, {"visual": "09_return_to_illumination", "narration": "To reuse the model, set its path and enable correction in the intended Mask or Measure workflow. Keep its channels, plate identities and settings with it, and avoid correcting the same intensities twice.", "focus": [363, 370, 1140, 800], "related_lessons": ["07_mask", "08_measure"], "hold_after": 0.7}], "narration_voices": {"en": ["af_heart"]}, "poster": "43_illumination/poster.jpg", "silent": "43_illumination/video/43_illumination_silent.mp4"}, {"id": "44_data_manager", "number": 44, "slug": "data_manager", "series": 5, "app_key": "data_manager", "section": "Data and batch runs", "title": "Data Manager: inspect usage, clean up and archive", "description": "Review project storage, preview a cleanup plan, and move a project to an archive destination.", "objectives": ["Inspect project disk usage.", "Review and apply a cleanup plan.", "Move and rescan an archived project."], "prerequisite": "Use a completed spaCR project and keep an independent backup before cleanup. The example uses a copy of the project produced by External Masks.", "scenes": [{"visual": "01_help_data_manager", "narration": "Open Help, then Data manager. Choose a completed project to inspect its storage and plan cleanup or archiving.", "hold_after": 0.7, "related_lessons": ["31_external_masks"]}, {"visual": "03_actual_usage", "narration": "Click Choose project and select the project root. Read Usage for its files, disk space and registered artifacts.", "hold_after": 0.7, "focus": [345, 175, 3400, 570]}, {"visual": "04_prune_choices", "narration": "Open Prune and select the artifact types to consider. Leave measurement databases and model weights unchecked when you want to keep them, then click Show what can be deleted.", "hold_after": 0.7, "focus": [345, 245, 3470, 230]}, {"visual": "05_real_prune_plan", "narration": "Review the proposed files, space saving and recovery information. The example selects the object-crop folder. Keep the inputs and settings needed to regenerate anything you remove.", "hold_after": 0.7, "focus": [345, 320, 3450, 160]}, {"visual": "09_confirmation_locked", "narration": "Click Delete to review the final file list. Deletion cannot be undone, so check the paths and your backup before acknowledging the plan.", "hold_after": 0.7}, {"visual": "11_acknowledged_not_deleted", "narration": "Use Cancel if you want to keep the files or revise the selection. Acknowledging the list enables the final Delete action.", "hold_after": 0.7}, {"visual": "14_actual_cleanup_result", "narration": "Confirm Delete when the plan is correct. Read the result for the number of removed files and space recovered.", "hold_after": 0.7, "focus": [345, 175, 2500, 240]}, {"visual": "15_usage_after_cleanup", "narration": "Review the updated Usage scan. Removed artifacts may remain listed as missing with their recorded recipe; regenerate them through the appropriate module when needed.", "hold_after": 0.7, "focus": [345, 170, 3450, 580]}, {"visual": "16_updated_archive_plan", "narration": "Open Archive and choose an empty destination outside the source project. Click Show what would move and inspect both paths.", "hold_after": 0.7}, {"visual": "17_archive_default_no", "narration": "Click Move to review the confirmation. Archive moves the project, so keep any separate backup you need before proceeding.", "hold_after": 0.7}, {"visual": "19_archive_confirm_yes", "narration": "Confirm Yes to move the project. Keep the manifest at the destination and the archive log left at the original location.", "hold_after": 0.7}, {"visual": "22_rescan_archived_project", "narration": "Select the destination as the project and scan it again. Check the moved files and update any external references that still point to the old location.", "hold_after": 0.7, "focus": [345, 80, 3470, 670]}, {"visual": "22_rescan_archived_project", "narration": "Use Database Browser to inspect measurement tables, Report to make a project summary, and Data Manager for storage maintenance. Keep the archive records with your project documentation.", "hold_after": 0.7, "related_lessons": ["06_api", "34_database", "29_report"]}], "narration_voices": {"en": ["af_heart"]}, "poster": "44_data_manager/poster.jpg", "silent": "44_data_manager/video/44_data_manager_silent.mp4"}, {"id": "45_project_browser", "number": 45, "slug": "project_browser", "series": 5, "app_key": "project_browser", "section": "Data and batch runs", "title": "Project Browser: find and inspect projects", "description": "Search project folders, inspect recorded stages, and identify the next tool to open.", "objectives": ["Discover projects using roots and search depth.", "Inspect artifacts and recorded stages.", "Choose the next relevant tool."], "prerequisite": "Choose folders containing your spaCR projects. Completed External Masks and Format Converter examples can be used for practice.", "scenes": [{"visual": "01_help_project_browser", "narration": "Open Help, then Project browser to find project folders and inspect their recorded outputs.", "hold_after": 0.7, "related_lessons": ["31_external_masks", "37_batch"]}, {"visual": "04_depth_zero_no_projects", "narration": "Click Add folder and choose a search root. Depth zero checks that folder itself; increase the depth when projects are inside subfolders.", "hold_after": 0.7, "focus": [345, 170, 3450, 360]}, {"visual": "05_real_unregistered_conversion", "narration": "Set Depth to one and click Scan to include folders immediately below the root. Inspect the resulting project rows.", "hold_after": 0.7, "focus": [345, 180, 3450, 660]}, {"visual": "05_real_unregistered_conversion", "narration": "Read State and Stage alongside the files found on disk. A folder without an artifact registry may show unknown even when it contains converted images.", "hold_after": 0.7, "focus": [345, 300, 3450, 560], "related_lessons": ["37_batch", "40_run_history"]}, {"visual": "07_two_real_projects", "narration": "Add further search roots to include other projects. Select a row to inspect it; if details are blank after a rescan, select another row and return.", "hold_after": 0.7, "focus": [345, 225, 3450, 260]}, {"visual": "09_enlarged_details", "narration": "Drag the divider to widen the details. Review recorded artifacts, unregistered files and the source of the last-run timestamp.", "hold_after": 0.7, "focus": [2020, 300, 1790, 260]}, {"visual": "10_stages_and_next_steps", "narration": "Open Stages to see which expected outputs are present. Use What could run next to choose a relevant workflow, then check that module’s required inputs.", "hold_after": 0.7, "focus": [2020, 520, 1790, 650], "related_lessons": ["31_external_masks"]}, {"visual": "12_size_descending", "narration": "Click a column heading such as Size to sort projects. Click it again to reverse the order.", "hold_after": 0.7, "focus": [345, 300, 1680, 170]}, {"visual": "14_depth_zero_keeps_direct_project", "narration": "Adjust Depth and scan again when you need a narrower or wider search. A directly selected project remains discoverable at depth zero.", "hold_after": 0.7, "focus": [345, 175, 3450, 340]}, {"visual": "16_remove_search_root_only", "narration": "Select a root and click Remove to stop searching it. This removes the search location from the list while leaving its files on disk.", "hold_after": 0.7}, {"visual": "18_restored_project_inventory", "narration": "Open Run History for job records, Database Browser for measurements, or Data Manager for cleanup and archiving. Use the relevant module tutorial to continue the analysis.", "hold_after": 0.7, "related_lessons": ["06_api", "40_run_history", "34_database", "44_data_manager"]}], "narration_voices": {"en": ["af_heart"]}, "poster": "45_project_browser/poster.jpg", "silent": "45_project_browser/video/45_project_browser_silent.mp4"}, {"id": "46_napari_bridge", "number": 46, "slug": "napari_bridge", "title": "Napari Bridge: edit and return a label mask", "series": 5, "app_key": "napari_bridge", "host_app_key": "make_masks", "section": "Mask correction", "description": "Open an image and mask in napari, edit labels, and save the corrected mask back to spaCR.", "objectives": ["Open corresponding image and label files.", "Edit and undo changes in napari.", "Return and inspect the saved mask."], "example_files": ["SYNTHETIC_napari_example.zip"], "prerequisite": "Install the optional napari dependency and unzip the synthetic example into a new folder. Keep an untouched backup: Take the mask back overwrites the selected working mask. Close and reopen the viewer between saved editing rounds.", "scenes": [{"visual": "02_actual_bridge", "narration": "Open Make Masks, then Napari Bridge. Use it to edit an existing label mask with its intensity image as a reference. Keep an untouched backup of the mask.", "focus": [460, 235, 3350, 510], "related_lessons": ["14_make_masks"], "hold_after": 0.7}, {"visual": "05_ready_to_open", "narration": "Download and unzip the synthetic example. Choose mask dot tif for Mask and image dot tif for Image, then press Open in napari.", "focus": [460, 365, 3350, 370], "hold_after": 0.7}, {"visual": "06_actual_napari_layers", "narration": "Select the mask Labels layer in napari. Label zero is background; each object label has a display colour. Make edits on the labels layer.", "hold_after": 0.7}, {"visual": "07_unchanged_round_trip", "narration": "Return to spaCR and use Take the mask back to import the viewer’s current labels. If you have made no changes, the status reports that the mask is unchanged.", "focus": [460, 445, 3350, 295], "hold_after": 0.7}, {"visual": "08_fill_one_synthetic_object", "narration": "For practice, select label eighteen, choose Fill, and click the object labelled two. Inspect the changed label before importing it.", "hold_after": 0.7}, {"visual": "09_actual_napari_undo", "narration": "Use Undo to reverse the last viewer edit. Repeat the Fill operation when you are ready to keep the change.", "hold_after": 0.7}, {"visual": "11_imported_and_recorded", "narration": "Click Take the mask back in spaCR. Review the changed-pixel count, then inspect the saved mask and its correction-history sidecar.", "focus": [460, 445, 3350, 295], "hold_after": 0.7}, {"visual": "12d_closed_before_next_edit", "narration": "Click Close viewer and reopen the mask before the next editing round. This makes the saved mask the starting point for subsequent corrections.", "focus": [460, 445, 3350, 295], "hold_after": 0.7}, {"visual": "14_history_preserved_after_reopen", "narration": "After the next edit, take the mask back and inspect the result again. Close the viewer when finished, keep the correction history, and rerun measurements affected by the changed labels.", "focus": [460, 445, 3350, 295], "related_lessons": ["08_measure", "06_api"], "hold_after": 0.7}], "narration_voices": {"en": ["af_heart"]}, "poster": "46_napari_bridge/poster.jpg", "silent": "46_napari_bridge/video/46_napari_bridge_silent.mp4"}, {"id": "47_barcode_qc", "number": 47, "slug": "barcode_qc", "title": "Barcode QC: inspect read depth and choose a cutoff", "series": 5, "app_key": "barcode_qc", "host_app_key": "map_barcodes", "section": "Map Barcodes", "description": "Load mapped counts, review well and guide coverage, and compare abundance thresholds.", "objectives": ["Choose count inputs and QC settings.", "Inspect coverage and positional effects.", "Compare thresholds and keep the resulting tables and plots."], "prerequisite": "Use plate_1_unique_combinations.csv from the downloaded example-screen data in the Regression tutorial, or your own mapped count table. Choose a new output folder. Supply mapping-QC and barcode-reference files when you need checks that depend on unmapped reads or the expected library.", "scenes": [{"visual": "02_barcode_qc_fold", "narration": "Open Map Barcodes, then Barcode QC. Start from a mapped count table; the linked Regression example provides one for practice.", "related_lessons": ["12_map_barcodes", "13_regression"], "hold_after": 0.7}, {"visual": "04_actual_count_input", "narration": "Set Count data to your count table and choose a new output destination. The example contains mapped reads across three hundred eighty-four wells.", "hold_after": 0.7}, {"visual": "05_01_target_grnas_per_well", "narration": "Set Target gRNAs per well from your experimental design and choose the summary method used to derive the cutoff. The example uses five and median.", "hold_after": 0.7}, {"visual": "05_04_starved_read_fraction", "narration": "Set Starved read fraction to flag wells with low reads relative to the plate median. The example uses zero point one. Review flagged wells before excluding them.", "hold_after": 0.7}, {"visual": "05_09_plot", "narration": "Enable Plot and Save, then press Run. Add mapping-QC or reference inputs when you want their corresponding checks; the count table alone describes observed mapped reads.", "hold_after": 0.7}, {"visual": "07_finished_console", "narration": "Read the completion log and saved output paths. Investigate errors against the selected inputs before using the results.", "hold_after": 0.7}, {"visual": "08_actual_figures_state", "narration": "Open barcode QC dot PNG and threshold sweep dot PNG from the output folder. Use an image viewer if the Figures panel is empty.", "hold_after": 0.7}, {"visual": "09_saved_barcode_qc", "narration": "Inspect read depth, row and column effects, and guide representation. Compare with a reference library when you need to identify expected guides that are missing entirely.", "hold_after": 0.7}, {"visual": "10_saved_threshold_sweep", "narration": "Inspect the threshold sweep. In this example, a cutoff near one point two one percent of each well’s reads gives a median of five guides while retaining about fifty-eight percent of mapped reads.", "hold_after": 0.7}, {"visual": "10_saved_threshold_sweep", "narration": "Compare retained reads, retained wells and wells above the guide target as the cutoff changes. Choose a cutoff appropriate to your design; the guide target does not establish single-guide attribution.", "hold_after": 0.7}, {"visual": "11_back_to_actual_gui", "narration": "Keep the recommendation, sweep table, plots and settings with the source counts. Use the chosen cutoff consistently in the downstream analysis and record the reason for your choice.", "related_lessons": ["06_api", "13_regression"], "hold_after": 0.7}], "narration_voices": {"en": ["af_heart"]}, "poster": "47_barcode_qc/poster.jpg", "silent": "47_barcode_qc/video/47_barcode_qc_silent.mp4"}, {"id": "48_hit_list", "number": 48, "slug": "hit_list", "title": "Hit List: inspect candidates with an explicit companion window", "series": 5, "app_key": "hit_list", "host_app_key": "regression", "section": "Regression", "example_files": ["Hit_List_real_results_companion.zip"], "description": "Use unchanged Regression results to explore real Hit List filters and exports, while explicitly working around the hidden native panel.", "objectives": ["Distinguish the broken native shortcut from the external companion.", "Interpret ranked candidates without claiming significant discoveries.", "Filter, restore and export the actual result rows."], "prerequisite": "Extract Hit_List_real_results_companion.zip. Activate your spaCR environment and run python hit_list_companion.py, then Browse to results. The companion wraps the unmodified HitListScreen; it does not repair Regression navigation or wire Investigate. The archive contains original Regression outputs, not a full project. There are 325 genes, 434 guide rows and zero genes passing q <= .05. Effects are standardized marginal effects, not simultaneous multivariable coefficients. Missing intervals are unavailable. Exported n_obs=0 does not report actual well support: use results_gene.csv wells_with_gene, which ranges from 2 to 48. Metadata joins, penalised ranking and Investigate are outside this demonstration. No model training, new regression, GPU or AI-provider request is needed. API: spacr.hits.build_hit_list and HitList.filter/write_csv/to_markdown/to_html.", "scenes": [{"visual": "01b_hit_list_route_failure", "narration": "Hit List belongs under Regression. In this build, clicking Hits selects a page inside a hidden panel, so the list does not appear. This tutorial shows that limitation openly. The following window is an external companion, not evidence that the native shortcut has been repaired.", "related_lessons": ["13_regression"], "hold_after": 0.7}, {"visual": "01c_explicit_companion_not_native_route", "narration": "Extract the linked example, activate your spaCR environment, and run the bundled Hit List companion script. The labelled companion opens spaCR's existing Hit List widget without changing its calculations. Click Browse and select the extracted results folder. No regression is rerun, and Investigate integration is not connected here.", "hold_after": 0.7}, {"visual": "03_all_325_ranked_genes_not_discoveries", "narration": "The original example loads three hundred twenty-five genes. Double-click column boundaries if values are clipped. Read effect direction, raw P, corrected q and guide agreement separately. Missing confidence intervals are unavailable. These are standardized marginal effects; the exported observation-count zero is not the true number of supporting wells.", "hold_after": 0.7}, {"visual": "04_no_genes_pass_q_point05", "narration": "Set Max q to zero point zero five. No genes remain because the smallest gene q-value is about zero point two seven one. An empty filtered table is not an import failure. Restore Max q to one to recover all candidates; this does not declare them discoveries.", "hold_after": 0.7}, {"visual": "06_at_least_two_tested_guides", "narration": "Minimum guides two keeps one hundred seventeen genes with at least two tested guide rows. This counts available evidence, not every guide originally designed for a library. The filter changes the displayed subset without recomputing the original multiple-testing correction.", "hold_after": 0.7}, {"visual": "07_all_tested_guides_same_sign", "narration": "Minimum agreement one additionally keeps fifty-seven genes whose tested guides all share the gene effect's sign. Agreement is not proof of significance or causality. The summary still reports zero significant corroborated genes, even though these candidate rows have agreeing guides.", "hold_after": 0.7}, {"visual": "08_hide_controls_not_recalculate_q", "narration": "Hide controls removes one control row, leaving fifty-six candidates in this subset. Restore it before the later export. Removing controls from view does not refit the model or change the correction family; retain their identities when interpreting your analysis.", "hold_after": 0.7}, {"visual": "10_positive_effect_magnitude_cut", "narration": "With the other filters cleared, Direction up shows positive effects. Adding a minimum absolute effect of zero point one leaves sixteen rows here. These are illustrative display choices, not recommended thresholds. Restore direction and effect controls before searching or comparing a different subset.", "hold_after": 0.7}, {"visual": "13_real_gene_returns", "narration": "Search a recorded identifier to inspect one real row. An unmatched query gives an empty table; returning to the known identifier restores it, and clearing search restores the population. This demonstrates reversible filtering. Annotation imports and the separate Investigate workflow require their own checks.", "hold_after": 0.7}, {"visual": "17_export_html_complete", "narration": "For export, restore two guides, full agreement, controls included and an empty search. All three exports contain the same fifty-seven candidates in this example. Markdown and HTML round numbers; CSV preserves numerical detail. Save the filter choices separately, because the files do not record every setting.", "hold_after": 0.7}, {"visual": "18_original_ranked_population_restored", "narration": "Clear the filters to recover all three hundred twenty-five genes. Keep exported subsets separate from unchanged originals and do not label nonsignificant candidates as validated hits. Python offers the same Hit List reader and filters, but check the format-specific row limits when exporting larger lists.", "related_lessons": ["06_api", "72_volcano_explorer"], "hold_after": 0.7}], "poster": "48_hit_list/poster.jpg", "silent": "48_hit_list/video/48_hit_list_silent.mp4"}, {"id": "49_methods_results", "number": 49, "slug": "methods_results", "title": "Methods & Results: draft and export a run report", "series": 5, "app_key": "methods_export", "host_app_key": "regression", "section": "Regression", "description": "Select a completed run, build its report, review the recorded settings and results, and export Markdown.", "objectives": ["Select the project, run journal and matching result folder.", "Build a digest and review the Methods, Results and Caveats tabs.", "Copy the report text or export Markdown with the run digest."], "prerequisite": "Complete the Regression example first. Keep its project folder, run journal and guide_permutation results together. Review inferred settings, analysis versions and statistical thresholds before using the generated text in a report.", "scenes": [{"visual": "01_regression_methods_host", "narration": "From Home, open Regression, then Methods and Results. Use this tool to draft a report from a completed analysis. This walkthrough continues with the saved run from the Regression example.", "related_lessons": ["13_regression"], "hold_after": 0.7}, {"visual": "02_real_project_journal_and_result_sources", "narration": "Choose the project folder, the run journal and the matching regression-results folder. Leave Classifier empty for this regression example. Confirm that all selected files belong to the run you want to describe.", "focus": [355, 270, 3450, 410], "hold_after": 0.7}, {"visual": "03_actual_deterministic_methods", "narration": "Click Build digest, then read the Methods and Results tabs. Check the analysis version against the saved run environment; the exporter version can differ from the version that performed the analysis.", "hold_after": 0.7}, {"visual": "04_actual_seed_caveat", "narration": "Read Caveats and compare seed entries by name with the saved settings. A permutation seed and a global seed refer to different generators. Leave an unrecorded historical seed unknown when editing the report.", "focus": [355, 640, 3450, 760], "hold_after": 0.7}, {"visual": "05_digest_run_record", "narration": "Open Run digest to inspect the structured settings and source records. Compare them with the prose and review warnings about missing reports or inferred defaults before sharing the draft.", "focus": [355, 680, 2400, 1120], "hold_after": 0.7}, {"visual": "06_zero_significant_genes_and_ranked_candidates", "narration": "In Results, inspect effect sizes and corrected q-values together. This example has no genes below a q-value threshold of zero point zero five. Describe the listed rows as ranked candidates when editing a heading that calls them hits.", "focus": [355, 680, 3450, 700], "hold_after": 0.7}, {"visual": "07_copy_sections_is_not_scientific_approval", "narration": "Click Copy sections to copy the displayed Methods and Results. Review the copied text against the source records. Use Export Markdown when you also need the structured run digest.", "hold_after": 0.7}, {"visual": "08_export_unreviewed_markdown_picker", "narration": "Click Export Markdown and choose a new filename. The file contains both report sections and the run digest as an appendix. Keep an original draft and save your reviewed revisions separately.", "focus": [1550, 780, 760, 540], "hold_after": 0.7}, {"visual": "09_actual_export_completed_not_approved", "narration": "Draft with AI is optional and sends the digest to your configured provider. Review its contents before using that option, then check any generated text against the saved analysis. You can also use build_digest, render_methods and render_results from Python.", "focus": [355, 560, 3450, 660], "related_lessons": ["06_api", "13_regression"], "hold_after": 0.7}], "narration_voices": {"en": ["af_heart"]}, "poster": "49_methods_results/poster.jpg", "silent": "49_methods_results/video/49_methods_results_silent.mp4"}, {"id": "50_run_compare", "number": 50, "slug": "run_compare", "title": "Run Compare: compare saved runs", "series": 5, "app_key": "run_compare", "section": "Data", "example_files": ["Run_Compare_real_snapshots.zip"], "description": "Choose two saved runs, inspect settings and count differences, and check available result comparisons.", "objectives": ["Select baseline and comparison runs.", "Inspect settings and count differences.", "Locate available result comparisons."], "prerequisite": "Download and unzip the linked snapshots. Follow its README to run prepare_run_compare_download.py in your spaCR environment with a new destination folder. For your own comparisons, preserve each run’s outputs before they are overwritten.", "scenes": [{"visual": "01_home_data", "narration": "From Home’s Data category, open Run Compare to inspect outputs recorded for two runs.", "focus_modules": ["run_compare"], "related_lessons": ["08_measure", "40_run_history"], "hold_after": 0.7}, {"visual": "02_actual_empty_compare", "narration": "Download and unzip the snapshot example. Follow its README to run the preparation script with a new destination folder.", "hold_after": 0.7}, {"visual": "03_actual_snapshot_project_picker", "narration": "Click Browse and select the prepared comparison folder. Keep original projects and their run snapshots available for your own comparisons.", "hold_after": 0.7}, {"visual": "04_two_actual_runs_no_setting_change", "narration": "Choose a baseline run as A and the comparison run as B, then click Compare. Check their module names and recorded versions.", "focus": [350, 235, 3450, 190], "hold_after": 0.7}, {"visual": "05_actual_unchanged_settings", "narration": "Enable Show unchanged settings to include matching values. Expand entries to inspect the configuration used by each run.", "focus": [350, 360, 2300, 1400], "hold_after": 0.7}, {"visual": "06_actual_equal_object_counts", "narration": "Open Counts to compare object totals. Delta is B minus A. The example has matching counts; inspect the relevant images and measurements when you need to understand a difference.", "focus": [350, 425, 1250, 720], "hold_after": 0.7}, {"visual": "07_actual_no_hit_list", "narration": "Open Hits when both runs have registered regression results. The example contains Measure snapshots, so no hit comparison is available.", "focus": [350, 405, 2400, 330], "related_lessons": ["13_regression", "40_run_history"], "hold_after": 0.7}, {"visual": "08_actual_same_run_warning", "narration": "Choose two distinct runs. If the same run is selected on both sides, use the warning to correct the selection.", "focus": [350, 235, 3450, 220], "hold_after": 0.7}, {"visual": "09_actual_distinct_runs_restored", "narration": "Keep both output snapshots and the settings that explain their differences. Use Run History for individual logs and Regression for the underlying hit results.", "related_lessons": ["06_api", "08_measure"], "hold_after": 0.7}], "narration_voices": {"en": ["af_heart"]}, "poster": "50_run_compare/poster.jpg", "silent": "50_run_compare/video/50_run_compare_silent.mp4"}, {"id": "51_control_charts", "number": 51, "slug": "control_charts", "series": 5, "app_key": "control_chart", "host_app_key": "qc_dashboard", "section": "Data", "title": "Control Charts: monitor controls across plates", "description": "Load a campaign table, select controls and baseline limits, inspect alerts, and export the plotted points.", "objectives": ["Choose the measurement and control population.", "Set the baseline and alert rules.", "Inspect alerts and export chart points."], "prerequisite": "Download the synthetic campaign CSV below, or prepare a well-level table with plate identity, run order, a measurement and control labels. The example illustrates thirty plates with programmed drift.", "scenes": [{"visual": "01_qc_host", "narration": "Open QC, then Control Charts to monitor repeated controls across a campaign. The practice CSV uses synthetic plates and a programmed drift.", "hold_after": 0.7, "related_lessons": ["54_qc_dashboard"]}, {"visual": "03_load_synthetic_csv", "narration": "Download the example CSV below, click Load table and select it. It contains thirty plates, each with three wells for each control type and three sample wells.", "hold_after": 0.7, "focus": [1550, 790, 740, 510]}, {"visual": "05_negative_control_default_rules", "narration": "Match Plate, Run order, Measurement and Control column to the table. Under Control is, select neg for the negative controls. An empty selection includes all rows.", "hold_after": 0.7, "focus": [290, 460, 740, 700]}, {"visual": "05a_sigma_choices", "narration": "Choose Sigma from to control the variation estimator. Auto uses the subgroup estimator here, because each plate contains three selected control wells.", "hold_after": 0.7, "focus": [290, 980, 1760, 600]}, {"visual": "05b_rule_choices", "narration": "Choose Rules for the alerts you want to inspect. The example uses Limits only to focus on points outside the three-sigma limits. Changing a setting redraws the chart.", "hold_after": 0.7, "focus": [290, 1160, 1900, 450]}, {"visual": "06_limits_only", "narration": "Set Baseline plates to twenty. The first twenty plates establish limits for the series. Read the report and rule table to locate flagged later plates.", "hold_after": 0.7, "focus": [1010, 450, 2790, 1600]}, {"visual": "07_positive_control", "narration": "To inspect positive controls, clear neg and select pos. Review their means and limits separately, then return to neg to continue the example.", "hold_after": 0.7}, {"visual": "09_shorter_baseline", "narration": "Adjust Baseline plates when your planned reference period differs. The tool requires at least eight plates; choose a stable baseline appropriate to the assay.", "hold_after": 0.7, "focus": [295, 1400, 2600, 375]}, {"visual": "11_actual_export_picker", "narration": "Click Export points and choose a CSV destination. It saves plate identities, means, subgroup sizes, limits, baseline membership and fired rules.", "hold_after": 0.7, "focus": [1550, 790, 740, 510]}, {"visual": "12_exported", "narration": "Keep the input CSV, selected controls and baseline settings with the exported points. Use the flagged plate identities to investigate acquisition or assay changes.", "hold_after": 0.7, "related_lessons": ["06_api", "54_qc_dashboard"]}], "example_files": ["Control_Charts_SYNTHETIC_campaign.csv"], "narration_voices": {"en": ["af_heart"]}, "poster": "51_control_charts/poster.jpg", "silent": "51_control_charts/video/51_control_charts_silent.mp4"}, {"id": "52_pipeline_graph", "number": 52, "slug": "pipeline_graph", "series": 5, "app_key": "pipeline_graph", "section": "Explore", "title": "Pipeline Graph: inspect outputs and dependencies", "description": "Open a project’s artifact graph, inspect missing outputs, and copy its dependency diagram.", "objectives": ["Open the artifact graph for a project.", "Inspect paths, states and dependencies.", "Copy the diagram and refresh its records."], "prerequisite": "Choose a spaCR project with registered outputs. The External Masks example supplies measurements and crops; the Data Manager lesson shows how a removed artifact appears.", "scenes": [{"visual": "01_help_pipeline_graph", "narration": "Open Help, then Pipeline graph to inspect a project’s recorded outputs and dependencies.", "hold_after": 0.7, "related_lessons": ["31_external_masks", "44_data_manager"]}, {"visual": "04_unregistered_is_not_unprocessed", "narration": "Browse to the project folder. If the graph is empty, check whether that folder has registered artifacts; existing files can be present without registry records.", "hold_after": 0.7, "focus": [345, 230, 3450, 360], "related_lessons": ["37_batch", "40_run_history"]}, {"visual": "06_three_actual_artifacts", "narration": "Choose the measured project to display its artifact boxes. The example includes measurements, crops and a resource log, with a removed crop folder marked missing.", "hold_after": 0.7, "focus": [345, 235, 500, 470]}, {"visual": "07_measurement_provenance", "narration": "Click an artifact and widen the details with the divider. Inspect its path, role, run identifier, production time and software version.", "hold_after": 0.7, "focus": [1940, 360, 1870, 345]}, {"visual": "08_missing_crop_provenance", "narration": "Select a Missing artifact to find its recorded path. Its displayed size describes the saved record, so check the actual location when investigating absent files.", "hold_after": 0.7, "focus": [1940, 360, 1870, 345]}, {"visual": "09_external_resource_log", "narration": "Inspect input and downstream links where they are recorded. Some artifacts, such as resource logs, may be located outside the project folder.", "hold_after": 0.7, "focus": [1940, 360, 1870, 345]}, {"visual": "11_missing_detail", "narration": "Use Current, Stale and Missing to choose which artifact states are visible. For example, hide Current to focus on missing outputs.", "hold_after": 0.7, "focus": [345, 235, 3450, 470]}, {"visual": "12_no_visible_artifacts", "narration": "If no boxes are visible, check the display filters and overall artifact counts. Restore the states you want to inspect.", "hold_after": 0.7, "focus": [345, 235, 3450, 470]}, {"visual": "13_copy_full_graph_not_filtered_view", "narration": "Click Copy Graphviz to copy the full diagram as DOT text, including nodes hidden by display filters. Paste it into a Graphviz tool to render or save it.", "hold_after": 0.7, "focus": [345, 230, 3450, 200]}, {"visual": "15_restore_all_nodes", "narration": "Restore the desired filters and select an artifact again to inspect its details. Use its recorded path and upstream workflow to decide what needs attention.", "hold_after": 0.7, "focus": [345, 235, 500, 470]}, {"visual": "16_redrawn_unchanged_graph", "narration": "Click Redraw after project changes to reread the registry. Open Run History for saved settings and logs, or Data Manager for cleanup and archiving.", "hold_after": 0.7, "related_lessons": ["06_api", "40_run_history", "44_data_manager", "45_project_browser"]}], "narration_voices": {"en": ["af_heart"]}, "poster": "52_pipeline_graph/poster.jpg", "silent": "52_pipeline_graph/video/52_pipeline_graph_silent.mp4"}, {"id": "53_prediction_profiler", "number": 53, "slug": "prediction_profiler", "title": "Prediction Profiler: explore a fitted model", "series": 5, "app_key": "profiler", "section": "Explore", "description": "Load model coefficients, vary one input while holding others fixed, and inspect predicted responses.", "objectives": ["Load coefficients with the correct model link.", "Sweep one input and adjust held values.", "Inspect response curves and sensitivity."], "example_files": ["SYNTHETIC_profiler_example.zip"], "prerequisite": "Download the synthetic coefficient example, or use coefficients from a suitable fitted model. Match its link and input encoding. The coefficient-file route assumes input ranges of zero to one; separate marginal effects are not substitutes for a jointly fitted prediction model.", "scenes": [{"visual": "01_regression_host", "narration": "Open Regression, then Prediction Profiler to explore predicted responses from a fitted model. The linked example uses synthetic data.", "focus": [460, 45, 3340, 540], "related_lessons": ["13_regression"], "hold_after": 0.7}, {"visual": "03_explicit_synthetic_coefficients_picker", "narration": "Download and unzip the example, then Browse to the synthetic OLS coefficients CSV. Include the intercept when supplying your own fitted coefficients.", "focus": [890, 390, 1920, 1080], "hold_after": 0.7}, {"visual": "05_link_options_keep_identity", "narration": "Set Link to the function used by the fitted model. Keep identity for this ordinary least-squares example.", "focus": [2910, 465, 900, 610], "hold_after": 0.7}, {"visual": "04_loaded_identity_model", "narration": "Check the range information after loading. The coefficient-file route assumes each input spans zero to one. Confirm that this matches your intended use before interpreting the curves.", "focus": [470, 530, 3320, 240], "hold_after": 0.7}, {"visual": "06_hold_b_at_one", "narration": "Select Input A for the sweep. Move the held Input B slider to one and inspect the resulting response curve.", "focus": [1480, 590, 2320, 1440], "hold_after": 0.7}, {"visual": "07_hold_b_at_zero", "narration": "Move B to zero and compare the response values. Watch the axis scale as well as the line, because the plot may rescale.", "focus": [1480, 590, 2320, 1440], "hold_after": 0.7}, {"visual": "08_reset_midpoints", "narration": "Click Reset held values to return the sliders to the midpoints of their assumed ranges, one half in this example.", "focus": [1470, 1435, 2330, 660], "hold_after": 0.7}, {"visual": "09_sweep_second_input", "narration": "Select Input B in the ranked list to sweep B while holding A fixed. The ranking summarizes model sensitivity over its configured input ranges.", "focus": [470, 590, 3330, 940], "hold_after": 0.7}, {"visual": "10_eleven_grid_points", "narration": "Change Points to choose the number of positions evaluated along the plotted curve. Eleven gives a coarser grid than sixty-one without changing the fitted model.", "focus": [1480, 465, 2320, 1040], "hold_after": 0.7}, {"visual": "11_hold_a_at_one", "narration": "Adjust the held values to explore further scenarios, then reset when finished. Interpret the curves as model predictions and assess real experimental effects with appropriate data.", "focus": [1480, 590, 2320, 1490], "related_lessons": ["06_api", "75_regression_diagnostics"], "hold_after": 0.7}], "host_app_key": "regression", "narration_voices": {"en": ["af_heart"]}, "poster": "53_prediction_profiler/poster.jpg", "silent": "53_prediction_profiler/video/53_prediction_profiler_silent.mp4"}, {"id": "54_qc_dashboard", "number": 54, "slug": "qc_dashboard", "series": 5, "app_key": "qc_dashboard", "section": "Data", "title": "QC: inspect project quality reports", "description": "Choose a project, read available quality reports, investigate warnings and refresh the dashboard.", "objectives": ["Choose the intended project or run.", "Read available, missing and outdated reports.", "Investigate findings and refresh the view."], "prerequisite": "Use a project with saved quality reports. The downloaded Mask and Annotate examples provide different report sets; choose the specific project or run folder you intend to inspect.", "scenes": [{"visual": "01_module", "narration": "Open QC from Home’s Data category to review quality reports saved with a project.", "hold_after": 0.7}, {"visual": "02_fold_layer_viewer", "narration": "The header opens Layer Viewer, Control Charts and Outliers. Use their tutorials when a dashboard finding needs further investigation.", "hold_after": 0.7, "focus_buttons": "FoldButton", "related_lessons": ["57_layer_viewer", "51_control_charts", "66_outliers"]}, {"visual": "03_missing_reports_picker", "narration": "Click Browse and choose the project folder. Select the folder containing the reports for the run you want to assess.", "hold_after": 0.7, "related_lessons": ["09_annotate"]}, {"visual": "03_missing_reports", "narration": "Read Missing as an unavailable report for that check. Follow the guidance to obtain the required report before drawing a conclusion.", "hold_after": 0.7}, {"visual": "04_computed_subset_picker", "narration": "Choose a run subfolder when its outputs are separate from the parent project. Check that the displayed scope matches the data you intend to review.", "hold_after": 0.7, "related_lessons": ["07_mask", "08_measure"]}, {"visual": "04_computed_subset", "narration": "Read segmentation warnings and inspect the corresponding fields. For a size-distribution warning, compare the images and object boundaries to understand the cause.", "hold_after": 0.7, "focus": [450, 450, 3000, 275], "related_lessons": ["14_make_masks", "57_layer_viewer"]}, {"visual": "05_subset_remaining_checks", "narration": "Review the units card alongside the remaining categories. A consistent units report addresses that check; missing reports still need attention.", "hold_after": 0.7}, {"visual": "05_subset_remaining_checks", "narration": "Read all five categories and their guidance. For leakage, check that sample identities and grouping reflect the intended independent validation units.", "hold_after": 0.7, "related_lessons": ["41_classify", "23_agreement", "33_plate_viewer"]}, {"visual": "07_original_plate_details", "narration": "Open the details of failures or warnings to identify affected fields and source reports. Use the relevant analysis tool to investigate them.", "hold_after": 0.7, "focus": [450, 400, 2950, 240]}, {"visual": "08_unchanged_refresh", "narration": "Click Refresh after reports change on disk. The dashboard rereads available evidence; generate updated reports through the analysis that produces them.", "hold_after": 0.7, "focus": [450, 2070, 2950, 50]}, {"visual": "08_unchanged_refresh", "narration": "Investigate an out-of-date report against its input data and settings. Keep unresolved findings visible in your project review.", "hold_after": 0.7}, {"visual": "08_unchanged_refresh", "narration": "Keep quality reports with the project. Continue in the linked specialist tools or the relevant module tutorial to address each finding.", "hold_after": 0.7, "related_lessons": ["06_api", "57_layer_viewer", "51_control_charts", "66_outliers"]}], "narration_voices": {"en": ["af_heart"]}, "poster": "54_qc_dashboard/poster.jpg", "silent": "54_qc_dashboard/video/54_qc_dashboard_silent.mp4"}, {"id": "55_image_scatter", "number": 55, "slug": "image_scatter", "series": 5, "app_key": "image_scatter", "host_app_key": "umap", "section": "Explore", "title": "Image Scatter: inspect measurements and their crops", "description": "Plot two measurement columns, preview object crops, and send a selected object to Annotate.", "objectives": ["Load measurements and choose axes.", "Inspect the crop behind a point.", "Send a selected object to Annotate."], "prerequisite": "Use a spaCR measurements database with matching object crops and crop-format files. The downloadable Annotate example provides these inputs.", "scenes": [{"visual": "01_image_umap_host", "narration": "Open Image UMAP, then Image Scatter to plot two existing measurements. Use the Annotate example database and its matching cell crops for practice.", "hold_after": 0.7, "related_lessons": ["09_annotate", "15_image_umap"]}, {"visual": "03_choose_real_measurements", "narration": "Click Browse and open measurements.db. Keep the project’s data folder and crop-format files with the database so thumbnails can be found.", "hold_after": 0.7}, {"visual": "04_choose_cell_not_children", "narration": "Select cell in the table selector and click Plot. When switching to another table, click Plot again to load its rows.", "hold_after": 0.7}, {"visual": "05_real_measurement_scatter", "narration": "Set x to cell area and y to cell channel one mean intensity. Axis choices redraw the loaded rows immediately.", "hold_after": 0.7, "related_lessons": ["62_feature_dictionary"], "focus": [410, 405, 3410, 120]}, {"visual": "06_genuine_large_cell_preview", "narration": "Hover over a point to inspect its saved crop and full object identity. Use the image to understand the measurement behind the point.", "hold_after": 0.7, "focus": [3500, 490, 330, 390]}, {"visual": "08_cached_same_cell", "narration": "Move the pointer away to clear the temporary preview, then hover over another point to inspect it.", "hold_after": 0.7, "focus": [3500, 490, 330, 390]}, {"visual": "09_swapped_raw_axes", "narration": "Swap the x and y measurements to explore the relationship from another view. Choose meaningful features and check their units.", "hold_after": 0.7, "focus": [410, 405, 3410, 120]}, {"visual": "11_missing_texture_not_plotted", "narration": "Select another measurement, such as the homogeneity feature. Rows with missing coordinates are omitted from the plot, so the plotted count can differ from the loaded table count.", "hold_after": 0.7, "focus": [410, 405, 3410, 120]}, {"visual": "12_constant_axis_is_centred", "narration": "A constant column, such as measurement dimension in this example, puts the points on a line. Return to a feature with useful variation for object inspection.", "hold_after": 0.7, "focus": [410, 405, 3410, 120]}, {"visual": "16_real_annotate_grid", "narration": "To inspect a selected crop in Annotate, first open Annotate and load the same project. Then return to the existing Image Scatter view.", "hold_after": 0.7, "related_lessons": ["09_annotate"]}, {"visual": "17c_native_point_click_target", "narration": "Click the point itself to send its object identity to Annotate, then switch to that page. Hovering only previews the crop.", "hold_after": 0.7, "focus": [3500, 490, 330, 390]}, {"visual": "18_verified_clicked_cell_in_annotate", "narration": "Inspect the selected object in Annotate before assigning a label. Use Database Browser for table exports, or PCA for component analysis.", "hold_after": 0.7, "related_lessons": ["34_database", "60_pca", "09_annotate"], "focus": [410, 330, 550, 410]}], "narration_voices": {"en": ["af_heart"]}, "poster": "55_image_scatter/poster.jpg", "silent": "55_image_scatter/video/55_image_scatter_silent.mp4"}, {"id": "56_lineage", "number": 56, "slug": "lineage", "series": 5, "app_key": "lineage", "host_app_key": "db_browser", "section": "Explore", "title": "Lineage: containment identities and verified parent crops", "description": "Inspect actual stored parent-child relationships, understand the display cap and distinguish a verified single-parent crop from the unsafe missing-child fallback.", "objectives": ["Find Lineage inside Database Browser and build the real containment tree.", "Distinguish complete counts, displayed families and typed object identities.", "Recognize the incorrect family-crop fallback and inspect only a verified parent.", "Use native crop zoom and distinguish the complete Python export from GUI controls."], "prerequisite": "Use the downloaded Annotate example with matching measurements and cell crops. The linked Graph Builder archive supplies the exact database but no images; the Lineage archive supplies the verified API CSV and review, not a replacement database. Do not use the current family-crop fallback to identify or label missing child images.", "example_files": ["Lineage_real_containment_review.zip", "Graph_Builder_real_measurements.zip"], "scenes": [{"visual": "02_database_host", "narration": "Find Database Browser under Help, then open its nested Lineage tool. Here lineage means stored containment: which objects belong inside which cells. It is not a cell-division history, genetic ancestry or a new segmentation. The surrounding database controls belong to the host module.", "hold_after": 0.7, "related_lessons": ["34_database"]}, {"visual": "04_choose_real_measurements", "narration": "Browse to measurements dot db from the real Annotate example and build the tree. This lesson uses an unchanged private copy. Widen the Object column and the divider if labels are cramped. Numeric labels repeat across fields and object types, so a number alone is not an identity.", "hold_after": 0.7}, {"visual": "05_full_counts_capped_tree_and_zero_orphans", "narration": "The complete source contains two thousand three hundred forty-one cells, two thousand six hundred eighty-two nuclei and two thousand one hundred seventy-eight objects in the pathogen table. Only two thousand parent families appear in the tree; three hundred forty-one are omitted from display, not deleted from the database.", "hold_after": 0.7}, {"visual": "06_one_nucleus_no_pathogen", "narration": "The summary says no cells have nothing inside, because a nucleus also counts as a child. That does not mean every cell contains a pathogen-table object: one thousand one hundred sixty-eight do not. No unattached children means every recorded parent exists, not that the segmentation is biologically correct.", "hold_after": 0.7}, {"visual": "07_cell_with_nucleus_and_pathogen", "narration": "Expand a parent to see its children. In this field, cell three contains nucleus five and pathogen one according to the stored links. These are typed object identities, not three interchangeable numbers. Selecting a child alone is different from selecting the whole family.", "hold_after": 0.7}, {"visual": "09_publish_three_typed_objects", "narration": "Select with contents publishes the parent and its children. Selecting the parent and a child together does not need a duplicate copy of that child. Published keys preserve field and object type, but the key column is hidden here. Publishing an identity does not prove that a matching crop exists.", "hold_after": 0.7}, {"visual": "11_large_family_not_biological_validation", "narration": "Large families deserve inspection, not automatic biological interpretation. This example includes one family with thirty-three objects in total. Containment may reflect segmentation errors or other acquisition issues. The tree reports saved relationships; it does not validate unusual counts as a discovery.", "hold_after": 0.7}, {"visual": "12_actual_header_sort_preserves_containment", "narration": "Clicking a header sorts the displayed families without changing their containment. The two-thousand-parent display limit still applies. We checked every displayed identity and parent edge as well as the full hierarchy. Do not confuse a reordered or truncated view with an edited measurement table.", "hold_after": 0.7}, {"visual": "13_real_open_annotate_prerequisite", "narration": "Open crops needs the Annotate screen, which supplies the image viewer. The actual message tells us to open Annotate first. A missing viewer is different from a missing image. Before requesting crops, load the matching example project in Annotate, not another run with coincidentally similar labels.", "hold_after": 0.7, "related_lessons": ["09_annotate"]}, {"visual": "16_real_downloaded_cell_crops", "narration": "The downloaded project provides real cell crops. The database-only archive linked here cannot supply those images by itself. We use the complete matching example and preserve every original crop. Opening the source does not train a classifier or establish new labels.", "hold_after": 0.7}, {"visual": "20_wrong_typed_children_are_unrelated_cell_crops", "narration": "There is a serious limitation in this build. Opening the three-object family displays cell three, then unrelated cell five and cell one crops instead of the requested nucleus and pathogen. The source has only cell crops. Reject this substitution: do not label those images as the missing children. This tutorial does not repair it.", "hold_after": 0.7}, {"visual": "22_verified_parent_only_real_cell_crop", "narration": "The verified alternative is narrower: return to Lineage and double-click the parent cell alone. Unlike Open crops, this sends only that parent, not its family. Annotate now shows exactly the requested cell crop. We checked its identity and original image bytes; no child-crop support is implied.", "hold_after": 0.7}, {"visual": "22a_zoom_parent_without_labelling", "narration": "Shift-click the parent thumbnail to enlarge its existing preview without assigning a class. Escape returns to the grid. This helps visual inspection but creates no extra image resolution. Use the correct gesture: an ordinary left click is an annotation action, not the zoom demonstrated here.", "hold_after": 0.7}, {"visual": "24_rebuild_preserves_full_containment", "narration": "Build tree refreshes the containment view. For Python, read_object_tables, build_forest and lineage_frame expose the same structure. The linked CSV contains all seven thousand two hundred one nodes, including families omitted from display. It was written by the API, not a Lineage export button, and is not biological validation.", "hold_after": 0.7, "related_lessons": ["06_api"]}], "poster": "56_lineage/poster.jpg", "silent": "56_lineage/video/56_lineage_silent.mp4"}, {"id": "57_layer_viewer", "number": 57, "slug": "layer_viewer", "series": 5, "app_key": "layer_viewer", "section": "Explore", "title": "Layer Viewer: inspect images and label overlays", "description": "Load a matching image and mask, adjust the overlay, and zoom in to inspect object boundaries.", "objectives": ["Open an image and its matching mask.", "Adjust visibility, opacity, blending and layer order.", "Inspect labels with zoom and pan."], "prerequisite": "Download and extract Layer_Viewer_real_image_mask.zip. Use the included intensity image and matching integer-label mask. Physical pixel calibration is unavailable for this example.", "scenes": [{"visual": "01_qc_host", "narration": "From Home, open QC, then Layer Viewer. Download and extract the linked image-and-mask example. The viewer has its own file controls for these two inputs.", "hold_after": 0.7, "related_lessons": ["31_external_masks", "54_qc_dashboard"]}, {"visual": "04_raw_image_in_wide_pane", "narration": "Click plus Image and open fov01_C1 dot tif. The grayscale image appears in the canvas with a percentile contrast stretch for display.", "hold_after": 0.7}, {"visual": "05_fit_after_actual_splitter_resize", "narration": "Click Fit to fill the image pane. Fit can stretch a square image in a wide pane; adjust the divider to make the pane approximately square when inspecting shape.", "hold_after": 0.7}, {"visual": "07_real_44_label_overlay", "narration": "Click plus Mask and open fov01_cell_mask dot tif. The forty-four labelled objects appear over the image. Zero is background and remains transparent.", "hold_after": 0.7}, {"visual": "09_mask_visible_again", "narration": "Select mask in the layer list before changing its controls. Toggle its checkbox to compare the boundaries with the image underneath.", "hold_after": 0.7, "focus": [1970, 365, 1840, 100]}, {"visual": "10_opacity_zero_not_deleted", "narration": "Move mask Opacity to zero to hide its colours while keeping the layer loaded. Check the selected row before adjusting another layer.", "hold_after": 0.7, "focus": [1970, 1800, 1840, 250]}, {"visual": "11_full_label_colours", "narration": "Move Opacity to one hundred percent to inspect the label shapes. The colours cover the image inside each labelled object.", "hold_after": 0.7}, {"visual": "12_half_opacity_restored", "narration": "Return Opacity to fifty percent and choose translucent blending to see the image texture through the mask. Compare object boundaries with the underlying signal.", "hold_after": 0.7}, {"visual": "13_blend_additive", "narration": "Choose additive blending to add the mask colours to the image. Bright areas can saturate in this display, so return to translucent when you need a clearer comparison.", "hold_after": 0.7}, {"visual": "15_blend_minimum", "narration": "Try multiply and minimum blending to compare darker overlays. These options change the displayed composite while the original intensity values remain available in the source image.", "hold_after": 0.7}, {"visual": "16_blend_opaque", "narration": "Choose opaque and adjust the Opacity slider to compare its appearance. With this integer mask, fifty-percent opaque blending looks like fifty-percent translucent blending. Restore translucent to continue.", "hold_after": 0.7}, {"visual": "18_cyan_image_not_changed_measurements", "narration": "Select image and choose cyan in the colour-map selector. The intensity image changes colour while the mask keeps its label colours. Choose gray to restore the grayscale view.", "hold_after": 0.7}, {"visual": "19_mask_under_image", "narration": "Select mask and press the down arrow to move it behind the image. The upper layer appears in front. Move the mask up again to inspect its labels.", "hold_after": 0.7}, {"visual": "21_actual_label_no_field_identity", "narration": "Click a visible labelled object to read its position and label number in the status line. Use your project metadata when you need to identify that object’s field, plate or well.", "hold_after": 0.7, "focus": [295, 1920, 3500, 165]}, {"visual": "22_native_wheel_zoom_keeps_world_anchor", "narration": "Roll the mouse wheel over an object to zoom around the pointer. Move closer until its boundary is easy to inspect.", "hold_after": 0.7}, {"visual": "23_native_pan", "narration": "Hold Shift and drag with the left mouse button to pan. You can also drag with the middle button. Move across the field while keeping the current zoom.", "hold_after": 0.7}, {"visual": "24_fit_restores_original_view", "narration": "Click Fit to return to the whole field. Adjust the pane shape if the fitted image looks stretched.", "hold_after": 0.7}, {"visual": "25_empty_shapes_layer", "narration": "Plus Points and plus Shapes add empty auxiliary layers. For drawing or editing segmentation masks, continue in Make Masks; this viewer has no drawing controls for those empty layers.", "hold_after": 0.7, "related_lessons": ["14_make_masks"]}, {"visual": "28_remove_mask_only_from_view", "narration": "Select a layer and use Remove to take it out of the view. Its original file remains on disk, ready to load again.", "hold_after": 0.7}, {"visual": "28_remove_mask_only_from_view", "narration": "The result is an inspected layer view. For an exported composite, use stack_from_paths and LayerStack.render_uint8 from Python. Continue to Make Masks for saved mask edits or Measure for object measurements.", "hold_after": 0.7, "related_lessons": ["06_api", "14_make_masks", "31_external_masks"]}], "example_files": ["Layer_Viewer_real_image_mask.zip"], "host_app_key": "qc_dashboard", "narration_voices": {"en": ["af_heart"]}, "poster": "57_layer_viewer/poster.jpg", "silent": "57_layer_viewer/video/57_layer_viewer_silent.mp4"}, {"id": "58_graph_builder", "number": 58, "slug": "graph_builder", "series": 5, "app_key": "graph_builder", "section": "Explore", "title": "Graph Builder: plot measurements and filter objects", "description": "Load a measurement table, assign plot axes, compare groups and filter the displayed objects.", "objectives": ["Load an example measurement table.", "Build a histogram, scatter plot and grouped panels.", "Filter objects and choose a follow-up view."], "prerequisite": "Download and extract Graph_Builder_real_measurements.zip. It contains measurements.db. To inspect image crops later, also keep the matching Annotate project and its images available.", "example_files": ["Graph_Builder_real_measurements.zip"], "scenes": [{"visual": "01_module", "narration": "Open Graph Builder from Home to explore a measurement table. Start with the linked example database, then repeat the steps with your own measured project.", "hold_after": 0.7}, {"visual": "03_choose_database", "narration": "Click Load table and open measurements dot db from the extracted archive. Choose the cell table. This example contains two thousand three hundred forty-one measured cells.", "hold_after": 0.7, "related_lessons": ["09_annotate", "34_database"]}, {"visual": "05_area_histogram", "narration": "Find cell_area in the column list and drag it onto X. The automatic chart becomes a histogram: each bar counts cells in an area interval. Check the measurement units before interpreting the axis.", "hold_after": 0.7}, {"visual": "06_real_scatter", "narration": "Drag cell_channel_1_mean_intensity onto Y to make a scatter plot. Each point places one cell by its area and channel-one mean intensity. Read the row-count notice when working with larger tables.", "hold_after": 0.7}, {"visual": "07_well_column_colour", "narration": "Drag columnID onto Colour to distinguish plate columns. Use the legend to match colours to the recorded column labels and look for groups that need closer inspection.", "hold_after": 0.7}, {"visual": "08_acquisition_row_facets", "narration": "Drag rowID onto the downward facet channel to create a panel for each plate row. Compare the panels using their shared axes. Use independent wells when making statistical comparisons between conditions.", "hold_after": 0.7}, {"visual": "09_live_area_filter", "narration": "In the filter panel on the right, add cell_area and enter a minimum. The example uses twenty-one thousand nine hundred twenty-five, leaving one thousand one hundred seventy-one rows. Choose thresholds appropriate to your own measurements and watch the plotted count and axes change.", "hold_after": 0.7}, {"visual": "10_filter_cleared", "narration": "Click Clear all in the filter panel to restore the full table. Use Clear all channels on the left when you want to remove the plot mappings and start a different chart.", "hold_after": 0.7}, {"visual": "11_actual_brush_state", "narration": "Remove a facet with its small cross to return to one scatter plot. Drag a rectangle around objects to select a region. If Open selection in Annotate is unavailable, open Annotate separately with the matching project and inspect objects there.", "hold_after": 0.7}, {"visual": "12_selection_cleared", "narration": "Click an empty part of the plot to clear the selection. Check the active filters and displayed count before exploring another group of objects.", "hold_after": 0.7}, {"visual": "02_fold_trellis", "narration": "Use the header shortcuts to open Plate Viewer for well heatmaps or Small Multiples for repeated charts. Keep the source database and your chosen columns and filters so you can reproduce the view.", "hold_after": 0.7, "related_lessons": ["33_plate_viewer", "63_small_multiples"]}, {"visual": "12_selection_cleared", "narration": "The current screen displays plots without a chart-export button. Use the Graph Builder API for scripted plots, or Database Browser to export a table for another plotting tool.", "hold_after": 0.7, "related_lessons": ["06_api"]}], "narration_voices": {"en": ["af_heart"]}, "poster": "58_graph_builder/poster.jpg", "silent": "58_graph_builder/video/58_graph_builder_silent.mp4"}, {"id": "59_anndata_export", "number": 59, "slug": "anndata_export", "title": "AnnData Export: current route and a verified API workaround", "series": 5, "app_key": "anndata_export", "host_app_key": "measure", "section": "Measure", "description": "Find the nested exporter, understand the observed missing-metadata failure, and export the real downloaded measurement example through an explicit, checked Python workaround.", "objectives": ["Find AnnData Export inside Measure and identify the source measurements database.", "Distinguish a failed GUI export from the verified API workaround without inventing missing metadata.", "Compare joined, cell-only and nucleus-only matrices and four missing-value policies.", "Reopen saved files and preserve object identities, annotations, source images and provenance."], "example_files": ["AnnData_API_workaround.zip"], "prerequisite": "Use the real downloaded measurement example from Annotate, retaining an untouched measurements.db and its source images. The recording uses spaCR 1.5.0.6 and AnnData in the same Python environment. Download the linked helper beside a COPY of measurements.db; it imports spacr.anndata_export.build_anndata. The unmodified GUI/API writer fails on entirely missing object-typed observation metadata, including unknown voxel calibration. A partial .h5ad is not a valid export. The helper explicitly encodes ONLY all-missing object metadata as empty pandas categoricals; it preserves missingness, does not invent calibration or labels, does not change X for this storage step, and does not repair the GUI. It writes a new destination, reloads and compares all values before accepting it; existing destinations are refused. Six exports were independently checked against SQLite: joined/keep 2341x1136 (400320 missing); cell/keep 2341x261 (28 missing); cell/mean 2341x261 (28 imputed); cell/drop_features 2341x257; cell/drop_objects 2334x261; nucleus/keep 2682x341 (1912 missing). No UMAP, GPU operation, image embedding, AI request, biological validation or publication is claimed. API: spacr.anndata_export.build_anndata and export_anndata. The original GUI failure remains preserved separately.", "scenes": [{"visual": "gui_02_current_anndata_form", "narration": "Open Measure, then its nested AnnData Export workflow. AnnData stores an object-by-feature matrix together with observation metadata and feature names. This lesson shows the current GUI route, but the demonstrated successful exports use an explicit Python workaround. We are not claiming that the GUI export defect is fixed.", "related_lessons": ["08_measure", "09_annotate"], "hold_after": 0.7}, {"visual": "gui_03_private_downloaded_project", "narration": "Use a copy of the real downloaded measurements database, not an invented table. Keep its images and original database unchanged. The GUI accepts the project folder; our command-line example takes the measurements database file itself. Disable the optional embedding for this export comparison. Exporting a matrix does not require a GPU.", "hold_after": 0.7}, {"visual": "api_01_unmodified_failure", "narration": "First observe the unmodified writer failing. Some observation columns contain only missing values with an object data type, which this writer cannot serialize. Unknown voxel calibration is one example. Exit status one and a partial file are not success. Do not replace unknown values with zero or the text None to silence the error.", "focus": [190, 1660, 3450, 340], "hold_after": 0.7}, {"visual": "api_02_explicit_workaround", "narration": "Download the linked helper and inspect its storage workaround. It uses the real build_anndata function, then encodes only entirely missing object metadata as empty categorical columns. Missing values remain missing; known metadata and the feature matrix are not changed by that encoding. This does not mean that physical calibration is a categorical scientific quantity.", "focus": [190, 80, 3450, 1400], "related_lessons": ["06_api"], "hold_after": 0.7}, {"visual": "api_03_joined_keep", "narration": "Run the helper with your source database, a new output path, and the keep policy. The joined example has two thousand three hundred forty-one cell rows and one thousand one hundred thirty-six features. Related nucleus and pathogen measurements are aggregated onto cells. Four hundred thousand three hundred twenty missing feature values remain missing, not zero.", "focus": [190, 80, 3450, 650], "hold_after": 0.7}, {"visual": "api_04_cell_keep", "narration": "For one object's own measurements, add single-table cell and keep the missing values. This file has the same two thousand three hundred forty-one cell rows but only two hundred sixty-one features. Twenty-eight feature values are missing. Compare feature names and row identities, not just file size or the number of columns.", "focus": [190, 80, 3450, 650], "hold_after": 0.7}, {"visual": "api_05_cell_mean", "narration": "The mean policy is a separate analytical choice, not part of the storage workaround. Here it fills twenty-eight missing feature values using the observed column means. The exported missing-value layer records their original positions. Check that imputation is appropriate for your analysis; a complete matrix is not automatically a better or unbiased dataset.", "focus": [190, 80, 3450, 650], "hold_after": 0.7}, {"visual": "api_06_cell_drop_features", "narration": "The drop-features policy removes columns containing missing values. In this example four columns are removed, leaving two hundred fifty-seven features and every cell row. Inspect which measurements were removed and why. This policy changes the feature set and can discard useful information; it is not a universal cleaning recommendation.", "focus": [190, 80, 3450, 650], "hold_after": 0.7}, {"visual": "api_07_cell_drop_objects", "narration": "The drop-objects policy instead removes rows containing missing feature values. Seven cells are removed here, leaving two thousand three hundred thirty-four rows and all two hundred sixty-one features. Missingness can be related to phenotype, acquisition or segmentation. Check what was excluded before treating the retained cells as representative.", "focus": [190, 80, 3450, 650], "hold_after": 0.7}, {"visual": "api_08_nucleus_keep", "narration": "Choose single-table nucleus for one row per nucleus, rather than aggregated nucleus features on cell rows. This example has two thousand six hundred eighty-two nuclei and three hundred forty-one features. Keep the parent links and object identities. More nuclei than cells does not mean that extra cells appeared during export.", "focus": [190, 80, 3450, 650], "hold_after": 0.7}, {"visual": "api_09_saved_shape", "narration": "Reopen each saved file. The helper compares the full matrix, ordered object and feature identities, missingness, and observation metadata; independent SQLite checks also passed for all six files. Annotations remain metadata, not training features inserted into the matrix. Images are not embedded, so retain the source files and their paths with the export.", "focus": [190, 80, 3450, 650], "hold_after": 0.7}, {"visual": "api_03_joined_keep", "narration": "Use a new output name for each policy and keep the script, settings and package versions. The helper refuses an existing destination instead of overwriting it. These checks establish data preservation for this example, not biological validity or a repaired GUI. Return to the linked API and measurement lessons for the surrounding workflow.", "focus": [190, 80, 3450, 650], "related_lessons": ["06_api", "08_measure"], "hold_after": 0.7}], "poster": "59_anndata_export/poster.jpg", "silent": "59_anndata_export/video/59_anndata_export_silent.mp4"}, {"id": "60_pca", "number": 60, "slug": "pca", "series": 5, "app_key": "pca", "host_app_key": "umap", "section": "Explore", "title": "PCA: real measurements, live refits and missing values", "description": "Explore the PCA submodule inside Image UMAP using genuine downloaded cells, checked component scores, reversible filters, explicit missing-value policies and three real CSV exports.", "objectives": ["Find PCA inside Image UMAP and choose an explicit measurement feature set.", "Read component variance and correlation arrows without claiming biological separation.", "Compare standardisation, live population refits and four missing-value policies.", "Export object scores, feature loadings and component variance while preserving the source."], "prerequisite": "Reuse a private byte-identical copy of the downloadable Annotate example: 2,341 cell rows, 276 source columns and four wells. This lesson fits cell_area, cell_channel_1_mean_intensity and cell_perimeter, then adds cell_channel_0_homogeneity_distance_32, which has seven genuinely missing values. The missingness mechanism and treatment identities are not established. Independent covariance eigendecomposition checks the application's small-table SVD, retained row positions, scores, loadings, correlations and variances; actual plotted coordinates and every exported source cell are checked. This is bounded to these full-rank, nondegenerate three- and four-feature fits, not a validation of all automatic features, arrow pixel geometry, rank-deficient inputs, image-linked brushing or biological conclusions. CPU NumPy PCA is separate from UMAP fitting and its GPU options. PCA has no dedicated test-data downloader, image preview, AI console or Run-level Plot switch. The three CSVs are not a fitted-model bundle, saved settings or exported figure. API: spacr.qt.widgets.pca_model.pca and PCASpec; PCAResult.scores_frame, loadings_frame and variance_frame.", "scenes": [{"visual": "01_image_umap_host", "narration": "Open Image UMAP from Home, then choose its nested PCA button. PCA is a linear summary of measurements, not another UMAP embedding. We reuse the downloadable Annotate example on a private copy. The Annotate tutorial shows where to obtain that real dataset.", "hold_after": 0.7, "related_lessons": ["09_annotate", "15_image_umap"]}, {"visual": "03_real_measurement_picker", "narration": "Use Load table beside the PCA heading and choose the copied measurements database, then cell. There are two thousand three hundred forty-one objects across four wells. This screen can also read a measurement CSV. A previously loaded host path is not proof that the intended table is open.", "hold_after": 0.7}, {"visual": "04_three_features_before_run", "narration": "Clear the feature search before choosing None, because that button unticks only the features currently shown. Search and tick cell_area, cell_channel_1_mean_intensity and cell_perimeter. Clear the search again, set Components to three, and choose Run PCA. Searching narrows the feature list, not the cell population.", "hold_after": 0.7, "related_lessons": ["62_feature_dictionary"], "focus": [300, 1490, 3350, 610]}, {"visual": "05_standardised_three_features", "narration": "Keep Standardise and read the scree plot. The first component explains about sixty-five point seven percent of these three features' standardised variance; the second explains thirty-one point seven percent. The points are individual measured cells, not independent experimental replicates. Explained variance is not classification accuracy.", "hold_after": 0.7, "focus": [300, 1490, 3350, 610]}, {"visual": "07_pc3_against_pc1", "narration": "Choose rowID in Colour, then PC three on X and PC one on Y. These controls redraw the existing decomposition without fitting again. The colours identify spatial rows, not established treatments. A separated-looking cloud is a prompt to investigate measurements and confounding, not proof of a biological effect.", "hold_after": 0.7, "focus": [1420, 335, 2220, 1600]}, {"visual": "09_biplot_restored", "narration": "Return to PC one and PC two. Toggle Loadings biplot off and back on. The arrows show feature correlations with these two components; their absolute length is scaled for display, with the dashed circle as a ruler. Nearby arrow directions do not establish causation.", "hold_after": 0.7, "focus": [1600, 500, 1660, 1070]}, {"visual": "11_raw_units_pca", "narration": "Change Scale to Centre only. The first component now explains about ninety point one percent, because the raw measurement scales change the analysis. That higher percentage does not make the model better. Restore Standardise before continuing; it centres each feature and divides by its sample standard deviation.", "hold_after": 0.7, "focus": [300, 1490, 3350, 610]}, {"visual": "13_live_filter_refits_basis", "narration": "In the right-hand filter, add cell_area and set the minimum to twenty-one thousand nine hundred twenty-five. The fit now uses one thousand one hundred seventy-one cells. This is a live refit: the population mean, scale and component directions change. It is not merely hiding points on the old axes.", "hold_after": 0.7, "focus": [3360, 325, 470, 620]}, {"visual": "14_clear_restores_full_basis", "narration": "Choose Clear all in the filter. All two thousand three hundred forty-one cells return, and the original decomposition is restored. Filtering never deletes database rows. Compare the population and report after every change; scores from separately fitted populations do not automatically share a common coordinate system.", "hold_after": 0.7, "focus": [1410, 1890, 2400, 225]}, {"visual": "15_missing_feature_ticked_not_run", "narration": "Now search for cell_channel_0_homogeneity_distance_32 and tick it. The existing result still contains three features until you choose Run PCA. This texture feature has seven genuinely missing values. We do not know why they are missing, so we must not call these cells uninfected or replace missing measurements with zero.", "hold_after": 0.7, "focus": [300, 1490, 3350, 610]}, {"visual": "16_auto_seven_rows_removed", "narration": "Run with Auto. All four features remain, but seven cells are removed, leaving two thousand three hundred thirty-four. Auto drops features missing in more than two percent of rows, then drops remaining incomplete rows. The three requested components capture about ninety-eight point six percent; a fourth direction still exists.", "hold_after": 0.7, "focus": [300, 1490, 3350, 610]}, {"visual": "18_drop_feature_keeps_objects", "narration": "Choose Drop features in NaN. All two thousand three hundred forty-one cells remain, but the texture feature is excluded from this fit. Four checkboxes can remain ticked while only three features are actually analysed. Read the result and dropped-feature notice, not just the requested selections.", "hold_after": 0.7, "focus": [300, 1490, 3350, 610]}, {"visual": "19_mean_imputes_seven_values", "narration": "Choose Mean-impute. All cells and all four features remain, with seven values replaced by that feature's mean for the calculation. These are invented values, not recovered measurements. The report states the replacement count. Disclose imputation whenever you present this result; the source database has not been rewritten.", "hold_after": 0.7, "focus": [300, 1490, 3350, 610]}, {"visual": "20_complete_cases", "narration": "Choose Complete cases. It keeps the four selected features and removes the same seven incomplete cells in this example. That agreement with Auto is specific to these data. Return to Auto, untick the texture feature, clear the search, choose Run PCA, and set Colour back to none.", "hold_after": 0.7, "focus": [300, 1490, 3350, 610]}, {"visual": "22_actual_three_file_export", "narration": "Choose Export and save a base name such as pca_example. The screen writes three CSV files: scores for each analysed object, loadings and correlations for each feature, and variance for each component. The scores file also retains the original measurement columns; it is not just three coordinate columns.", "hold_after": 0.7}, {"visual": "23_export_confirmation", "narration": "These exports preserve two thousand three hundred forty-one object rows and leave both databases unchanged. Record your feature list, filters, scaling and missing-value policy separately: this button does not save settings or a fitted-model bundle. For code, use pca and PCASpec in spaCR's Qt pca_model module. This CPU table view is separate from image previews, GPU analysis and spaCR AI.", "hold_after": 0.7, "related_lessons": ["06_api", "15_image_umap"]}], "poster": "60_pca/poster.jpg", "silent": "60_pca/video/60_pca_silent.mp4"}, {"id": "61_tabulate", "number": 61, "slug": "tabulate", "series": 5, "app_key": "tabulate", "section": "Explore", "title": "Tabulate: group real measurements, inspect counts and refresh the summary plot", "description": "Open Tabulate inside Database Browser, pivot downloaded measurements by well and field, inspect real missing values, export checked statistics and distinguish a live pivot from a stale or categorical chart.", "objectives": ["Find the nested Tabulate route and build well and field summaries with actual column drags.", "Read counts, missing combinations, sample standard deviations and quantiles without inventing independent replicates.", "Apply a live measurement filter, explicitly refresh its summary chart and distinguish categorical from numeric axes.", "Export the full checked pivot and keep a reproducible record of its grouping, statistics and filter."], "prerequisite": "Use the downloadable Annotate example on a byte-identical private copy of its measurements.db. The cell table contains 2,341 measured objects across four wells and 51 observed well/field combinations. These are not 2,341 independent experiments, and rowID is a spatial label, not an established treatment assignment. This lesson independently checks every demonstrated pivot statistic and CSV cell, plus all 51 final scatter-point ordinates. It does not validate biological effects, arbitrary missing axis labels, infinite values or capped large grids. Tabulate has no dedicated test-data downloader, image preview, GPU pipeline, AI console or run-level Plot switch; it summarizes existing data. Use its own Load table and Export CSV controls, not the surrounding Database Browser controls.", "scenes": [{"visual": "02_database_host", "narration": "Open Help, then Database browser, and choose the nested Tabulate button. This is a submodule of Database Browser, not a separate Home tile. We use the real downloadable Annotate example on a private copy. The earlier Annotate lesson shows how to obtain that dataset.", "hold_after": 0.7, "related_lessons": ["09_annotate", "34_database"]}, {"visual": "03_choose_real_measurements", "narration": "Inside Tabulate, choose Load table, open the private measurements database and select cell. The full table contains two thousand three hundred forty-one objects. The surrounding Database Browser has its own controls; those are not this pivot's input or export. Loading alone does not choose your grouping.", "hold_after": 0.7}, {"visual": "05_well_count_preset", "narration": "Choose Plate slash row slash column. The three keys appear in Rows in hierarchy order. Leave Values empty to count source rows: four wells contain six hundred fifteen, five hundred twenty-five, seven hundred and five hundred one objects. These counts are cells, not independent experimental replicates.", "hold_after": 0.7}, {"visual": "06b_blank_not_zero_tooltip", "narration": "Search for fieldID and drag it into Columns. Four wells by thirteen field labels gives fifty-two possible combinations, but only fifty-one contain measurements. Hover over the blank at row five, column two, field twenty. It means no source rows for that combination, not a measured value of zero.", "hold_after": 0.7, "focus": [985, 405, 2300, 260]}, {"visual": "08_area_mean_sample_sd", "narration": "Clear the Columns well, then search for cell_area and drag it into Values. The default statistics are count, mean and sample standard deviation. The table recomputes as you change the axes or statistics. The search box filters column names, not the cell population.", "hold_after": 0.7}, {"visual": "08b_read_full_cell_statistics", "narration": "In this build, the short table rows can hide the later lines, including n. Hover over a result cell to read its complete statistics and contributing count. Standard deviation describes variation among those objects; it is not uncertainty across independent wells. The popup rounds numbers for display.", "hold_after": 0.7, "focus": [985, 405, 1190, 450]}, {"visual": "09b_full_median_sem_quantile", "narration": "Turn on median, sem and quantile. At zero point seven five, quantile is the upper quartile, using linear interpolation. SEM is sample standard deviation divided by the square root of the available count. It does not correct for objects sharing a field or well, so do not treat it as independent biological uncertainty.", "hold_after": 0.7, "focus": [295, 410, 2050, 890]}, {"visual": "10b_half_quantile_tooltip", "narration": "Change Quantile at to zero point five. The quantile now matches the median: twenty-two thousand four hundred in the first well. The other statistics remain unchanged. Restore zero point seven five and turn the extra statistics off before returning to the simpler summary.", "hold_after": 0.7, "focus": [295, 410, 2050, 890]}, {"visual": "11b_source_count_vs_feature_n", "narration": "Replace area with the channel-zero homogeneity feature at distance thirty-two. It has seven genuinely missing values, leaving two thousand three hundred thirty-four available measurements. In this well, five hundred one source rows contribute only four hundred ninety-eight values. Count depends on the selected feature; missing measurements are not zeros.", "hold_after": 0.7, "focus": [295, 410, 1760, 890]}, {"visual": "13_all_well_statistics_picker", "narration": "Restore cell_area and choose Tabulate's Export CSV with a new filename. This well summary has four rows and six columns: three grouping keys, n, mean and standard deviation. We checked every exported value against the source. Keep the grouping, statistic and filter choices separately; the CSV is not a saved live specification.", "hold_after": 0.7}, {"visual": "14_four_group_means_not_2341_objects", "narration": "Choose Plot this table, then drag columnID onto X, mean onto Y and rowID onto Colour. The chart receives four summary rows, not thousands of individual cells. There is a trap: Automatic treats these four distinct means as categories and draws a heatmap. This is not a continuous-scale plot of their magnitudes.", "hold_after": 0.7, "related_lessons": ["58_graph_builder"], "focus": [295, 1300, 3340, 690]}, {"visual": "15_live_pivot_old_plot", "narration": "Use the right-hand filter to add cell_area and set its minimum to twenty-one thousand nine hundred twenty-five. The pivot immediately summarizes one thousand one hundred seventy-one remaining objects. The chart still contains the old summary until you press Plot this table again. A visible chart is not proof that it reflects the current filter.", "hold_after": 0.7}, {"visual": "16_plot_this_table_refreshes_summary", "narration": "Press Plot this table again to transfer the newly computed means. The chart now holds the four filtered groups, though Automatic still treats those means categorically. A note says the original area filter cannot apply directly to this summary table: it has mean, not cell_area. That does not mean the upstream pivot ignored the filter.", "hold_after": 0.7, "focus": [295, 1300, 3340, 690]}, {"visual": "19_replot_restores_original_summary", "narration": "Choose Clear all in the right-hand filter, then Plot this table again. The original two thousand three hundred forty-one objects and well means return. Filtering here does not delete source measurements. Export the filtered and unfiltered summaries under different names if both are needed.", "hold_after": 0.7, "focus": [295, 1300, 3340, 690]}, {"visual": "20_field_level_is_a_different_unit", "narration": "For a separate field-level view, drag fieldID into Rows after the well keys. There are fifty-two grid rows and fifty-one observed groups. The statistic now describes a field within a well, not the whole well. Fifteen to eighty-eight objects contribute to each observed group; adding groups does not create independent experiments.", "hold_after": 0.7}, {"visual": "21_actual_plot_choices", "narration": "Press Plot this table, put fieldID on X, keep mean on Y and rowID on Colour, then choose Scatter from Plot. With these fifty-one distinct field means, the actual column list identifies mean as continuous. Check the role and axis labels rather than assuming that a number is always treated numerically.", "hold_after": 0.7}, {"visual": "22_fifty_one_actual_field_means", "narration": "The chart now displays fifty-one real field means on a continuous vertical scale. Each plotted height was checked against the independently computed summary. Repeated field labels belong to different wells; colours show spatial row labels, not verified treatments. This grouped table has no object keys, so brushing cannot select individual images.", "hold_after": 0.7, "related_lessons": ["58_graph_builder", "09_annotate"], "focus": [295, 1300, 3340, 690]}, {"visual": "23_field_level_statistics_complete", "narration": "Export the field summary: fifty-two rows and seven columns, with one genuinely empty combination kept blank. The plotting hand-off omits that empty group, leaving fifty-one points. For reproducible code, pivot and PivotSpec in spacr's Qt pivot_spec module consume these choices, and to_csv writes the result. Preserve your source and record the exact grouping and filter.", "hold_after": 0.7, "related_lessons": ["06_api"]}], "host_app_key": "db_browser", "poster": "61_tabulate/poster.jpg", "silent": "61_tabulate/video/61_tabulate_silent.mp4"}, {"id": "62_feature_dictionary", "number": 62, "slug": "feature_dictionary", "series": 5, "app_key": "feature_dict", "section": "Help", "title": "Feature Dictionary: find definitions and units", "description": "Search by measurement name or concept, read the definition and units, and copy useful reference text.", "objectives": ["Find a definition by name or concept.", "Narrow the results with concept and object filters.", "Read units and notes, then copy the definition."], "prerequisite": "Have a measurement column name ready, or start with an idea such as size or intensity. The built-in dictionary can be opened without loading a project.", "scenes": [{"visual": "01_help_dictionary", "narration": "Open Help, then Feature Dictionary. Use this window when you want to understand a measurement column in a results table or plot.", "hold_after": 0.7, "related_lessons": ["34_database"]}, {"visual": "03_search_by_idea", "narration": "Type size in the search field and select Area from the results. The definition appears on the right, and the matching list updates as you type.", "hold_after": 0.7, "focus": [420, 150, 3020, 550]}, {"visual": "04_actual_concept_object_filters", "narration": "Choose a concept and object type to narrow the definitions. Try intensity and cell. Reset the selectors to Any concept and Any object for a broader search.", "hold_after": 0.7, "focus": [420, 150, 3020, 450]}, {"visual": "05_measurement_name", "narration": "Search for cell_channel_1_mean_intensity and select Mean intensity. Read the statistic and units to understand what the column describes.", "hold_after": 0.7, "focus": [1620, 265, 1780, 355]}, {"visual": "06_computing_function", "narration": "Scroll down to Channel, Module and Computed by for more detail. Use the named computing function as a starting point in the API reference.", "hold_after": 0.7, "focus": [1630, 1650, 1760, 225], "related_lessons": ["06_api"]}, {"visual": "07_conditional_area_units", "narration": "Look up cell_area and read Unit. In two-dimensional measurements it represents area; in three-dimensional measurements it represents volume. Check the measurement units recorded in your project before converting values.", "hold_after": 0.7, "focus": [1620, 265, 1780, 380]}, {"visual": "08_area_caveats", "narration": "Read Note for qualifications such as values already expressed in physical units. For a dictionary of the columns actually present in a database, use describe_database and export_dictionary from Python.", "hold_after": 0.7, "focus": [1630, 1520, 1760, 355], "related_lessons": ["06_api", "34_database"]}, {"visual": "09_unknown_search", "narration": "If no definitions match, clear the filters and try a broader term or the exact column name. Custom features may need documentation from the workflow that created them.", "hold_after": 0.7, "focus": [420, 150, 3020, 450]}, {"visual": "11_actual_text_copy", "narration": "Select the definition text and copy it into your notes. Use the Python export functions when you need a project-specific dictionary file, then return to your table or plot.", "hold_after": 0.7, "related_lessons": ["06_api", "34_database"]}], "narration_voices": {"en": ["af_heart"]}, "poster": "62_feature_dictionary/poster.jpg", "silent": "62_feature_dictionary/video/62_feature_dictionary_silent.mp4"}, {"id": "63_small_multiples", "number": 63, "slug": "small_multiples", "series": 5, "app_key": "trellis", "section": "Explore", "title": "Small Multiples: real groups, live filters and honest scales", "description": "Open the nested Small Multiples view, compare genuine downloaded measurements on matched or independent scales, inspect real empty groups and capped wrapping, and create a reversible derived column.", "objectives": ["Find Small Multiples inside Graph Builder and build a real object-level scatter grid.", "Compare shared, free, per-row and per-column limits without confusing scale changes with data changes.", "Filter live, distinguish empty groups from unused wrap slots and account for omitted facet levels.", "Create and remove an in-memory rescaling, preserving the source and recording reproducible chart choices."], "prerequisite": "Use the downloadable Annotate example on a byte-identical private copy of measurements.db: 2,341 objects across four wells. The source includes 13 field labels and 51 observed well/field combinations. Object counts are not independent experimental replication, and spatial labels are not established treatments. All demonstrated continuous scatter-point coordinates, exact group memberships, axis limits, group titles and visible-versus-hidden panels are independently checked against source rows. The proof is bounded to finite, nondegenerate axes and this unsampled dataset; it does not validate arbitrary plots, linked-view brushing, biological effects or physical-unit calibration. Small Multiples is a table-only Graph Builder submodule, with no dedicated download, image preview, GPU pipeline, AI console, Run-level Plot switch or export button. Reuse Annotate's test data and its own Load table control.", "scenes": [{"visual": "01_graph_builder_host", "narration": "Open Graph Builder from Home, then choose its nested Small Multiples button. This is the current submodule route, not a separate Home tile. We reuse the genuine downloadable Annotate measurements on a private copy; the Annotate tutorial shows how to obtain that example.", "hold_after": 0.7, "related_lessons": ["09_annotate", "58_graph_builder"]}, {"visual": "03_choose_real_measurements", "narration": "Use Load table inside Small Multiples and select the private measurements database, then cell. It contains two thousand three hundred forty-one measured objects across four wells. The host Graph Builder has a separate Load table button. Use the one beside the Small Multiples heading for this workflow.", "hold_after": 0.7}, {"visual": "05_four_wells_shared_axes", "narration": "Search for cell_area and drag it onto X, then put cell_channel_1_mean_intensity on Y. Choose Scatter in Plot. Drag rowID onto Facet down and columnID onto Facet across. Search narrows the column list, not the cell population. Each plotted point here is an existing measured object.", "hold_after": 0.7, "focus": [300, 1720, 700, 390]}, {"visual": "05_four_wells_shared_axes", "narration": "With both scales shared, all four panels use the same horizontal and vertical limits. Their titles report six hundred fifteen, five hundred twenty-five, seven hundred and five hundred one objects. The row and column labels describe position, not verified treatments. These cells are not independent experimental replicates.", "hold_after": 0.7}, {"visual": "06_both_axes_free", "narration": "Set both X scale and Y scale to free. Each panel now uses its own range. This reveals within-group shape, but equally wide clouds need not span equal measurement values. Read the tick labels before comparing panels. Changing the scales does not alter any source measurements.", "hold_after": 0.7}, {"visual": "07_both_axes_row", "narration": "Choose per row for both scales. Panels on the same grid row now share limits, while different grid rows can differ. This is a layout-based scale group, not a statistical correction. Here the two columns within each row are directly comparable on their matched axes.", "hold_after": 0.7}, {"visual": "08_both_axes_col", "narration": "Choose per column for both scales. Panels in the same grid column now share limits. X and Y can also be configured separately; this demonstration changes both together. Restore shared for both before comparing all four wells. Shared means common within the current grid, not fixed across every later filter.", "hold_after": 0.7}, {"visual": "10_live_area_filter", "narration": "In the Filter tab, add cell_area and set its lower bound to twenty-one thousand nine hundred twenty-five. The actual grid updates immediately to one thousand one hundred seventy-one objects. The panel counts and points change together. This is a live measurement filter, not image segmentation or a new analysis run.", "hold_after": 0.7}, {"visual": "11_all_cells_restored", "narration": "Choose Clear all in the Filter tab. All two thousand three hundred forty-one objects return, with their original point positions and shared limits. This button clears the filter; Clear all channels on the left instead removes the chart assignments. Neither action deletes rows from the database.", "hold_after": 0.7}, {"visual": "12_real_empty_group", "narration": "To inspect a genuine missing group, filter columnID to c two and fieldID to f twenty and f twenty-one, scrolling the category list as needed. Put fieldID on Facet across and keep rowID on Facet down. One hundred seventy-four cells remain. The row-five, field-twenty panel has n equals zero: no source objects, not a measured zero intensity.", "hold_after": 0.7, "related_lessons": ["61_tabulate"]}, {"visual": "14_two_way_wrap_ignored", "narration": "Clear the filters and restore columnID on Facet across. Set Wrap at to five while both facet channels are assigned. The grid remains two by two, and the notice says wrapping is ignored. Wrapping applies when only one facet channel is in use; it does not rearrange a two-way grid.", "hold_after": 0.7}, {"visual": "15_twelve_fields_and_three_unused_slots", "narration": "Clear Facet down, put fieldID on Facet across and keep Wrap at five. The retained fields now form three rows, five slots wide. Only twelve field levels are drawn, although the source has thirteen. The three unused positions are hidden layout padding, unlike a real group displayed with n equals zero.", "hold_after": 0.7}, {"visual": "15_twelve_fields_and_three_unused_slots", "narration": "Read the notice below the grid. Field twenty-one falls outside the twelve displayed levels, excluding two hundred sixty-four source objects from the panels. Two thousand seventy-seven points are actually drawn, even though the loaded table still contains two thousand three hundred forty-one rows. A loaded-row count is not proof that every row is visible.", "hold_after": 0.7, "focus": [1000, 1460, 2150, 650]}, {"visual": "17_actual_area_formula", "narration": "Turn wrapping off and restore rowID and columnID as the two facets. In Columns, enter area_k as the name and cell_area divided by one thousand as the expression, exactly as shown. The preview checks the first two thousand rows. Choose Add column to compute the derived values for the full table, without rewriting the database.", "hold_after": 0.7, "focus": [3120, 315, 460, 940]}, {"visual": "18_rescaled_area_not_new_measurement", "narration": "Drag area_k onto X. Every horizontal coordinate is now the original cell area divided by one thousand; Y values and group membership remain unchanged. This is a numerical rescaling, not calibration to square micrometres, a new measurement or evidence of a biological effect. All two thousand three hundred forty-one derived values were checked.", "hold_after": 0.7}, {"visual": "19_formula_removed_original_points", "narration": "Put cell_area back on X before selecting area_k in Columns and choosing Remove. The original four-panel plot returns and the derived column disappears. Both the private database and the original downloaded data remain unchanged. Record your variables, grouping, filters and scale choices so someone else can reproduce the view.", "hold_after": 0.7}, {"visual": "19_formula_removed_original_points", "narration": "For code, trellis and TrellisSpec in spaCR's Qt trellis_spec module define the grouping, scales and wrap; GraphSpec defines the chart channels. This screen has no dedicated export button or downloadable dataset of its own. Use Tabulate for checked summary CSV exports. Image previews, GPU pipelines and spaCR AI belong to the relevant analysis lessons, not this table-only view.", "hold_after": 0.7, "related_lessons": ["06_api", "61_tabulate"]}], "host_app_key": "graph_builder", "poster": "63_small_multiples/poster.jpg", "silent": "63_small_multiples/video/63_small_multiples_silent.mp4"}, {"id": "64_gate_editor", "number": 64, "slug": "gate_editor", "series": 5, "app_key": "gate_editor", "section": "Tools", "title": "Gate Editor: real populations, reversible views and exact exports", "description": "Draw gates on downloaded cell measurements, verify saved membership, compare real three-dimensional and projected views, and inspect bounded clustering without inventing biological labels.", "objectives": ["Load real measurements and distinguish gates, view filters and visibility.", "Save and restore feature boundaries, then export membership with exact object identities.", "Explore three-dimensional bounds and principal components without confusing a projection with a reusable fitted transform.", "Compare actual cluster-search outcomes and use the local measurement console."], "prerequisite": "Download the Annotate example first, then make a private copy of its measurements database. Gate Editor has no separate example-download button. This recording uses all 2,341 real cell rows and modifies only that private copy when exporting; tutorial gate names are inspection labels, not biological ground truth.", "scenes": [{"visual": "01b_readable_panels", "narration": "Open Gate Editor in Home's Tools category. Drag the dividers to give the plot, gate table and side controls enough room. This lesson uses the downloaded Annotate measurements; Gate Editor does not have its own example-download button.", "hold_after": 0.7, "related_lessons": ["09_annotate"]}, {"visual": "02_real_database_picker", "narration": "Use Load table to open a private copy of measurements dot D B. Choose the cell table: this example contains two thousand three hundred and forty-one real objects. Export gates writes to a database, so keep the original example unchanged and work on the copy.", "hold_after": 0.7}, {"visual": "04_real_scatter", "narration": "Choose cell area for X and cell channel one mean intensity for Y, with the Rectangle tool. Each point represents a measured object. Inspect the feature names and units before drawing; an area-intensity region alone does not establish an infected cell or another biological class.", "hold_after": 0.7}, {"visual": "05_name_drawn_gate", "narration": "Drag across the scatter, release and enter a descriptive gate name. Our tutorial population is deliberately an inspection example. The shape records numerical boundaries in these two measurements; it is not a model trained to recognise cells from their images.", "hold_after": 0.7}, {"visual": "06_real_gate_and_counts", "narration": "This drawn region contains six hundred and fifty-five objects, about twenty-eight percent of the table. Read the count and percentages beside the gate name. Different mouse positions produce different boundaries and counts, so use the saved strategy when you need an exact repeat.", "hold_after": 0.7, "focus": [2420, 375, 820, 430]}, {"visual": "07_gate_hidden_not_deleted", "narration": "Unticking the gate hides its overlay without deleting its definition or changing membership. Tick it again to restore the view. This is different from Delete gate, and different from the Filter tab, which changes the objects displayed beneath the gates.", "hold_after": 0.7, "focus": [2420, 375, 820, 430]}, {"visual": "09_save_strategy", "narration": "Use Save gates to keep the named feature boundaries in a JSON strategy. Here we save, actually delete the gate, and then load the saved file. Reusing a strategy requires matching measurement names, units and preprocessing, not simply a table with the same number of columns.", "hold_after": 0.7}, {"visual": "12_strategy_restored", "narration": "Load gates restores the same boundaries and all six hundred and fifty-five members. We checked membership after actually deleting and reloading the gate, rather than merely saving a file. On another dataset, verify the restored boundaries and object identities before relying on its counts.", "hold_after": 0.7}, {"visual": "12b_save_graph", "narration": "Save graph writes the actual figure; this recording's preferences produce a PNG and a PDF. A figure is different from a gate strategy or exported membership. Keep the corresponding data and strategy when you need to reproduce how a displayed population was defined.", "hold_after": 0.7}, {"visual": "12c_exported_gate_membership", "narration": "Export gates writes membership flags to the private database's filters table. Our first gate marks exactly six hundred and fifty-five cell identities, matched by plate, row, column, field, object label and object type. The original download and underlying cell measurements remain unchanged.", "hold_after": 0.7}, {"visual": "14_second_gate_not_automatically_nested", "narration": "Draw a second shape while the first is selected. Its two hundred and fifty-nine objects include some outside the first: new drawing is not automatically nested, despite older status wording. Save this two-gate strategy separately and inspect any parent relationships explicitly when loading an existing hierarchy.", "hold_after": 0.7, "focus": [2420, 375, 820, 520]}, {"visual": "16_actual_three_dimensional_view", "narration": "Choose three D and cell perimeter for Z to inspect three actual measurements. The spin-axis buttons guide rotation. Rotating changes the view, not the saved boundaries of the two existing area-intensity gates; return to two D to inspect those shapes again.", "hold_after": 0.7}, {"visual": "17c_actual_volume_gate", "narration": "From view creates a named box with bounds on all three displayed measurements. Our full-volume example includes every loaded object: it demonstrates the control, not an enriched biological population. Save the three-gate strategy separately so the earlier two-gate file remains available.", "hold_after": 0.7}, {"visual": "18_actual_projection_2d", "narration": "The x D toggle computes principal components from eligible measurements. It is separate from the two D or three D view choice. Here the source label reports seventeen, thirteen and six percent explained variance for the first three components; these are variance fractions, not classification accuracy.", "hold_after": 0.7}, {"visual": "20_projection_off_keeps_columns", "narration": "Turning x D off retains the component columns; choose the raw axes again when returning to raw-feature gates. A saved gate strategy does not save the fitted projection. Component names alone do not make independently fitted projections compatible, so do not reuse their gate boundaries blindly.", "hold_after": 0.7}, {"visual": "21_bounded_walk_settings", "narration": "For Search, widen the side panel and remove the temporary gates after saving them. Use the same two raw features, scaling enabled, twenty minimum neighbours and five Walk steps. Run walk opens a confirmation in this build; check that its values match the visible controls.", "hold_after": 0.7}, {"visual": "22_walk_outcome", "narration": "The actual Walk selects a radius near zero point one six seven and reports two populations, with thirty-three percent of objects outside them. Inspect the resulting outlines. Density clustering and its saved polygon gates are exploratory descriptions, not validated cell types or proof that excluded objects are invalid.", "hold_after": 0.7}, {"visual": "25_fixed_radius_result", "narration": "Save the Walk strategy, remove its temporary gates, turn Walk off and run radius zero point five. This separate choice creates one larger polygon gate, containing two thousand two hundred and thirty-nine objects. It is not a better answer merely because it includes more cells.", "hold_after": 0.7}, {"visual": "28_live_area_filter", "narration": "Reload the saved two-gate raw-feature strategy, then add cell area in Filter. Setting the lower cutoff to twenty-one thousand nine hundred and twenty-five leaves one thousand one hundred and seventy-one displayed objects. This live preview narrows the view without rewriting the saved gate boundaries.", "hold_after": 0.7}, {"visual": "29_live_filter_cleared", "narration": "Clear the filter and all two thousand three hundred and forty-one objects return. Check both the active view filter and the gate definition before interpreting counts or exporting. Hiding an overlay, filtering a view and deleting a gate are three different operations.", "hold_after": 0.7}, {"visual": "31_real_console_answer", "narration": "Drag the far-right divider left to reveal the console. Enter len, open parenthesis, D F, close parenthesis: the real table returns two thousand three hundred and forty-one. The expression console works locally; it is not an answer generated by an artificial-intelligence model.", "hold_after": 0.7, "focus": [3090, 320, 740, 1795]}, {"visual": "32_chat_draft_not_sent", "narration": "The chat box is separate from expressions. We leave an unsent draft, without demonstrating an assistant or biological interpretation. In Python, GateSet from spacr.qt.widgets.gate_spec stores definitions; gate_mask_over_table and export_gate in spacr.filters evaluate and save full-table object flags. Verify the identities before downstream annotation.", "hold_after": 0.7, "focus": [3090, 320, 740, 1795], "related_lessons": ["06_api", "09_annotate"]}], "poster": "64_gate_editor/poster.jpg", "silent": "64_gate_editor/video/64_gate_editor_silent.mp4"}, {"id": "65_feature_explorer", "number": 65, "slug": "feature_explorer", "series": 5, "app_key": "feature_explorer", "section": "Explore", "title": "Feature Explorer: rank real measurements and keep the comparison explicit", "description": "Open the Classify submodule, compare real plate-row measurements, inspect distributions, filter live, add a computed column and export the intended ranking without training a classifier.", "objectives": ["Find Feature Explorer inside Classify and load existing cell measurements.", "Distinguish AUC from separation, and inspect class counts and distribution differences.", "Filter live without overlooking an automatic change of comparison column.", "Use Top deliberately, verify a scaled computed column and export the actual ranking."], "prerequisite": "Use the downloaded Annotate example, not invented measurements. The recording opens a byte-identical private copy of its 2,341-cell, 276-column measurement database. The two rowID groups are spatial plate rows r12 and r5, not asserted treatments; cells share fields and wells and are not independent experiments. Original data remain unchanged. AUC, KS, ranking order and finite class counts are independently checked for the intended two-class comparisons. The automatically selected eight-class comparison is a warning example, not independently validated inference. Shuffle test stays off. No classifier training, new image analysis, dedicated download, GPU operation or AI request occurs here; the displayed histograms are the module's own plots.", "scenes": [{"visual": "01_classify_host", "narration": "Open Classify, then its Feature Explorer button. This nested tool ranks existing measurements; opening it does not train a classifier. We use the real downloadable Annotate example on a private database copy. Follow the Annotate lesson to obtain the example, and keep your experimental source unchanged.", "hold_after": 0.7, "related_lessons": ["09_annotate"]}, {"visual": "04_real_row_comparison", "narration": "Choose Load table, select the measurement database and its cell table, then set Split by to rowID. There are two thousand three hundred forty-one cells and two hundred seventy-six columns. Our two groups are recorded plate rows, not established treatments; these cells are not independent experiments.", "hold_after": 0.7, "focus": [345, 280, 3460, 370]}, {"visual": "05_four_distributions", "narration": "Rank by AUC and read both numeric columns. Separation is the absolute value of twice AUC minus one, so about zero point three four separation is not a zero point three four AUC. Higher in names the direction; min n counts finite measurements in the smaller class, not replicate experiments.", "hold_after": 0.7, "focus": [345, 380, 950, 275]}, {"visual": "05_four_distributions", "narration": "Set Top to four to inspect four overlaid histograms. Classes share the same bin edges within each feature, and bar heights are counts. The largest ranking is not automatically a useful biomarker. Read the warning: AUC can miss differences in spread even when the distributions differ.", "hold_after": 0.7, "focus": [1290, 460, 1810, 1590]}, {"visual": "06_top_four_ranking_complete", "narration": "Export ranking with Top four writes four feature rows. In this build the export follows Top, despite wording that suggests the whole ranking. It does not export the underlying cells or save a trained model. We compared every exported value with the actual current ranking.", "hold_after": 0.7}, {"visual": "08_full_ranking_complete", "narration": "Set Top to five hundred before exporting all scored features in this example. Two hundred sixty-one features can be scored; two numeric candidates cannot. The export contains all two hundred sixty-one rows, while the display draws at most eight distributions. Feature counts, table rows and plotted panels are different quantities.", "hold_after": 0.7, "focus": [345, 375, 2760, 1650]}, {"visual": "09_ks_comparison", "narration": "Switch Rank by to KS to compare the largest gap between cumulative distributions, then return to AUC. KS can reveal distribution differences that AUC misses but does not provide direction itself. Other offered statistics have their own limitations; read the visible warning rather than treating a rank as a significance test.", "hold_after": 0.7, "focus": [345, 375, 2760, 400]}, {"visual": "10_live_area_filter", "narration": "In Filter, add cell_area and set the minimum to twenty-one thousand nine hundred twenty-five. The visible population changes to one thousand one hundred seventy-one cells, and two hundred fifty-five features remain scorable. This median-based demonstration threshold is not a biological quality cutoff. Rankings and distributions update without remeasuring images.", "hold_after": 0.7, "focus": [3105, 375, 355, 420]}, {"visual": "11_restore_all_cells", "narration": "Clear all removes the display filters, not the data. All two thousand three hundred forty-one cells and the original ranking return. Recheck the population and Split by whenever you change filters. A difference that changes after filtering describes a different selected population, not a new experiment.", "hold_after": 0.7}, {"visual": "12_one_row_changes_comparison", "narration": "There is an important trap in this build. Filtering rowID to r12 removes the other row, but the screen silently switches Split by to cell_channel_0_maxima_count. It now compares eight groups, with only one object in the smallest. Those impressive scores are not the original row comparison or evidence of a biological discovery.", "hold_after": 0.7, "focus": [345, 375, 3460, 400]}, {"visual": "13_restore_two_classes", "narration": "Clear the filter and explicitly choose rowID again. Clearing alone does not necessarily restore the original comparison. Verify both the class column and the population before exporting. Shuffle test offers fifty label shuffles, but we leave it off: freely shuffling these correlated cells would not establish well-level or treatment-level evidence.", "hold_after": 0.7, "focus": [345, 375, 3460, 275]}, {"visual": "14_scaled_area_formula", "narration": "Open Columns and name a new column area_k. Enter cell_area divided by one e three, meaning one thousand, and choose Add column with replacement off. This rescales area; it does not calibrate physical units or add a new measurement. Preview checks the first two thousand rows; adding applies the formula to the full table.", "hold_after": 0.7, "focus": [3105, 375, 355, 1030]}, {"visual": "16_ranking_with_derived_area_complete", "narration": "The scaled column joins the ranking and export, giving two hundred sixty-two scored features. Its AUC and KS equal those of cell_area because positive rescaling preserves order. We checked every computed value. Remove the formula to return to the original two hundred sixty-one features; the measurement database remains unchanged.", "hold_after": 0.7}, {"visual": "17_original_features_restored", "narration": "Use these rankings for descriptive exploration, not independent validation of a selected feature or a trained classifier. In Python, spacr.qt.widgets.feature_rank provides rank_features and ExplorerSpec. For inspecting raw tables or drawing other comparisons, continue with Database Browser and Graph Builder. No new image-analysis pipeline or AI request was run.", "hold_after": 0.7, "related_lessons": ["06_api", "34_database", "58_graph_builder"]}], "host_app_key": "classify_merged", "poster": "65_feature_explorer/poster.jpg", "silent": "65_feature_explorer/video/65_feature_explorer_silent.mp4"}, {"id": "66_outliers", "number": 66, "slug": "outliers", "series": 5, "app_key": "outliers", "section": "Explore", "title": "Outliers: inspect real flags without deleting observations", "description": "Open Outliers inside QC, compare robust rules on real cell measurements, distinguish unscored wells from clean wells, inspect an actual log-transform refusal and export every row with its flags.", "objectives": ["Find the QC submodule and select measured features deliberately before Scan.", "Compare MAD, IQR and explicit log transforms without treating flags as validated errors.", "Distinguish object counts, displayed rows and unscored well comparisons.", "Export original measurements with flags and recover safely from an invalid transform."], "prerequisite": "Use the downloadable Annotate example on a byte-identical private database copy. Its 2,341 cells occupy four recorded wells; they are not independent experiments or known defective objects. Original measurements are never edited or deleted. The lesson independently checks finite, nondegenerate single-feature MAD/IQR arithmetic, each object's flag position, well medians/counts and the explicit fewer-than-five-wells refusal. It does not validate the automatic all-feature scan, zero-scale fallback, multivariate MCD inference or biological quality. These are scans of an existing measurement table, not new image segmentation, GPU analysis or classifier training. This screen has no image preview, Plot toggle, dedicated test-data downloader or AI console; its Objects, Wells and Report tabs are the actual outputs.", "scenes": [{"visual": "02_qc_host", "narration": "Open QC from Home, then choose its Outliers button. QC's dashboard reads stored checks, while this nested tool computes flags from a measurement table. We use the real downloadable Annotate example on a private database copy. Follow that lesson to obtain the example and leave your experimental source unchanged.", "hold_after": 0.7, "related_lessons": ["09_annotate", "54_qc_dashboard"]}, {"visual": "04_automatic_all_features", "narration": "Choose Load table and the database's cell table. Loading automatically scans all selected continuous features: two hundred fifty-five here, over two thousand three hundred forty-one cells. This broad default flags two thousand three hundred thirty-eight objects. That does not prove nearly every cell is bad. Loading the wide result table can take time.", "hold_after": 0.7, "focus": [295, 345, 3515, 170]}, {"visual": "05_choose_one_feature_before_scan", "narration": "With the feature search empty, choose None to untick everything. Search for cell_area and tick only that exact feature, then press Scan. The search narrows feature names, not cell rows. Changing the selection does not automatically rescan: the old result can remain visible until you run the new rule.", "hold_after": 0.7, "focus": [3295, 455, 390, 1595]}, {"visual": "06_area_mad_3_5", "narration": "For MAD, leave the transform at none and k at three point five. The rule divides the absolute distance from the median by about one point four eight two six times the median absolute deviation. It flags twenty-six cells. These are candidates for inspection, not confirmed segmentation mistakes, and no row has been removed.", "hold_after": 0.7, "focus": [295, 455, 1510, 315]}, {"visual": "07_four_wells_not_scored", "narration": "Open Wells. All four wells contain over five hundred objects, but none is scored: the across-well comparison needs at least five eligible wells. Read well_scored and the specific reason, not just Wells zero. Flagged share summarizes object flags; it is not a well-level score or evidence that the well is clean.", "hold_after": 0.7, "focus": [295, 455, 3005, 300]}, {"visual": "08_area_report", "narration": "The Report gives the rule, measured centre, scale and caveats. One caveat in this build wrongly says these four wells had fewer than twenty objects. Their actual counts are five hundred one to seven hundred; the reason is too few wells. Use the specific well-table reason, and do not repeat the incorrect count explanation.", "hold_after": 0.7, "focus": [295, 455, 3005, 550]}, {"visual": "10_broad_rule_not_quality_cutoff", "narration": "A stricter distance requirement flags fewer objects. Lowering k to two produced one hundred forty-two flags; at zero point five it produces one thousand four hundred seventy-nine. That last setting is deliberately broad for demonstration, not a recommended quality cutoff. The object table displays only five hundred rows, so its row count is not the flag count.", "hold_after": 0.7, "focus": [3295, 1745, 390, 330]}, {"visual": "11_all_rows_not_display_cap_complete", "narration": "Choose Export and a new filename. The objects CSV keeps all two thousand three hundred forty-one rows and appends flags; flagged contains the one thousand four hundred seventy-nine flagged rows. Wells contains four summaries, and report is a text file. Every exported measurement and flag was checked. Export is not deletion, and it is not limited to the displayed five hundred rows.", "hold_after": 0.7, "focus": [295, 345, 3515, 170]}, {"visual": "13_area_iqr", "narration": "Restore the original rule, then choose IQR. The threshold now means c times the interquartile range, not robust standard deviations. With c at one point five, raw cell area gives fifty-five flags. We independently checked both quartile fences and every flagged position. A tail of a skewed distribution can be flagged even when its measurements are valid.", "hold_after": 0.7, "focus": [295, 455, 1510, 315]}, {"visual": "14_iqr_report", "narration": "There is another wording error to recognize. This IQR report labels twenty-two thousand six hundred sixty-three as the median, but that number is the midpoint of the first and third quartiles. The actual median is twenty-one thousand nine hundred twenty-five. The checked fences are correct; do not cite that displayed centre as the median.", "hold_after": 0.7, "focus": [295, 455, 3005, 550]}, {"visual": "16_log_area_mad", "narration": "Choose log10 explicitly and scan again. On these positive areas, IQR gives seventy-nine flags, while switching back to MAD at three point five gives thirty-six. Log transformation changes distances and the question being asked; it does not guarantee fewer flags or biological correctness. The reported centres and scales are now in log10 units.", "hold_after": 0.7, "focus": [3295, 1745, 390, 330]}, {"visual": "17_real_intensity_raw", "narration": "For a real refusal example, return to no transform and select cell_channel_0_min_intensity alone. Scan succeeds and flags sixty-eight objects. One measured value is actually zero. This positive counterpart matters: the table and feature work before we ask for a transform whose domain excludes that value.", "hold_after": 0.7, "focus": [295, 455, 1700, 315]}, {"visual": "18_real_zero_refusal", "narration": "Now select log10 and press Scan. The real error names the one zero or negative value and its feature. No pseudocount is invented and no object is dropped; export is disabled. Old object-table rows and its count can remain visible after failure, so they are not a successful new result. Read the error and restore a valid rule.", "hold_after": 0.7, "focus": [295, 375, 3540, 230]}, {"visual": "21_low_count_reasons", "narration": "Return to raw cell_area and MAD three point five, then scan to recover the original twenty-six flags. Raising Min objects per well to seven hundred changes eligibility: only one well reaches that count, while the other three retain explicit low-count reasons. Lowering this minimum cannot create the missing fifth well. Not scored is never the same as cleared.", "hold_after": 0.7, "focus": [295, 455, 3005, 300]}, {"visual": "22_objects_only", "narration": "Restore the minimum to twenty and switch Score wells too off, then scan. Object flags remain twenty-six and no well comparison is requested. Switch it back on and scan to restore the four unscored well summaries. This setting changes the analysis level; it is not a filter that deletes cells or wells from your database.", "hold_after": 0.7, "focus": [3295, 1745, 390, 330]}, {"visual": "24_final_flags_and_report_complete", "narration": "Export the restored rule under a different filename. The final files contain two thousand three hundred forty-one object rows, twenty-six flagged rows, four well summaries and the report. Both the original and private measurement database are unchanged. Keep the rule and report with the flags so a different threshold is not mistaken for the same analysis.", "hold_after": 0.7, "focus": [295, 345, 3515, 170]}, {"visual": "method_choices_mad", "narration": "The menu also offers robust multivariate Mahalanobis, which we have not run in this lesson. Its alpha depends on distribution assumptions and is not a guaranteed error rate. The Python consumer is detect_outliers with OutlierSpec in spacr.qt.widgets.outlier_model. To inspect distributions or images, continue with Feature Explorer or Annotate; no image preview or AI request happened here.", "hold_after": 0.7, "related_lessons": ["06_api", "09_annotate", "65_feature_explorer"], "focus": [3435, 1785, 395, 155]}], "host_app_key": "qc_dashboard", "poster": "66_outliers/poster.jpg", "silent": "66_outliers/video/66_outliers_silent.mp4"}, {"id": "67_experiment_design", "number": 67, "slug": "experiment_design", "series": 5, "app_key": "experiment_design", "section": "Data", "title": "Experiment Design: a reproducible plate plan and exact export", "description": "Edit a proposed plate layout through the actual controls, inspect capacity and replication warnings, reproduce random assignments and export the exact well map.", "objectives": ["Plan conditions and control roles before acquisition.", "Demonstrate warning and recovery states without treating layout checks as biological validation.", "Reproduce the same random layout and distinguish selected wells from assigned conditions.", "Export and retain the exact well table when row/column settings cannot express the design."], "prerequisite": "No acquired images or downloaded dataset are required for this planning module. The recording uses the application's real draft of six negative-control, six positive-control and twelve treatment wells, named tutorial_plan. These counts illustrate the interface; they are not a power calculation or acquired experimental result.", "scenes": [{"visual": "01_module", "narration": "Open Experiment Design in Home's Data category before acquisition. This module creates a proposed plate layout, not measured biological results. Our negative, positive and treatment names are draft labels; choose meaningful names and controls for your own experiment.", "hold_after": 0.7}, {"visual": "02_named_draft", "narration": "Name the plate so its identifier will match the images and measurements later. If a table column is narrow, double-click its header boundary to fit the contents. Review Condition, Replicates and Role together. The example's six, six and twelve wells demonstrate the interface, not a justified sample size.", "hold_after": 0.7, "related_lessons": ["68_power_design"]}, {"visual": "03_capacity_warning", "narration": "Choosing a six-well format while requesting twenty-four wells produces a capacity error. The map does not quietly drop excess replicates. Read the message, then change the format or experimental plan; do not treat an empty map as a valid allocation.", "hold_after": 0.7, "focus": [450, 1910, 3150, 205]}, {"visual": "04_capacity_restored", "narration": "Returning to ninety-six wells restores all twenty-four assignments. The plate map updates from the current table. Add condition and Remove selected manage condition rows; the square wells below are a separate selection surface, not those table rows.", "hold_after": 0.7, "focus": [450, 365, 3370, 285]}, {"visual": "05_single_replicate_warning", "narration": "Select a replicate cell and press F two to edit it. Reducing the negative control to one well raises a warning; restoring six removes that warning. Many cells within one well do not substitute for independent experimental replication.", "hold_after": 0.7}, {"visual": "06_block_layout_warning", "narration": "Block layout places conditions together and raises positional-confounding warnings. Read these as prompts to inspect the design, not automatic biological conclusions. Optical illumination correction does not correct evaporation or temperature effects; experimental layout and image shading are different problems.", "hold_after": 0.7}, {"visual": "07_random_interior_seed42", "narration": "Choose random layout, leave edge empty, and seed forty-two. The outer ring leaves sixty usable wells on this ninety-six-well plate; our plan assigns twenty-four. Avoiding the outer ring costs capacity and does not guarantee freedom from all spatial effects.", "hold_after": 0.7, "focus": [450, 635, 620, 445]}, {"visual": "08_seed43", "narration": "Changing the seed to forty-three changes the actual assignments while preserving the requested condition counts. Randomisation reduces systematic placement bias, but a single random layout still needs review. Do not pick a seed to favour a desired outcome.", "hold_after": 0.7, "focus": [450, 635, 620, 445]}, {"visual": "09_seed42_restored", "narration": "Returning to forty-two restores exactly the same well-to-condition mapping. Record the seed together with the plate format, edge policy and condition table. The seed alone does not define a design if those other inputs change.", "hold_after": 0.7, "focus": [450, 635, 620, 445]}, {"visual": "10_selected_wells_not_reassigned", "narration": "Drag across B zero two to C zero four to select six wells. The selection outline changes, but their conditions do not: this gesture selects wells and does not assign a treatment. Check the condition table and the displayed map when revising an allocation.", "hold_after": 0.7, "focus": [450, 635, 620, 445]}, {"visual": "11_export_folder", "narration": "Use Export plate map and choose a dedicated folder. The real export writes plate_map dot CSV, plate_map dot JSON and plate_map_settings dot JSON. Keep the three files together; selecting a destination is not the same as acquiring the planned experiment.", "hold_after": 0.7}, {"visual": "12_real_export_complete", "narration": "The CSV contains one row per assigned well: twenty-four here, matching every displayed condition and role. It joins to measurements using plate I D, row I D and column I D together. The JSON records the seed, design and findings, including warnings rather than hiding them.", "hold_after": 0.7, "focus": [450, 2070, 3300, 50]}, {"visual": "09_seed42_restored", "narration": "This random layout cannot be represented by the row-or-column treatment settings. The settings file explicitly reports expressible as false; it is not a complete analysis configuration. Use the exact exported well table and an explicit join, rather than approximating mixed wells with whole-row labels.", "hold_after": 0.7, "focus": [450, 2070, 3300, 50]}, {"visual": "12_real_export_complete", "narration": "The Python interface lives in spacr.qt.widgets.plate_layout: Condition and PlateDesign describe the plan; assign_wells, check_design and write_design allocate, inspect and save it. Layout checks do not establish statistical power or biological validity. Review the design before acquisition and keep its exact map for downstream analysis.", "hold_after": 0.7, "related_lessons": ["06_api", "68_power_design", "33_plate_viewer"]}], "poster": "67_experiment_design/poster.jpg", "silent": "67_experiment_design/video/67_experiment_design_silent.mp4"}, {"id": "68_power_design", "number": 68, "slug": "power_design", "title": "Power / Design: read the simulator and its limitations", "series": 5, "app_key": "power", "section": "Design", "example_files": ["Power_recorded_simulation_review.zip"], "description": "Understand the actual planning controls, simulated detection curves and warnings without mistaking a small demonstration or contradictory headline for validated design advice.", "objectives": ["Distinguish simulation assumptions from acquired experimental data.", "Read usable fits, detection fractions and uncertainty correctly.", "Recognize the same-design recommendation error and preserve the recorded evidence."], "prerequisite": "This is a critical review of the actual recorded simulator, not calibrated statistical power or sample-size advice. Power_recorded_simulation_review.zip preserves the original JSON and an explanatory review; it is not a GUI-importable completed run or a native export demonstration. The recorded spaCR 1.5.0.4 screen, design adapter, simulator and fitting code still match current source bytes. Two marginal scans produced 18 fits and nine points, two replicates per point; four nonconverged fits remain in the denominator. Two simulations clipped probabilities. The same nominal baseline has different random draws: 1/2 versus 2/2 detections. The advice to increase to the existing well count is explicitly rejected and remains unfixed. Some plot endpoint labels are clipped; the verified table contains all nine coordinates. No new simulation, acquired data, biological calibration, GPU task, AI-provider request or publication is claimed. API: spacr.qt.widgets.power_design.DesignSpec/simulator_kwargs/power_curve and spacr.qt.screens.power.run_power_sweep; spacr.power_simulate and spacr.power_model perform simulation and fitting.", "scenes": [{"visual": "01_module", "narration": "Power and Design explores assumptions with simulated data. It does not load an acquired experiment or establish that its assumptions match yours. This lesson reads a real recorded run, including its warnings and a misleading recommendation. Do not use this small demonstration as validated sample-size advice.", "related_lessons": ["67_experiment_design"], "hold_after": 0.7}, {"visual": "03_guide_library", "narration": "Start with the library and scoring unit. Switching between guide and gene changes what the model scores: the displayed example has forty genes and four guides per gene, so guide scoring has one hundred sixty units. Gene scoring pools the guide information. These are teaching assumptions, not new biological measurements.", "hold_after": 0.7}, {"visual": "04_bounded_library_plate", "narration": "The plate and effect controls describe the assumed design. A positive-call rate is a simulated classification probability, not a count of organisms or a measured infection rate. Inspect the background, effect and prevalence together, and remember that the displayed assumptions do not validate the model.", "hold_after": 0.7}, {"visual": "05_unsupported_effect_warning", "narration": "An effect below one triggers the native unsupported-direction warning and disables Run. The recording then restores a supported value so the controls recover. This is a software guard, not a claim that effects in the other direction are biologically impossible. Do not bypass the warning to obtain a convenient curve.", "hold_after": 0.7}, {"visual": "08_run_settings", "narration": "This bounded demonstration uses only two replicates per point. The detection rule is a usable fit reaching the chosen area under the receiver operating characteristic curve threshold. It is not a hypothesis-test P-value cutoff. The seed and backend are recorded; selecting Torch alone does not prove GPU execution.", "hold_after": 0.7}, {"visual": "09_real_simulation_running", "narration": "Run starts the actual threaded simulator. It varies the cell-count and well-count axes separately, rather than evaluating every combination. The recording completed eighteen fits across nine points. Keep the settings and raw replicate records together so a plotted fraction can be traced to the fits that produced it.", "hold_after": 0.7}, {"visual": "10_actual_results", "narration": "Read detections as counts over all requested replicates. Four fits did not converge and remain in the denominator as non-detections; they are not silently discarded. A plotted hundred percent here means only two out of two. Such a small sample cannot establish a precise detection probability.", "hold_after": 0.7}, {"visual": "10_actual_results", "focus": [1450, 1590, 2380, 460], "narration": "The table separates detection fractions from mean performance among usable fits. An unavailable mean is not zero. Average precision also needs its prevalence baseline for context. Read the table when a plot-end label is clipped, and inspect nonconvergence counts instead of judging the design from the blue line alone.", "hold_after": 0.7}, {"visual": "12_results_and_limitations", "focus": [1450, 210, 2380, 110], "narration": "The headline contains an error. Both baseline estimates already use ninety-six wells, but different random draws produce one of two detections in one scan and two of two in the other. Going to the same ninety-six wells is not an improvement in design. Reject that recommendation; this tutorial does not repair it.", "hold_after": 0.7}, {"visual": "11_full_caveats", "narration": "Expand the remaining caveats. Two simulated screens clipped probabilities above one, so their realised occupancy differs from the requested value. The model has other assumptions and limitations; listing them is not validation. Review these warnings and the failed fits before drawing conclusions from any simulation.", "hold_after": 0.7}, {"visual": "12_results_and_limitations", "narration": "The linked archive preserves the actual recorded specification, replicate outputs, curves, table and incorrect headline for inspection. It is an external evidence download, not a native GUI export or an imported result. The Python design adapter and simulation APIs expose the same workflow, but real planning requires separate validation of assumptions and uncertainty.", "related_lessons": ["06_api"], "hold_after": 0.7}], "poster": "68_power_design/poster.jpg", "silent": "68_power_design/video/68_power_design_silent.mp4"}, {"id": "69_dose_response", "number": 69, "slug": "dose_response", "series": 5, "app_key": "dose_response", "section": "Data", "title": "Dose Response: fitted curves, uncertainty and honest refusals", "description": "Use the current Dose Response screen with a reproducible synthetic table, compare profile and Wald intervals, and distinguish fitted, unbounded and refused results.", "objectives": ["Load explicit concentrations and responses and fit one curve per named series.", "Interpret midpoint estimates, interval methods, vehicle controls and refused curves.", "Compare results before sorting, copy the actual report and distinguish GUI controls from API exports."], "example_files": ["SYNTHETIC_dose_response_examples.csv"], "prerequisite": "Download the accompanying SYNTHETIC CSV. It has 120 constructed rows: four named series, nine positive concentrations plus a zero-dose vehicle, and three observations per concentration. Balanced offsets of minus 0.5, zero and plus 0.5 are not biological replicates or a calibration study. Planted midpoints are 1.5, 2 and an out-of-range 500; the fourth series reverses. No registered Dose Response dataset downloader, normalization, weighting, replicate selector, GUI export button or AI console is demonstrated. The Unit field changes a label, not the data. In this build, refitting after sorting can corrupt the displayed row identities; this recording completes every refit before sorting. Preserve refusals and inspect the full report. API: spacr.qt.widgets.dose_response.DoseResponseSpec, fit_frame and DoseResponseSet.table. The example data and plot checks are independent of spaCR's fitting functions; profile endpoints are checked to the implementation's declared log10 bracket precision, not as a coverage guarantee.", "scenes": [{"visual": "01_home_data", "narration": "Open Dose Response in Home's Data section. This standalone viewer fits a four-parameter logistic curve to a concentration series. It needs the actual concentrations and responses; it does not infer doses from well names, image coordinates or treatment labels.", "hold_after": 0.7, "focus_modules": ["dose_response"]}, {"visual": "03_choose_disclosed_synthetic_csv", "narration": "Download the synthetic CSV linked in this lesson's prerequisites, then choose Load table. These are deliberately constructed software examples, not measured compounds. The file and every series name say synthetic, so the clean curves must not be mistaken for experimental results.", "hold_after": 0.7}, {"visual": "04_loaded_120_synthetic_rows", "narration": "The file contains one hundred twenty rows across four series. Each has nine positive concentrations, a zero-dose vehicle, and three observations at each concentration. The small, balanced artificial offsets preserve the model mean at every dose; this convenient example does not validate statistical performance on real experiments.", "hold_after": 0.7, "focus": [285, 40, 2200, 170]}, {"visual": "05_explicit_columns_and_profile", "narration": "Select concentration as the concentration column, response as the response column, and series under One curve per. Supply raw concentrations, not their logarithms. Grouping is important: fitting all four different series as one curve would answer the wrong question.", "hold_after": 0.7, "focus": [285, 145, 1470, 75]}, {"visual": "05_explicit_columns_and_profile", "narration": "The Unit field is only a label. Here we type u M to label the illustrative concentrations as micromolar; changing this text never rescales the numbers. Prepare any required normalization or unit conversion upstream, because this screen has no normalization or weighting controls.", "hold_after": 0.7, "focus": [285, 145, 1470, 75], "related_lessons": ["61_tabulate"]}, {"visual": "06_profile_results", "narration": "Leave Profile likelihood selected and Fit non-monotone data switched off, then choose Fit. The curve panel and results table update together. All four series stay accounted for, including an unbounded result and a refusal; a missing estimate is not the same as a missing series.", "hold_after": 0.7, "focus": [2000, 190, 1810, 210]}, {"visual": "07_inhibition_midpoint", "narration": "Select synthetic inhibition. The recovered midpoint is one point five, with a negative Hill slope because the response falls as concentration increases. Half-maximum means halfway between the fitted plateaus, which are five and ninety-five here; it does not automatically mean fifty percent viability.", "hold_after": 0.7, "focus": [285, 210, 1710, 1900]}, {"visual": "08_activation_midpoint", "narration": "Select synthetic activation. Its recovered midpoint is two and its Hill slope is positive. The selected curve is emphasized while the other fitted curves remain visible. Read the selected row and report together rather than assigning another curve's estimate to this series.", "hold_after": 0.7, "focus": [285, 210, 1710, 1900]}, {"visual": "09_unbounded_not_a_point_estimate", "narration": "The beyond-range example was constructed with a midpoint of five hundred, but its concentrations stop at one hundred. The screen reports an unbounded result, leaves the midpoint and interval cells blank, and shows a bound at the edge. A fitted extrapolation is not a supported point estimate.", "hold_after": 0.7, "focus": [2000, 1140, 1810, 450]}, {"visual": "10_refused_reversing_series", "narration": "The reversing series is refused because a monotonic logistic curve is the wrong shape. Read the full explanation below the table. A turning response does not by itself establish cytotoxicity or another biological cause; investigate the experiment instead of blindly removing doses or forcing a fit.", "hold_after": 0.7, "focus": [2000, 1140, 1810, 450]}, {"visual": "07_inhibition_midpoint", "narration": "The inhibition report counts twenty-seven fitted observations and three zero-dose controls. Zero concentrations are excluded from the logarithmic fit and summarized separately; they are not silently converted to tiny positive doses. The synthetic vehicle mean is ninety-five, matching the constructed low-dose plateau.", "hold_after": 0.7, "focus": [2000, 1140, 1810, 450]}, {"visual": "07_inhibition_midpoint", "narration": "Also read residual error and the lack-of-fit assessment, not just R squared. This deliberately balanced example has exceptionally tidy diagnostics. Repeated observations at each concentration are used without a separate replicate selector, and these artificial repeats do not establish the independence of measurements in a real experiment.", "hold_after": 0.7, "focus": [2000, 1140, 1810, 450]}, {"visual": "13_choose_wald", "narration": "To compare interval methods, choose Wald and press Fit again. Changing the selector alone does not recompute an existing result. The interval is calculated for the logarithm of the midpoint and transformed back; it is not a symmetric error bar added directly to concentration.", "hold_after": 0.7, "focus": [285, 145, 1470, 75]}, {"visual": "14_wald_results", "narration": "The well-bracketed examples keep their midpoint estimates while the interval endpoints change slightly. The beyond-range example still withholds its midpoint. Finite intervals on these tidy examples do not prove that another experiment identifies its midpoint or that nominal coverage holds for its noise and sampling design.", "hold_after": 0.7, "focus": [2000, 190, 1810, 210]}, {"visual": "15_profile_restored", "narration": "Restore Profile likelihood and choose Fit again. Check that the results now correspond to that method. The curve, table and selected report are linked views of the completed fit; they are not a live preview that automatically refits whenever a control changes.", "hold_after": 0.7, "focus": [2000, 1140, 1810, 450]}, {"visual": "16_select_after_sorting", "narration": "Finish the fitting comparisons before sorting the table. This build can misalign displayed rows when a sorted table is refitted, so do not rely on that sequence. Here we sort only after fitting, then select inhibition and verify that its matching report is shown.", "hold_after": 0.7, "focus": [2000, 190, 1810, 210]}, {"visual": "17_copy_actual_report", "narration": "Select and copy the report text using the normal copy shortcut. Keep the warnings, refusal explanations, input concentrations and chosen interval method with the result. Copying a single midpoint without that context discards the information that determines whether it can be interpreted.", "hold_after": 0.7, "focus": [2000, 1140, 1810, 500]}, {"visual": "15_profile_restored", "narration": "There is no export button in this screen. For programmatic output, the dose-response API provides fit_frame and a result table; the API lesson explains working from Python. Preserve unbounded and refused rows when exporting, rather than keeping only the compounds that produced convenient numbers.", "hold_after": 0.7, "related_lessons": ["06_api"], "focus": [2000, 190, 1810, 210]}], "poster": "69_dose_response/poster.jpg", "silent": "69_dose_response/video/69_dose_response_silent.mp4"}, {"id": "70_explain_cv", "number": 70, "slug": "explain_cv", "title": "Explain CV Model", "series": 5, "app_key": "explain_cv", "section": "Results and quality control", "host_app_key": "classify_merged", "description": "Inspect a real surrogate fit inside Classify, verify its held-out fidelity and recognise when feature explanations must not be interpreted.", "objectives": ["Select matching measurements and existing classifier predictions through the nested workbench.", "Distinguish surrogate agreement from independent classifier validation.", "Inspect failed fidelity, class errors, table limits and complete saved artifacts."], "prerequisite": "Use a measurements database and predictions CSV from the same cropped objects. This recording reuses 234 genuine saved predictions from the one-epoch Annotate/Classify example, not the separate portable Evaluation inspector bundle. Original filename and predicted_label columns are preserved. The earlier classifier split shares wells with training, so this is not independent classifier validation. The surrogate uses 89 complete cases and 1126 features; 145 joined rows are excluded for nonfinite features. It fits 68 objects from two wells and tests 21 from a third. All surrogate calls are class 1: fidelity 17/21, balanced accuracy 0.5. The displayed majority baseline is 81/89 across all complete cases. Importance is withheld; visible SHAP values are not a faithful account of the CV model. Eighteen cv_intensity measurement names are excluded by the name heuristic, which does not prove actual leakage. GUI correlations and distributions stop at 1000 rows; inspect full CSV exports. API: spacr.surrogate.explain_classifier, fit_surrogate and write_surrogate_result. No GUI controls for permutation repeats, feature exclusions or SHAP budget are claimed. CPU demonstration only; no new training, external AI request, native-listening approval or publication.", "scenes": [{"visual": "01_classify_host", "narration": "Open Classify, then the Explain CV Model icon at the upper right. It opens a nested workbench, not another Home module. We reuse existing image-classifier predictions and the matching measurements from the example workflow. Explaining those predictions does not validate the classifier itself.", "focus": [3579, 100, 80, 80], "related_lessons": ["09_annotate", "39_classifier_evaluation"], "hold_after": 0.7}, {"visual": "04_recorded_predictions_picker", "narration": "Choose the matching measurements database and saved predictions CSV. The file must identify the same cropped objects, not just use similar well names. Here we use unchanged copies of two hundred thirty-four real saved predictions. This is not a new training run or a newly validated dataset.", "hold_after": 0.7}, {"visual": "06_ready_existing_predictions_not_retraining", "narration": "If Browse leaves the old column choices, confirm the prediction path with Enter. Select filename for the crop path and predicted underscore label for the model's class calls, not the true labels or a continuous probability. Choose Random Forest, well grouping and a new output folder.", "focus": [462, 463, 2680, 459], "hold_after": 0.7}, {"visual": "07_actual_fitting", "narration": "Click Explain model. The surrogate learns from measured features to imitate existing class calls; it does not rerun the vision model. This example uses CPU processing. The GUI offers backend and grouping choices; permutation repeats, feature exclusions and the SHAP budget are API options, not controls on this form.", "focus": [462, 678, 2200, 365], "related_lessons": ["06_api"], "hold_after": 0.7}, {"visual": "08_result_tab_0", "narration": "Read Fidelity first. All predictions joined, but only eighty-nine rows had complete features. The surrogate fits sixty-eight objects from two wells and tests twenty-one from a third. Fidelity is about eighty-one percent, below the displayed ninety-one percent majority baseline. That baseline uses all complete cases, not only the held-out well.", "focus": [474, 1010, 2900, 890], "hold_after": 0.7}, {"visual": "09_result_tab_1", "narration": "Importance is withheld because the fidelity gate failed. Do not turn this fit into a claim about what the vision classifier recognises. Also review automatic exclusions: the warning calls eighteen measurement names leaky, but names containing coefficient-of-variation intensity do not by themselves establish label leakage.", "focus": [465, 937, 2420, 810], "hold_after": 0.7}, {"visual": "11_result_tab_3", "narration": "Confusion compares the original model's class calls with the surrogate's calls, not biological truth. Here the surrogate calls every held-out object class one: seventeen agreements and four errors. Balanced accuracy is one half. A high-looking overall percentage can hide failure on the smaller class.", "focus": [465, 948, 2000, 650], "hold_after": 0.7}, {"visual": "12_result_tab_4", "narration": "Per-cell SHAP is still visible even though fidelity failed. These values describe this surrogate; they do not rescue its explanation of the vision model or establish a biological mechanism. Keep this limitation attached to exported attribution tables. Activation maps answer a different, spatial question, covered in their own lesson.", "focus": [465, 948, 2700, 1050], "related_lessons": ["16_activation"], "hold_after": 0.7}, {"visual": "14_result_tab_6", "narration": "Inspect Correlations and Feature distributions as data summaries, not proof of causation. Each GUI table stops at a thousand rows. The full exports here contain one thousand eighty-seven correlation pairs and two thousand two hundred fifty-two distribution rows. Read the saved files before reporting totals or missing features.", "focus": [465, 948, 2910, 1050], "hold_after": 0.7}, {"visual": "15_result_tab_7", "narration": "Held-out cells retains the object identities and both sets of predictions. Open held-out objects is disabled in this recording, so no crop handoff is demonstrated. Keep the eleven saved artifacts, settings and fidelity warning together. The Evaluation lesson explains classifier validation limits; a plot, SHAP table or spaCR AI response cannot certify a classifier.", "focus": [465, 865, 2910, 1150], "related_lessons": ["39_classifier_evaluation", "06_api"], "hold_after": 0.7}], "poster": "70_explain_cv/poster.jpg", "silent": "70_explain_cv/video/70_explain_cv_silent.mp4"}, {"id": "71_investigate_hit", "number": 71, "slug": "investigate_hit", "title": "Investigate Hit", "series": 5, "app_key": "investigate_hit", "section": "Results and quality control", "description": "This tutorial is not available yet. Please explore the other tutorials.", "objectives": [], "prerequisite": "", "scenes": [], "status": "coming_soon", "availability_title": "Coming soon", "host_app_key": "regression"}, {"id": "72_volcano_explorer", "number": 72, "slug": "volcano_explorer", "title": "Volcano Explorer: inspect existing results and export a figure", "series": 5, "app_key": "volcano_explorer", "host_app_key": "regression", "section": "Regression", "example_files": ["Volcano_real_guide_family.zip"], "description": "Explore the real Regression example, synchronize the current style controls, distinguish visual thresholds from statistical testing, and save reproducible figure styles and exports.", "objectives": ["Open the nested Volcano Explorer with the completed Regression guide family.", "Synchronize initial controls through the verified Save style and Load style workaround.", "Inspect point identities, effect and P-value axes, colour and reference lines without inventing new hits.", "Restore a saved style and inspect vector PDF and PNG exports."], "prerequisite": "Extract Volcano_real_guide_family.zip and open its results folder. These are unchanged outputs from the downloaded-data Regression tutorial, not a new analysis or a complete project archive. One family contains 434 guides, outcome log_pred, minimum_wells_threshold=2, plus-one permutation P values and BH correction. Minimum raw P=0.005, minimum adjusted P=0.39454545454545453; zero significant at original alpha=0.05. Standardized marginal effects are not simultaneously fitted multivariable coefficients or log2 fold changes. The native initial style-control defect remains: displayed alpha=1e-6, multiplier=0 and log=False disagree with rendered .05/3/True. Before editing, Save style then Load that same style synchronizes controls. All 67 style fields survive the later roundtrip. Moving alpha to .5 puts nineteen adjusted values below that cutoff but preserves zero source significance flags; it is not new testing. Restore .05 and adjusted_p_value before export. An explicit effect cut .1 with multiplier 3 gives lines at +/-0.3. Actual point coordinates, identities, source flags and support colours are checked. Nominal 7-by-5-inch, 150-DPI settings export a tightly cropped 492.536-by-348.485-point PDF and 1026-by-726-pixel PNG. The PDF has embedded fonts and no raster images; labels were visually rechecked. Some GUI labels remain clipped and the application warns about white marker outlines on light paper. Annotation merging, broken axes, localization and control-MAD rules are not certified by this example. The preserved recording was made with spaCR 1.5.0.4; its screen, widget and renderer source bytes still match the current checkout. No new regression, GPU, AI provider request, application modification, biological validation or publication. API: spacr.volcano_style.VolcanoStyle and render_volcano.", "scenes": [{"visual": "01_regression_host", "narration": "Open Regression and its nested Volcano Explorer. This lesson belongs under Regression in the submodule section. The explorer reads completed results; it does not rerun the analysis. We use the real downloaded-data Regression example, with a companion archive containing the exact result tables and recorded figure styles.", "related_lessons": ["13_regression"], "hold_after": 0.7}, {"visual": "03_real_guide_family_no_adjusted_hits", "narration": "Choose Open results and select the extracted results folder. Each point here is one guide from a single family of four hundred thirty-four tests, using the same outcome and minimum-well rule. Do not pool different correction families. No guide is significant at the original adjusted-P cutoff of zero point zero five.", "hold_after": 0.7}, {"visual": "03a_save_rendered_baseline_style", "narration": "Before changing any setting, use Save style to save the actual rendered style, then Load style from that same file. In this build the initial controls disagree with the figure, and editing immediately can pull incorrect defaults into the plot. This normal save-and-load workaround synchronizes them; it does not fix the application.", "hold_after": 0.7}, {"visual": "03c_rendered_baseline_and_controls_agree", "narration": "After reloading, confirm alpha zero point zero five, multiplier three, and the negative-log transform. Some setting labels remain clipped in this build, so check the values and saved JSON. The horizontal axis is standardized marginal effect, not log-two fold change or a coefficient from a simultaneously fitted multivariable model.", "focus": [2305, 270, 1500, 570], "hold_after": 0.7}, {"visual": "05_selected_real_guide", "narration": "Click an existing point to inspect its source row. The selected guide has raw P zero point zero zero five, but adjusted P about zero point three nine. Its large marginal effect and four supporting wells do not make it significant. Use the identity and source fields rather than guessing from a dot's position.", "focus": [305, 1830, 1990, 275], "hold_after": 0.7}, {"visual": "07_raw_p_values_not_new_hits", "narration": "Switching the vertical column to raw permutation P changes the plotted quantity, not the analysis. Small raw values do not replace the family-adjusted values. Restore adjusted P afterwards. The saved source significance flags remain unchanged; the explorer is a reader and figure editor, not a new statistical test.", "hold_after": 0.7}, {"visual": "10_log_transform_restored", "narration": "The negative-log-ten switch changes how P values are displayed. With it on, smaller P values appear higher; turning it off displays the original values. We restore the transformed adjusted-P view here. Always read the axis label, and do not confuse the transform with a different multiple-testing correction.", "hold_after": 0.7}, {"visual": "11_reference_line_does_not_retest", "narration": "For demonstration, moving alpha to zero point five moves the reference line. Nineteen adjusted values fall below that new P cutoff, but none gains a new source significance flag. This is not a valid claim of nineteen discoveries. Restore the original zero point zero five before exporting or interpreting this example.", "hold_after": 0.7}, {"visual": "13_explicit_effect_cut_times_multiplier", "narration": "An explicit effect cutoff of zero point one combines with multiplier three, placing vertical lines at minus and plus zero point three. Check the multiplier rather than reading the cutoff field alone. An effect threshold does not replace statistical correction. Restore Auto after this exercise; no result-table values are rewritten.", "hold_after": 0.7}, {"visual": "15_colour_by_actual_support", "narration": "Colour by wells with guide displays actual support from the source table. It is not a confidence score or proof of accuracy. Return to the original significance colours before the final export. Optional annotation joins and other layouts need their own validation and are outside this verified example.", "hold_after": 0.7}, {"visual": "17_publication_size_settings", "narration": "Set the intended figure size, font sizes and resolution, then inspect the result. Here the nominal size is seven by five inches at one hundred fifty dots per inch. Tight bounding-box cropping changes the final dimensions. A readable exported figure does not mean every native settings label fits this window.", "hold_after": 0.7}, {"visual": "21_saved_style_restored", "narration": "Save the final style as JSON. After a temporary marker-size change, Load style restores every recorded style field. Keep that file with the original result table so another session can reproduce the appearance. Style settings describe presentation; they do not establish that a different regression or significance test was run.", "hold_after": 0.7}, {"visual": "24_export_finished_source_preserved", "narration": "Export PDF and PNG re-render the figure rather than capture the screen. Our PDF contains vector marks and embedded fonts; inspect labels, contrast and the warning about white marker outlines on light paper. Original data remain unchanged. Python provides VolcanoStyle and render_volcano for the same rendering workflow, without a GPU or AI provider.", "related_lessons": ["06_api", "13_regression"], "hold_after": 0.7}], "poster": "72_volcano_explorer/poster.jpg", "silent": "72_volcano_explorer/video/72_volcano_explorer_silent.mp4"}, {"id": "73_parameter_sweep", "number": 73, "slug": "parameter_sweep", "title": "Parameter Sweep", "series": 5, "app_key": "parameter_sweep", "section": "Results and quality control", "host_app_key": "regression", "description": "Run two bounded trials inside Regression, inspect saved guide and gene results, and distinguish execution success from valid inference.", "objectives": ["Find the nested sweep and select four ordered score/count pairs from Regression’s test data.", "Limit a grid to two trials and one worker, then inspect saved results without refitting.", "Keep failed inference checks and separate coefficient families visible when comparing outputs."], "prerequisite": "Use the four downloaded plate score/count pairs from the Regression lesson and a new output folder. This is a computational demonstration, not a validated hit-discovery analysis: both recorded ridge trials fail inference QC. The full recipe is visible in the sweep form; only alpha varies, 0.01 and 0.1. Parametric inference, well aggregation, mean response and no transform are fixed explicitly. Other parent settings are not automatically inherited. Do not use the displayed n_rows_fitted as sample size: it counts 1174 coefficient rows here, not 620 wells or 2955 prepared long-form rows. The trial table omits alpha and the saved QC verdicts; inspect sweep_results.csv and each trial’s actual settings. API: spacr.parameter_sweep.SweepSpace and run_sweep_parallel. No GPU acceleration benchmark, external AI request, native-speaker sign-off or publication is claimed.", "scenes": [{"visual": "01_regression_with_four_existing_pairs", "narration": "Open Regression, then Parameter sweep at the bottom right. This workflow lives inside Regression, not on a separate Home tile. The Regression lesson explains downloading the four example score and count pairs that we reuse here.", "focus": [3380, 1880, 440, 150], "related_lessons": ["13_regression"], "hold_after": 0.7}, {"visual": "03_count_file_picker", "narration": "Check the sweep’s own input lists. They are initially empty even when the parent form contains paired data. Add the four score files and four count files in matching plate order. Choose a new output folder so this demonstration cannot overwrite an earlier analysis.", "hold_after": 0.7}, {"visual": "05_two_trials_one_worker_budget", "narration": "Only tick alpha: the values are zero point zero one and zero point one. Unticked rows still supply fixed settings. Here we explicitly choose ridge, parametric inference, well-level mean aggregation and no transform. This bounded recipe demonstrates operation; it is not a recommendation for your experiment.", "focus": [850, 490, 680, 680], "hold_after": 0.7}, {"visual": "06_actual_estimate", "narration": "Set grid sampling, maximum trials two, and one worker, then click Estimate. Two valid combinations means the settings combinations are allowed, not that the statistical conclusions are valid. The time estimate assumes a minute per trial; it is not a benchmark. Read the available resource limits before starting.", "focus": [850, 1190, 680, 375], "hold_after": 0.7}, {"visual": "07_actual_sweep_running", "narration": "Click Start sweep, not the parent Regression Run button. Each trial writes into its own folder. These two real trials run sequentially; adding workers increases resource demand. This example demonstrates CPU regression, not GPU acceleration, and no request to spaCR AI is needed.", "hold_after": 0.7}, {"visual": "08_actual_sweep_finished", "narration": "Both rows report ok because computation finished. Crucially, both saved inference quality checks report fail. The table omits those verdicts and the varied alpha, so inspect the full sweep results file and each trial’s settings. Do not select a model just because it produces more small adjusted P values.", "focus": [1550, 205, 2215, 290], "hold_after": 0.7}, {"visual": "10_saved_guide_family", "narration": "Select the first row and click Show figures for selected row. This reads its saved results without refitting. The guide view contains seven hundred ninety-two coefficient rows, including an intercept; the plot excludes that nuisance term and shows seven hundred ninety-one guides. Height represents negative log ten of the raw P value.", "focus": [1545, 510, 2255, 1040], "hold_after": 0.7}, {"visual": "11_saved_gene_family", "narration": "Switch Level to Gene. The table now contains three hundred eighty-two rows, including its intercept, and the plot shows three hundred eighty-one genes. Guides and genes are separate coefficient families. Changing this view does not make the failed inference valid or create independent evidence.", "focus": [1545, 555, 2255, 995], "hold_after": 0.7}, {"visual": "12_saved_guide_family_restored", "narration": "Switch back to guides: the original rows and points return, and the saved files are unchanged. The summary’s rows fitted field is misleading here: it reports coefficient rows, not wells. Keep the input sample count, output coefficient count and plotted family distinct when reporting an analysis.", "focus": [1545, 555, 2255, 995], "hold_after": 0.7}, {"visual": "13_actual_saved_model_summary", "narration": "Use the saved settings, summary and quality-control files together. A plot or an AI explanation cannot certify a study design. Regression Diagnostics explains further inspection, while the API reference documents sweep execution. This example teaches a reproducible workflow and its limitations, not validated biological hits.", "related_lessons": ["75_regression_diagnostics", "06_api"], "hold_after": 0.7}], "poster": "73_parameter_sweep/poster.jpg", "silent": "73_parameter_sweep/video/73_parameter_sweep_silent.mp4"}, {"id": "74_import_images", "number": 74, "slug": "import_images", "title": "Import Images: inspect the plan before importing", "series": 2, "app_key": "import_images", "host_app_key": "foreign", "section": "spaCR", "description": "Open Import Images inside Import, check a real microscopy subset before writing, and save a reusable plan. The example explicitly distinguishes unsupported raw naming from prepared copies.", "objectives": ["Find Import Images inside the Import module and distinguish it from importing existing measurements and masks.", "Check image identities and unresolved filename tokens before writing a project.", "Choose copying or linking, save and reload a plan, and verify the completed import."], "prerequisite": "Download Mask's real example first. This recording uses copied E01/F001 and L01/F009 fields, four C channels each. Prepared copies omit only the A token immediately before Z; originals remain unchanged. This is a specifically checked example, not a general instruction to delete unfamiliar filename metadata.", "scenes": [{"visual": "02_import_fold", "narration": "Open Import from Home's Data category, then choose Import Images. This nested tool prepares raw image files. Import Project, Format Converter, and External Masks are related workflows with their own tutorials.", "hold_after": 0.7, "focus_buttons": "FoldButton", "related_lessons": ["36_import", "35_converter", "31_external_masks"]}, {"visual": "04_source_options", "narration": "Our eight images are real microscopy data from Mask's downloadable example: one field from each of two wells, with four channels per field. We work on separate copies and leave the downloaded originals untouched.", "hold_after": 0.7, "related_lessons": ["07_mask"]}, {"visual": "04a_unresolved_acquisition_token", "narration": "Scan reveals an unresolved acquisition token in these raw names. Import stays disabled and nothing is written. Do not guess a channel mapping: two different channels share this acquisition value, so that answer would corrupt their identities.", "hold_after": 0.7}, {"visual": "05_scan_proposal", "narration": "For this checked example, prepared copies omit only the redundant acquisition token. Their well, field, and channel names remain intact. Scan now shows eight rows, two wells, two field numbers, and four channels. This does not mean the original naming was accepted.", "hold_after": 0.7}, {"visual": "06_check_filename", "narration": "Compare the proposal with the filenames before importing. Read inside each file checks embedded axis metadata as well as names. Sample limits the files inspected; ensure the proposal includes the images you intend to import. Resolve questions from acquisition records, not guesses.", "hold_after": 0.7, "focus": [350, 665, 1770, 675]}, {"visual": "07_copy_destination", "narration": "Choose a destination outside the input folder and set the plate name. We turn off Link instead of copy for an independent project. Links save disk space, but depend on the originals staying accessible at their existing locations.", "hold_after": 0.7, "focus": [345, 1600, 3420, 210]}, {"visual": "07_copy_destination", "narration": "These example files are not tiles. For tiled acquisitions, read the Tiles choice carefully: stitching assembles fields, keeping tiles separately changes what a field means, and skipping loses those images. Check the report and any unverified seams before measuring.", "hold_after": 0.7, "related_lessons": ["32_align_stitch"]}, {"visual": "09_saved_plan", "narration": "Save plan writes a JSON record of the source and your mapping answers, not a backup of the images. Keep it with the acquisition notes. The same plan can be read through the Python image import API.", "hold_after": 0.7, "related_lessons": ["06_api"]}, {"visual": "11_reloaded_plan", "narration": "Load plan reads the source folder again and reuses the saved answers. Check the new proposal before importing; a saved plan does not guarantee that a changed acquisition is correct. Here it restores the same eight checked image identities.", "hold_after": 0.7}, {"visual": "12_import_complete", "narration": "Press Import and read the summary. This run wrote eight independent image copies with no skipped files; their contents match the source. Next, point Mask at the project and inspect its live preview before segmentation. Importing alone does not generate masks or measurements.", "hold_after": 0.7, "related_lessons": ["07_mask", "08_measure"]}], "poster": "74_import_images/poster.jpg", "silent": "74_import_images/video/74_import_images_silent.mp4"}, {"id": "75_regression_diagnostics", "number": 75, "slug": "regression_diagnostics", "title": "Regression Diagnostics: read the evidence behind the results", "series": 2, "app_key": "regression_diagnostics", "host_app_key": "regression", "section": "spaCR", "description": "Open the diagnostic files produced by a real example-screen analysis, distinguish design warnings from permutation results, and recognize the limits of a short demonstration run.", "objectives": ["Open Diagnostics inside Regression and verify the output folder being inspected.", "Interpret design identifiability, guide support and inference panels in the context of the selected analysis.", "Recognize missing fitted-residual panels and limited permutation resolution without inventing a model fit."], "prerequisite": "Complete the Regression example using its four downloadable score/count pairs. This recording inspects a bounded nonparametric run with 199 permutations, a minimum of two wells, and both guide and gene results. It demonstrates the software and diagnostic interpretation, not final discovery-quality inference.", "scenes": [{"visual": "02_diagnostics_button", "narration": "Inside Regression, hover over Diagnostics and open it after an analysis has completed. This button reads saved output; it does not fit another model. It opens the newest diagnostics folder found in the project, so verify the path when several runs exist.", "hold_after": 0.7, "focus_buttons": "FoldButton", "related_lessons": ["13_regression"]}, {"visual": "03_diagnostics_folder", "narration": "The system file manager shows the actual files from our downloaded example-screen analysis. Here the figure preference was PNG. The folder contains design identifiability, design diagnostics, inference diagnostics, a summary table, and a table of collinear guide pairs.", "hold_after": 0.7, "focus": [535, 230, 1420, 285]}, {"visual": "04_design_identifiability", "narration": "The design has six hundred and six wells, seven hundred and ninety-three parameters, and rank five hundred and ninety-nine. It cannot identify a unique simultaneous coefficient for every guide. This warning explains why we used a permutation analysis; it does not mean a simultaneous model was fitted successfully.", "hold_after": 0.7}, {"visual": "04_design_identifiability", "narration": "Guide support is uneven: three hundred and fifty-five guides occur in just one well in this design. Sparse support limits what the experiment can establish. Inspect coverage before interpreting effects, and distinguish the full design from the filtered family of guides actually tested.", "hold_after": 0.7}, {"visual": "05_design_diagnostics", "narration": "The design panel helps locate poor support and dependencies between guide predictors. Guides that always occur together are hard to distinguish statistically. Use the collinear-pairs table to inspect specific pairs rather than treating a warning badge as a complete explanation.", "hold_after": 0.7}, {"visual": "06_inference_diagnostics", "narration": "The inference panel summarizes four hundred and thirty-four guide tests: their p-value distribution, comparison with a uniform null, and discoveries across adjusted thresholds. This short run has no discoveries at the displayed threshold. A calibration warning is a prompt to investigate, not proof of biological effects.", "hold_after": 0.7}, {"visual": "06_inference_diagnostics", "narration": "We used only one hundred and ninety-nine permutations to keep the demonstration short. The minimum attainable empirical p-value is therefore zero point zero zero five. That resolution can be inadequate after multiple-testing correction; use an appropriately planned permutation count for the real analysis.", "hold_after": 0.7}, {"visual": "03_diagnostics_folder", "narration": "There is no fitted-residual panel for this permutation run because it did not fit the simultaneous regression model. The p-value comparison we just viewed is not a residual diagnostic. Other analysis modes can write residual panels when they supply observed and fitted values.", "hold_after": 0.7}, {"visual": "03_diagnostics_folder", "narration": "The summary records individual panel assessments and the worst assessment for the suite. Read each assessment in context rather than interpreting the overall badge as a software error. The Python regression diagnostics API writes the same kinds of panels from the inputs it is given.", "hold_after": 0.7, "related_lessons": ["06_api"]}, {"visual": "07_back_to_regression", "narration": "Return to Regression to investigate the inputs or change an analysis choice deliberately. A change needs a new run and new diagnostics; opening this folder never updates old results. Use the Regression tutorial for the full dataset, console, interactive results, and assistance workflow.", "hold_after": 0.7, "related_lessons": ["13_regression", "48_hit_list", "72_volcano_explorer"]}], "poster": "75_regression_diagnostics/poster.jpg", "silent": "75_regression_diagnostics/video/75_regression_diagnostics_silent.mp4"}, {"id": "77_embeddings", "number": 77, "slug": "embeddings", "title": "Embeddings: current screen and a real Python example", "series": 2, "app_key": "embeddings", "section": "Data", "description": "Inspect the new Home module, encode real downloaded crops with the supported API, and compare channel policies without claiming a repaired GUI or a validated phenotype.", "objectives": ["Find Embeddings and distinguish its current GUI limitation from the working API.", "Encode sixteen real crops, preserve identities and inspect both channel policies.", "Read saved vectors and exploratory plots with appropriate limitations."], "example_files": ["Embeddings_API_example.zip"], "prerequisite": "spaCR 1.5.0.7 with its embeddings extra; the recording uses timm 1.0.29 and cached pretrained ResNet18 weights on CPU. Download Annotate's real example as shown in that tutorial. Extract the helper ZIP, locate plate1/data/single_nucleus/uninfected/plate1_E02/cell_png, and use NEW output directories. The helper reads sixteen sorted PNGs without resizing; filenames identify the demonstration rows, not verified database join keys. The standalone Embeddings screen still lacks a crop-loading control. Successful operations here use the public Python API, not programmatic injection disguised as a GUI action. The default encoder is ImageNet-supervised, not microscopy-trained. No native-speaker signoff, biological validation, GPU benchmark or provider request is claimed. Read the included README for normalization, provenance, device and channel-mapping details.", "scenes": [{"visual": "gui_00_home", "narration": "Embeddings is a new Home module in spaCR. It turns image crops into numerical vectors without training on your annotations. This lesson demonstrates the current screen and a working Python example, using real downloaded images.", "focus_modules": ["embeddings"], "related_lessons": ["05_home", "06_api"], "hold_after": 0.7}, {"visual": "gui_01_no_gui_crop_input", "narration": "In version one point five point zero point seven, this screen has no crop-loading control, and Embed remains disabled. We will not simulate a successful GUI run. The supported Python API performs the actual encoding shown next.", "focus": [340, 55, 3480, 190], "hold_after": 0.7}, {"visual": "gui_02_channel_policies", "narration": "Per channel encodes each stored channel separately, then concatenates the vectors. Project to three encodes the combined image instead. That changes the representation, not just its speed. A saved PNG slot is not automatically a verified stain identity.", "focus": [340, 145, 1050, 270], "hold_after": 0.7}, {"visual": "api_00_version", "narration": "Install the optional embeddings extra in your spaCR environment. The default ResNet eighteen uses ImageNet-supervised weights, not a cell-trained self-supervised model. This small example uses the CPU; no GPU or remote AI service is required.", "focus": [200, 100, 3440, 700], "hold_after": 0.7}, {"visual": "api_01_inputs", "narration": "Use Annotate's downloadable example and the crop folder named in the instructions. The linked helper selects sixteen existing images in sorted filename order. Each is two hundred twenty-four pixels square, with three stored channels. No resizing or new segmentation is performed.", "focus": [200, 100, 3440, 1100], "related_lessons": ["09_annotate"], "hold_after": 0.7}, {"visual": "api_02_per_channel", "narration": "Run the helper with a new output directory. It calls embed_array with the real pretrained encoder and batches of four. Per-channel encoding produces sixteen rows and one thousand five hundred thirty-six dimensions. The saved matrix is reopened and checked value by value.", "focus": [200, 100, 3440, 1000], "hold_after": 0.7}, {"visual": "api_03_project", "narration": "Now choose project and a different output directory. The same images produce sixteen rows and five hundred twelve dimensions. These combined-channel columns are not interchangeable with the earlier per-channel columns. Compare policies deliberately and retain the settings for each run.", "focus": [200, 100, 3440, 1000], "hold_after": 0.7}, {"visual": "api_05_input_crops", "narration": "Inspect the actual input montage in the image viewer. Its numbers match the output row order. Check crop quality and the export's channel mapping before interpreting vectors. Filenames identify this example; validate the object keys before joining to a measurements database.", "hold_after": 0.7}, {"visual": "api_06_per_channel_pca", "narration": "This saved plot projects the per-channel vectors onto two principal components. The numbered points refer to those same crops. It is exploratory visualization of a tiny sample, not proof of distinct phenotypes. A single embedding dimension is not a biological measurement.", "hold_after": 0.7}, {"visual": "api_07_project_pca", "narration": "The combined-channel vectors have their own projection. Do not compare axis coordinates across these separate plots as if they shared a fitted transformation. Neither picture measures retrieval accuracy or establishes that embeddings outperform the hand-measured feature panel.", "hold_after": 0.7}, {"visual": "api_04_provenance", "narration": "Keep the vectors, source identities, weights checksum, settings and package versions. The helper checks that source images remain unchanged and refuses existing destinations. Match input crops, normalization and channel mapping between comparisons. Use the linked instructions to reproduce this API example.", "focus": [200, 100, 3440, 1200], "related_lessons": ["06_api", "08_measure"], "hold_after": 0.7}], "poster": "77_embeddings/poster.jpg", "silent": "77_embeddings/video/77_embeddings_silent.mp4"}, {"id": "76_ops", "number": 76, "slug": "ops", "title": "OPS: current screen and four-tile image alignment", "series": 2, "app_key": "ops", "host_app_key": "mask", "section": "Segmentation models", "description": "Find OPS under Mask, then follow a measured four-tile geometry and composition example on real acquisition images. This is not a completed full-plate, segmentation or decoding workflow.", "objectives": ["Find the current nested OPS screen and understand the demonstration's limits.", "Register four real neighboring image tiles while retaining their original acquisition coordinates.", "Inspect independently checked overlaps, coverage and saved provenance."], "prerequisite": "The recording uses spaCR 1.5.0.7 nightly's ops_layout, ops_stitch and ops_compose Python APIs on CPU. The current GUI Run dispatches to a different legacy engine and is not run here. Source: screenA/20200202_6W-LaC024A, sequencing/images/input/c1, sites 0, 1, 10 and 11. These are existing maintainer NAS data, NOT a bundled or publicly downloadable OPS example. You need authorized access to that acquisition to reproduce the exact measurements; the tutorial does not grant data redistribution rights. Each original TIFF is uint16, five planes by 1480 by 1480 pixels, with DAPI at plane zero. The helper retains the acquisition's 333-site layout while processing only four neighbors. Do not reuse its layout, overlap or acceptance thresholds for an unmeasured acquisition. No source file is edited; choose a new output folder outside the acquisition. Full-well validation, segmentation, sequencing-cycle registration, barcode decoding and biological hit analysis are outside this lesson's demonstrated scope.", "scenes": [{"visual": "gui_00_home", "narration": "Optical pooled screening begins with images acquired across neighboring fields and repeated imaging cycles. In spaCR, open Mask to find the nested OPS screen. This lesson shows its location and a small, verified image-alignment example.", "focus_modules": ["mask"], "related_lessons": ["05_home", "07_mask"], "hold_after": 0.7}, {"visual": "gui_01_mask_host", "narration": "Use the OPS toggle in Mask's action row. It opens a separate page inside the host module. OPS is not a second Home tile, and it is not the Map Barcodes workflow for sequencing read files.", "hold_after": 0.7}, {"visual": "gui_02_ops_settings", "narration": "The current OPS page exposes input, stitching, mosaic, alignment and quality-control settings. Its Run button uses a different, legacy engine. We do not start it here or imply that a complete screening pipeline has been validated. The next steps use the geometry APIs directly.", "focus": [340, 170, 1210, 1310], "hold_after": 0.7}, {"visual": "api_00_scope", "narration": "This CPU demonstration registers and composes four real image tiles from an existing acquisition. It does not segment cells, decode barcodes or process a whole plate. The original acquisition is not a bundled test download; exact reproduction requires authorized access to those files.", "focus": [200, 100, 3440, 800], "related_lessons": ["06_api"], "hold_after": 0.7}, {"visual": "api_01_inputs", "narration": "Select sites zero, one, ten and eleven from the first imaging cycle. Each original file has five planes; plane zero contains the nuclear stain. Keep the original three hundred thirty-three-site layout and site numbers. Four selected tiles do not define a new four-tile well.", "focus": [200, 100, 3440, 1000], "hold_after": 0.7}, {"visual": "api_02_geometry", "narration": "The helper calls stitch_well, checks all four neighboring overlaps, and then calls compose_window. All four tiles are placed. Their patch is two thousand seven hundred fifty-six pixels square. The loop closes within a quarter pixel in this acquisition, not a universal accuracy guarantee.", "focus": [200, 100, 3440, 900], "hold_after": 0.7}, {"visual": "api_03_independent_checks", "narration": "Do not trust placement alone. Compare actual overlapping pixels independently of the registration score. Here, aligned correlations are much stronger than correlations after deliberately shifting either axis by seventeen pixels. Those wrong-offset controls help detect a plausible-looking but incorrect placement.", "focus": [200, 100, 3440, 1000], "hold_after": 0.7}, {"visual": "api_05_geometry_figure", "narration": "Inspect the actual saved image and coverage map. The left panel shows the composed nuclear image; the right counts contributing tiles. Zero coverage means no acquisition pixel, not biological background. This combines spatial neighbors within one plane, never different sequencing cycles.", "focus": [600, 390, 2630, 1400], "hold_after": 0.7}, {"visual": "api_04_provenance", "narration": "Save the array, coverage, placements, source checksums and run report together. The helper reopens its outputs and confirms all four source files are unchanged. Treat this as a reproducible geometry checkpoint. A full optical screening tutorial still needs separately validated downstream stages.", "focus": [200, 100, 3440, 1100], "hold_after": 0.7}], "poster": "76_ops/poster.jpg", "silent": "76_ops/video/76_ops_silent.mp4"}, {"id": "78_spacr_screens", "number": 78, "slug": "spacr_screens", "title": "spaCR screens", "series": 1, "app_key": null, "section": "Workflows", "description": "Follow a pooled image-based screen from Home through image measurements, phenotype classification, barcode counts and regression.", "objectives": ["Choose a starting module from the data you already have.", "Identify what each module reads and writes.", "Follow the linked module lessons and API contracts for the next step."], "prerequisite": "Install spaCR and open Home. This lesson explains navigation and data handoffs; the linked module lessons provide the worked data examples. Inputs and outputs include conditional alternatives, as explained for each module.", "scenes": [{"visual": "home", "narration": "Start on Home with the material you already have. A pooled image-based screen has two data branches: images describe the phenotype, while sequencing identifies the perturbations represented in each well. Mask, Measure, Annotate and Classify build the image branch. Map Barcodes builds the sequencing branch. Regression brings compatible scores and guide counts together. These are connected data products, not six buttons that must always be run in a fixed order.", "hold_after": 0.7, "related_lessons": ["05_home"]}, {"visual": "module_mask", "narration": "Open Mask from Home. Select channels and models, inspect a preview, then run Mask. Measure consumes the merged arrays; the counts database is not yet a feature table. Input data: Microscope images; Segmentation checkpoint. Output data: Images and label masks; Label masks; Object counts. Mask to Measure: Use the same project and the correct image/mask channel indices.", "hold_after": 0.7, "related_lessons": ["07_mask", "08_measure"]}, {"visual": "module_measure", "narration": "Open Measure from Home. Measure reads images and label planes together. Enable crop saving if you need PNG files; keep the database and source project together for streamed crops. Input data: Images and label masks; Label masks. Output data: Measured objects; Object crops. Mask to Measure: Use the same project and the correct image/mask channel indices. Measure to Annotate: Save or stream crops with stable object identities. Measure to Classify: Choose the image or tabular family to match your input.", "hold_after": 0.7, "related_lessons": ["07_mask", "08_measure", "09_annotate", "41_classify"]}, {"visual": "module_annotate", "narration": "Open Annotate from Home. Label representative objects in png_list before supervised training. Use separate annotations for different questions and keep training and evaluation groups independent. Input data: Measured objects; Object crops; Reusable gates. Output data: Training annotations. Measure to Annotate: Save or stream crops with stable object identities. Annotate to Classify: Keep labelled training and evaluation groups separate.", "hold_after": 0.7, "related_lessons": ["08_measure", "09_annotate", "41_classify"]}, {"visual": "module_classify_merged", "narration": "Open Classify from Home. Choose Computer Vision for crops or streamed object images, or Tabular Machine Learning for measured feature columns. The two families consume different inputs. Input data: Measured objects; Object crops; Training annotations. Output data: Object classification scores; Trained image classifier; Fitted feature classifier; Classifier evaluation bundle. Measure to Classify: Choose the image or tabular family to match your input. Annotate to Classify: Keep labelled training and evaluation groups separate. Classify to Regression: Select the intended CV or ML score column and preserve plate/well identity.", "hold_after": 0.7, "related_lessons": ["08_measure", "09_annotate", "13_regression", "41_classify"]}, {"visual": "module_map_barcodes", "narration": "Open Map Barcodes from Home. Supply the references that encode your experiment. Inspect mapped counts and barcode QC before pairing well-level guide counts with phenotype scores. Input data: Sequencing reads. Output data: Guide counts per well. Map Barcodes to Regression: Pair guide counts with phenotype scores using consistent plate/well keys.", "hold_after": 0.7, "related_lessons": ["12_map_barcodes", "13_regression"]}, {"visual": "module_regression", "narration": "Open Regression from Home. Match plate and well identifiers across phenotype and guide-count inputs, select the response and controls, and inspect diagnostics before interpreting hits. Direct measured responses are also supported. Input data: Object classification scores; Guide counts per well; Optical barcode assignments; Measured objects. Output data: Regression results and hits. Classify to Regression: Select the intended CV or ML score column and preserve plate/well identity. Map Barcodes to Regression: Pair guide counts with phenotype scores using consistent plate/well keys. OPS to Regression: Join/aggregate decoded objects to phenotype and guide inputs explicitly before Regression; this is not a direct CSV handoff.", "hold_after": 0.7, "related_lessons": ["12_map_barcodes", "13_regression", "41_classify", "76_ops"]}, {"visual": "home_summary", "narration": "Before Regression, check that the image scores, sequencing counts and experimental layout use matching plate and well identities. Preserve the object identifiers, annotation column, classifier settings and barcode references with the run. Use the linked module lessons for a worked example of each step; choose the pooled-screen walkthrough when you want Home to guide the navigation.", "hold_after": 0.7}], "narration_voices": {"en": ["af_aoede", "af_bella", "af_heart", "af_jessica", "af_river", "af_sarah", "af_sky", "am_adam", "am_echo", "am_eric", "am_fenrir", "am_liam", "am_michael", "am_onyx", "am_puck", "am_santa", "bf_alice", "bf_emma", "bf_isabella", "bf_lily", "bm_daniel", "bm_fable", "bm_george", "bm_lewis"], "es": ["ef_dora", "em_alex", "em_santa"], "fr": ["ff_siwis"], "hi": ["hf_alpha", "hf_beta", "hm_omega", "hm_psi"], "it": ["if_sara", "im_nicola"], "ja": ["jf_alpha", "jf_gongitsune", "jf_nezumi", "jf_tebukuro", "jm_kumo"], "pt-BR": ["pf_dora", "pm_alex", "pm_santa"], "zh-CN": ["zf_xiaobei", "zf_xiaoni", "zf_xiaoxiao", "zf_xiaoyi", "zm_yunjian", "zm_yunxi", "zm_yunxia", "zm_yunyang"]}, "poster": "78_spacr_screens/poster.jpg", "silent": "78_spacr_screens/video/78_spacr_screens_silent.mp4"}, {"id": "79_module_inputs_outputs", "number": 79, "slug": "module_inputs_outputs", "title": "Module inputs and outputs", "series": 1, "app_key": null, "section": "Workflows", "description": "Find every current module's input data, saved outputs, upstream producers and downstream consumers, including tools nested inside a Home module.", "objectives": ["Choose a starting module from the data you already have.", "Identify what each module reads and writes.", "Follow the linked module lessons and API contracts for the next step."], "prerequisite": "Install spaCR and open Home. This lesson explains navigation and data handoffs; the linked module lessons provide the worked data examples. Inputs and outputs include conditional alternatives, as explained for each module.", "scenes": [{"visual": "home", "narration": "Choose a module by the data you have and the result you need. Home shows the main modules; related tools can open inside a parent. This chapter-by-chapter reference covers every current route. Inputs and outputs can be conditional: an image classifier and a feature classifier need different data, and a viewer does not automatically save everything it displays. The notes for each module explain those differences. Keep the original files and use the recorded object, plate and well identities when passing results between modules.", "hold_after": 0.7, "related_lessons": ["05_home"]}, {"visual": "module_mask", "narration": "Open Mask from Home. Select channels and models, inspect a preview, then run Mask. Measure consumes the merged arrays; the counts database is not yet a feature table. Input data: Microscope images; Segmentation checkpoint. Microscope images: Source image folder; original files, supported vendor files or imported TIFFs. Segmentation checkpoint: Saved Cellpose-compatible checkpoint or a compatible installed backend selected with its own configuration. Output data: Images and label masks; Label masks; Object counts. Images and label masks: merged/*.npy in the project; channels and integer label planes share each field array. Label masks: masks/ when retained, or explicitly saved image/mask pairs. Intermediate masks may be removed by cleanup. Object counts: measurements/measurements.db; Mask counts alone are not per-object feature measurements. Mask to Measure: Use the same project and the correct image/mask channel indices. Cellpose Workbench to Mask: Select the saved compatible checkpoint in Mask. Import Images to Mask: Use imported image planes and identities; image-only imports still need segmentation. Format Converter to Mask: Use the converted layout and preserve source identity mappings. Mask to Timelapse: Enable the nested time-series route before generating linked labels. Import to Mask: For image-only imports, use Import Images or Format Converter and point Mask at the formatted image project. External measurements alone are not segmentation input.", "hold_after": 0.7, "related_lessons": ["07_mask", "08_measure", "17_timelapse", "19_train_cellpose", "35_converter", "36_import", "74_import_images"]}, {"visual": "module_measure", "narration": "Open Measure from Home. Measure reads images and label planes together. Enable crop saving if you need PNG files; keep the database and source project together for streamed crops. Input data: Images and label masks; Label masks. Output data: Measured objects; Object crops. Measured objects: measurements/measurements.db; object tables depend on the enabled cell, nucleus, pathogen and organelle masks. Relevant tables depend on the selected route: cell, nucleus, pathogen, cytoplasm. Relevant columns depend on the selected route: plateID, rowID, columnID, fieldID. Object crops: data/**/*_png when save_png is enabled; png_list indexes saved crops. Supported workflows can instead stream crops from merged arrays and masks. Relevant tables depend on the selected route: png_list. Relevant columns depend on the selected route: png_path, prcfo. Mask to Measure: Use the same project and the correct image/mask channel indices. Measure to Annotate: Save or stream crops with stable object identities. Measure to Classify: Choose the image or tabular family to match your input. Make Masks to Measure: Use FEATURES to pair images and masks and write a measured project; standalone masks are not merged arrays. External Masks to Measure: Re-measure only when needed; External Masks can already perform measurement. Measure to Image UMAP: Choose feature columns and inspect representative crops. Measure to Embeddings: Retain encoder and channel-policy provenance. Measure to Gate Editor: Use the actual measured feature definitions and units. Measure to Graph Builder: Choose explicit variables, groups and filters. Measure to QC: Review available checks and missing evidence. Measure to Recruitment: Require the intended compartment intensities and identities. Measure to Invasion Assay: Require two-colour stain measurements and appropriate baseline controls. Measure to Replication Assay: Require explicit parasite-to-vacuole identities. Timelapse to Measure: Use the time-series project with stable frame/object identities. Measure to Motility Assay: Combine measured objects with matching tracks. Measure to Feature Explorer: Define the class comparison and inspect filtering. Measure to Database Browser: Inspect actual tables before exporting. Measure to AnnData Export: Export compatible feature and metadata columns. Measure to Dose–Response: Join the measured response to explicit doses and controls. Measure to Endodyogeny size proxy: Supply the measured project roots and required object/png_list tables. Verify host-cell aggregation and area units before interpreting size bins; the Mask counts database alone is insufficient. Import to Measure: Import matching images and external integer masks to build merged project arrays, then open Measure on that project. Skip this step when compatible measurements have already been imported or computed. Do not append duplicate measurements to an existing imported table. Measure to Host–Pathogen Analysis: Keep uninfected cells in Measure. Supply whole-vacuole masks, host reference intensities and optional explicit parasite-to-vacuole links; host identity alone does not define a vacuole.", "hold_after": 0.7, "related_lessons": ["07_mask", "08_measure", "09_annotate", "14_make_masks", "15_image_umap", "17_timelapse", "18_motility", "25_recruitment", "26_invasion", "27_replication", "31_external_masks", "34_database", "36_import", "41_classify", "54_qc_dashboard", "58_graph_builder", "59_anndata_export", "64_gate_editor", "65_feature_explorer", "69_dose_response", "77_embeddings", "85_host_pathogen"]}, {"visual": "module_annotate", "narration": "Open Annotate from Home. Label representative objects in png_list before supervised training. Use separate annotations for different questions and keep training and evaluation groups independent. Input data: Measured objects; Object crops; Reusable gates. Reusable gates: Saved threshold/polygon gate definitions or a selected object set; apply a gate to the same feature definitions. Output data: Training annotations. Training annotations: A chosen annotation column in measurements/measurements.db, table png_list; labels belong to object identities. Relevant tables depend on the selected route: png_list. Relevant columns depend on the selected route: prcfo. Measure to Annotate: Save or stream crops with stable object identities. Annotate to Classify: Keep labelled training and evaluation groups separate. External Masks to Annotate: Keep the newly measured project and crop index together. Import to Annotate: Imported tables require explicit column and object-identity mappings. Gate Editor to Annotate: Apply compatible gates, then review candidate labels. Annotate to Annotator Agreement: Choose independent annotation columns for the same objects.", "hold_after": 0.7, "related_lessons": ["08_measure", "09_annotate", "23_agreement", "31_external_masks", "36_import", "41_classify", "64_gate_editor"]}, {"visual": "module_classify_merged", "narration": "Open Classify from Home. Choose Computer Vision for crops or streamed object images, or Tabular Machine Learning for measured feature columns. The two families consume different inputs. Input data: Measured objects; Object crops; Training annotations. Output data: Object classification scores; Trained image classifier; Fitted feature classifier; Classifier evaluation bundle. Object classification scores: Saved score CSVs and, when merged, measurements/measurements.db, table png_list. Relevant tables depend on the selected route: png_list. Relevant columns depend on the selected route: pred, cv_predictions, ml_pred, predictions. Trained image classifier: Saved classifier checkpoint, model settings and matching channel/preprocessing configuration. Fitted feature classifier: The fitted tabular classifier and its recorded feature list, training settings and validation results. Classifier evaluation bundle: Held-out predictions, labels, split metadata and calibration/leakage metrics for a saved classifier run. Measure to Classify: Choose the image or tabular family to match your input. Annotate to Classify: Keep labelled training and evaluation groups separate. Classify to Regression: Select the intended CV or ML score column and preserve plate/well identity. Classify to Classifier Evaluation: Use the matching held-out predictions and split metadata. Classify to Activation: Also provide the matching crops and channel preprocessing. Classify to Explain CV Model: Select CV predictions and the matching measured objects. Gate Editor to Classify: Write reviewed gate selections to an annotation column, then select that same column and object population in Classify. Keep validation objects separate from training labels. Image UMAP to Classify: Write reviewed lasso selections to an annotation column in the matching object database, then select that column in Classify. Inspect crops and validate labels; embedding clusters are not ground truth.", "hold_after": 0.7, "related_lessons": ["08_measure", "09_annotate", "13_regression", "15_image_umap", "16_activation", "39_classifier_evaluation", "41_classify", "64_gate_editor", "70_explain_cv"]}, {"visual": "module_map_barcodes", "narration": "Open Map Barcodes from Home. Supply the references that encode your experiment. Inspect mapped counts and barcode QC before pairing well-level guide counts with phenotype scores. Input data: Sequencing reads. Sequencing reads: Single-end or paired FASTQ files, with the matching barcode reference tables. Output data: Guide counts per well. Guide counts per well: Map Barcodes run folder: unique_combinations.csv and annotated_reads.h5. Well identity requires the corresponding barcode references. Relevant columns depend on the selected route: count. Map Barcodes to Regression: Pair guide counts with phenotype scores using consistent plate/well keys. Map Barcodes to Barcode QC: Check mapping and coverage before guide filtering.", "hold_after": 0.7, "related_lessons": ["12_map_barcodes", "13_regression", "47_barcode_qc"]}, {"visual": "module_regression", "narration": "Open Regression from Home. Match plate and well identifiers across phenotype and guide-count inputs, select the response and controls, and inspect diagnostics before interpreting hits. Direct measured responses are also supported. Input data: Object classification scores; Guide counts per well; Optical barcode assignments; Measured objects. Optical barcode assignments: OPS destination measurements.db: per-well geometry, phenotype alignment, nuclei and barcode tables; optional per-cycle reads. Relevant tables depend on the selected route: ops_geometry, ops_phenotype, ops_objects, ops_barcodes, ops_reads. Output data: Regression results and hits. Regression results and hits: Selected run results folder: coefficient/result CSVs, hit tables, settings and diagnostic figures. Classify to Regression: Select the intended CV or ML score column and preserve plate/well identity. Map Barcodes to Regression: Pair guide counts with phenotype scores using consistent plate/well keys. OPS to Regression: Join/aggregate decoded objects to phenotype and guide inputs explicitly before Regression; this is not a direct CSV handoff. Regression to Run Compare: Compare compatible saved result sets and their settings. Regression to Hit List: Inspect ranked hits and guide agreement. Regression to Volcano Explorer: Inspect saved effects and adjusted significance. Regression to Diagnostics: Open the diagnostics actually written by this run. Regression to Methods & Results: Review exported prose and every traced result. Regression to Investigate Hit: Join compatible phenotype and object data for the chosen hit.", "hold_after": 0.7, "related_lessons": ["12_map_barcodes", "13_regression", "41_classify", "48_hit_list", "49_methods_results", "50_run_compare", "72_volcano_explorer", "75_regression_diagnostics", "76_ops"]}, {"visual": "module_feature_explorer", "narration": "Open Classify from Home, then choose Feature Explorer. Rank measured features for a chosen class comparison; review filtering and class definitions before interpreting the ranking. Input data: Measured objects; Training annotations. Output data: Figures and table exports. Figures and table exports: The output location chosen by the tool; exports describe the selected data and filters. Measure to Feature Explorer: Define the class comparison and inspect filtering.", "hold_after": 0.7, "related_lessons": ["08_measure", "65_feature_explorer"]}, {"visual": "module_convert", "narration": "Open Import from Home, then choose Format Converter. Convert supported microscope formats to a configured TIFF layout while preserving source mappings. Conversion does not generate object measurements. Input data: Microscope images. Output data: Microscope images. Format Converter to Mask: Use the converted layout and preserve source identity mappings.", "hold_after": 0.7, "related_lessons": ["07_mask", "35_converter"]}, {"visual": "module_foreign", "narration": "Open Import from Home. Import external measurements with explicit object/column mappings, or choose Import Images, Format Converter or External Masks. Imported measurements are not a fresh Measure run. With matching source images and external integer masks, Import builds the merged project arrays used by Measure. Choose the route matching your files and inspect object identities before measuring; imported feature tables can be used directly when they already contain the required measurements. Input data: Microscope images; Label masks; External measurements. External measurements: Third-party measurement CSV/database tables and their image, mask and object-identity mappings. Output data: Measured objects; Object crops; Images and label masks; Label masks. Import to Annotate: Imported tables require explicit column and object-identity mappings. Import to Measure: Import matching images and external integer masks to build merged project arrays, then open Measure on that project. Skip this step when compatible measurements have already been imported or computed. Do not append duplicate measurements to an existing imported table. Import to Mask: For image-only imports, use Import Images or Format Converter and point Mask at the formatted image project. External measurements alone are not segmentation input.", "hold_after": 0.7, "related_lessons": ["07_mask", "08_measure", "09_annotate", "36_import"]}, {"visual": "module_external_masks", "narration": "Open Import from Home, then choose External Masks. Assign corresponding images and existing integer label masks, then create and measure a spaCR project without rerunning segmentation. Input data: Microscope images; Label masks. Output data: Images and label masks; Measured objects; Object crops. External Masks to Measure: Re-measure only when needed; External Masks can already perform measurement. External Masks to Annotate: Keep the newly measured project and crop index together. Direct Cellpose mask generation to External Masks: Provide the saved label TIFFs and their original images to External Masks, assign object roles and create the merged project before Measure.", "hold_after": 0.7, "related_lessons": ["08_measure", "09_annotate", "31_external_masks"]}, {"visual": "module_queue", "narration": "Find Plate Queue in the application's Help or tools menus. Run the chosen pipeline across plates. Outputs are those of each queued module; retain each plate and its settings separately. Input data: Run queue. Run queue: Saved module/plate/settings job definitions and dependency order. Output data: Run history and artifacts. Run history and artifacts: Project run records, settings, output paths, artifact provenance, status and logs.", "hold_after": 0.7, "related_lessons": ["30_plate_queue"]}, {"visual": "module_batch", "narration": "Find Batch Runner in the application's Help or tools menus. Validate and execute module jobs in dependency order. Each job writes its own module outputs and log. Input data: Run queue. Output data: Run history and artifacts.", "hold_after": 0.7, "related_lessons": ["37_batch"]}, {"visual": "module_distributed_jobs", "narration": "Find Distributed Jobs in the application's Help or tools menus. Submit a configured run to a remote execution target and inspect its status and logs. Retrieve the actual module artifacts before downstream analysis. Input data: Run queue. Output data: Run history and artifacts.", "hold_after": 0.7, "related_lessons": ["38_distributed_jobs"]}, {"visual": "module_db_browser", "narration": "Find Database Browser in the application's Help or tools menus. Browse selected tables and export rows; table inspection does not rerun image analysis. Input data: Measured objects. Output data: Figures and table exports. Measure to Database Browser: Inspect actual tables before exporting.", "hold_after": 0.7, "related_lessons": ["08_measure", "34_database"]}, {"visual": "module_run_history", "narration": "Find Run History in the application's Help or tools menus. Inspect saved run status, settings, outputs and logs; a completed run does not establish biological validity. Input data: Run history and artifacts. Output data: Run history and artifacts.", "hold_after": 0.7, "related_lessons": ["40_run_history"]}, {"visual": "module_report", "narration": "Find Report in the application's Help or tools menus. Package recorded results, settings and QC into a shareable report without silently rerunning the analysis. Input data: Run history and artifacts; Quality-control results; Figures and table exports. Quality-control results: Stored project checks and QC reports; a missing check is not a passing result. Output data: Shareable reports. Shareable reports: Exported HTML/PDF or methods/results documents derived from recorded analysis outputs.", "hold_after": 0.7, "related_lessons": ["29_report"]}, {"visual": "module_data_manager", "narration": "Find Data Manager in the application's Help or tools menus. Inspect project files and disk usage. Removing derived artifacts invalidates downstream uses of those files; original images must remain recoverable. Input data: Run history and artifacts. Output data: Run history and artifacts.", "hold_after": 0.7, "related_lessons": ["44_data_manager"]}, {"visual": "module_pipeline_graph", "narration": "Find Pipeline Graph in the application's Help or tools menus. Read recorded artifact dependencies and stale/missing status. The graph describes provenance and does not regenerate missing artifacts. Input data: Run history and artifacts. Output data: Figures and table exports.", "hold_after": 0.7, "related_lessons": ["52_pipeline_graph"]}, {"visual": "module_qc_dashboard", "narration": "Open QC from Home. Inspect stored segmentation, unit, leakage and plate-effect checks. Open its nested viewers for detailed inspection. Input data: Measured objects; Quality-control results. Output data: Quality-control results; Figures and table exports. Measure to QC: Review available checks and missing evidence.", "hold_after": 0.7, "related_lessons": ["08_measure", "54_qc_dashboard"]}, {"visual": "module_lineage", "narration": "Open Database Browser through Help search, then choose Lineage. Inspect recorded cell/nucleus/pathogen/organelle containment links; this is object containment, not time-series lineage inference. Input data: Measured objects. Output data: Figures and table exports.", "hold_after": 0.7, "related_lessons": ["56_lineage"]}, {"visual": "module_experiment_design", "narration": "Open Experiment Design from Home. Enter conditions, controls, replicates and plate constraints, then export the experimental layout before acquisition. Input data: Screen design and power estimates. Screen design and power estimates: Saved planning tables or figures based on explicitly chosen effect sizes, variability and sampling assumptions. Output data: Experimental layout. Experimental layout: Exported plate/condition/control/replicate map. Keep its plate and well identifiers consistent with the acquired data. Experiment Design to Power / Design: Use the experimental layout to define sampling assumptions, then revise the design. Experiment Design to Dose–Response: Acquire and measure the experiment first, preserving dose/condition identities.", "hold_after": 0.7, "related_lessons": ["67_experiment_design", "68_power_design", "69_dose_response"]}, {"visual": "module_layer_viewer", "narration": "Open QC from Home, then choose Layer Viewer. Inspect aligned image, label and point/ROI layers for the selected field. Input data: Microscope images; Label masks. Output data: Figures and table exports.", "hold_after": 0.7, "related_lessons": ["57_layer_viewer"]}, {"visual": "module_power", "narration": "Open Power / Design from Home. Estimate sampling needs from chosen effect sizes and variability; pilot measurements are optional evidence for assumptions. Input data: Screen design and power estimates; Measured objects; Experimental layout. Output data: Screen design and power estimates. Experiment Design to Power / Design: Use the experimental layout to define sampling assumptions, then revise the design.", "hold_after": 0.7, "related_lessons": ["67_experiment_design", "68_power_design"]}, {"visual": "module_run_compare", "narration": "Open Run Compare from Home. Compare compatible saved settings, counts and hit lists without treating changed input data as a controlled model comparison. Input data: Run history and artifacts; Regression results and hits. Output data: Run/model comparison. Run/model comparison: Comparison tables and figures from compatible saved runs or masks; agreement is not ground-truth accuracy. Regression to Run Compare: Compare compatible saved result sets and their settings.", "hold_after": 0.7, "related_lessons": ["13_regression", "50_run_compare"]}, {"visual": "module_tabulate", "narration": "Open Database Browser through Help search, then choose Tabulate. Choose grouping variables and measurement columns, then inspect pivot tables and groupwise sample sizes. Input data: Measured objects. Output data: Figures and table exports.", "hold_after": 0.7, "related_lessons": ["61_tabulate"]}, {"visual": "module_dose_response", "narration": "Open Dose–Response from Home. Supply dose and response columns, controls and units before curve fitting; this route does not require sequencing. Input data: Measured objects; Experimental layout. Output data: Assay results; Figures and table exports. Assay results: Assay-specific result tables and figures in the configured destination, preserving well and condition identities. Experiment Design to Dose–Response: Acquire and measure the experiment first, preserving dose/condition identities. Measure to Dose–Response: Join the measured response to explicit doses and controls.", "hold_after": 0.7, "related_lessons": ["08_measure", "67_experiment_design", "69_dose_response"]}, {"visual": "module_project_browser", "narration": "Find Project Browser in the application's Help or tools menus. Locate projects and inspect their stage, last run, disk use and stale outputs. Input data: Run history and artifacts. Output data: Run history and artifacts.", "hold_after": 0.7, "related_lessons": ["45_project_browser"]}, {"visual": "module_outliers", "narration": "Open QC from Home, then choose Outliers. Review robust object/well outlier scores and the selected exclusion rule before carrying filtered data into analysis. Input data: Measured objects. Output data: Quality-control results; Figures and table exports.", "hold_after": 0.7, "related_lessons": ["66_outliers"]}, {"visual": "module_embeddings", "narration": "Open Embeddings from Home. Encode object images with a chosen model and channel policy. Retain object identities and encoder provenance when supplying the features to downstream exploration. Input data: Measured objects; Object crops. Output data: Image embeddings. Image embeddings: Object-indexed encoder features, with channel policy and encoder provenance. The encoding API returns features; persistence is caller-dependent. Measure to Embeddings: Retain encoder and channel-policy provenance. Embeddings to Image UMAP: Supply the encoder feature table with matching object IDs; do not assume every GUI route automatically persists it.", "hold_after": 0.7, "related_lessons": ["08_measure", "15_image_umap", "77_embeddings"]}, {"visual": "module_control_chart", "narration": "Open QC from Home, then choose Control Charts. Compare designated controls across plates and inspect drift; the definition of a control comes from the experiment. Input data: Measured objects; Experimental layout. Output data: Quality-control results; Figures and table exports.", "hold_after": 0.7, "related_lessons": ["51_control_charts"]}, {"visual": "module_train_compare", "narration": "Open Classify from Home, then choose Training Runs. Compare saved training histories, metrics and settings from compatible model runs. Input data: Run history and artifacts. Output data: Run/model comparison.", "hold_after": 0.7, "related_lessons": ["28_training_runs"]}, {"visual": "module_align", "narration": "Open Align & Stitch from Home. Inspect tile geometry, overlap and channel mapping, then save the mosaic with coordinate records. OPS also needs the original cycle/site identities. Input data: Microscope images. Output data: Aligned mosaic and coordinates. Aligned mosaic and coordinates: Align & Stitch destination: composed image and the tile-coordinate/layout records needed to interpret it. Align & Stitch to OPS: Carry tile coordinates and original sequencing cycles into OPS; a flattened mosaic alone is insufficient.", "hold_after": 0.7, "related_lessons": ["32_align_stitch", "76_ops"]}, {"visual": "module_make_masks", "narration": "Open Make Masks from Home. Curate image/mask pairs for segmentation training, or use FEATURES to assign images and masks and invoke measurement. Saving a mask does not train a classifier. Input data: Microscope images; Label masks. Output data: Curated training fields; Label masks. Curated training fields: Separate image and integer-mask files with matching field identities; preserve original images and labels. Make Masks to Cellpose Workbench: Use independently checked image/mask pairs. Make Masks to Measure: Use FEATURES to pair images and masks and write a measured project; standalone masks are not merged arrays. Make Masks to Plaque Assay: Use plaque masks with matching source images; cell masks are not automatically plaque labels.", "hold_after": 0.7, "related_lessons": ["08_measure", "14_make_masks", "19_train_cellpose", "24_plaque"]}, {"visual": "module_plate_view", "narration": "Open Graph Builder from Home, then choose Plate Viewer. Aggregate the selected measurement by well and inspect plate patterns and controls. Input data: Measured objects; Experimental layout. Output data: Figures and table exports.", "hold_after": 0.7, "related_lessons": []}, {"visual": "module_umap", "narration": "Open Image UMAP from Home. Project measured features or supplied encoder features and inspect representative crops. A cluster is a candidate grouping, not a validated phenotype. Use the lasso and annotation controls to write reviewed selections to an annotation column in the matching measurement database. A geometric selection alone does not establish a biological phenotype. Input data: Measured objects; Object crops; Image embeddings. Output data: Projection and clusters; Training annotations. Projection and clusters: Image UMAP/PCA coordinate tables, selected clusters and figures for the loaded measurement data. Measure to Image UMAP: Choose feature columns and inspect representative crops. Embeddings to Image UMAP: Supply the encoder feature table with matching object IDs; do not assume every GUI route automatically persists it. Image UMAP to Gate Editor: Supply the matching coordinate/feature columns when defining a selection. Image UMAP to Classify: Write reviewed lasso selections to an annotation column in the matching object database, then select that column in Classify. Inspect crops and validate labels; embedding clusters are not ground truth.", "hold_after": 0.7, "related_lessons": ["08_measure", "15_image_umap", "41_classify", "64_gate_editor", "77_embeddings"]}, {"visual": "module_profiler", "narration": "Open Regression from Home, then choose Prediction Profiler. Inspect how a fitted model responds as an input feature changes; predictions do not establish causal effects. Input data: Fitted feature classifier. Output data: Figures and table exports.", "hold_after": 0.7, "related_lessons": ["53_prediction_profiler"]}, {"visual": "module_graph_builder", "narration": "Open Graph Builder from Home. Choose variables, groups and plotting settings from the loaded table, then export the figure with its analysis context. Input data: Measured objects. Output data: Figures and table exports. Measure to Graph Builder: Choose explicit variables, groups and filters.", "hold_after": 0.7, "related_lessons": ["08_measure", "58_graph_builder"]}, {"visual": "module_investigate_hit", "narration": "Open Regression from Home, then choose Investigate Hit. Link a regression hit to candidate objects and quantitative well-level evidence. This does not independently validate the hit. Input data: Regression results and hits; Object classification scores; Measured objects. Output data: Figures and table exports. Regression to Investigate Hit: Join compatible phenotype and object data for the chosen hit.", "hold_after": 0.7, "related_lessons": ["13_regression"]}, {"visual": "module_gate_editor", "narration": "Open Gate Editor from Home. Define threshold or polygon gates on actual feature/coordinate columns, then apply the saved gate to compatible objects. Use Annotate to write the displayed gates to an annotation column; review the selected objects and choose binary or multiclass labels. Input data: Measured objects; Projection and clusters. Output data: Reusable gates; Training annotations. Image UMAP to Gate Editor: Supply the matching coordinate/feature columns when defining a selection. Gate Editor to Annotate: Apply compatible gates, then review candidate labels. Measure to Gate Editor: Use the actual measured feature definitions and units. Gate Editor to Classify: Write reviewed gate selections to an annotation column, then select that same column and object population in Classify. Keep validation objects separate from training labels.", "hold_after": 0.7, "related_lessons": ["08_measure", "09_annotate", "15_image_umap", "41_classify", "64_gate_editor"]}, {"visual": "module_feature_dict", "narration": "Find Feature Dictionary in the application's Help or tools menus. Look up feature definitions and units before choosing measurement columns. Input data: Feature definitions. Feature definitions: The installed feature dictionary; definitions describe existing measurements and do not compute them. Output data: Feature definitions.", "hold_after": 0.7, "related_lessons": ["62_feature_dictionary"]}, {"visual": "module_trellis", "narration": "Open Graph Builder from Home, then choose Small Multiples. Compare groups in small-multiple plots with explicit shared or independent axes. Input data: Measured objects. Output data: Figures and table exports.", "hold_after": 0.7, "related_lessons": ["63_small_multiples"]}, {"visual": "module_analyze_plaques", "narration": "Open Toxoplasma from Home, then choose Plaque Assay. Analyse plaque images or existing masks with the configured plaque model. This route need not pass through Measure; use the dedicated plaque example. Input data: Microscope images; Label masks. Output data: Assay results; Label masks. Make Masks to Plaque Assay: Use plaque masks with matching source images; cell masks are not automatically plaque labels.", "hold_after": 0.7, "related_lessons": ["14_make_masks", "24_plaque"]}, {"visual": "module_recruitment", "narration": "Open Toxoplasma from Home, then choose Recruitment. Use compartment intensity measurements and matching host/pathogen identities to compute recruitment ratios. Input data: Measured objects. Output data: Assay results. Measure to Recruitment: Require the intended compartment intensities and identities.", "hold_after": 0.7, "related_lessons": ["08_measure", "25_recruitment"]}, {"visual": "module_host_pathogen", "narration": "Open Toxoplasma from Home, then choose Host–Pathogen Analysis. Measure whole vacuoles and host reference compartments, keeping uninfected host cells for the infection denominator. Select marker channels and control-calibrated ratio thresholds. Optionally count individually segmented parasites from explicit vacuole links or a measured count column. Review vacuole, host and well tables, joint marker states, replication distributions and unmatched parasite links; unknown measurements remain unknown. Input data: Measured objects. Output data: Assay results. Measure to Host–Pathogen Analysis: Keep uninfected cells in Measure. Supply whole-vacuole masks, host reference intensities and optional explicit parasite-to-vacuole links; host identity alone does not define a vacuole.", "hold_after": 0.7, "related_lessons": ["08_measure", "85_host_pathogen"]}, {"visual": "module_invasion", "narration": "Open Toxoplasma from Home, then choose Invasion Assay. Use the required two-colour differential-staining measurements and stain-baseline controls to distinguish attachment from invasion. Input data: Measured objects. Output data: Assay results. Measure to Invasion Assay: Require two-colour stain measurements and appropriate baseline controls.", "hold_after": 0.7, "related_lessons": ["08_measure", "26_invasion"]}, {"visual": "module_replication", "narration": "Open Toxoplasma from Home, then choose Replication Assay. Count parasites using explicit vacuole identity and compare condition distributions; host identity alone does not define a vacuole. Input data: Measured objects. Output data: Assay results. Measure to Replication Assay: Require explicit parasite-to-vacuole identities.", "hold_after": 0.7, "related_lessons": ["08_measure", "27_replication"]}, {"visual": "module_train_cellpose", "narration": "Open Make Masks from Home, then choose Cellpose Workbench. Open Cellpose Workbench inside Make Masks and train from verified image/mask pairs. Evaluate on separate fields before selecting the checkpoint in Mask. Input data: Curated training fields. Output data: Segmentation checkpoint. Make Masks to Cellpose Workbench: Use independently checked image/mask pairs. Cellpose Workbench to Mask: Select the saved compatible checkpoint in Mask. Cellpose Workbench to Direct Cellpose mask generation: Pass the trained checkpoint as custom_model with the matching image channels and preprocessing.", "hold_after": 0.7, "related_lessons": ["07_mask", "14_make_masks", "19_train_cellpose"]}, {"visual": "module_cellpose_all", "narration": "Open Make Masks from Home, then choose Mask the whole folder. Apply the selected segmentation model to the open image folder through Make Masks; inspect saved labels before measuring them. Input data: Microscope images; Segmentation checkpoint. Output data: Label masks.", "hold_after": 0.7, "related_lessons": ["20_cellpose_masks"]}, {"visual": "module_model_compare", "narration": "Open Make Masks from Home, then choose Model Compare. Compare model masks on identical fields. Without independent reference labels, agreement does not measure segmentation accuracy. Input data: Microscope images; Label masks; Segmentation checkpoint. Output data: Run/model comparison.", "hold_after": 0.7, "related_lessons": ["21_model_compare"]}, {"visual": "module_model_zoo", "narration": "Open Make Masks from Home, then choose Model Zoo. Inspect model provenance and download/install compatible checkpoints or backends. A listed backend is not itself a checkpoint file. Input data: Segmentation checkpoint. Output data: Segmentation checkpoint.", "hold_after": 0.7, "related_lessons": ["22_model_zoo"]}, {"visual": "module_curate", "narration": "Open Make Masks from Home, then choose Curate. Correct labels and track assignments while retaining a record of the edits. Input data: Microscope images; Label masks; Linked time-series objects. Linked time-series objects: Tracked labels and frame/object associations from the time-series project, with frame interval and units. Output data: Label masks; Linked time-series objects.", "hold_after": 0.7, "related_lessons": ["42_curate"]}, {"visual": "module_napari_bridge", "narration": "Open Make Masks from Home, then choose Napari Bridge. Send the matching image/labels to napari and import the revised labels back with field identity preserved. Input data: Microscope images; Label masks. Output data: Label masks.", "hold_after": 0.7, "related_lessons": ["46_napari_bridge"]}, {"visual": "module_import_images", "narration": "Open Import from Home, then choose Import Images. Review field identities, image channels and optional external masks before writing a separate project. Image-only imports still need segmentation before measurement. Input data: Microscope images. Output data: Microscope images; Images and label masks; Label masks. Import Images to Mask: Use imported image planes and identities; image-only imports still need segmentation.", "hold_after": 0.7, "related_lessons": ["07_mask", "74_import_images"]}, {"visual": "module_barcode_qc", "narration": "Open Map Barcodes from Home, then choose Barcode QC. Inspect mapping depth, coverage, collisions and positional effects before guide-count filtering. Input data: Guide counts per well. Output data: Quality-control results; Figures and table exports. Map Barcodes to Barcode QC: Check mapping and coverage before guide filtering.", "hold_after": 0.7, "related_lessons": ["12_map_barcodes", "47_barcode_qc"]}, {"visual": "module_image_scatter", "narration": "Open Image UMAP from Home, then choose Image Scatter. Plot selected measurement columns with object-crop inspection. Input data: Measured objects; Object crops. Output data: Projection and clusters; Figures and table exports.", "hold_after": 0.7, "related_lessons": ["55_image_scatter"]}, {"visual": "module_pca", "narration": "Open Image UMAP from Home, then choose PCA. Inspect principal components and feature loadings for the selected measured objects. Input data: Measured objects. Output data: Projection and clusters; Figures and table exports.", "hold_after": 0.7, "related_lessons": ["60_pca"]}, {"visual": "module_volcano_explorer", "narration": "Open Regression from Home, then choose Volcano Explorer. Open a saved regression result and inspect effect sizes, adjusted significance and individual hit records. Input data: Regression results and hits. Output data: Figures and table exports. Regression to Volcano Explorer: Inspect saved effects and adjusted significance.", "hold_after": 0.7, "related_lessons": ["13_regression", "72_volcano_explorer"]}, {"visual": "module_hit_list", "narration": "Open Regression from Home, then choose Hit List. Filter and rank saved hits with their effects, FDR and guide agreement. Input data: Regression results and hits. Output data: Figures and table exports. Regression to Hit List: Inspect ranked hits and guide agreement.", "hold_after": 0.7, "related_lessons": ["13_regression", "48_hit_list"]}, {"visual": "module_methods_export", "narration": "Open Regression from Home, then choose Methods & Results. Draft methods/results text from recorded settings and results; review every claim before publication. Input data: Run history and artifacts; Regression results and hits. Output data: Shareable reports. Regression to Methods & Results: Review exported prose and every traced result.", "hold_after": 0.7, "related_lessons": ["13_regression", "49_methods_results"]}, {"visual": "module_regression_diagnostics", "narration": "Open Regression from Home, then choose Diagnostics. Inspect the diagnostic panels saved by the chosen regression run; distinguish missing diagnostics from passed assumptions. Input data: Regression results and hits. Output data: Quality-control results; Figures and table exports. Regression to Diagnostics: Open the diagnostics actually written by this run.", "hold_after": 0.7, "related_lessons": ["13_regression", "75_regression_diagnostics"]}, {"visual": "module_illumination", "narration": "Open Measure from Home, then choose Illumination. Estimate and apply flat-field correction at configured stages. Keep corrected display values distinct from raw measurements and record the applied policy. Input data: Microscope images. Output data: Microscope images.", "hold_after": 0.7, "related_lessons": ["43_illumination"]}, {"visual": "module_anndata_export", "narration": "Open Measure from Home, then choose AnnData Export. Export an AnnData .h5ad file with object metadata and measured features for downstream single-cell analysis. Input data: Measured objects. Output data: AnnData export. AnnData export: An exported .h5ad file containing measured features and object metadata. Measure to AnnData Export: Export compatible feature and metadata columns.", "hold_after": 0.7, "related_lessons": ["08_measure", "59_anndata_export"]}, {"visual": "module_motility", "narration": "Open Measure from Home, then choose Motility Assay. Inspect track speed and infection-related measurements with an explicit frame interval and pixel calibration. Input data: Linked time-series objects; Measured objects. Output data: Assay results; Figures and table exports. Timelapse to Motility Assay: Supply frame interval and pixel calibration. Measure to Motility Assay: Combine measured objects with matching tracks.", "hold_after": 0.7, "related_lessons": ["08_measure", "17_timelapse", "18_motility"]}, {"visual": "module_timelapse", "narration": "Open Mask from Home, then choose Timelapse. Open Timelapse within Mask to segment and link objects across ordered frames; inspect links before downstream motility analysis. Input data: Microscope images. Output data: Images and label masks; Label masks; Linked time-series objects. Mask to Timelapse: Enable the nested time-series route before generating linked labels. Timelapse to Measure: Use the time-series project with stable frame/object identities. Timelapse to Motility Assay: Supply frame interval and pixel calibration.", "hold_after": 0.7, "related_lessons": ["07_mask", "08_measure", "17_timelapse", "18_motility"]}, {"visual": "module_ops", "narration": "Open Mask from Home, then choose OPS. Use sequencing-cycle images and phenotype alignment to decode barcodes per nucleus. Aggregate/join the decoded identities to compatible phenotype inputs before Regression; the OPS database is not a drop-in FASTQ count CSV. Input data: Microscope images; Aligned mosaic and coordinates. Output data: Optical barcode assignments. Align & Stitch to OPS: Carry tile coordinates and original sequencing cycles into OPS; a flattened mosaic alone is insufficient. OPS to Regression: Join/aggregate decoded objects to phenotype and guide inputs explicitly before Regression; this is not a direct CSV handoff.", "hold_after": 0.7, "related_lessons": ["13_regression", "32_align_stitch", "76_ops"]}, {"visual": "module_classifier_evaluation", "narration": "Open Classify from Home, then choose Classifier Evaluation. Inspect held-out predictions, calibration and split/leakage evidence for the matching classifier. Input data: Classifier evaluation bundle. Output data: Quality-control results; Figures and table exports. Classify to Classifier Evaluation: Use the matching held-out predictions and split metadata.", "hold_after": 0.7, "related_lessons": ["39_classifier_evaluation", "41_classify"]}, {"visual": "module_explain_cv", "narration": "Open Classify from Home, then choose Explain CV Model. Fit a measured-feature surrogate to existing computer-vision scores, preserving identity joins. A surrogate explanation is not causality. Input data: Measured objects; Object classification scores. Output data: Fitted feature classifier; Figures and table exports. Classify to Explain CV Model: Select CV predictions and the matching measured objects.", "hold_after": 0.7, "related_lessons": ["41_classify", "70_explain_cv"]}, {"visual": "module_activation", "narration": "Open Classify from Home, then choose Activation. Apply the matching image classifier and preprocessing to inspect saliency/model-response maps. Input data: Trained image classifier; Object crops. Output data: Image attribution maps. Image attribution maps: Saved model-response/saliency images for the matching classifier and input preprocessing. Classify to Activation: Also provide the matching crops and channel preprocessing.", "hold_after": 0.7, "related_lessons": ["16_activation", "41_classify"]}, {"visual": "module_agreement", "narration": "Open Annotate from Home, then choose Annotator Agreement. Compare independent annotation columns and inspect discordant objects; agreement is separate from classification accuracy. Input data: Training annotations; Object crops. Output data: Quality-control results; Figures and table exports. Annotate to Annotator Agreement: Choose independent annotation columns for the same objects.", "hold_after": 0.7, "related_lessons": ["09_annotate", "23_agreement"]}, {"visual": "module_classify", "narration": "Open Classify from Home, then choose Computer Vision. Train an image classifier from labelled object crops, archives or supported streamed crops. Match channels and preprocessing when applying its checkpoint. Input data: Measured objects; Object crops; Training annotations. Output data: Object classification scores; Trained image classifier; Classifier evaluation bundle.", "hold_after": 0.7, "related_lessons": ["10_classify_cv"]}, {"visual": "module_ml_analyze", "narration": "Open Classify from Home, then choose Tabular Machine Learning. Train a feature-based classifier from measured objects and labels. Inspect missing-feature exclusions and grouped held-out performance before using scores. Input data: Measured objects; Training annotations. Output data: Object classification scores; Fitted feature classifier; Classifier evaluation bundle.", "hold_after": 0.7, "related_lessons": ["11_classify_ml"]}, {"visual": "module_parameter_sweep", "narration": "Open Regression from Home, then choose Parameter Sweep. Run explicitly selected regression settings and compare their diagnostics. Keep the input data and evaluation question fixed. Input data: Object classification scores; Guide counts per well. Output data: Run/model comparison; Regression results and hits.", "hold_after": 0.7, "related_lessons": ["73_parameter_sweep"]}, {"visual": "module_toxoplasma", "narration": "Open Toxoplasma from Home. Open the organism guide from Home, inspect the compartment diagram, then select Plaque Assay, Recruitment, Invasion Assay or Replication Assay. The four Coming soon tiles describe proposals and cannot run. The guide itself does not analyse a project or produce a measurement table. Input data: Bundled organism reference. Bundled organism reference: Installed organism descriptions and SwissBioPics cell diagrams; no project input is required. Output data: Organism guide and assay selection. Organism guide and assay selection: GUI-only compartment highlights and navigation to available assays; no measurements or files are produced.", "hold_after": 0.7, "related_lessons": ["82_toxoplasma"]}, {"visual": "module_plasmodium", "narration": "Open Plasmodium spp. from Home. Open the organism guide from Home to read the planned malaria imaging workflows and inspect the shared apicomplexan diagram. All eight assay tiles are Coming soon; none starts an analysis or produces a result. Input data: Bundled organism reference. Output data: Organism guide and assay selection.", "hold_after": 0.7, "related_lessons": ["83_plasmodium"]}, {"visual": "module_candida", "narration": "Open Candida spp. from Home. Open the organism guide from Home to read the planned fungal imaging workflows and inspect the generic budding-yeast diagram. All eight assay tiles are Coming soon; none starts an analysis or produces a result. Input data: Bundled organism reference. Output data: Organism guide and assay selection.", "hold_after": 0.7, "related_lessons": ["84_candida"]}, {"visual": "module_endodyogeny", "narration": "Use Endodyogeny size proxy from Python through spacr.submodules.analyze_endodyogeny. This API-only workflow has no Home tile or menu entry. Read measured compartment areas, annotate conditions and bin area ** 1.5 into log2 size doublings. Defaults aggregate pathogen area per host cell, not per vacuole: multiple vacuoles in one cell are combined. This is an area-derived size proxy, not measured volume or a parasite count. Use Replication Assay with explicit vacuole identity for parasites-per-vacuole counts. Configure compartment, area filters, calibration, conditions and grouping before calling the API; saving is optional. Input data: Host-cell-aggregated compartment areas. Host-cell-aggregated compartment areas: Each src project root/measurements/measurements.db; tables defaults to cell, nucleus, pathogen and cytoplasm, with png_list added for merging. The compartment setting selects the area column; default pathogen_area is summed per host cell. Relevant tables depend on the selected route: cell, nucleus, pathogen, cytoplasm, png_list. Relevant columns depend on the selected route: cell_id, pathogen_area. Output data: Area-derived size-proxy results. Area-derived size-proxy results: Returned data and chi_squared DataFrames; save=True also writes data.csv, chi_squared_results.csv, chi_squared_pairwise_results.csv and a figure under the first project root/results/analyze_endodyogeny/. Relevant columns depend on the selected route: pathogen_area, pathogen_volume, pathogen_volume_bin, bin_index. Measure to Endodyogeny size proxy: Supply the measured project roots and required object/png_list tables. Verify host-cell aggregation and area units before interpreting size bins; the Mask counts database alone is insufficient.", "hold_after": 0.7, "related_lessons": ["08_measure"]}, {"visual": "module_cellpose_masks", "narration": "Use Direct Cellpose mask generation from Python through spacr.spacr_cellpose.identify_masks_finetune. This API-only workflow has no Home tile or menu entry. Run a stock or custom Cellpose model on TIFF fields through the Python API. Despite its historical identify_masks_finetune name, this function performs inference, not training. Review normalization, channels, resizing and model parameters; masks are written only when save is enabled. Import compatible image/mask pairs through External Masks before Measure, or curate the pairs before training. This call does not build a Measure-ready merged project. Input data: TIFF fields for direct Cellpose inference; Segmentation checkpoint. TIFF fields for direct Cellpose inference: Top-level, lowercase .tif files in src; existing same-name files in src/masks are skipped. Supply the configured channels and a compatible stock model_name or custom_model checkpoint. Output data: Direct Cellpose TIFF masks. Direct Cellpose TIFF masks: When save=True, src/masks/<image-name>.tif contains integer labels. The call returns None and does not produce merged arrays or measurements.db. Cellpose Workbench to Direct Cellpose mask generation: Pass the trained checkpoint as custom_model with the matching image channels and preprocessing. Direct Cellpose mask generation to External Masks: Provide the saved label TIFFs and their original images to External Masks, assign object roles and create the merged project before Measure.", "hold_after": 0.7, "related_lessons": ["19_train_cellpose", "31_external_masks"]}, {"visual": "module_simulation", "narration": "Use Pooled-screen simulation sweep from Python through spacr.sim.run_multiple_simulations. This API-only workflow has no Home tile or menu entry. Use the Python sweep API to explore stated screen-design assumptions. It expands combinations, runs simulations in a process pool and writes synthetic summary statistics; it returns None. Set a small explicit max_workers value and a bounded parameter grid before running. The output does not replace measurements or barcode counts for experimental Regression. Use the findings as planning evidence, with their assumptions recorded. Review the synthetic summaries when choosing planning assumptions; transfer those assumptions manually into Power / Design or Experiment Design. Neither tool imports this simulation database, and neither exports the simulation settings grid. Input data: Pooled-screen simulation assumptions. Pooled-screen simulation assumptions: Python settings dictionary: iterable sweep values for screen size, occupancy, classifier accuracy and sequencing assumptions, plus replicates, src, name, variable, plot and max_workers. generate_parameters expands their Cartesian product; begin with a small sweep and an explicit worker bound. Output data: Synthetic screen simulation summaries. Synthetic screen simulation summaries: src/<YYMMDD>/<name>/simulations.db; the sweep appends summary rows to simulations and optionally writes plots. These are synthetic performance estimates, not measured experimental hits. Relevant tables depend on the selected route: simulations.", "hold_after": 0.7, "related_lessons": []}, {"visual": "home_summary", "narration": "Return to the chapter matching your next data product rather than repeating work you already completed. A count table is not a measured feature table, a projection is not a trained classifier, and a comparison is not a new experiment. The linked API pages carry the same file, table and column contracts, and the specialist lessons demonstrate the individual controls.", "hold_after": 0.7}], "narration_voices": {"en": ["af_heart"]}, "poster": "79_module_inputs_outputs/poster.jpg", "silent": "79_module_inputs_outputs/video/79_module_inputs_outputs_silent.mp4"}, {"id": "80_image_analysis_pathways", "number": 80, "slug": "image_analysis_pathways", "title": "Image analysis modules and how they relate", "series": 1, "app_key": null, "section": "Workflows", "description": "Choose an image-analysis route through segmentation, measurement, annotation, classification, projections, gates, image registration, quality control and assays.", "objectives": ["Choose a starting module from the data you already have.", "Identify what each module reads and writes.", "Follow the linked module lessons and API contracts for the next step."], "prerequisite": "Install spaCR and open Home. This lesson explains navigation and data handoffs; the linked module lessons provide the worked data examples. Inputs and outputs include conditional alternatives, as explained for each module.", "scenes": [{"visual": "home", "narration": "Begin on Home by deciding whether you have raw images, existing masks or measured objects. Mask creates segmentation outputs; Make Masks curates individual fields; Measure turns compatible images and labels into object measurements and optional crops. From there, the scientific question determines whether to classify, explore a projection, define a gate or run an assay. Align tiled images before the analysis that needs a common coordinate system. The routes here are alternatives and branches, not a requirement to run every module.", "hold_after": 0.7, "related_lessons": ["05_home"]}, {"visual": "module_mask", "narration": "Open Mask from Home. Select channels and models, inspect a preview, then run Mask. Measure consumes the merged arrays; the counts database is not yet a feature table. Input data: Microscope images; Segmentation checkpoint. Output data: Images and label masks; Label masks; Object counts. Mask to Measure: Use the same project and the correct image/mask channel indices.", "hold_after": 0.7, "related_lessons": ["07_mask", "08_measure"]}, {"visual": "module_make_masks", "narration": "Open Make Masks from Home. Curate image/mask pairs for segmentation training, or use FEATURES to assign images and masks and invoke measurement. Saving a mask does not train a classifier. Input data: Microscope images; Label masks. Output data: Curated training fields; Label masks. Make Masks to Measure: Use FEATURES to pair images and masks and write a measured project; standalone masks are not merged arrays. Make Masks to Plaque Assay: Use plaque masks with matching source images; cell masks are not automatically plaque labels.", "hold_after": 0.7, "related_lessons": ["08_measure", "14_make_masks", "24_plaque"]}, {"visual": "module_measure", "narration": "Open Measure from Home. Measure reads images and label planes together. Enable crop saving if you need PNG files; keep the database and source project together for streamed crops. Input data: Images and label masks; Label masks. Output data: Measured objects; Object crops. Mask to Measure: Use the same project and the correct image/mask channel indices. Measure to Annotate: Save or stream crops with stable object identities. Measure to Classify: Choose the image or tabular family to match your input. Make Masks to Measure: Use FEATURES to pair images and masks and write a measured project; standalone masks are not merged arrays. Measure to Image UMAP: Choose feature columns and inspect representative crops. Measure to Embeddings: Retain encoder and channel-policy provenance. Measure to Gate Editor: Use the actual measured feature definitions and units. Measure to QC: Review available checks and missing evidence. Measure to Recruitment: Require the intended compartment intensities and identities. Measure to Invasion Assay: Require two-colour stain measurements and appropriate baseline controls. Measure to Replication Assay: Require explicit parasite-to-vacuole identities. Measure to Endodyogeny size proxy: Supply the measured project roots and required object/png_list tables. Verify host-cell aggregation and area units before interpreting size bins; the Mask counts database alone is insufficient. Measure to Host–Pathogen Analysis: Keep uninfected cells in Measure. Supply whole-vacuole masks, host reference intensities and optional explicit parasite-to-vacuole links; host identity alone does not define a vacuole.", "hold_after": 0.7, "related_lessons": ["07_mask", "08_measure", "09_annotate", "14_make_masks", "15_image_umap", "25_recruitment", "26_invasion", "27_replication", "41_classify", "54_qc_dashboard", "64_gate_editor", "77_embeddings", "85_host_pathogen"]}, {"visual": "module_annotate", "narration": "Open Annotate from Home. Label representative objects in png_list before supervised training. Use separate annotations for different questions and keep training and evaluation groups independent. Input data: Measured objects; Object crops; Reusable gates. Output data: Training annotations. Measure to Annotate: Save or stream crops with stable object identities. Annotate to Classify: Keep labelled training and evaluation groups separate. Gate Editor to Annotate: Apply compatible gates, then review candidate labels.", "hold_after": 0.7, "related_lessons": ["08_measure", "09_annotate", "41_classify", "64_gate_editor"]}, {"visual": "module_classify_merged", "narration": "Open Classify from Home. Choose Computer Vision for crops or streamed object images, or Tabular Machine Learning for measured feature columns. The two families consume different inputs. Input data: Measured objects; Object crops; Training annotations. Output data: Object classification scores; Trained image classifier; Fitted feature classifier; Classifier evaluation bundle. Measure to Classify: Choose the image or tabular family to match your input. Annotate to Classify: Keep labelled training and evaluation groups separate. Classify to Regression: Select the intended CV or ML score column and preserve plate/well identity. Gate Editor to Classify: Write reviewed gate selections to an annotation column, then select that same column and object population in Classify. Keep validation objects separate from training labels. Image UMAP to Classify: Write reviewed lasso selections to an annotation column in the matching object database, then select that column in Classify. Inspect crops and validate labels; embedding clusters are not ground truth.", "hold_after": 0.7, "related_lessons": ["08_measure", "09_annotate", "13_regression", "15_image_umap", "41_classify", "64_gate_editor"]}, {"visual": "module_umap", "narration": "Open Image UMAP from Home. Project measured features or supplied encoder features and inspect representative crops. A cluster is a candidate grouping, not a validated phenotype. Use the lasso and annotation controls to write reviewed selections to an annotation column in the matching measurement database. A geometric selection alone does not establish a biological phenotype. Input data: Measured objects; Object crops; Image embeddings. Output data: Projection and clusters; Training annotations. Measure to Image UMAP: Choose feature columns and inspect representative crops. Embeddings to Image UMAP: Supply the encoder feature table with matching object IDs; do not assume every GUI route automatically persists it. Image UMAP to Gate Editor: Supply the matching coordinate/feature columns when defining a selection. Image UMAP to Classify: Write reviewed lasso selections to an annotation column in the matching object database, then select that column in Classify. Inspect crops and validate labels; embedding clusters are not ground truth.", "hold_after": 0.7, "related_lessons": ["08_measure", "15_image_umap", "41_classify", "64_gate_editor", "77_embeddings"]}, {"visual": "module_gate_editor", "narration": "Open Gate Editor from Home. Define threshold or polygon gates on actual feature/coordinate columns, then apply the saved gate to compatible objects. Use Annotate to write the displayed gates to an annotation column; review the selected objects and choose binary or multiclass labels. Input data: Measured objects; Projection and clusters. Output data: Reusable gates; Training annotations. Image UMAP to Gate Editor: Supply the matching coordinate/feature columns when defining a selection. Gate Editor to Annotate: Apply compatible gates, then review candidate labels. Measure to Gate Editor: Use the actual measured feature definitions and units. Gate Editor to Classify: Write reviewed gate selections to an annotation column, then select that same column and object population in Classify. Keep validation objects separate from training labels.", "hold_after": 0.7, "related_lessons": ["08_measure", "09_annotate", "15_image_umap", "41_classify", "64_gate_editor"]}, {"visual": "module_align", "narration": "Open Align & Stitch from Home. Inspect tile geometry, overlap and channel mapping, then save the mosaic with coordinate records. OPS also needs the original cycle/site identities. Input data: Microscope images. Output data: Aligned mosaic and coordinates.", "hold_after": 0.7, "related_lessons": ["32_align_stitch"]}, {"visual": "module_analyze_plaques", "narration": "Open Toxoplasma from Home, then choose Plaque Assay. Analyse plaque images or existing masks with the configured plaque model. This route need not pass through Measure; use the dedicated plaque example. Input data: Microscope images; Label masks. Output data: Assay results; Label masks. Make Masks to Plaque Assay: Use plaque masks with matching source images; cell masks are not automatically plaque labels.", "hold_after": 0.7, "related_lessons": ["14_make_masks", "24_plaque"]}, {"visual": "module_recruitment", "narration": "Open Toxoplasma from Home, then choose Recruitment. Use compartment intensity measurements and matching host/pathogen identities to compute recruitment ratios. Input data: Measured objects. Output data: Assay results. Measure to Recruitment: Require the intended compartment intensities and identities.", "hold_after": 0.7, "related_lessons": ["08_measure", "25_recruitment"]}, {"visual": "module_host_pathogen", "narration": "Open Toxoplasma from Home, then choose Host–Pathogen Analysis. Measure whole vacuoles and host reference compartments, keeping uninfected host cells for the infection denominator. Select marker channels and control-calibrated ratio thresholds. Optionally count individually segmented parasites from explicit vacuole links or a measured count column. Review vacuole, host and well tables, joint marker states, replication distributions and unmatched parasite links; unknown measurements remain unknown. Input data: Measured objects. Output data: Assay results. Measure to Host–Pathogen Analysis: Keep uninfected cells in Measure. Supply whole-vacuole masks, host reference intensities and optional explicit parasite-to-vacuole links; host identity alone does not define a vacuole.", "hold_after": 0.7, "related_lessons": ["08_measure", "85_host_pathogen"]}, {"visual": "module_invasion", "narration": "Open Toxoplasma from Home, then choose Invasion Assay. Use the required two-colour differential-staining measurements and stain-baseline controls to distinguish attachment from invasion. Input data: Measured objects. Output data: Assay results. Measure to Invasion Assay: Require two-colour stain measurements and appropriate baseline controls.", "hold_after": 0.7, "related_lessons": ["08_measure", "26_invasion"]}, {"visual": "module_replication", "narration": "Open Toxoplasma from Home, then choose Replication Assay. Count parasites using explicit vacuole identity and compare condition distributions; host identity alone does not define a vacuole. Input data: Measured objects. Output data: Assay results. Measure to Replication Assay: Require explicit parasite-to-vacuole identities.", "hold_after": 0.7, "related_lessons": ["08_measure", "27_replication"]}, {"visual": "module_qc_dashboard", "narration": "Open QC from Home. Inspect stored segmentation, unit, leakage and plate-effect checks. Open its nested viewers for detailed inspection. Input data: Measured objects; Quality-control results. Output data: Quality-control results; Figures and table exports. Measure to QC: Review available checks and missing evidence.", "hold_after": 0.7, "related_lessons": ["08_measure", "54_qc_dashboard"]}, {"visual": "module_embeddings", "narration": "Open Embeddings from Home. Encode object images with a chosen model and channel policy. Retain object identities and encoder provenance when supplying the features to downstream exploration. Input data: Measured objects; Object crops. Output data: Image embeddings. Measure to Embeddings: Retain encoder and channel-policy provenance. Embeddings to Image UMAP: Supply the encoder feature table with matching object IDs; do not assume every GUI route automatically persists it.", "hold_after": 0.7, "related_lessons": ["08_measure", "15_image_umap", "77_embeddings"]}, {"visual": "module_endodyogeny", "narration": "Use Endodyogeny size proxy from Python through spacr.submodules.analyze_endodyogeny. This API-only workflow has no Home tile or menu entry. Read measured compartment areas, annotate conditions and bin area ** 1.5 into log2 size doublings. Defaults aggregate pathogen area per host cell, not per vacuole: multiple vacuoles in one cell are combined. This is an area-derived size proxy, not measured volume or a parasite count. Use Replication Assay with explicit vacuole identity for parasites-per-vacuole counts. Configure compartment, area filters, calibration, conditions and grouping before calling the API; saving is optional. Input data: Host-cell-aggregated compartment areas. Output data: Area-derived size-proxy results. Measure to Endodyogeny size proxy: Supply the measured project roots and required object/png_list tables. Verify host-cell aggregation and area units before interpreting size bins; the Mask counts database alone is insufficient.", "hold_after": 0.7, "related_lessons": ["08_measure"]}, {"visual": "module_cellpose_masks", "narration": "Use Direct Cellpose mask generation from Python through spacr.spacr_cellpose.identify_masks_finetune. This API-only workflow has no Home tile or menu entry. Run a stock or custom Cellpose model on TIFF fields through the Python API. Despite its historical identify_masks_finetune name, this function performs inference, not training. Review normalization, channels, resizing and model parameters; masks are written only when save is enabled. Import compatible image/mask pairs through External Masks before Measure, or curate the pairs before training. This call does not build a Measure-ready merged project. Input data: TIFF fields for direct Cellpose inference; Segmentation checkpoint. Output data: Direct Cellpose TIFF masks.", "hold_after": 0.7, "related_lessons": []}, {"visual": "home_summary", "narration": "For high-content analysis, follow Mask into Measure and then choose the method that answers your question. For segmentation training, curate image-mask pairs in Make Masks before Train Cellpose and test the saved model in Mask. Existing compatible masks or measurements let you enter later. Preserve channel identities, units, object keys and the settings used to create each result; follow the dedicated walkthrough for the route you choose.", "hold_after": 0.7}], "narration_voices": {"en": ["af_heart"]}, "poster": "80_image_analysis_pathways/poster.jpg", "silent": "80_image_analysis_pathways/video/80_image_analysis_pathways_silent.mp4"}, {"id": "81_sequencing_pathways", "number": 81, "slug": "sequencing_pathways", "title": "Sequencing modules and how they relate", "series": 1, "app_key": null, "section": "Workflows", "description": "Connect sequencing and optical barcode workflows to phenotype scores, regression, experiment planning, power estimates, dose-response analysis and run comparison.", "objectives": ["Choose a starting module from the data you already have.", "Identify what each module reads and writes.", "Follow the linked module lessons and API contracts for the next step."], "prerequisite": "Install spaCR and open Home. This lesson explains navigation and data handoffs; the linked module lessons provide the worked data examples. Inputs and outputs include conditional alternatives, as explained for each module.", "scenes": [{"visual": "home", "narration": "Start on Home with the question and the type of barcode data. Map Barcodes reads sequencing files; optical pooled screening reads registered image cycles through OPS. Both need an explicit mapping from barcode identities to the experiment. Regression relates compatible perturbation counts and phenotype scores; it does not replace barcode decoding. Experiment Design and Power belong before acquisition when you are planning the screen, while Dose-Response and Run Compare inspect suitable results afterwards.", "hold_after": 0.7, "related_lessons": ["05_home"]}, {"visual": "module_map_barcodes", "narration": "Open Map Barcodes from Home. Supply the references that encode your experiment. Inspect mapped counts and barcode QC before pairing well-level guide counts with phenotype scores. Input data: Sequencing reads. Output data: Guide counts per well. Map Barcodes to Regression: Pair guide counts with phenotype scores using consistent plate/well keys. Map Barcodes to Barcode QC: Check mapping and coverage before guide filtering.", "hold_after": 0.7, "related_lessons": ["12_map_barcodes", "13_regression", "47_barcode_qc"]}, {"visual": "module_barcode_qc", "narration": "Open Map Barcodes from Home, then choose Barcode QC. Inspect mapping depth, coverage, collisions and positional effects before guide-count filtering. Input data: Guide counts per well. Output data: Quality-control results; Figures and table exports. Map Barcodes to Barcode QC: Check mapping and coverage before guide filtering.", "hold_after": 0.7, "related_lessons": ["12_map_barcodes", "47_barcode_qc"]}, {"visual": "module_ops", "narration": "Open Mask from Home, then choose OPS. Use sequencing-cycle images and phenotype alignment to decode barcodes per nucleus. Aggregate/join the decoded identities to compatible phenotype inputs before Regression; the OPS database is not a drop-in FASTQ count CSV. Input data: Microscope images; Aligned mosaic and coordinates. Output data: Optical barcode assignments. OPS to Regression: Join/aggregate decoded objects to phenotype and guide inputs explicitly before Regression; this is not a direct CSV handoff.", "hold_after": 0.7, "related_lessons": ["13_regression", "76_ops"]}, {"visual": "module_regression", "narration": "Open Regression from Home. Match plate and well identifiers across phenotype and guide-count inputs, select the response and controls, and inspect diagnostics before interpreting hits. Direct measured responses are also supported. Input data: Object classification scores; Guide counts per well; Optical barcode assignments; Measured objects. Output data: Regression results and hits. Classify to Regression: Select the intended CV or ML score column and preserve plate/well identity. Map Barcodes to Regression: Pair guide counts with phenotype scores using consistent plate/well keys. OPS to Regression: Join/aggregate decoded objects to phenotype and guide inputs explicitly before Regression; this is not a direct CSV handoff. Regression to Run Compare: Compare compatible saved result sets and their settings.", "hold_after": 0.7, "related_lessons": ["12_map_barcodes", "13_regression", "41_classify", "50_run_compare", "76_ops"]}, {"visual": "module_power", "narration": "Open Power / Design from Home. Estimate sampling needs from chosen effect sizes and variability; pilot measurements are optional evidence for assumptions. Input data: Screen design and power estimates; Measured objects; Experimental layout. Output data: Screen design and power estimates. Experiment Design to Power / Design: Use the experimental layout to define sampling assumptions, then revise the design.", "hold_after": 0.7, "related_lessons": ["67_experiment_design", "68_power_design"]}, {"visual": "module_experiment_design", "narration": "Open Experiment Design from Home. Enter conditions, controls, replicates and plate constraints, then export the experimental layout before acquisition. Input data: Screen design and power estimates. Output data: Experimental layout. Experiment Design to Power / Design: Use the experimental layout to define sampling assumptions, then revise the design. Experiment Design to Dose–Response: Acquire and measure the experiment first, preserving dose/condition identities.", "hold_after": 0.7, "related_lessons": ["67_experiment_design", "68_power_design", "69_dose_response"]}, {"visual": "module_dose_response", "narration": "Open Dose–Response from Home. Supply dose and response columns, controls and units before curve fitting; this route does not require sequencing. Input data: Measured objects; Experimental layout. Output data: Assay results; Figures and table exports. Experiment Design to Dose–Response: Acquire and measure the experiment first, preserving dose/condition identities.", "hold_after": 0.7, "related_lessons": ["67_experiment_design", "69_dose_response"]}, {"visual": "module_run_compare", "narration": "Open Run Compare from Home. Compare compatible saved settings, counts and hit lists without treating changed input data as a controlled model comparison. Input data: Run history and artifacts; Regression results and hits. Output data: Run/model comparison. Regression to Run Compare: Compare compatible saved result sets and their settings.", "hold_after": 0.7, "related_lessons": ["13_regression", "50_run_compare"]}, {"visual": "module_simulation", "narration": "Use Pooled-screen simulation sweep from Python through spacr.sim.run_multiple_simulations. This API-only workflow has no Home tile or menu entry. Use the Python sweep API to explore stated screen-design assumptions. It expands combinations, runs simulations in a process pool and writes synthetic summary statistics; it returns None. Set a small explicit max_workers value and a bounded parameter grid before running. The output does not replace measurements or barcode counts for experimental Regression. Use the findings as planning evidence, with their assumptions recorded. Review the synthetic summaries when choosing planning assumptions; transfer those assumptions manually into Power / Design or Experiment Design. Neither tool imports this simulation database, and neither exports the simulation settings grid. Input data: Pooled-screen simulation assumptions. Output data: Synthetic screen simulation summaries.", "hold_after": 0.7, "related_lessons": []}, {"visual": "home_summary", "narration": "Keep sequencing references and plate layouts with the counts, and check the join to image-derived scores before interpreting a regression. Optical assignments require their own object join and aggregation; they are not automatically a drop-in sequencing count file. Treat planning assumptions, fitted effects and comparisons between completed runs as distinct results. The linked lessons and Home walkthroughs show the route for each kind of experiment.", "hold_after": 0.7}], "narration_voices": {"en": ["af_aoede", "af_bella", "af_heart", "af_jessica", "af_river", "af_sarah", "af_sky", "am_adam", "am_echo", "am_eric", "am_fenrir", "am_liam", "am_michael", "am_onyx", "am_puck", "am_santa", "bf_alice", "bf_emma", "bf_isabella", "bf_lily", "bm_daniel", "bm_fable", "bm_george", "bm_lewis"], "es": ["ef_dora", "em_alex", "em_santa"], "fr": ["ff_siwis"], "hi": ["hf_alpha", "hf_beta", "hm_omega", "hm_psi"], "it": ["if_sara", "im_nicola"], "ja": ["jf_alpha", "jf_gongitsune", "jf_nezumi", "jf_tebukuro", "jm_kumo"], "pt-BR": ["pf_dora", "pm_alex", "pm_santa"], "zh-CN": ["zf_xiaobei", "zf_xiaoni", "zf_xiaoxiao", "zf_xiaoyi", "zm_yunjian", "zm_yunxi", "zm_yunxia", "zm_yunyang"]}, "poster": "81_sequencing_pathways/poster.jpg", "silent": "81_sequencing_pathways/video/81_sequencing_pathways_silent.mp4"}, {"id": "82_toxoplasma", "number": 82, "slug": "toxoplasma", "title": "Toxoplasma: explore the page and choose an assay", "series": 3, "app_key": "toxoplasma", "section": "Organisms and assays", "description": "Open the organism page, explore the cell diagram and choose an available assay.", "objectives": ["Open the page from Home and find its main controls.", "Identify the available inputs, actions and outputs.", "Choose the next available analysis or reference."], "prerequisite": "Open spaCR Home. The organism guide requires no input files. Each assay has its own inputs and linked walkthrough.", "scenes": [{"visual": "00_home", "narration": "From Home, choose Toxoplasma. This page brings the organism guide, cell diagram and available assays together. You can explore it before loading any images or measurements.", "hold_after": 0.7}, {"visual": "01_organism", "narration": "Read the introduction in the information pane. Scroll each pane independently, or drag the divider to give the guide or assay tiles more room.", "hold_after": 0.7}, {"visual": "02_diagram", "narration": "Hover over a cell component to read its description. Select several components to keep them highlighted, and use Clear components to reset the diagram.", "hold_after": 0.7}, {"visual": "03_assays", "narration": "Choose Plaque Assay for plaque counts and areas, Invasion Assay for entry measurements, Recruitment for marker ratios, Replication Assay for parasite counts, or Host–Pathogen for linked vacuole and host summaries. Open the matching lesson for its inputs, settings and results.", "hold_after": 0.7}, {"visual": "04_host_pathogen", "narration": "Click Host–Pathogen to open its analysis screen. Use Load test data to start with the supplied microscopy example, then follow the Host–Pathogen tutorial through the settings, preview and Run.", "hold_after": 0.7}, {"visual": "05_starplast", "narration": "Return to Toxoplasma and choose Starplast to explore the knowledge map in its separate application. On first use, follow the offered installation steps. The reference links also open organism resources in your browser.", "hold_after": 0.7}, {"visual": "06_home_return", "narration": "The guide itself writes no analysis files. Return to Home when you need image segmentation or measurement first; use the assay pages once the required images or tables are ready.", "hold_after": 0.7}], "narration_voices": {"en": ["af_heart"]}, "poster": "82_toxoplasma/poster.jpg", "silent": "82_toxoplasma/video/82_toxoplasma_silent.mp4"}, {"id": "83_plasmodium", "number": 83, "slug": "plasmodium", "title": "Plasmodium: explore the organism guide", "series": 3, "app_key": "plasmodium", "section": "Organisms and assays", "description": "Browse the Plasmodium guide, explore the cell diagram and find available general image-analysis workflows.", "objectives": ["Open the page from Home and find its main controls.", "Identify the available inputs, actions and outputs.", "Choose the next available analysis or reference."], "prerequisite": "Open spaCR Home. No input files are needed for the guide. The Plasmodium-specific assay tiles currently show Coming soon.", "scenes": [{"visual": "00_home", "narration": "From Home, choose Plasmodium. Open this guide to browse organism information, cell compartments and the planned assay topics.", "hold_after": 0.7}, {"visual": "01_organism", "narration": "Scroll the information pane to read the blood-stage, liver-stage and motility sections. Drag the divider to adjust the space beside the module tiles.", "hold_after": 0.7}, {"visual": "02_diagram", "narration": "Hover over the apicomplexan diagram for compartment descriptions. Select components to highlight them together, then use Clear components to reset the view.", "hold_after": 0.7}, {"visual": "03_modules", "narration": "The assay tiles currently show Coming soon and are disabled. Browse their descriptions to see the intended readouts. For an available image workflow, return to Home and open Mask or Measure with your own images and suitable channel settings.", "hold_after": 0.7}, {"visual": "04_references", "narration": "Use the PlasmoDB and UniProt links to open organism resources in your browser. The guide requires no dataset, has no Run action and creates no output files.", "hold_after": 0.7}], "narration_voices": {"en": ["af_heart"]}, "poster": "83_plasmodium/poster.jpg", "silent": "83_plasmodium/video/83_plasmodium_silent.mp4"}, {"id": "84_candida", "number": 84, "slug": "candida", "title": "Candida: explore the organism guide", "series": 3, "app_key": "candida", "section": "Organisms and assays", "description": "Browse the Candida guide, explore the yeast diagram and find available general image-analysis workflows.", "objectives": ["Open the page from Home and find its main controls.", "Identify the available inputs, actions and outputs.", "Choose the next available analysis or reference."], "prerequisite": "Open spaCR Home. No input files are needed for the guide. The Candida-specific assay tiles currently show Coming soon.", "scenes": [{"visual": "00_home", "narration": "From Home, choose Candida. Browse the guide for morphology, filamentation, biofilm and host-cell interaction topics.", "hold_after": 0.7}, {"visual": "01_organism", "narration": "Scroll the information pane and review the module descriptions beside it. Drag the divider to make either pane wider when reading.", "hold_after": 0.7}, {"visual": "02_diagram", "narration": "Hover over a component in the budding-yeast diagram to read its description. Select several components to keep them highlighted, and use Clear components to reset the selection.", "hold_after": 0.7}, {"visual": "03_modules", "narration": "The Candida-specific assay tiles currently show Coming soon and are disabled. To analyse images with the available general tools, return to Home, select Mask and Measure, and choose channels and masks suited to your species and experiment.", "hold_after": 0.7}, {"visual": "04_references", "narration": "Open the Candida Genome Database or UniProt links for gene and protein information. This guide uses no input files and writes no analysis outputs. Follow a runnable module’s tutorial when you are ready to process images.", "hold_after": 0.7}], "narration_voices": {"en": ["af_heart"]}, "poster": "84_candida/poster.jpg", "silent": "84_candida/video/84_candida_silent.mp4"}, {"id": "85_host_pathogen", "number": 85, "slug": "host_pathogen", "title": "Host–Pathogen: link vacuole markers and parasite counts", "series": 3, "app_key": "host_pathogen", "section": "Organisms and assays", "description": "Load the microscopy example, choose marker and count inputs, inspect the preview, and export linked vacuole, host-cell and well summaries.", "objectives": ["Load the example project and identify the host and vacuole measurements.", "Choose marker channels and inspect vacuole-level recruitment in Live preview.", "Run the analysis and read the output tables with the correct denominators."], "prerequisite": "Use Load test data for the supplied THP-1 microscopy example, or select a measured project with host cells, vacuoles and host-reference intensities. Retain uninfected host cells during Measure when you need an infection denominator. Individual parasite counts require a linked parasite table or a measured count column.", "scenes": [{"visual": "00_home", "narration": "From Home, open Toxoplasma, then choose Host–Pathogen. This module joins vacuole marker measurements and parasite counts to their host cells and well summaries.", "hold_after": 0.7}, {"visual": "01_test_data", "narration": "Choose Load test data to download the microscopy example and fill in its settings. It contains two fields with images, host and vacuole masks, and measurement tables. Use it to practise the controls before selecting your own measured project.", "hold_after": 0.7}, {"visual": "02_source", "narration": "Check Source. It should point to the project containing measurements/measurements.db. The module can also read a database directly or combine several project sources while keeping their identities separate.", "hold_after": 0.7}, {"visual": "03_compartments", "narration": "Choose the vacuole table and its intensity-column prefix, then the host-reference table and prefix. The example uses pathogen for vacuoles and cytoplasm for the host reference. The object links must associate each vacuole with the correct host cell.", "hold_after": 0.7}, {"visual": "04_markers", "narration": "Set Marker channels to the zero-based intensity channels you want to compare. The example selects channel one for the RNF213 marker. Each selected channel needs intensity measurements in both the vacuole and reference compartments.", "hold_after": 0.7}, {"visual": "05_thresholds", "narration": "Leave Marker thresholds empty to inspect recruitment ratios first. To classify a marker as positive or negative, enter its channel number and a ratio threshold chosen from your assay controls. A ratio at or above the threshold is positive. Missing or invalid reference measurements remain unknown.", "hold_after": 0.7}, {"visual": "06_counts", "narration": "For parasite counts, choose either a parasite table with explicit parent-vacuole links or a measured count column on each vacuole. The microscopy example has neither, so keep both choices empty. Its parasite counts and replication readouts remain unknown.", "hold_after": 0.7}, {"visual": "07_preview", "narration": "Turn on Live, choose a field and click Run preview. Inspect the vacuole table beside the image. Select a row or click a vacuole to inspect the corresponding marker measurements and any available parasite count.", "hold_after": 0.7}, {"visual": "08_run", "narration": "Turn off Live and expand Actions if it is folded. Keep Save enabled, then press Run. Wait for the output path in the console. Results are written to results/host_pathogen in the first selected project.", "hold_after": 0.7}, {"visual": "09_vacuoles", "narration": "Open vacuoles.csv for one row per vacuole, including its host link, marker ratios, marker state and available parasite count. Open cells.csv for host-cell infection and vacuole counts, then wells.csv for their well summaries.", "hold_after": 0.7}, {"visual": "10_summaries", "narration": "Use marker_states.csv to inspect joint marker states and replication_distribution.csv for parasite counts per counted vacuole. orphan_parasites.csv lists parasites without a usable parent link. Keep settings.json with these tables so the channel and threshold choices remain available.", "hold_after": 0.7}, {"visual": "11_denominators", "narration": "Check the denominators before comparing conditions. Infection fractions use retained measured host cells, including uninfected hosts only when Measure retained them. Count distributions use vacuoles with known parasite counts; unknown values remain distinct from zero.", "hold_after": 0.7}], "host_app_key": "toxoplasma", "narration_voices": {"en": ["af_heart"]}, "poster": "85_host_pathogen/poster.jpg", "silent": "85_host_pathogen/video/85_host_pathogen_silent.mp4"}]});
